                  </motion.tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="border-t-2 border-cyan-400/30">
                  <td colSpan={2} className="cyber-subheading text-xs text-cyan-400 uppercase py-2">Total</td>
                  <td className="hidden md:table-cell" />
                  <td className="text-center cyber-mono text-green-400 py-2">{data.totals.hMasuk}</td>
                  <td className="text-center cyber-mono text-cyan-400 py-2">{data.totals.hSakit}</td>
                  <td className="text-center cyber-mono text-yellow-400 py-2">{data.totals.hIzin}</td>
                  <td className="text-center cyber-mono text-red-400 py-2">{data.totals.hAlfa}</td>
                  <td className="text-center cyber-mono text-orange-400 py-2">{data.totals.terlambat}</td>
                  <td className="text-center cyber-mono py-2">{data.effectiveDays * data.students.length}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      ) : !loading && data && data.students.length === 0 ? (
        <div className="neon-card rounded-xl p-12 text-center"><p className="text-muted-foreground cyber-body">Belum ada data siswa</p></div>
      ) : null}
    </div>
  );
}
"},{"path":"src/components/app/RekapPerSiswaTab.tsx","content":"'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Calendar, Download, Loader2, ChevronUp, ChevronDown,
  FileText, Archive, User
} from 'lucide-react';
import { ClassData, Student, AttendanceStatus, ATTENDANCE_ICONS, ATTENDANCE_COLORS } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTH_NAMES = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];

interface DayResult {
  date: string;
  dayName: string;
  dayOfWeek: number;
  status: AttendanceStatus | null;
  hourDetails: Record<number, AttendanceStatus>;
}

interface RekapPerSiswaTabProps {
  classData: ClassData;
  students: Student[];
}

const STATUS_DISPLAY: Record<string, { icon: string; label: string; color: string }> = {
  Hadir: { icon: '✅', label: 'Masuk', color: 'text-green-400' },
  Terlambat: { icon: '⏱️', label: 'Terlambat', color: 'text-orange-400' },
  Alfa: { icon: '❌', label: 'Alfa', color: 'text-red-400' },
  Sakit: { icon: '💙', label: 'Sakit', color: 'text-cyan-400' },
  Izin: { icon: '✉️', label: 'Izin', color: 'text-yellow-400' },
};

// Tooltip component matching RekapHarianContent pattern
function StatusTooltip({ status, children }: { status: string; children: React.ReactNode }) {
  const [show, setShow] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const display = STATUS_DISPLAY[status] || { icon: '➖', label: status, color: 'text-muted-foreground' };

  return (
    <div
      className="relative inline-flex cursor-default"
      onMouseEnter={() => { if (timeoutRef.current) clearTimeout(timeoutRef.current); setShow(true); }}
      onMouseLeave={() => { timeoutRef.current = setTimeout(() => setShow(false), 300); }}
      onClick={() => setShow(p => !p)}
    >
      {children}
      {show && status && status !== 'Libur' && (
        <div className="status-tooltip" style={{ color: display.color.replace('text-', '') === 'text-green-400' ? '#39ff14' : display.color.replace('text-', '') === 'text-orange-400' ? '#ff6600' : display.color.replace('text-', '') === 'text-red-400' ? '#ff0044' : display.color.replace('text-', '') === 'text-cyan-400' ? '#00f0ff' : display.color.replace('text-', '') === 'text-yellow-400' ? '#ffe600' : '#94a3b8' }}>
          {display.label}
        </div>
      )}
    </div>
  );
}

export function RekapPerSiswaTab({ classData, students }: RekapPerSiswaTabProps) {
  const { toast } = useToast();
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [dayResults, setDayResults] = useState<DayResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [bulkExporting, setBulkExporting] = useState(false);
  const [error, setError] = useState('');

  // Initialize date range to current week (Monday to Sunday)
  useEffect(() => {
    const now = new Date();
    const dayOfWeek = now.getDay(); // 0=Sun, 1=Mon, ...
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    const monday = new Date(now);
    monday.setDate(now.getDate() + mondayOffset);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    setStartDate(formatDateStr(monday));
    setEndDate(formatDateStr(sunday));
  }, []);

  const currentStudent = students[currentIndex] || null;

  const fetchRecap = useCallback(async () => {
    if (!startDate || !endDate || !currentStudent) return;
    setLoading(true);
    setError('');
    try {
      const data = await safeFetchJson(`/api/recap/student?studentId=${currentStudent.id}&classId=${classData.id}&startDate=${startDate}&endDate=${endDate}`);
      if (data && data.days) {
        setDayResults(data.days);
      } else {
        setDayResults([]);
        if (data?.error) setError(data.error);
      }
    } catch {
      setDayResults([]);
    }
    setLoading(false);
  }, [currentStudent, classData.id, startDate, endDate]);

  useEffect(() => {
    if (startDate && endDate && currentStudent) {
      fetchRecap();
    }
  }, [fetchRecap, startDate, endDate, currentStudent]);

  // Clamp index when students change
  useEffect(() => {
    if (students.length === 0) return;
    if (currentIndex >= students.length) setCurrentIndex(students.length - 1);
    if (currentIndex < 0) setCurrentIndex(0);
  }, [students.length, currentIndex]);

  const handlePrev = () => {
    if (currentIndex > 0) setCurrentIndex(i => i - 1);
  };
  const handleNext = () => {
    if (currentIndex < students.length - 1) setCurrentIndex(i => i + 1);
  };

  const handleDateChange = (newStart: string, newEnd: string) => {
    // Validate max 1 week
    const diff = (new Date(newEnd).getTime() - new Date(newStart).getTime()) / 86400000;
    if (diff > 7) {
      setError('Rentang tanggal maksimal 1 minggu (7 hari)');
      return;
    }
    setError('');
    setStartDate(newStart);
    setEndDate(newEnd);
  };

  // Compute totals
  const totals = dayResults.reduce(
    (acc, day) => {
      if (day.status === 'Hadir') acc.Masuk++;
      else if (day.status === 'Terlambat') acc.Terlambat++;
      else if (day.status === 'Alfa') acc.Alfa++;
      else if (day.status === 'Sakit') acc.Sakit++;
      else if (day.status === 'Izin') acc.Izin++;
      return acc;
    },
    { Masuk: 0, Terlambat: 0, Alfa: 0, Sakit: 0, Izin: 0 }
  );

  const handleExport = async () => {
    if (!currentStudent || dayResults.length === 0) return;
    setExporting(true);
    try {
      const url = `/api/recap/student-pdf?studentId=${currentStudent.id}&classId=${classData.id}&startDate=${startDate}&endDate=${endDate}`;
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 60000);
      const res = await fetch(url, { signal: controller.signal });
      clearTimeout(timeoutId);
      if (!res.ok) {
        let errMsg = 'Export gagal';
        try {
          const errData = await res.json();
          errMsg = errData.error || errMsg;
        } catch { /* ignore parse error */ }
        throw new Error(errMsg);
      }
      const contentType = res.headers.get('content-type') || '';
      if (!contentType.includes('pdf')) {
        throw new Error('Response bukan PDF');
      }
      const blob = await res.blob();
      if (blob.size === 0) throw new Error('File PDF kosong');
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      const safeName = currentStudent.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_');
      link.download = `Rekap_${classData.name}_${safeName}_${startDate}_sd_${endDate}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(link.href);
      toast({ title: 'PDF berhasil diunduh' });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Export gagal';
      if (msg.includes('abort')) {
        toast({ title: 'Export timeout', description: 'Server membutuhkan waktu terlalu lama', variant: 'destructive' });
      } else {
        toast({ title: 'Export gagal', description: msg, variant: 'destructive' });
      }
    }
    setExporting(false);
  };

  const handleBulkExport = async () => {
    if (students.length === 0 || !startDate || !endDate) return;
    setBulkExporting(true);
    try {
      const url = `/api/recap/student-bulk-zip?classId=${classData.id}&startDate=${startDate}&endDate=${endDate}`;
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 180000);
      const res = await fetch(url, { signal: controller.signal });
      clearTimeout(timeoutId);
      if (!res.ok) {
        let errMsg = 'Bulk export gagal';
        try {
          const errData = await res.json();
          errMsg = errData.error || errMsg;
        } catch { /* ignore parse error */ }
        throw new Error(errMsg);
      }
      const contentType = res.headers.get('content-type') || '';
      if (!contentType.includes('zip') && !contentType.includes('octet-stream')) {
        throw new Error('Response bukan ZIP');
      }
      const blob = await res.blob();
      if (blob.size === 0) throw new Error('File ZIP kosong');
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `Rekap_${classData.name}_${startDate}_sd_${endDate}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(link.href);
      toast({ title: 'ZIP berhasil diunduh' });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Bulk export gagal';
      if (msg.includes('abort')) {
        toast({ title: 'Bulk Export timeout', description: 'Jumlah siswa terlalu banyak, coba kurangi rentang tanggal', variant: 'destructive' });
      } else {
        toast({ title: 'Bulk export gagal', description: msg, variant: 'destructive' });
      }
    }
    setBulkExporting(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <User className="w-3.5 h-3.5 sm:w-4 sm:h-4 neon-text-cyan" />
        <span className="cyber-subheading text-[10px] sm:text-xs neon-text-cyan">REKAP PER SISWA</span>
      </div>

      {/* Date range picker */}
      <div className="neon-card rounded-xl p-3 sm:p-4">
        <div className="flex flex-wrap items-end gap-2 sm:gap-3">
          <div>
            <label className="cyber-mono text-[10px] text-muted-foreground uppercase">Tanggal Mulai</label>
            <input
              type="date"
              value={startDate}
              onChange={e => handleDateChange(e.target.value, endDate)}
              className="neon-input px-3 py-2 rounded-lg mt-1 text-xs"
              max={endDate}
            />
          </div>
          <div>
            <label className="cyber-mono text-[10px] text-muted-foreground uppercase">Tanggal Akhir</label>
            <input
              type="date"
              value={endDate}
              onChange={e => handleDateChange(startDate, e.target.value)}
              className="neon-input px-3 py-2 rounded-lg mt-1 text-xs"
              min={startDate}
            />
          </div>
        </div>
        {error && <p className="cyber-mono text-[10px] text-red-400 mt-2">{error}</p>}
      </div>

      {/* Student navigation with spin button */}
      <div className="neon-card rounded-xl p-3 sm:p-4">
        <div className="flex items-center gap-2">
          <button
            onClick={handlePrev}
            disabled={currentIndex <= 0 || loading}
            className="p-1.5 rounded-lg border border-cyan-400/30 bg-cyan-400/5 text-cyan-400 hover:bg-cyan-400/15 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
            title="Siswa sebelumnya"
          >
            <ChevronUp className="w-4 h-4" />
          </button>

          <div className="flex-1 min-w-0 px-2">
            <div className="flex items-center justify-between gap-2">
              <div className="flex-1 min-w-0">
                <p className="text-xs text-muted-foreground cyber-mono">{currentIndex + 1} / {students.length}</p>
                <p className="cyber-heading text-lg sm:text-xl truncate neon-text-cyan">
                  {currentStudent?.name || '-'}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 mt-1">
              <span className="cyber-mono text-[10px] text-muted-foreground">
                NISN: {currentStudent?.nisn || '-'}
              </span>
              <span className="cyber-mono text-[10px] text-muted-foreground">
                {currentStudent?.gender || '-'}
              </span>
            </div>
          </div>

          <button
            onClick={handleNext}
            disabled={currentIndex >= students.length - 1 || loading}
            className="p-1.5 rounded-lg border border-cyan-400/30 bg-cyan-400/5 text-cyan-400 hover:bg-cyan-400/15 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
            title="Siswa selanjutnya"
          >
            <ChevronDown className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Attendance table */}
      {loading ? (
        <div className="neon-card rounded-xl p-12 text-center">
          <div className="cyber-mono text-sm text-muted-foreground animate-neon-pulse">LOADING...</div>
        </div>
      ) : dayResults.length > 0 ? (
        <div className="neon-card rounded-xl overflow-hidden">
          {/* Header info */}
          <div className="p-2 sm:p-3 border-b border-cyan-400/20 bg-cyan-400/5">
            <span className="cyber-subheading text-[10px] sm:text-xs neon-text-cyan truncate">
              {classData.name.toUpperCase()} &mdash; {currentStudent?.name}
            </span>
            <span className="cyber-mono text-[9px] sm:text-[10px] text-muted-foreground ml-2">
              {startDate} s/d {endDate}
            </span>
          </div>

          <div className="overflow-x-auto">
            <table className="neon-table">
              <thead>
                <tr>
                  <th className="w-14 sm:w-20">HARI</th>
                  <th className="min-w-[80px] sm:min-w-[130px]">TANGGAL</th>
                  <th className="w-12 sm:w-16 text-center">MASUK</th>
                  <th className="w-12 sm:w-16 text-center">TERLAMBAT</th>
                  <th className="w-12 sm:w-16 text-center">ALFA</th>
                  <th className="w-12 sm:w-16 text-center">SAKIT</th>
                  <th className="w-12 sm:w-16 text-center">IZIN</th>
                </tr>
              </thead>
              <tbody>
                {dayResults.map((day, idx) => {
                  const display = day.status ? STATUS_DISPLAY[day.status] : null;
                  return (
                    <motion.tr
                      key={day.date}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: idx * 0.03 }}
                    >
                      <td className="cyber-mono text-xs text-center">{day.dayName}</td>
                      <td className="cyber-mono text-xs">{formatDateIndo(day.date)}</td>
                      {(['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin'] as const).map(s => {
                        const isMatch = day.status === s;
                        const d = STATUS_DISPLAY[s];
                        return (
                          <td key={s} className="text-center">
                            {isMatch ? (
                              <StatusTooltip status={s}>
                                <span className={`text-base sm:text-lg ${d.color}`}>{d.icon}</span>
                              </StatusTooltip>
                            ) : (
                              <span className="text-muted-foreground/40">➖</span>
                            )}
                          </td>
                        );
                      })}
                    </motion.tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr className="border-t-2 border-cyan-400/30">
                  <td colSpan={2} className="cyber-subheading text-xs text-cyan-400 uppercase py-2">Total</td>
                  <td className="text-center cyber-mono text-green-400 py-2 font-bold">{totals.Masuk}</td>
                  <td className="text-center cyber-mono text-orange-400 py-2 font-bold">{totals.Terlambat}</td>
                  <td className="text-center cyber-mono text-red-400 py-2 font-bold">{totals.Alfa}</td>
                  <td className="text-center cyber-mono text-cyan-400 py-2 font-bold">{totals.Sakit}</td>
                  <td className="text-center cyber-mono text-yellow-400 py-2 font-bold">{totals.Izin}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      ) : !loading && dayResults.length === 0 ? (
        <div className="neon-card rounded-xl p-12 text-center">
          <p className="text-muted-foreground cyber-body">
            {students.length === 0 ? 'Belum ada data siswa' : 'Tidak ada data absensi untuk periode ini'}
          </p>
        </div>
      ) : null}

      {/* Export buttons */}
      {dayResults.length > 0 && (
        <div className="flex flex-wrap gap-2">
          <button
            onClick={handleExport}
            disabled={exporting || !currentStudent}
            className="neon-btn-green px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {exporting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <FileText className="w-3.5 h-3.5" />}
            {exporting ? 'EXPORTING...' : 'Export PDF'}
          </button>
          <button
            onClick={handleBulkExport}
            disabled={bulkExporting || students.length === 0}
            className="neon-btn-orange px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {bulkExporting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Archive className="w-3.5 h-3.5" />}
            {bulkExporting ? 'PROCESSING...' : `Bulk Export ZIP (${students.length} siswa)`}
          </button>
        </div>
      )}
    </div>
  );
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function formatDateIndo(dateStr: string): string {
  const [y, m, d] = dateStr.split('-').map(Number);
  return `${d} ${MONTH_NAMES[m - 1]} ${y}`;
}
