"},{"path":"src/components/app/RombelView.tsx","content":"'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Pencil, Trash2, Save, X, Check, Users, AlertTriangle, Search,
  CalendarDays, UserCheck, UserCog
} from 'lucide-react';
import { ClassData } from './types';
import { JadwalMingguanView } from './JadwalMingguanView';
import { GuruView } from './GuruView';

interface RombelViewProps {
  classes: ClassData[];
  onRefresh: () => void;
}

export function RombelView({ classes, onRefresh }: RombelViewProps) {
  const [activeTab, setActiveTab] = useState<'wali' | 'jadwal' | 'guru'>('wali');
  const [showAdd, setShowAdd] = useState(false);
  const [newName, setNewName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [waliMap, setWaliMap] = useState<Record<string, string>>(() => {
    const map: Record<string, string> = {};
    classes.forEach(c => { map[c.id] = c.waliKelasName || ''; });
    return map;
  });
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState<Record<string, boolean>>({});
  const [adding, setAdding] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [error, setError] = useState('');

  const filteredClasses = classes.filter(c =>
    c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    (c.waliKelasName || '').toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleAdd = async () => {
    const trimmed = newName.trim();
    if (!trimmed) { setError('Nama rombel tidak boleh kosong'); return; }
    if (classes.some(c => c.name.toLowerCase() === trimmed.toLowerCase())) {
      setError('Nama rombel sudah ada'); return;
    }
    setAdding(true); setError('');
    try {
      const res = await fetch('/api/classes', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: trimmed }),
      });
      if (!res.ok) { const data = await res.json().catch(() => ({})); setError(data.error || 'Gagal menambah rombel'); return; }
      setNewName(''); setShowAdd(false); onRefresh();
    } catch { setError('Terjadi kesalahan'); } finally { setAdding(false); }
  };

  const handleRename = async (classId: string) => {
    const trimmed = editName.trim();
    if (!trimmed) { setError('Nama tidak boleh kosong'); return; }
    if (classes.some(c => c.id !== classId && c.name.toLowerCase() === trimmed.toLowerCase())) {
      setError('Nama rombel sudah ada'); return;
    }
    setSaving(prev => ({ ...prev, [classId]: true })); setError('');
    try {
      const res = await fetch('/api/classes', {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ classId, name: trimmed }),
      });
      if (!res.ok) { const data = await res.json().catch(() => ({})); setError(data.error || 'Gagal mengubah nama'); return; }
      setSaved(prev => ({ ...prev, [classId]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [classId]: false })), 2000);
      setEditingId(null); onRefresh();
    } catch { setError('Terjadi kesalahan'); } finally { setSaving(prev => ({ ...prev, [classId]: false })); }
  };

  const handleDelete = async (classId: string) => {
    setDeletingId(null);
    try {
      const res = await fetch(`/api/classes?classId=${classId}`, { method: 'DELETE' });
      if (!res.ok) { const data = await res.json().catch(() => ({})); setError(data.error || 'Gagal menghapus rombel'); return; }
      onRefresh();
    } catch { setError('Terjadi kesalahan'); }
  };

  const handleSaveWali = async (classId: string) => {
    setSaving(prev => ({ ...prev, [`wk-${classId}`]: true }));
    try {
      await fetch('/api/wali-kelas', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ classId, name: waliMap[classId] || '' }),
      });
      setSaved(prev => ({ ...prev, [`wk-${classId}`]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [`wk-${classId}`]: false })), 2000);
      onRefresh();
    } catch (e) { console.error(e); } finally { setSaving(prev => ({ ...prev, [`wk-${classId}`]: false })); }
  };

  const currentClassesStr = classes.map(c => `${c.id}:${c.waliKelasName || ''}`).join('|');
  useEffect(() => {
    setWaliMap(prev => {
      const map: Record<string, string> = {};
      classes.forEach(c => { map[c.id] = prev[c.id] !== undefined ? prev[c.id] : (c.waliKelasName || ''); });
      return map;
    });
  }, [currentClassesStr]);

  const startEdit = (cls: ClassData) => { setEditingId(cls.id); setEditName(cls.name); setError(''); };

  const confirmDelete = (cls: ClassData) => {
    if (cls.studentCount > 0) { setDeletingId(cls.id); return; }
    handleDelete(cls.id);
  };

  const tabItems = [
    { key: 'wali' as const, label: 'Wali Kelas', icon: UserCheck },
    { key: 'jadwal' as const, label: 'Jadwal Mingguan', icon: CalendarDays },
    { key: 'guru' as const, label: 'Guru', icon: UserCog },
  ];

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header with Tabs */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">ROMBEL</h2>
          <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1">MANAJEMEN ROMBONGAN BELAJAR</p>
        </div>
        <div className="flex items-center gap-2">
          <span className="cyber-mono text-[10px] text-muted-foreground">{classes.length} rombel</span>
          {activeTab === 'wali' && (
            <button onClick={() => { setShowAdd(true); setError(''); }} className="neon-btn-green px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg text-xs flex items-center gap-1.5">
              <Plus className="w-3.5 h-3.5" /> Tambah
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 p-1 rounded-lg bg-[var(--sl-surface)] border border-[var(--sl-border)]">
        {tabItems.map(tab => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-2 rounded-md text-xs font-medium transition-all ${
                isActive
                  ? 'bg-fuchsia-500/20 text-fuchsia-300 border border-fuchsia-400/30'
                  : 'text-muted-foreground hover:text-foreground hover:bg-[var(--sl-glow-strong)]'
              }`}
            >
              <Icon className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">{tab.label}</span>
              <span className="sm:hidden">{tab.label.split(' ')[0]}</span>
            </button>
          );
        })}
      </div>

      {/* Tab Content */}
      {activeTab === 'wali' ? (
        <WaliKelasContent
          classes={classes}
          filteredClasses={filteredClasses}
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          showAdd={showAdd}
          setShowAdd={setShowAdd}
          newName={newName}
          setNewName={setNewName}
          adding={adding}
          editingId={editingId}
          editName={editName}
          setEditName={setEditName}
          saving={saving}
          saved={saved}
          deletingId={deletingId}
          error={error}
          setError={setError}
          setDeletingId={setDeletingId}
          waliMap={waliMap}
          setWaliMap={setWaliMap}
          handleAdd={handleAdd}
          handleRename={handleRename}
          handleDelete={handleDelete}
          handleSaveWali={handleSaveWali}
          startEdit={startEdit}
          confirmDelete={confirmDelete}
        />
      ) : activeTab === 'jadwal' ? (
        <JadwalMingguanView classes={classes} />
      ) : (
        <GuruView />
      )}
    </div>
  );
}

// Extracted Wali Kelas content for cleaner code
interface WaliKelasContentProps {
  classes: ClassData[];
  filteredClasses: ClassData[];
  searchQuery: string;
  setSearchQuery: (q: string) => void;
  showAdd: boolean;
  setShowAdd: (v: boolean) => void;
  newName: string;
  setNewName: (v: string) => void;
  adding: boolean;
  editingId: string | null;
  editName: string;
  setEditName: (v: string) => void;
  saving: Record<string, boolean>;
  saved: Record<string, boolean>;
  deletingId: string | null;
  error: string;
  setError: (v: string) => void;
  setDeletingId: (v: string | null) => void;
  waliMap: Record<string, string>;
  setWaliMap: (m: Record<string, string>) => void;
  handleAdd: () => void;
  handleRename: (id: string) => void;
  handleDelete: (id: string) => void;
  handleSaveWali: (id: string) => void;
  startEdit: (cls: ClassData) => void;
  confirmDelete: (cls: ClassData) => void;
}

function WaliKelasContent({
  filteredClasses, searchQuery, setSearchQuery,
  showAdd, setShowAdd, newName, setNewName, adding,
  editingId, editName, setEditName, saving, saved,
  deletingId, error, setError, setDeletingId,
  waliMap, setWaliMap,
  handleAdd, handleRename, handleDelete, handleSaveWali,
  startEdit, confirmDelete,
}: WaliKelasContentProps) {
  return (
    <>
      {/* Error */}
      <AnimatePresence>
        {error && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex items-center gap-2 p-3 rounded-lg border border-red-400/40 bg-red-400/10">
            <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0" />
            <span className="cyber-body text-xs text-red-400 flex-1">{error}</span>
            <button onClick={() => setError('')} className="text-red-400 hover:text-red-300"><X className="w-4 h-4" /></button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Add form */}
      <AnimatePresence>
        {showAdd && (
          <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
            <div className="neon-card rounded-xl p-4 border border-green-400/30">
              <div className="flex items-center gap-2 mb-3">
                <Plus className="w-4 h-4 neon-text-green" />
                <span className="cyber-subheading text-xs neon-text-green">TAMBAH ROMBEL BARU</span>
              </div>
              <div className="flex gap-2">
                <input type="text" value={newName} onChange={e => setNewName(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAdd()} className="neon-input flex-1 px-3 py-2 rounded-lg text-sm" placeholder="Nama rombel baru..." autoFocus />
                <button onClick={handleAdd} disabled={adding} className={`neon-btn-green px-4 py-2 rounded-lg text-xs flex items-center gap-1.5 ${adding ? 'opacity-50' : ''}`}>
                  {adding ? '...' : <><Save className="w-3.5 h-3.5" /> Simpan</>}
                </button>
                <button onClick={() => { setShowAdd(false); setNewName(''); setError(''); }} className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 hover:bg-red-400/15">
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Delete confirmation */}
      <AnimatePresence>
        {deletingId && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="neon-card rounded-xl p-4 border border-red-400/40">
            <div className="flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="cyber-body text-sm text-red-400 font-medium">Hapus rombel ini?</p>
                <p className="cyber-mono text-[10px] text-muted-foreground mt-1">Semua data siswa dan absensi di rombel ini akan ikut terhapus.</p>
                <div className="flex gap-2 mt-3">
                  <button onClick={() => handleDelete(deletingId)} className="neon-btn-red px-3 py-1.5 rounded-lg text-xs flex items-center gap-1.5">
                    <Trash2 className="w-3.5 h-3.5" /> <span className="hidden sm:inline">Ya, Hapus</span><span className="sm:hidden">Hapus</span>
                  </button>
                  <button onClick={() => setDeletingId(null)} className="px-3 py-1.5 rounded-lg text-xs border border-[var(--sl-border)] cyber-body hover:bg-[var(--sl-glow-strong)] transition-colors">
                    Batal
                  </button>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="neon-input w-full pl-9 pr-3 py-2 rounded-lg text-sm" placeholder="Cari rombel atau wali kelas..." />
      </div>

      {/* Mobile: Card layout */}
      <div className="sm:hidden space-y-2">
        {filteredClasses.length === 0 && (
          <div className="text-center py-8 text-muted-foreground cyber-mono text-xs">Tidak ada data rombel</div>
        )}
        {filteredClasses.map((cls, idx) => (
          <motion.div key={cls.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: idx * 0.04 }} className="neon-card rounded-lg p-3">
            <div className="flex items-center justify-between mb-2">
              {editingId === cls.id ? (
                <div className="flex items-center gap-1.5 flex-1 min-w-0">
                  <input type="text" value={editName} onChange={e => setEditName(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleRename(cls.id)} className="neon-input flex-1 px-2 py-1 rounded text-xs min-w-0" autoFocus />
                  <button onClick={() => handleRename(cls.id)} disabled={saving[cls.id]} className="sl-icon-btn border-green-400/40 bg-green-400/5 text-green-400 p-1"><Save className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setEditingId(null)} className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 p-1"><X className="w-3.5 h-3.5" /></button>
                </div>
              ) : (
                <>
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="cyber-mono text-[10px] text-muted-foreground w-5 text-right flex-shrink-0">{idx + 1}</span>
                    <span className="cyber-heading text-sm neon-text-cyan truncate">{cls.name}</span>
                    {saved[cls.id] && <Check className="w-3.5 h-3.5 text-green-400 flex-shrink-0" />}
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0">
                    <button onClick={() => startEdit(cls)} className="sl-icon-btn border-[var(--sl-border)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)] p-1" title="Ubah nama"><Pencil className="w-3.5 h-3.5" /></button>
                    <button onClick={() => confirmDelete(cls)} className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 hover:bg-red-400/15 p-1" title="Hapus"><Trash2 className="w-3.5 h-3.5" /></button>
                  </div>
                </>
              )}
            </div>
            <div className="flex items-center gap-2 mb-2 px-7">
              <Users className="w-3.5 h-3.5 text-muted-foreground" />
              <span className="cyber-mono text-[10px] text-muted-foreground">{cls.studentCount} siswa</span>
            </div>
            <div className="flex items-center gap-2 px-7">
              <input type="text" value={waliMap[cls.id] || ''} onChange={e => setWaliMap(prev => ({ ...prev, [cls.id]: e.target.value }))} className="neon-input flex-1 px-2.5 py-1.5 rounded-lg text-xs min-w-0" placeholder="Wali kelas..." />
              <button onClick={() => handleSaveWali(cls.id)} disabled={saving[`wk-${cls.id}`]} className={`neon-btn-green px-2.5 py-1.5 rounded-lg text-[10px] flex items-center gap-1 ${saving[`wk-${cls.id}`] ? 'opacity-50' : ''}`}>
                {saved[`wk-${cls.id}`] ? <><Check className="w-3 h-3" /> OK</> : <><Save className="w-3 h-3" /> Simpan</>}
              </button>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Desktop: Table layout */}
      <div className="hidden sm:block neon-card rounded-xl overflow-hidden">
        <div className="p-3 sm:p-4 border-b border-fuchsia-400/20 bg-fuchsia-400/5">
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 sm:w-5 sm:h-5 neon-text-magenta" />
            <h3 className="cyber-subheading text-[10px] sm:text-sm neon-text-magenta">DATA ROMBONGAN BELAJAR</h3>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="neon-table">
            <thead>
              <tr>
                <th className="w-12">NO</th>
                <th className="w-40">NAMA ROMBEL</th>
                <th className="w-24">SISWA</th>
                <th>NAMA WALI KELAS</th>
                <th className="w-32">AKSI</th>
              </tr>
            </thead>
            <tbody>
              {filteredClasses.length === 0 && (
                <tr><td colSpan={5} className="text-center py-8 text-muted-foreground cyber-mono text-sm">Tidak ada data rombel</td></tr>
              )}
              {filteredClasses.map((cls, idx) => (
                <motion.tr key={cls.id} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: idx * 0.04 }}>
                  <td className="text-center cyber-mono">{idx + 1}</td>
                  <td>
                    {editingId === cls.id ? (
                      <div className="flex items-center gap-1.5">
                        <input type="text" value={editName} onChange={e => setEditName(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleRename(cls.id)} className="neon-input flex-1 px-2 py-1 rounded text-xs" autoFocus />
                        <button onClick={() => handleRename(cls.id)} disabled={saving[cls.id]} className="sl-icon-btn border-green-400/40 bg-green-400/5 text-green-400 p-1"><Save className="w-3.5 h-3.5" /></button>
                        <button onClick={() => setEditingId(null)} className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 p-1"><X className="w-3.5 h-3.5" /></button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span className="neon-text-cyan font-semibold cyber-body truncate">{cls.name}</span>
                        {saved[cls.id] && <Check className="w-3.5 h-3.5 text-green-400 flex-shrink-0" />}
                      </div>
                    )}
                  </td>
                  <td className="text-center">
                    <span className="cyber-mono text-sm text-cyan-300">{cls.studentCount}</span>
                  </td>
                  <td>
                    <input type="text" value={waliMap[cls.id] || ''} onChange={e => setWaliMap(prev => ({ ...prev, [cls.id]: e.target.value }))} className="neon-input w-full px-3 py-2 rounded-lg" placeholder="Masukkan nama wali kelas..." />
                  </td>
                  <td>
                    <div className="flex items-center gap-1">
                      <button onClick={() => handleSaveWali(cls.id)} disabled={saving[`wk-${cls.id}`]} className={`neon-btn-green px-2.5 py-1.5 rounded-lg text-[10px] flex items-center gap-1 ${saving[`wk-${cls.id}`] ? 'opacity-50' : ''}`}>
                        {saved[`wk-${cls.id}`] ? <><Check className="w-3 h-3" /> OK</> : <><Save className="w-3 h-3" /> WK</>}
                      </button>
                      <button onClick={() => startEdit(cls)} className="sl-icon-btn border-[var(--sl-border)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)]" title="Ubah nama"><Pencil className="w-3.5 h-3.5" /></button>
                      <button onClick={() => confirmDelete(cls)} className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 hover:bg-red-400/15" title="Hapus"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}
"},{"path":"src/components/app/SyncNotification.tsx","content":"'use client';

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  RefreshCw, CloudUpload, CloudDownload, Database, AlertTriangle,
  CheckCircle, XCircle, Loader2, X,
} from 'lucide-react';

interface SyncState {
  currentOperation: string | null;
  startedAt: string | null;
  label: string;
  progress: { current: number; total: number; percentage: number; label: string } | null;
  isRunning: boolean;
  lastResults: Record<string, { success: boolean; message: string; timestamp: string }>;
}

const OP_ICONS: Record<string, any> = {
  'auto-sync': CloudUpload,
  'sync': CloudUpload,
  'pull-diff': CloudDownload,
  'pull-full': CloudDownload,
  'restore-local': Database,
  // G-Sheet pull shown (user needs to know when data fetched from G-Sheet)
  'gsheet-pull': CloudDownload,
  // G-Sheet sync hidden (push happens silently)
};

const OP_LABELS: Record<string, string> = {
  'auto-sync': 'Auto-Sync',
  'sync': 'Sync ke GitHub',
  'pull-diff': 'Pull Diff',
  'pull-full': 'Pull Full',
  'restore-local': 'Restore Lokal',
  'gsheet-pull': 'G-Sheet Pull',
};

// Operations that are HIDDEN from the notification system.
// G-Sheet sync/pull happens in the background — user doesn't need to see it.
// G-Sheet sync is hidden (push happens silently in background)
// G-Sheet PULL is shown (user needs to know when data is fetched from G-Sheet on server reset)
const HIDDEN_OPS = new Set(['gsheet-sync']);

/**
 * Custom success/fail toast titles for specific operations.
 * Falls back to the standard `${opLabel} berhasil/gagal` pattern when not set.
 */
const OP_CUSTOM_MESSAGES: Record<string, { success: string; fail: string }> = {
  'gsheet-sync': { success: 'Data tersinkron ke G-Sheet', fail: 'Gagal sync G-Sheet' },
  'gsheet-pull': { success: 'Data diambil dari G-Sheet', fail: 'Gagal pull dari G-Sheet' },
};

/**
 * Custom running banner color themes for specific operations.
 * Falls back to default cyan theme when not set.
 * Each theme is a complete set of Tailwind class strings (no composition)
 * to avoid Tailwind purge issues.
 */
const OP_RUNNING_THEME: Record<string, {
  card: string;
  icon: string;
  text: string;
  bar: string;
  percentText: string;
}> = {
  'gsheet-sync': {
    card: 'neon-card rounded-xl p-3 sm:p-4 border border-green-400/40 bg-[var(--sl-surface)]/95 backdrop-blur-md shadow-lg shadow-green-500/10',
    icon: 'w-5 h-5 animate-spin text-green-400 flex-shrink-0',
    text: 'cyber-mono text-xs sm:text-sm text-green-300 font-bold truncate',
    bar: 'h-full bg-gradient-to-r from-green-500 to-emerald-500',
    percentText: 'cyber-mono text-[10px] text-green-300 font-bold flex-shrink-0',
  },
  'gsheet-pull': {
    card: 'neon-card rounded-xl p-3 sm:p-4 border border-blue-400/40 bg-[var(--sl-surface)]/95 backdrop-blur-md shadow-lg shadow-blue-500/10',
    icon: 'w-5 h-5 animate-spin text-blue-400 flex-shrink-0',
    text: 'cyber-mono text-xs sm:text-sm text-blue-300 font-bold truncate',
    bar: 'h-full bg-gradient-to-r from-blue-500 to-cyan-500',
    percentText: 'cyber-mono text-[10px] text-blue-300 font-bold flex-shrink-0',
  },
};

const DEFAULT_RUNNING_THEME = {
  card: 'neon-card rounded-xl p-3 sm:p-4 border border-cyan-400/40 bg-[var(--sl-surface)]/95 backdrop-blur-md shadow-lg shadow-cyan-500/10',
  icon: 'w-5 h-5 animate-spin neon-text-cyan flex-shrink-0',
  text: 'cyber-mono text-xs sm:text-sm text-cyan-300 font-bold truncate',
  bar: 'h-full bg-gradient-to-r from-cyan-500 to-fuchsia-500',
  percentText: 'cyber-mono text-[10px] neon-text-cyan font-bold flex-shrink-0',
};

export function SyncNotification() {
  const [state, setState] = useState<SyncState | null>(null);
  const [lastOp, setLastOp] = useState<string | null>(null);
  const [lastResultShown, setLastResultShown] = useState<string | null>(null);
  const [showBanner, setShowBanner] = useState(false);
  const [toast, setToast] = useState<{ type: 'info' | 'success' | 'error' | 'warning'; title: string; message: string } | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    const poll = async () => {
      try {
        const res = await fetch('/api/sync-status', { cache: 'no-store' });
        if (!res.ok) return;
        const data: SyncState = await res.json();
        setState(data);

        // Detect operation STARTED
        // SKIP hidden operations (G-Sheet sync/pull — not shown to user)
        if (data.currentOperation && data.currentOperation !== lastOp && !HIDDEN_OPS.has(data.currentOperation)) {
          setLastOp(data.currentOperation);
          setShowBanner(true);
          const label = OP_LABELS[data.currentOperation] || data.label;
          setToast({
            type: 'info',
            title: `${label} dimulai`,
            message: data.label || 'Operasi sedang berjalan...',
          });
        }

        // Detect operation COMPLETED (was running, now not)
        // SKIP hidden operations (G-Sheet sync/pull — not shown to user)
        if (!data.currentOperation && lastOp && !HIDDEN_OPS.has(lastOp)) {
          const result = data.lastResults?.[lastOp];
          const opLabel = OP_LABELS[lastOp] || lastOp;
          const customMsg = OP_CUSTOM_MESSAGES[lastOp];
          if (result && lastOp !== lastResultShown) {
            setLastResultShown(lastOp);
            // Only show toast for MANUAL operations, not auto-sync background failures
            // Auto-sync failures happen frequently (G-Sheet webhook down, rate limit, etc.)
            // and shouldn't bother the user with error toasts
            if (lastOp !== 'auto-sync' || result.success) {
              setToast({
                type: result.success ? 'success' : 'error',
                title: customMsg
                  ? (result.success ? customMsg.success : customMsg.fail)
                  : (result.success ? `${opLabel} berhasil` : `${opLabel} gagal`),
                message: result.message?.substring(0, 200) || '',
              });
            }
          }
          setLastOp(null);
          setShowBanner(false);
        }

        // Detect CONFLICT (operation rejected — not in currentOperation but lastResults shows failure)
        if (data.currentOperation === null && lastOp === null) {
          // Check for recent conflict in lastResults
          for (const [op, result] of Object.entries(data.lastResults || {})) {
            const ts = result.timestamp;
            if (ts && Date.now() - new Date(ts).getTime() < 5000 && op !== lastResultShown) {
              if (result.message?.includes('Operasi lain sedang berjalan')) {
                setLastResultShown(op);
                setToast({
                  type: 'warning',
                  title: 'Operasi diblokir',
                  message: `${OP_LABELS[op] || op} tidak bisa berjalan — operasi lain sedang aktif.`,
                });
              }
            }
          }
        }
      } catch {
        // Silent fail — don't spam console
      }
    };

    // Poll every 3 seconds
    poll();
    intervalRef.current = setInterval(poll, 3000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [lastOp, lastResultShown]);

  // Auto-dismiss toast after 8 seconds
  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 8000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  // Resolve running banner theme based on current operation
  const currentOp = state?.currentOperation ?? null;
  const runningTheme = currentOp ? (OP_RUNNING_THEME[currentOp] || DEFAULT_RUNNING_THEME) : DEFAULT_RUNNING_THEME;

  return (
    <>
      {/* Progress Banner (shown while operation is running) */}
      <AnimatePresence>
        {showBanner && currentOp && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] min-w-[300px] max-w-[90vw]"
          >
            <div className={runningTheme.card}>
              <div className="flex items-center gap-3">
                <Loader2 className={runningTheme.icon} />
                <div className="flex-1 min-w-0">
                  <p className={runningTheme.text}>
                    {state?.label || OP_LABELS[currentOp] || currentOp}
                  </p>
                  {state?.progress && (
                    <>
                      <div className="flex items-center justify-between gap-2 mt-1">
                        <span className="cyber-mono text-[10px] text-muted-foreground truncate">
                          {state.progress.label}
                        </span>
                        <span className={runningTheme.percentText}>
                          {state.progress.percentage}%
                        </span>
                      </div>
                      <div className="h-1 bg-[var(--sl-border)] rounded-full overflow-hidden mt-1">
                        <motion.div
                          className={runningTheme.bar}
                          animate={{ width: `${state.progress.percentage}%` }}
                          transition={{ duration: 0.3 }}
                        />
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Toast Notification (shown on completion/conflict) */}
      <AnimatePresence>
        {toast && !showBanner && (
          <motion.div
            initial={{ opacity: 0, x: 100 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 100 }}
            className="fixed top-4 right-4 z-[100] min-w-[280px] max-w-[90vw]"
          >
            <div className={`neon-card rounded-xl p-3 sm:p-4 backdrop-blur-md shadow-lg ${
              toast.type === 'success' ? 'border border-green-400/40 bg-green-500/10' :
              toast.type === 'error' ? 'border border-red-400/40 bg-red-500/10' :
              toast.type === 'warning' ? 'border border-yellow-400/40 bg-yellow-500/10' :
              'border border-cyan-400/40 bg-cyan-500/10'
            }`}>
              <div className="flex items-start gap-3">
                {toast.type === 'success' && <CheckCircle className="w-5 h-5 text-green-400 flex-shrink-0 mt-0.5" />}
                {toast.type === 'error' && <XCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />}
                {toast.type === 'warning' && <AlertTriangle className="w-5 h-5 text-yellow-400 flex-shrink-0 mt-0.5" />}
                {toast.type === 'info' && <RefreshCw className="w-5 h-5 text-cyan-400 flex-shrink-0 mt-0.5" />}
                <div className="flex-1 min-w-0">
                  <p className={`cyber-mono text-xs sm:text-sm font-bold ${
                    toast.type === 'success' ? 'text-green-300' :
                    toast.type === 'error' ? 'text-red-300' :
                    toast.type === 'warning' ? 'text-yellow-300' :
                    'text-cyan-300'
                  }`}>
                    {toast.title}
                  </p>
                  {toast.message && (
                    <p className="cyber-body text-[10px] sm:text-xs text-muted-foreground mt-1 break-words">
                      {toast.message}
                    </p>
                  )}
                </div>
                <button
                  onClick={() => setToast(null)}
                  className="text-muted-foreground hover:text-foreground flex-shrink-0"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
"},{"path":"src/components/app/ThemeToggle.tsx","content":"'use client';

import { useTheme } from 'next-themes';
import { Sun, Moon } from 'lucide-react';

export function ThemeToggle() {
  const { theme, setTheme, resolvedTheme } = useTheme();
  const isDark = resolvedTheme !== 'light';

  return (
    <button
      onClick={() => setTheme(isDark ? 'light' : 'dark')}
      className="sl-icon-btn border-[var(--sl-border)] text-[var(--sl-text-accent)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)]"
      title={isDark ? 'Tema Terang' : 'Tema Gelap'}
    >
      {isDark ? (
        <Sun className="w-4 h-4 sm:w-5 sm:h-5" />
      ) : (
        <Moon className="w-4 h-4 sm:w-5 sm:h-5" />
      )}
    </button>
  );
}
"},{"path":"src/components/app/VersiAplikasiView.tsx","content":"'use client';

import { useEffect, useState, useCallback } from 'react';
import {
  ShieldCheck, ShieldAlert, Loader2, CheckCircle, XCircle,
  RefreshCw, Users, CalendarOff, FileSpreadsheet, GitBranch,
  AlertTriangle, Database, Ban, Info,
} from 'lucide-react';
import { VersionStatus } from './VersionStatus';
import { BackupPemulihanPanel } from './BackupPemulihanPanel';

interface FeatureStatus {
  id: string;
  name: string;
  status: 'present' | 'missing' | 'unknown';
}
interface AppVersionInfo {
  version: string;
  versionCode: number;
  releasedAt: string;
  note: string;
  rollbackDetected: boolean;
  features: FeatureStatus[];
  missingFeatures: string[];
  checkedAt?: string;
}

interface DataIntegrity {
  studentCount?: number;
  holidayCount?: number;
  attendanceCount?: number;
  classCount?: number;
  excludedStudentCount?: number;
  lastAttendanceDate?: string | null;
  checkedAt?: string;
  error?: string;
}

const EXPECTED = {
  studentCount: 135,
  excludedStudentCount: 2,
  attendanceMin: 76000, // guard: anything well below 76k → data rollback
};

/**
 * VERSI APLIKASI VIEW
 *
 * Dedicated page that shows:
 *   1. The latest version banner (reuses <VersionStatus />) — exactly the
 *      "VERSI TERBARU AKTIF — DD MMMM YYYY … 8/8 fitur kunci terverifikasi"
 *      text the user requested.
 *   2. A detailed 8-feature checklist (each marker checked live against the
 *      source files via /api/app-version).
 *   3. Live DB data-integrity counts (students, holidays, attendance,
 *      blocklisted students) via /api/app-version/data-integrity.
 *   4. A rollback-protection explainer so the user understands WHY a rollback
 *      is immediately visible here.
 *
 * Old version history entries are intentionally NOT shown — per the user's
 * request, only the newest version is tracked.
 */
export function VersiAplikasiView() {
  const [info, setInfo] = useState<AppVersionInfo | null>(null);
  const [data, setData] = useState<DataIntegrity | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  // Shared fetch helper — returns parsed payloads (does NOT call setState
  // synchronously, so it's safe to invoke from both the mount effect and the
  // refresh button handler).
  const fetchAll = useCallback(async () => {
    const [vRes, dRes] = await Promise.all([
      fetch('/api/app-version', { cache: 'no-store' }),
      fetch('/api/app-version/data-integrity', { cache: 'no-store' }),
    ]);
    const vData = vRes.ok ? await vRes.json().catch(() => null) : null;
    const dData = dRes.ok ? await dRes.json().catch(() => null) : null;
    return { vData, dData };
  }, []);

  // Initial load on mount — setState happens inside the async continuation
  // (after await), not synchronously in the effect body.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { vData, dData } = await fetchAll();
        if (cancelled) return;
        if (vData) setInfo(vData);
        if (dData) setData(dData);
      } catch {
        // ignore — status cards show "tidak terbaca"
      }
      if (!cancelled) setLoading(false);
    })();
    return () => { cancelled = true; };
  }, [fetchAll]);

  // Manual refresh (button handler — setState here is fine, it's an event).
  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      const { vData, dData } = await fetchAll();
      if (vData) setInfo(vData);
      if (dData) setData(dData);
    } catch {
      // ignore
    }
    setRefreshing(false);
  }, [fetchAll]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-5 h-5 animate-spin text-cyan-400" />
        <span className="ml-2 cyber-mono text-xs text-muted-foreground">Memuat versi aplikasi...</span>
      </div>
    );
  }

  const presentCount = info?.features.filter(f => f.status === 'present').length ?? 0;
  const checkableCount = info?.features.filter(f => f.status !== 'unknown').length ?? 0;
  const dataRollbackSuspected =
    !!data &&
    (data.studentCount !== undefined && data.studentCount < EXPECTED.studentCount - 5) ||
    (data.excludedStudentCount !== undefined && data.excludedStudentCount < EXPECTED.excludedStudentCount) ||
    (data.attendanceCount !== undefined && data.attendanceCount < EXPECTED.attendanceMin);

  return (
    <div className="space-y-4 sm:space-y-5">
      {/* ===== HEADER ===== */}
      <div className="neon-card rounded-xl p-4 sm:p-5">
        <div className="flex items-center gap-2 mb-1.5">
          <GitBranch className="w-4 h-4 text-cyan-400 flex-shrink-0" />
          <h2 className="cyber-heading text-sm sm:text-base neon-text-cyan leading-none">VERSI APLIKASI</h2>
        </div>
        <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground leading-relaxed">
          Single source of truth untuk versi &amp; fitur aktif. Setiap fitur kunci ditandai marker unik di dalam berkas kode sumber — jika platform memulihkan working tree lama, marker hilang &amp; rollback langsung terdeteksi di sini.
        </p>
      </div>

      {/* ===== MAIN VERSION BANNER (the exact text the user wants) ===== */}
      <VersionStatus />

      {/* ===== REFRESH BUTTON ===== */}
      <div className="flex justify-end">
        <button
          onClick={() => handleRefresh()}
          disabled={refreshing}
          className="sl-icon-btn border-cyan-400/40 bg-cyan-400/5 text-cyan-300 hover:bg-cyan-400/15 px-3 py-1.5 text-[10px] gap-1.5 flex items-center rounded-lg transition-colors disabled:opacity-50"
          aria-label="Periksa ulang versi"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${refreshing ? 'animate-spin' : ''}`} />
          <span className="cyber-mono">Periksa ulang</span>
        </button>
      </div>

      {/* ===== DATA ROLLBACK WARNING (separate from code-marker rollback) ===== */}
      {dataRollbackSuspected && (
        <div className="rounded-xl p-3 border-2 border-amber-500/60 bg-amber-500/10 space-y-1.5" role="alert">
          <div className="flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-amber-400 flex-shrink-0" />
            <p className="cyber-subheading text-xs text-amber-400">DATA ROLLBACK TERDUGA</p>
          </div>
          <p className="cyber-mono text-[10px] text-amber-300/90 leading-relaxed">
            Jumlah siswa / record absensi / blocklist di bawah nilai yang diharapkan. Snapshot database mungkin telah dikembalikan ke versi lama.
          </p>
        </div>
      )}

      {/* ===== DETAILED FEATURE CHECKLIST ===== */}
      <div className="neon-card rounded-xl p-4 sm:p-5">
        <div className="flex items-center justify-between mb-3">
          <h3 className="cyber-subheading text-xs sm:text-sm neon-text-cyan">DAFTAR FITUR KUNCI</h3>
          <span className={`cyber-mono text-[10px] font-bold ${info?.rollbackDetected ? 'text-red-400' : 'text-green-400'}`}>
            {presentCount}/{checkableCount} terverifikasi
          </span>
        </div>
        <div className="space-y-1.5 max-h-[420px] overflow-y-auto sl-scroll">
          {info?.features.map(f => (
            <div
              key={f.id}
              className={`flex items-center gap-2 p-2 sm:p-2.5 rounded-lg border ${
                f.status === 'present'
                  ? 'border-green-400/30 bg-green-400/5'
                  : f.status === 'missing'
                    ? 'border-red-400/40 bg-red-400/10'
                    : 'border-yellow-400/30 bg-yellow-400/5'
              }`}
            >
              {f.status === 'present' ? (
                <CheckCircle className="w-4 h-4 text-green-400 flex-shrink-0" />
              ) : f.status === 'missing' ? (
                <XCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
              ) : (
                <AlertTriangle className="w-4 h-4 text-yellow-400 flex-shrink-0" />
              )}
              <span className="flex-1 cyber-body text-xs sm:text-sm break-words min-w-0">{f.name}</span>
              <span
                className={`cyber-mono text-[8px] sm:text-[9px] font-bold px-1.5 py-0.5 rounded flex-shrink-0 ${
                  f.status === 'present'
                    ? 'text-green-300 bg-green-400/10'
                    : f.status === 'missing'
                      ? 'text-red-300 bg-red-400/10'
                      : 'text-yellow-300 bg-yellow-400/10'
                }`}
              >
                {f.status === 'present' ? 'AKTIF' : f.status === 'missing' ? 'HILANG' : 'TIDAK DIKETAHUI'}
              </span>
            </div>
          ))}
          {!info && (
            <p className="cyber-mono text-[10px] text-muted-foreground text-center py-3">
              Tidak dapat memuat daftar fitur.
            </p>
          )}
        </div>
      </div>

      {/* ===== DATA INTEGRITY ===== */}
      <div className="neon-card rounded-xl p-4 sm:p-5">
        <div className="flex items-center gap-2 mb-3">
          <Database className="w-4 h-4 text-cyan-400 flex-shrink-0" />
          <h3 className="cyber-subheading text-xs sm:text-sm neon-text-cyan">INTEGRITAS DATA (LIVE DB)</h3>
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-2.5">
          <DataCard
            icon={Users}
            label="Siswa aktif"
            value={data?.studentCount}
            expected={EXPECTED.studentCount}
          />
          <DataCard
            icon={CalendarOff}
            label="Hari libur"
            value={data?.holidayCount}
          />
          <DataCard
            icon={FileSpreadsheet}
            label="Record absensi"
            value={data?.attendanceCount}
            expected={EXPECTED.attendanceMin}
            compareMode="min"
          />
          <DataCard
            icon={Ban}
            label="Siswa diblokkir"
            value={data?.excludedStudentCount}
            expected={EXPECTED.excludedStudentCount}
          />
        </div>
        {data?.lastAttendanceDate && (
          <p className="cyber-mono text-[9px] text-muted-foreground mt-3">
            Absensi terakhir di DB: <span className="text-cyan-300">{data.lastAttendanceDate}</span>
            {data.classCount !== undefined && <> · {data.classCount} kelas</>}
          </p>
        )}
        {data?.error && (
          <p className="cyber-mono text-[9px] text-red-400 mt-2">Error membaca DB: {data.error}</p>
        )}
      </div>

      {/* ===== BACKUP & PEMULIHAN (JSON + GITHUB) ===== */}
      <BackupPemulihanPanel onDataRestored={handleRefresh} />

      {/* ===== ROLLBACK PROTECTION EXPLAINER ===== */}
      <div className="neon-card rounded-xl p-4 sm:p-5">
        <div className="flex items-center gap-2 mb-2">
          <ShieldCheck className="w-4 h-4 text-green-400 flex-shrink-0" />
          <h3 className="cyber-subheading text-xs sm:text-sm neon-text-cyan">PROTEKSI ROLLBACK</h3>
        </div>
        <ul className="space-y-1.5 cyber-mono text-[10px] sm:text-xs text-muted-foreground leading-relaxed">
          <li className="flex gap-1.5"><ShieldCheck className="w-3 h-3 text-green-400 flex-shrink-0 mt-0.5" /><span>Setiap fitur kunci ditandai marker unik di dalam berkas kode sumber (bukan metadata).</span></li>
          <li className="flex gap-1.5"><ShieldCheck className="w-3 h-3 text-green-400 flex-shrink-0 mt-0.5" /><span><code className="text-cyan-300">/api/app-version</code> memeriksa marker langsung dari berkas saat runtime — bukan dari cache.</span></li>
          <li className="flex gap-1.5"><ShieldCheck className="w-3 h-3 text-green-400 flex-shrink-0 mt-0.5" /><span>Jika platform memulihkan working tree lama, marker hilang &rarr; rollbackDetected=true &rarr; banner merah muncul.</span></li>
          <li className="flex gap-1.5"><Ban className="w-3 h-3 text-fuchsia-400 flex-shrink-0 mt-0.5" /><span>Blocklist siswa 6 lapis mencegah siswa terhapus kembali via restore/import manapun.</span></li>
          <li className="flex gap-1.5"><Info className="w-3 h-3 text-cyan-400 flex-shrink-0 mt-0.5" /><span>Versi lama sengaja dihapus dari history — hanya versi terbaru yang ditampilkan.</span></li>
        </ul>
      </div>
    </div>
  );
}

/** Compact data card with optional expected-value comparison. */
function DataCard({
  icon: Icon,
  label,
  value,
  expected,
  compareMode = 'exact',
}: {
  icon: typeof Users;
  label: string;
  value?: number;
  expected?: number;
  compareMode?: 'exact' | 'min';
}) {
  const ok =
    value === undefined
      ? null
      : expected === undefined
        ? null
        : compareMode === 'min'
          ? value >= expected
          : value === expected;
  return (
    <div
      className={`p-2.5 sm:p-3 rounded-lg border ${
        ok === false
          ? 'border-red-400/40 bg-red-400/5'
          : ok === true
            ? 'border-green-400/30 bg-green-400/5'
            : 'border-[var(--sl-border)] bg-[var(--sl-surface)]'
      }`}
    >
      <div className="flex items-center gap-1.5 mb-1">
        <Icon className={`w-3.5 h-3.5 flex-shrink-0 ${ok === false ? 'text-red-400' : 'text-cyan-400'}`} />
        <span className="cyber-mono text-[8px] sm:text-[9px] text-muted-foreground truncate">{label}</span>
      </div>
      <p className={`cyber-heading text-base sm:text-lg font-bold leading-none ${ok === false ? 'text-red-400' : 'neon-text-cyan'}`}>
        {value === undefined ? '—' : value.toLocaleString('id-ID')}
      </p>
      {expected !== undefined && (
        <p className="cyber-mono text-[8px] text-muted-foreground mt-0.5">
          {compareMode === 'min' ? `min ` : ``}{expected.toLocaleString('id-ID')}
        </p>
      )}
    </div>
  );
}
"},{"path":"src/components/app/VersionStatus.tsx","content":"'use client';

import { useEffect, useState } from 'react';
import { ShieldCheck, ShieldAlert, Loader2 } from 'lucide-react';

interface FeatureStatus {
  id: string;
  name: string;
  status: 'present' | 'missing' | 'unknown';
}
interface AppVersionInfo {
  version: string;
  versionCode: number;
  releasedAt: string;
  note: string;
  rollbackDetected: boolean;
  features: FeatureStatus[];
  missingFeatures: string[];
}

/**
 * VERSION STATUS — shows ONLY the latest version (old versions removed).
 *
 * Fetches /api/app-version which checks critical feature markers inside the
 * live source files. If a rollback happened (platform restored an older
 * working tree), the newest features disappear from the code and a prominent
 * RED warning banner appears — making rollbacks immediately visible to the
 * user instead of silently losing features.
 */
export function VersionStatus() {
  const [info, setInfo] = useState<AppVersionInfo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch('/api/app-version', { cache: 'no-store' });
        if (res.ok) {
          const data = await res.json();
          if (!cancelled) setInfo(data);
        }
      } catch {
        // ignore — badge stays hidden
      }
      if (!cancelled) setLoading(false);
    };
    load();
    return () => { cancelled = true; };
  }, []);

  if (loading) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 rounded-lg border border-cyan-400/20 bg-cyan-400/5">
        <Loader2 className="w-3.5 h-3.5 animate-spin text-cyan-400" />
        <span className="cyber-mono text-[10px] text-muted-foreground">Memeriksa versi...</span>
      </div>
    );
  }

  if (!info) return null;

  // ===== ROLLBACK DETECTED — loud warning =====
  if (info.rollbackDetected) {
    return (
      <div className="rounded-xl p-3 border-2 border-red-500/60 bg-red-500/10 space-y-2" role="alert">
        <div className="flex items-center gap-2">
          <ShieldAlert className="w-4 h-4 text-red-400 flex-shrink-0" />
          <p className="cyber-subheading text-xs text-red-400">ROLLBACK TERDETEKSI — FITUR TERBARU HILANG DARI KODE</p>
        </div>
        <p className="cyber-mono text-[10px] text-red-300/90 leading-relaxed">
          Versi seharusnya: <span className="text-red-300 font-bold">{info.version}</span> — namun fitur berikut tidak ditemukan dalam kode yang berjalan:
        </p>
        <ul className="cyber-mono text-[10px] text-red-300/80 list-disc pl-4 space-y-0.5">
          {info.missingFeatures.map(name => <li key={name}>{name}</li>)}
        </ul>
        <p className="cyber-mono text-[10px] text-red-300/70 italic">
          Sistem ter-rollback ke versi lama. Minta asisten AI untuk memulihkan fitur terbaru.
        </p>
      </div>
    );
  }

  // ===== OK — compact green badge =====
  const presentCount = info.features.filter(f => f.status === 'present').length;
  return (
    <div className="rounded-xl p-3 border border-green-400/40 bg-green-400/5 space-y-1.5">
      <div className="flex items-center gap-2">
        <ShieldCheck className="w-4 h-4 text-green-400 flex-shrink-0" />
        <p className="cyber-subheading text-xs text-green-400">
          VERSI TERBARU AKTIF — {info.version}
        </p>
      </div>
      <p className="cyber-mono text-[10px] text-muted-foreground leading-relaxed">
        {info.note}
      </p>
      <p className="cyber-mono text-[9px] text-green-300/70">
        {presentCount}/{info.features.filter(f => f.status !== 'unknown').length} fitur kunci terverifikasi di kode yang berjalan
      </p>
    </div>
  );
}
"},{"path":"src/components/app/WaliKelasView.tsx","content":"'use client';

import { useState } from 'react';
import { motion } from 'framer-motion';
import { Save, Check, ScrollText } from 'lucide-react';
import { ClassData } from './types';

interface WaliKelasViewProps {
  classes: ClassData[];
  onRefresh: () => void;
}

export function WaliKelasView({ classes, onRefresh }: WaliKelasViewProps) {
  const [waliKelasMap, setWaliKelasMap] = useState<Record<string, string>>(() => {
    const map: Record<string, string> = {};
    classes.forEach(c => {
      map[c.id] = c.waliKelasName || '';
    });
    return map;
  });
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState<Record<string, boolean>>({});
  const [showHolidayManager, setShowHolidayManager] = useState(false);

  const handleSave = async (classId: string) => {
    setSaving(prev => ({ ...prev, [classId]: true }));
    try {
      await fetch('/api/wali-kelas', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ classId, name: waliKelasMap[classId] }),
      });
      setSaved(prev => ({ ...prev, [classId]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [classId]: false })), 2000);
      onRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      setSaving(prev => ({ ...prev, [classId]: false }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
        <div>
          <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">WALI KELAS</h2>
          <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1">MANAJEMEN DATA WALI KELAS</p>
        </div>
      </div>

      {/* Mobile: Card layout */}
      <div className="sm:hidden space-y-2">
        {classes.map((cls, idx) => (
          <motion.div
            key={cls.id}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05 }}
            className="neon-card rounded-lg p-3"
          >
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2 min-w-0">
                <span className="cyber-mono text-[10px] text-muted-foreground w-5 text-right flex-shrink-0">{idx + 1}</span>
                <span className="cyber-heading text-sm neon-text-cyan truncate">{cls.name}</span>
              </div>
            </div>
            <div className="space-y-2">
              <input
                type="text"
                value={waliKelasMap[cls.id] || ''}
                onChange={(e) => setWaliKelasMap(prev => ({ ...prev, [cls.id]: e.target.value }))}
                className="neon-input w-full px-2.5 py-1.5 rounded-lg text-xs"
                placeholder="Nama wali kelas..."
              />
              <button
                onClick={() => handleSave(cls.id)}
                disabled={saving[cls.id]}
                className={`neon-btn-green w-full px-3 py-1.5 rounded-lg text-[11px] flex items-center justify-center gap-1.5 ${saving[cls.id] ? 'opacity-50' : ''}`}
              >
                {saved[cls.id] ? (
                  <><Check className="w-3 h-3" /> Tersimpan</>
                ) : (
                  <><Save className="w-3 h-3" /> Simpan</>
                )}
              </button>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Desktop: Table layout */}
      <div className="hidden sm:block neon-card rounded-xl overflow-hidden">
        <div className="p-3 sm:p-4 border-b border-fuchsia-400/20 bg-fuchsia-400/5">
          <div className="flex items-center gap-2">
            <ScrollText className="w-4 h-4 sm:w-5 sm:h-5 neon-text-magenta" />
            <h3 className="cyber-subheading text-[10px] sm:text-sm neon-text-magenta">DATA WALI KELAS</h3>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="neon-table">
            <thead>
              <tr>
                <th className="w-16">NO</th>
                <th className="w-28">KELAS</th>
                <th>NAMA WALI KELAS</th>
                <th className="w-32">AKSI</th>
              </tr>
            </thead>
            <tbody>
              {classes.map((cls, idx) => (
                <motion.tr
                  key={cls.id}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: idx * 0.05 }}
                >
                  <td className="text-center cyber-mono">{idx + 1}</td>
                  <td className="neon-text-cyan font-semibold cyber-body">{cls.name}</td>
                  <td>
                    <input
                      type="text"
                      value={waliKelasMap[cls.id] || ''}
                      onChange={(e) => setWaliKelasMap(prev => ({ ...prev, [cls.id]: e.target.value }))}
                      className="neon-input w-full px-3 py-2 rounded-lg"
                      placeholder="Masukkan nama wali kelas..."
                    />
                  </td>
                  <td>
                    <button
                      onClick={() => handleSave(cls.id)}
                      disabled={saving[cls.id]}
                      className={`neon-btn-green px-4 py-2 rounded-lg text-xs flex items-center justify-center gap-1.5 ${saving[cls.id] ? 'opacity-50' : ''}`}
                    >
                      {saved[cls.id] ? (
                        <><Check className="w-3.5 h-3.5" /> Tersimpan</>
                      ) : (
                        <><Save className="w-3.5 h-3.5" /> Simpan</>
                      )}
                    </button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
