const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}
"},{"path":"src/hooks/use-toast.ts","content":""use client"

// Inspired by react-hot-toast library
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
    type: ActionType["ADD_TOAST"]
    toast: ToasterToast
  }
  | {
    type: ActionType["UPDATE_TOAST"]
    toast: Partial<ToasterToast>
  }
  | {
    type: ActionType["DISMISS_TOAST"]
    toastId?: ToasterToast["id"]
  }
  | {
    type: ActionType["REMOVE_TOAST"]
    toastId?: ToasterToast["id"]
  }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
              ...t,
              open: false,
            }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }"},{"path":"src/instrumentation.ts","content":"/**
 * Next.js Instrumentation — runs ONCE when the server starts, before any
 * request is handled.
 *
 * This file is compiled for BOTH edge and nodejs runtimes by Turbopack.
 * To avoid Edge Runtime warnings, it contains NO Node.js-specific APIs
 * (no fs, no setImmediate, no setInterval). All such logic lives in
 * src/lib/instrumentation-node.ts and is dynamically imported at runtime.
 *
 * GUARD EXPLANATION:
 * We only SKIP in Edge Runtime (NEXT_RUNTIME === 'edge'). In all other cases
 * (nodejs dev, nodejs prod, standalone production server), we proceed.
 * Previously used `!== 'nodejs'` which would skip instrumentation entirely
 * if NEXT_RUNTIME was undefined in standalone mode — causing auto-restore,
 * periodic checks, and auto-sync to NOT run in production.
 *
 * Data protection system (Node.js runtime only):
 * 1. Auto-restore from local backup (if DB is empty)
 * 2. Periodic backup + reset detection every 2 minutes
 * 3. Reset detection: if attendance drops or 0% completeness after 07:30 WIB → pull from GitHub
 * 4. Online JSON backup (GitHub) — auto-sync + auto-restore on reset detection
 *
 * NOTE: Auto-sync and auto-pull are DISABLED in preview chat environments
 * to prevent GitHub API rate limits and data conflicts.
 */

export async function register() {
  // CRITICAL: Only skip in Edge Runtime. In Node.js (dev, prod, standalone),
  // always proceed so instrumentation (auto-restore, periodic checks, auto-sync) runs.
  // This file has NO fs/setImmediate/setInterval — only a dynamic import — so
  // Turbopack will NOT flag it for Edge Runtime.
  if (process.env.NEXT_RUNTIME === 'edge') {
    return;
  }

  console.log('[Instrumentation] Server started. (runtime=' + (process.env.NEXT_RUNTIME || 'standalone') + ')');

  // Dynamically import Node.js-only logic so Turbopack does not statically
  // analyze fs/setImmediate/setInterval as part of this Edge-compiled file.
  try {
    const { startInstrumentationNode } = await import('./lib/instrumentation-node');
    await startInstrumentationNode();
  } catch (e) {
    console.warn('[Instrumentation] Failed to start Node.js instrumentation:', e);
  }
}
"},{"path":"src/lib/app-version.ts","content":"/**
 * APP VERSION REGISTRY — single source of truth (HANYA VERSI TERBARU)
 *
 * Per user request: "hapus versi lama dan hanya tampilkan history version
 * dari yang terbaru" — old version entries are REMOVED. Only the newest
 * version is recorded here. When features are added/changed, UPDATE this
 * record (do not append history entries).
 *
 * ROLLBACK PROTECTION:
 * /api/app-version checks each FEATURE_MARKERS entry against the actual
 * source files at runtime. If the deployed code no longer contains a marker
 * (e.g., a platform rollback restored an older working tree), the API reports
 * rollbackDetected=true and the UI shows a warning banner — so a rollback is
 * immediately VISIBLE instead of silently losing features.
 *
 * GIT NOTE (root-cause fix for the rollback problem):
 * The platform "Version history" panel is driven by GIT COMMITS. Work that
 * is not committed never appears in the panel, and the platform may restore
 * the working tree to the last commit — wiping uncommitted features.
 * ALWAYS commit after finishing a feature session.
 */

export interface FeatureMarker {
  id: string;
  name: string;
  file: string;
  /** Substring that must exist in the file for the feature to be considered present. */
  pattern: string;
}

export const APP_VERSION = {
  version: '17 November 2026',
  versionCode: 20261117,
  releasedAt: '2026-11-17',
  note: 'Backup Kode Aplikasi (chunk khusus code-backup/) + Ahad hari efektif rekap bulanan (libur mingguan Jumat)',
  // Old versions intentionally removed — only the latest version is tracked.
  previousVersions: [] as { version: string; versionCode: number }[],
};

export const FEATURE_MARKERS: FeatureMarker[] = [
  { id: 'isi-cepat', name: 'ISI CEPAT (isi absensi tap-and-drop)', file: 'src/components/app/IsiAbsensiTab.tsx', pattern: 'ISI CEPAT ABSENSI' },
  { id: 'isi-cepat-calendar', name: 'Popup kalender langsung pada ISI CEPAT', file: 'src/components/app/IsiAbsensiTab.tsx', pattern: 'showQuickCalendar' },
  { id: 'rekap-guru-ui', name: 'REKAP GURU Per Bulan / Per Rentang', file: 'src/components/app/CheckAbsensiView.tsx', pattern: 'Per Rentang' },
  { id: 'rekap-guru-groupby', name: 'REKAP GURU kelompok Per Guru', file: 'src/components/app/CheckAbsensiView.tsx', pattern: 'value="teacher"' },
