"},{"path":"src/lib/apps-script-v6.ts","content":"export const APPS_SCRIPT_V6 = [
  '// Apps Script v7.0 - Chunked Storage (NO MERGE, NO CORRUPTION)',
  '// Each sync chunk is stored as a separate row in _CHUNKS_ sheet.',
  '// doGet?action=restore → returns chunk 0 (meta) + totalChunks',
  '// doGet?action=restore&chunk=N → returns chunk N',
  '// This eliminates the O(n²) merge problem that caused data corruption.',
  '',
  'const CHUNKS_SHEET = "_CHUNKS_";',
  'const DATA_SHEET = "_DATA_";',
  'const BACKUP_SHEET = "_BACKUP_";',
  'const INFO_SHEET = "_INFO_";',
  'const SUB_CHUNK_SIZE = 40000; // Google Sheets cell limit is 50,000 chars — stay safe at 40K',
  '',
  'function doPost(e) {',
  '  try {',
  '    var payload = JSON.parse(e.postData.contents);',
  '    var ss = SpreadsheetApp.getActiveSpreadsheet();',
  '    var chunkInfo = payload.chunk || {};',
  '    var index = chunkInfo.index !== undefined ? chunkInfo.index : 0;',
  '    var total = chunkInfo.total !== undefined ? chunkInfo.total : 1;',
  '    var type = chunkInfo.type || "data";',
  '',
  '    // Get or create _CHUNKS_ sheet',
  '    var chunksSheet = ss.getSheetByName(CHUNKS_SHEET);',
  '    if (!chunksSheet) {',
  '      chunksSheet = ss.insertSheet(CHUNKS_SHEET);',
  '    }',
  '',
  '    // If this is chunk 0 (meta/first chunk), clear the sheet for a fresh sync',
  '    if (index === 0) {',
  '      chunksSheet.clearContents();',
  '    }',
  '',
  '    // Serialize the chunk to JSON',
  '    var chunkJson = JSON.stringify(payload);',
  '',
  '    // Split into sub-chunks to avoid the 50,000 char per-cell limit',
  '    // Each sub-chunk is stored in a separate COLUMN of the same ROW',
  '    var subChunks = [];',
  '    for (var i = 0; i < chunkJson.length; i += SUB_CHUNK_SIZE) {',
  '      subChunks.push(chunkJson.substring(i, i + SUB_CHUNK_SIZE));',
  '    }',
  '',
  '    // Write all sub-chunks to row (index + 1), one per column',
  '    // Use setValues() to write the entire row at once',
  '    var rowValues = [];',
  '    for (var sc = 0; sc < subChunks.length; sc++) {',
  '      rowValues.push(subChunks[sc]);',
  '    }',
  '    chunksSheet.getRange(index + 1, 1, 1, subChunks.length).setValues([rowValues]);',
  '',
  '    // Save metadata to ScriptProperties',
  '    ScriptProperties.setProperty("backup_version", "v7.0");',
  '    ScriptProperties.setProperty("backup_lastUpdate", new Date().toISOString());',
  '    ScriptProperties.setProperty("backup_totalChunks", total.toString());',
  '    ScriptProperties.setProperty("backup_storage", "chunks");',
  '',
  '    // If this is the meta chunk (chunk 0), save summary metadata',
  '    if (index === 0) {',
  '      var d = payload.data || {};',
  '      var classes = d.classes ? d.classes.length : 0;',
  '      var students = d.students ? d.students.length : 0;',
  '      ScriptProperties.setProperty("backup_exportedAt", payload.exportedAt || new Date().toISOString());',
  '      ScriptProperties.setProperty("backup_classes", classes.toString());',
  '      ScriptProperties.setProperty("backup_students", students.toString());',
  '    }',
  '',
  '    // If this is an attendance chunk, record it',
  '    if (type === "attendance") {',
  '      ScriptProperties.setProperty("backup_attendance_chunks", total.toString());',
  '    }',
  '',
  '    return ContentService.createTextOutput(JSON.stringify({',
  '      status: "ok", version: "7.0", storage: "chunks",',
  '      chunk: { index: index, total: total, type: type },',
  '      subChunks: subChunks.length, size: chunkJson.length',
  '    })).setMimeType(ContentService.MimeType.JSON);',
  '',
  '  } catch(err) {',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "error", message: err.toString()})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '}',
  '',
  'function doGet(e) {',
  '  try {',
  '    var action = (e && e.parameter && e.parameter.action) ? e.parameter.action : "";',
  '    var ss = SpreadsheetApp.getActiveSpreadsheet();',
  '',
  '    if (action === "restore") {',
  '      return doRestore(ss, e);',
  '    }',
  '    if (action === "check") {',
  '      return doCheck(ss);',
  '    }',
  '',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "ready", version: "7.0"})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '',
  '  } catch(ex) {',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "error", message: ex.toString()})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '}',
  '',
  'function doRestore(ss, e) {',
  '  var chunksSheet = ss.getSheetByName(CHUNKS_SHEET);',
  '',
  '  // --- NEW FORMAT: _CHUNKS_ sheet exists ---',
  '  if (chunksSheet) {',
  '    var lastRow = chunksSheet.getLastRow();',
  '    if (lastRow < 1) {',
  '      return ContentService.createTextOutput(',
  '        JSON.stringify({status: "error", error: "Sheet _CHUNKS_ kosong. Lakukan SYNC dulu."})',
  '      ).setMimeType(ContentService.MimeType.JSON);',
  '    }',
  '',
  '    var totalChunks = parseInt(ScriptProperties.getProperty("backup_totalChunks") || lastRow);',
  '',
  '    // Helper: read all columns for a given row and concatenate (handles sub-chunks)',
  '    function readChunkRow(rowIdx) {',
  '      var lastCol = chunksSheet.getLastColumn();',
  '      if (lastCol < 1) return "";',
  '      var values = chunksSheet.getRange(rowIdx, 1, 1, lastCol).getValues()[0];',
  '      var json = "";',
  '      for (var c = 0; c < values.length; c++) {',
  '        if (values[c]) json += values[c];',
  '      }',
  '      return json;',
  '    }',
  '',
  '    // If chunk param is given, return that specific chunk',
  '    if (e && e.parameter && e.parameter.chunk !== undefined && e.parameter.chunk !== "") {',
  '      var chunkIdx = parseInt(e.parameter.chunk);',
  '      var row = chunkIdx + 1;',
  '      if (row > lastRow) {',
  '        return ContentService.createTextOutput(',
  '          JSON.stringify({status: "error", error: "Chunk " + chunkIdx + " tidak ada. Total: " + lastRow})',
  '        ).setMimeType(ContentService.MimeType.JSON);',
  '      }',
  '      var chunkJson = readChunkRow(row);',
  '      if (!chunkJson || chunkJson.trim() === "") {',
  '        return ContentService.createTextOutput(',
  '          JSON.stringify({status: "error", error: "Chunk " + chunkIdx + " kosong."})',
  '        ).setMimeType(ContentService.MimeType.JSON);',
  '      }',
  '      // Return the chunk JSON directly',
  '      return ContentService.createTextOutput(chunkJson).setMimeType(ContentService.MimeType.JSON);',
  '    }',
  '',
  '    // No chunk param: return the first chunk (meta) + totalChunks info',
  '    var firstChunkJson = readChunkRow(1);',
  '    if (!firstChunkJson || firstChunkJson.trim() === "") {',
  '      return ContentService.createTextOutput(',
  '        JSON.stringify({status: "error", error: "Chunk 0 (meta) kosong. Meta chunk gagal tersimpan. Lakukan SYNC ulang."})',
  '      ).setMimeType(ContentService.MimeType.JSON);',
  '    }',
  '    var firstChunk = JSON.parse(firstChunkJson);',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({',
  '        status: "ok",',
  '        backup: firstChunk,',
  '        totalChunks: totalChunks,',
  '        chunksStored: lastRow',
  '      })',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '',
  '  // --- OLD FORMAT FALLBACK: _DATA_ sheet (merged data from v6) ---',
  '  var dataSheet = ss.getSheetByName(DATA_SHEET);',
  '  if (!dataSheet) {',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "error", error: "Tidak ada sheet _CHUNKS_ atau _DATA_. Lakukan SYNC dulu."})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '',
  '  var lastRowData = dataSheet.getLastRow();',
  '  if (lastRowData < 1) {',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "error", error: "Sheet _DATA_ kosong. Lakukan SYNC dulu."})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '',
  '  var jsonStr = "";',
  '  for (var i = 1; i <= lastRowData; i++) {',
  '    jsonStr += dataSheet.getRange(i, 1).getValue();',
  '  }',
  '',
  '  try {',
  '    var backup = JSON.parse(jsonStr);',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "ok", backup: backup, totalChunks: 1})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  } catch(parseErr) {',
  '    return ContentService.createTextOutput(',
  '      JSON.stringify({status: "error", error: "Gagal parse data lama: " + parseErr.toString() + ". Lakukan SYNC ulang dengan Apps Script v7."})',
  '    ).setMimeType(ContentService.MimeType.JSON);',
  '  }',
  '}',
  '',
  'function doCheck(ss) {',
  '  var version = ScriptProperties.getProperty("backup_version") || "";',
  '  var exportedAt = ScriptProperties.getProperty("backup_exportedAt") || ScriptProperties.getProperty("backup_lastUpdate") || "";',
  '  var classes = ScriptProperties.getProperty("backup_classes") || "0";',
  '  var students = ScriptProperties.getProperty("backup_students") || "0";',
  '  var totalChunks = ScriptProperties.getProperty("backup_totalChunks") || "0";',
  '  var storage = ScriptProperties.getProperty("backup_storage") || "unknown";',
  '',
  '  var hasBackup = parseInt(totalChunks) > 0;',
  '  var chunksSheet = ss.getSheetByName(CHUNKS_SHEET);',
  '  if (chunksSheet) {',
  '    var stored = chunksSheet.getLastRow();',
  '    hasBackup = hasBackup && stored > 0;',
  '  } else {',
  '    hasBackup = false;',
  '  }',
  '',
  '  return ContentService.createTextOutput(',
  '    JSON.stringify({',
  '      status: "ok", hasBackup: hasBackup, version: version,',
  '      exportedAt: exportedAt,',
  '      classes: parseInt(classes), students: parseInt(students),',
  '      totalChunks: parseInt(totalChunks),',
  '      chunksStored: chunksSheet ? chunksSheet.getLastRow() : 0,',
  '      storage: storage',
  '    })',
  '  ).setMimeType(ContentService.MimeType.JSON);',
  '}',
  '',
  'function buildReadableSheetsSafe(ss, data) {',
  '  try { buildReadableSheets(ss, data); } catch(e) { Logger.log("Readable sheets skipped: " + e); }',
  '}',
  '',
  'function buildReadableSheets(ss, data) {',
  '  var protectedNames = [CHUNKS_SHEET, DATA_SHEET, BACKUP_SHEET, INFO_SHEET];',
  '  var sheets = ss.getSheets();',
  '  for (var i = sheets.length - 1; i >= 0; i--) {',
  '    var name = sheets[i].getName();',
  '    var isProtected = false;',
  '    for (var p = 0; p < protectedNames.length; p++) {',
  '      if (name === protectedNames[p]) { isProtected = true; break; }',
  '    }',
  '    if (!isProtected) { ss.deleteSheet(sheets[i]); }',
  '  }',
  '',
  '  var classes = data.classes || [];',
  '  var students = data.students || [];',
  '  var waliKelas = data.waliKelas || [];',
  '',
  '  var studentsByClass = {};',
  '  var waliByClass = {};',
  '',
  '  for (var s = 0; s < students.length; s++) {',
  '    var st = students[s];',
  '    if (!studentsByClass[st.classId]) studentsByClass[st.classId] = [];',
  '    studentsByClass[st.classId].push(st);',
  '  }',
  '',
  '  for (var w = 0; w < waliKelas.length; w++) {',
  '    waliByClass[waliKelas[w].classId] = waliKelas[w].name;',
  '  }',
  '',
  '  for (var c = 0; c < classes.length; c++) {',
  '    var cls = classes[c];',
  '    var sheet = ss.insertSheet(cls.name);',
  '    var clsStudents = studentsByClass[cls.id] || [];',
  '    var waliName = waliByClass[cls.id] || "-";',
  '',
  '    sheet.getRange(1, 1, 1, 5).setValues([["No", "Nama Siswa", "NISN", "Gender", "WhatsApp"]]);',
  '    sheet.getRange(1, 1, 1, 5).setFontWeight("bold").setBackground("#1a1a3e").setFontColor("#00f0ff");',
  '',
  '    var row = 2;',
  '    for (var si = 0; si < clsStudents.length; si++) {',
  '      var stu = clsStudents[si];',
  '      sheet.getRange(row, 1, 1, 5).setValues([[',
  '        si + 1, stu.name, stu.nisn || "", stu.gender || "", stu.whatsapp || ""',
  '      ]]);',
  '      row++;',
  '    }',
  '',
  '    sheet.getRange(row + 1, 1, 1, 2).setValues([["Wali Kelas:", waliName]]);',
  '    sheet.getRange(row + 1, 1, 1, 2).setFontWeight("bold");',
  '',
  '    for (var col = 1; col <= 5; col++) {',
  '      sheet.autoResizeColumn(col);',
  '    }',
  '  }',
  '}',
].join("\n");
"},{"path":"src/lib/auto-sync.ts","content":"// Auto-sync debouncer: triggers GitHub sync (attendance) + Google Sheets sync (non-attendance)
// after any user-initiated DB mutation (save button click, max hour click, etc.)
// Uses debounce to avoid excessive syncs during rapid operations
// Uses skip flag to prevent sync during restore operations (pull-diff/auto-restore)
// Production ONLY — both GitHub and G-Sheet sync are disabled in sandbox/dev.
// Non-blocking: runs via setImmediate, never blocks HTTP responses
//
// SYNC DIRECTION:
//   - GitHub: auto-push NEW attendance records (production → GitHub)
//   - G-Sheet: push ONLY when user changes non-attendance data (teachers, students, schedules, etc.)
//   - G-Sheet: auto-PULL on server reset (G-Sheet → production, BEFORE GitHub pull-diff)
//   - G-Sheet push is SKIPPED when:
//     1. No non-attendance data changed (dirty flag not set)
//     2. Server reset in progress (_skipSync = true)
//     3. GitHub attendance count > local DB count (server reset detected)
//     4. Not production environment

let syncTimer: ReturnType<typeof setTimeout> | null = null;
let gsheetTimer: ReturnType<typeof setTimeout> | null = null;
let _skipSync = false;
let _lastSyncTime = 0;
let _lastGSheetSyncTime = 0;
let _gsheetDirty = false; // true = non-attendance data changed, needs G-Sheet push
const MIN_SYNC_INTERVAL = 60000; // Minimum 60 seconds between GitHub auto-syncs
const MIN_GSHEET_SYNC_INTERVAL = 10000; // Minimum 10 seconds between G-Sheet pushes

/**
 * Check if we're in production environment.
 */
export function isProductionEnv(): boolean {
  const nodeEnv = process.env.NODE_ENV || '';
  const selfUrl = process.env.AUTORESTORE_SELF_URL || '';
  return (nodeEnv === 'production') ||
    (selfUrl.includes('mtss-alishlah-absensi') && !selfUrl.includes('preview-chat'));
}

/**
 * Set whether auto-sync should be skipped (e.g., during restore/pull)
 */
export function setSkipAutoSync(skip: boolean) {
  _skipSync = skip;
  if (skip) {
    if (syncTimer) { clearTimeout(syncTimer); syncTimer = null; }
    if (gsheetTimer) { clearTimeout(gsheetTimer); gsheetTimer = null; }
  }
}

/**
 * Mark that non-attendance data has changed (G-Sheet push needed).
 * Called by routes that modify teachers, students, schedules, holidays, settings, etc.
 * NOT called by attendance routes (attendance goes to GitHub, not G-Sheet).
 */
export function markGSheetDirty() {
  _gsheetDirty = true;
}

/**
 * Schedule GitHub auto-sync (attendance records only).
 * Called after attendance saves. Does NOT trigger G-Sheet push.
 * Skipped during server reset (_skipSync = true).
 */
export function scheduleAutoSync() {
  if (_skipSync) return;
  if (!isProductionEnv()) return;
  if (syncTimer) clearTimeout(syncTimer);
  syncTimer = setTimeout(() => {
    syncTimer = null;
    setImmediate(() => {
      const now = Date.now();
      if (now - _lastSyncTime >= MIN_SYNC_INTERVAL) {
        _lastSyncTime = now;
        import('./online-backup').then(({ triggerOnlineAutoSync }) => {
          triggerOnlineAutoSync().catch(() => {});
        }).catch(() => {});
      }
    });
  }, 5000);
}

/**
 * Schedule G-Sheet push (non-attendance data).
 * Called after user changes teachers, students, schedules, holidays, settings, etc.
 *
 * Routes that modify non-attendance data MUST call `markGSheetDirty()` BEFORE
 * calling this function. Without the dirty flag, the push is SKIPPED.
 * This ensures G-Sheet push ONLY happens when data actually changed —
 * if a background task or non-mutating route calls `scheduleGSheetSync()`
 * without `markGSheetDirty()`, no push occurs.
 *
 * SKIPPED if:
 *   1. _skipSync is true (server reset in progress)
 *   2. _gsheetDirty is false (no non-attendance data changed — route didn't call markGSheetDirty)
 *   3. Not production environment
 *   4. GitHub attendance count > local DB count (server reset detected)
 *      → Don't push to G-Sheet during server reset — only PULL from G-Sheet
 *
 * pushToGSheets uses MERGE mode — does NOT delete existing G-Sheet data.
 * Only inserts/updates records. G-Sheet data is never auto-deleted.
 */
export function scheduleGSheetSync() {
  if (_skipSync) return;
  if (!isProductionEnv()) return;
  // NOTE: Do NOT call markGSheetDirty() here — routes must call it explicitly.
  // This ensures the dirty flag is only set when data actually changed.
  if (gsheetTimer) clearTimeout(gsheetTimer);
  gsheetTimer = setTimeout(() => {
    gsheetTimer = null;
    setImmediate(async () => {
      // Check 1: Only push if data actually changed (route called markGSheetDirty)
      if (!_gsheetDirty) {
        console.log('[AutoSync] G-Sheet push skipped — no non-attendance data changed (dirty flag not set)');
        return;
      }
      // Check 2: Server reset detection — if GitHub count > local count, skip push
      // This means a server reset just happened — only PULL from G-Sheet, don't PUSH
      try {
        const { db } = await import('./db');
        const localCount = await db.attendance.count();
        const setting = await db.settings.findUnique({ where: { key: 'online_attendance_count' } });
        const ghCount = setting ? parseInt(setting.value, 10) || 0 : 0;
        if (ghCount > 0 && localCount < ghCount) {
          console.log(`[AutoSync] G-Sheet push SKIPPED — server reset detected (local=${localCount} < GitHub=${ghCount}). Wait for pull-diff.`);
          return;
        }
      } catch {}
      // Push to G-Sheet (merge mode — does NOT delete existing data)
      const gsNow = Date.now();
      if (gsNow - _lastGSheetSyncTime >= MIN_GSHEET_SYNC_INTERVAL) {
        _lastGSheetSyncTime = gsNow;
        import('./google-sheets-v4').then(({ pushToGSheets }) => {
          pushToGSheets().then(() => {
            _gsheetDirty = false;
            console.log('[AutoSync] G-Sheet push success — dirty flag cleared');
          }).catch((e) => {
            console.warn('[AutoSync] G-Sheet push failed:', e instanceof Error ? e.message : String(e));
          });
        }).catch(() => {});
      }
    });
  }, 5000);
}

/**
 * Schedule an IMMEDIATE GitHub auto-sync (attendance) — bypasses the 5s debounce.
 * Does NOT trigger G-Sheet push (attendance → GitHub, not G-Sheet).
 */
export function scheduleImmediateSync() {
  if (_skipSync) return;
  if (!isProductionEnv()) return;

  setImmediate(() => {
    const now = Date.now();
    if (now - _lastSyncTime >= MIN_SYNC_INTERVAL) {
      _lastSyncTime = now;
      import('./online-backup').then(({ triggerOnlineAutoSync }) => {
        triggerOnlineAutoSync().catch(() => {});
      }).catch(() => {});
    }
  });
}

/**
 * Check if auto-sync is currently skipped (e.g., during server reset recovery).
 */
export function isAutoSyncSkipped(): boolean {
  return _skipSync;
}

/**
 * Check if there is a pending auto-sync scheduled
 */
export function isAutoSyncPending(): boolean {
  return syncTimer !== null;
}
"},{"path":"src/lib/code-backup.ts","content":"import * as fs from 'fs';
import * as path from 'path';
import {
  getConfig,
  githubPutFile,
  githubGetFile,
  githubDeleteFile,
  type GitHubConfig,
} from '@/lib/online-backup';
import { APP_VERSION } from '@/lib/app-version';

/**
 * CODE BACKUP SYSTEM — backup & restore KODE APLIKASI (versi terakhir) ke GitHub
 *
 * Berbeda dari backup absensi (backup/chunk-{N}.json + backup/meta.json),
 * backup kode menggunakan FOLDER + NAMA CHUNK KHUSUS agar restore aplikasi
 * tidak pernah salah mengambil chunk absensi:
 *
 *   - code-backup/code-meta.json    — daftar chunk (path + sha), daftar file, versi app
 *   - code-backup/code-chunk-0.json .. code-chunk-N.json — potongan manifest kode
 *
 * Restore HANYA membaca code-backup/code-meta.json lalu mengambil chunk yang
 * tercantum di sana (divalidasi prefix 'code-backup/code-chunk-'), sehingga
 * tidak mungkin tercampur dengan backup/chunk-*.json (absensi siswa).
 *
 * Scope backup (semua yang dibutuhkan untuk menjalankan versi terakhir):
 *   - src/**          (komponen, API routes, lib)
 *   - prisma/**       (schema)
 *   - public/**       (aset)
 *   - scripts/**      (util kecil)
 *   - file konfigurasi root: package.json, tsconfig.json, next.config.ts, dsb.
 *
 * TIDAK di-backup (secrets/data/runtime):
 *   - .env*, upload/github-config.json (token GitHub), db/**, node_modules,
 *     .next, log, dsb.
 */

const CODE_BACKUP_DIR = 'code-backup';
export const CODE_META_FILE = `${CODE_BACKUP_DIR}/code-meta.json`;
const CODE_CHUNK_PREFIX = `${CODE_BACKUP_DIR}/code-chunk-`;

// Max serialized characters per chunk file. JSON-string escaping can inflate
// content, so keep well below GitHub's content-size comfort zone.
const CODE_CHUNK_MAX_CHARS = 800_000;

const PROJECT_ROOT = process.cwd();

// Directories backed up recursively.
const INCLUDE_DIRS = ['src', 'prisma', 'public', 'scripts'];
// Root-level files backed up as-is.
const INCLUDE_ROOT_FILES = [
  'package.json',
  'bun.lock',
  'tsconfig.json',
  'next.config.ts',
  'postcss.config.mjs',
  'components.json',
  'eslint.config.mjs',
  'tailwind.config.ts',
  'next-env.d.ts',
  'Caddyfile',
  '.gitignore',
  'firebase.json',
  'firestore.indexes.json',
  'firestore.rules',
  'storage.rules',
];
// Text extensions eligible for inclusion when walking directories.
const TEXT_EXTENSIONS = new Set([
  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.json', '.css', '.scss',
  '.md', '.txt', '.prisma', '.svg', '.html', '.yml', '.yaml', '.toml', '.xml',
  '.sh', '.sql', '.graphql', '.editorconfig',
]);
// Files that must NEVER enter a backup regardless of location.
const EXCLUDED_PATTERNS = [
  /^\.env/i,
  /(^|\/)\.env/,
  /github-config\.json$/i,   // contains the GitHub token!
  /(^|\/)node_modules\//,
  /(^|\/)\.next\//,
  /(^|\/)\.git\//,
  /dev\.log$/i,
  /nohup\.out$/i,
  /\.tsbuildinfo$/i,
  /(^|\/)custom\.db/i,       // SQLite data — handled by attendance backup
  /auto_restore\.json$/i,
];

interface CodeFileEntry {
  path: string;
  content: string;
}

interface CodeManifest {
  backedUpAt: string;
  appVersion: string;
  fileCount: number;
  files: CodeFileEntry[];
}

interface CodeMetaChunk {
  path: string;
  sha: string;
  size: number;
}

export interface CodeBackupMeta {
  totalChunks: number;
  totalBytes: number;
  fileCount: number;
  backedUpAt: string;
  appVersion: string;
  chunks: CodeMetaChunk[];
  files: { path: string; size: number }[];
}

export interface CodeBackupProgress {
  current: number;
  total: number;
  percentage: number;
  label: string;
}

export interface CodeBackupStatus {
  running: boolean;
  operation: 'backup' | 'restore' | null;
  lastResult: { success: boolean; message: string } | null;
  progress: CodeBackupProgress | null;
  startedAt: string | null;
}

let status: CodeBackupStatus = {
  running: false,
  operation: null,
  lastResult: null,
  progress: null,
  startedAt: null,
};

export function getCodeBackupStatus(): CodeBackupStatus {
  return { ...status };
}

function setProgress(current: number, total: number, label: string) {
  status = {
    ...status,
    progress: {
      current,
      total,
      percentage: total > 0 ? Math.round((current / total) * 100) : 0,
      label,
    },
  };
}

function finish(result: { success: boolean; message: string }) {
  status = {
    running: false,
    operation: null,
    lastResult: result,
    progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' },
    startedAt: status.startedAt,
  };
}

// ===== Manifest collection =====

function isExcluded(relPath: string): boolean {
  for (const p of EXCLUDED_PATTERNS) {
    if (p.test(relPath)) return true;
  }
  return false;
}

function looksBinary(content: string): boolean {
  // Heuristic: NUL byte or a high ratio of replacement/control characters.
  if (content.includes('\u0000')) return true;
  const sample = content.slice(0, 2000);
  let suspicious = 0;
  for (const ch of sample) {
    const code = ch.charCodeAt(0);
    if (code === 0xFFFD || (code < 9 && code !== 0)) suspicious++;
  }
  return suspicious > sample.length * 0.05;
}

function collectCodeManifest(): CodeManifest {
  const files: CodeFileEntry[] = [];

  const pushFile = (absPath: string, relPath: string) => {
    if (isExcluded(relPath)) return;
    const ext = path.extname(relPath).toLowerCase();
    const noExt = !ext;
    if (!noExt && !TEXT_EXTENSIONS.has(ext)) return;
    try {
      const stat = fs.statSync(absPath);
      if (stat.size > 4 * 1024 * 1024) return; // skip >4MB (shouldn't happen for code)
      const content = fs.readFileSync(absPath, 'utf8');
      if (looksBinary(content)) return;
      files.push({ path: relPath, content });
    } catch {
      // unreadable file — skip
    }
  };

  for (const dir of INCLUDE_DIRS) {
    const absDir = path.join(PROJECT_ROOT, dir);
    if (!fs.existsSync(absDir)) continue;
    const walk = (cur: string) => {
      let entries: fs.Dirent[] = [];
      try {
        entries = fs.readdirSync(cur, { withFileTypes: true });
      } catch {
        return;
      }
      for (const e of entries) {
        const abs = path.join(cur, e.name);
        const rel = path.relative(PROJECT_ROOT, abs);
        if (isExcluded(rel)) continue;
        if (e.isDirectory()) walk(abs);
        else if (e.isFile()) pushFile(abs, rel);
      }
    };
    walk(absDir);
  }

  for (const f of INCLUDE_ROOT_FILES) {
    const abs = path.join(PROJECT_ROOT, f);
    if (fs.existsSync(abs) && fs.statSync(abs).isFile()) {
      try {
        const content = fs.readFileSync(abs, 'utf8');
        if (!looksBinary(content)) {
          files.push({ path: f, content });
        }
      } catch {
        // skip
      }
    }
  }

  return {
    backedUpAt: new Date().toISOString(),
    appVersion: `${APP_VERSION.version} (code ${APP_VERSION.versionCode})`,
    fileCount: files.length,
    files,
  };
}

// ===== GitHub blob helpers =====

async function githubGetBlob(config: GitHubConfig, sha: string): Promise<string | null> {
  const url = `${'https://api.github.com'}/repos/${config.owner}/${config.repo}/git/blobs/${sha}`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60000);
  try {
    const res = await fetch(url, {
      headers: {
        'Authorization': `Bearer ${config.token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
      signal: controller.signal,
    });
    clearTimeout(timeout);
    if (!res.ok) return null;
    const data = await res.json();
    if (data.encoding === 'base64' && typeof data.content === 'string') {
      return Buffer.from(data.content, 'base64').toString('utf8');
    }
    return typeof data.content === 'string' ? data.content : null;
  } catch (e) {
    clearTimeout(timeout);
    throw e;
  }
}

// ===== Backup (push) =====

export async function backupCodeToGitHub(): Promise<{ success: boolean; message: string }> {
  const config = await getConfig();
  if (!config) {
    return { success: false, message: 'GitHub belum terkonfigurasi (token/owner/repo tidak ditemukan).' };
  }

  status = {
    running: true,
    operation: 'backup',
    lastResult: null,
    progress: null,
    startedAt: new Date().toISOString(),
  };

  try {
    setProgress(0, 100, 'Membaca seluruh file kode aplikasi...');
    const manifest = collectCodeManifest();
    if (manifest.fileCount === 0) {
      finish({ success: false, message: 'Tidak ada file kode yang terbaca — manifest kosong.' });
      return { success: false, message: 'Manifest kosong.' };
    }

    // Serialize manifest once, slice into fixed-size character chunks.
    const serialized = JSON.stringify(manifest);
    const totalChunks = Math.max(1, Math.ceil(serialized.length / CODE_CHUNK_MAX_CHARS));

    // Previous meta (to clean stale chunks after upload) — also reuse its sha.
    const prevMetaRaw = await githubGetFile(config, CODE_META_FILE);
    let prevMeta: CodeBackupMeta | null = null;
    if (prevMetaRaw) {
      try { prevMeta = JSON.parse(prevMetaRaw.content); } catch { prevMeta = null; }
    }

    // Upload chunks: code-chunk-0 .. code-chunk-{totalChunks-1}
    const metaChunks: CodeMetaChunk[] = [];
    for (let i = 0; i < totalChunks; i++) {
      const slice = serialized.slice(i * CODE_CHUNK_MAX_CHARS, (i + 1) * CODE_CHUNK_MAX_CHARS);
      const chunkPath = `${CODE_CHUNK_PREFIX}${i}.json`;
      setProgress(i, totalChunks + 1, `Mengunggah chunk kode ${i + 1}/${totalChunks}...`);
      const chunkContent = JSON.stringify({ index: i, total: totalChunks, data: slice });
      const existing = prevMeta?.chunks.find(c => c.path === chunkPath);
      const put = await githubPutFile(
        config,
        chunkPath,
        chunkContent,
        `code-backup: chunk ${i}/${totalChunks - 1} (${APP_VERSION.version})`,
        existing?.sha,
      );
      metaChunks.push({
        path: chunkPath,
        sha: put.sha || existing?.sha || '',
        size: Buffer.byteLength(chunkContent, 'utf8'),
      });
    }

    // Delete stale chunks (when the new backup uses fewer chunks).
    if (prevMeta && prevMeta.chunks) {
      for (const old of prevMeta.chunks) {
        const idx = Number(old.path.match(/code-chunk-(\d+)\.json$/)?.[1] ?? -1);
        if (idx >= totalChunks) {
          try {
            await githubDeleteFile(config, old.path, old.sha, `code-backup: hapus chunk usang ${idx}`);
          } catch {
            // non-fatal
          }
        }
      }
    }

    // Upload meta LAST (it is the source of truth for restore).
    const meta: CodeBackupMeta = {
      totalChunks,
      totalBytes: Buffer.byteLength(serialized, 'utf8'),
      fileCount: manifest.fileCount,
      backedUpAt: manifest.backedUpAt,
      appVersion: manifest.appVersion,
      chunks: metaChunks,
      files: manifest.files.map(f => ({ path: f.path, size: Buffer.byteLength(f.content, 'utf8') })),
    };
    setProgress(totalChunks, totalChunks + 1, 'Menyimpan meta backup kode...');
    await githubPutFile(
      config,
      CODE_META_FILE,
      JSON.stringify(meta),
      `code-backup: meta (${manifest.fileCount} files, ${totalChunks} chunks, ${APP_VERSION.version})`,
      prevMetaRaw?.sha,
    );

    finish({
      success: true,
      message: `Backup kode berhasil: ${manifest.fileCount} file (${(meta.totalBytes / 1024 / 1024).toFixed(2)} MB) dalam ${totalChunks} chunk — versi ${manifest.appVersion}.`,
    });
    return { success: true, message: status.lastResult!.message };
  } catch (error) {
    const msg = 'Backup kode gagal: ' + (error instanceof Error ? error.message : String(error));
    finish({ success: false, message: msg });
    return { success: false, message: msg };
  }
}

// ===== Restore (pull) =====

function safeJoin(relPath: string): string | null {
  const abs = path.resolve(PROJECT_ROOT, relPath);
  const root = path.resolve(PROJECT_ROOT);
  if (!abs.startsWith(root + path.sep) && abs !== root) return null;
  return abs;
}

export async function restoreCodeFromGitHub(): Promise<{ success: boolean; message: string }> {
  const config = await getConfig();
  if (!config) {
    return { success: false, message: 'GitHub belum terkonfigurasi (token/owner/repo tidak ditemukan).' };
  }

  status = {
    running: true,
    operation: 'restore',
    lastResult: null,
    progress: null,
    startedAt: new Date().toISOString(),
  };

  try {
    setProgress(0, 100, 'Membaca meta backup kode dari GitHub...');
    const metaRaw = await githubGetFile(config, CODE_META_FILE);
    if (!metaRaw) {
      finish({ success: false, message: 'Belum ada backup kode di GitHub (code-backup/code-meta.json tidak ditemukan). Jalankan "Backup Kode ke GitHub" terlebih dahulu.' });
      return { success: false, message: status.lastResult!.message };
    }
    const meta: CodeBackupMeta = JSON.parse(metaRaw.content);
    if (!Array.isArray(meta.chunks) || meta.chunks.length === 0) {
      finish({ success: false, message: 'Meta backup kode tidak valid (daftar chunk kosong).' });
      return { success: false, message: status.lastResult!.message };
    }

    // GUARD: every chunk MUST live in the code-backup/ namespace — never mix
    // with attendance chunks (backup/chunk-*.json).
    for (const c of meta.chunks) {
      if (!c.path.startsWith(CODE_CHUNK_PREFIX) || !c.path.endsWith('.json')) {
        finish({ success: false, message: `Chunk tidak valid terdeteksi (${c.path}) — restore dibatalkan demi keamanan data.` });
        return { success: false, message: status.lastResult!.message };
      }
    }

    // Fetch & reassemble chunks (via git blob API — contents GET is 1MB-limited).
    let serialized = '';
    for (let i = 0; i < meta.chunks.length; i++) {
      const c = meta.chunks[i];
      setProgress(i, meta.chunks.length + 1, `Mengambil chunk kode ${i + 1}/${meta.chunks.length}...`);
      const chunkJson = await githubGetBlob(config, c.sha);
      if (!chunkJson) {
        finish({ success: false, message: `Gagal mengambil chunk ${c.path} dari GitHub.` });
        return { success: false, message: status.lastResult!.message };
      }
      const parsed = JSON.parse(chunkJson) as { index?: number; data?: string };
      if (typeof parsed.data !== 'string' || typeof parsed.index !== 'number' || parsed.index !== i) {
        finish({ success: false, message: `Chunk ${c.path} tidak valid (index tidak cocok) — restore dibatalkan.` });
        return { success: false, message: status.lastResult!.message };
      }
      serialized += parsed.data;
    }

    setProgress(meta.chunks.length, meta.chunks.length + 1, 'Menulis ulang file kode aplikasi...');
    const manifest: CodeManifest = JSON.parse(serialized);
    if (!Array.isArray(manifest.files) || manifest.files.length === 0) {
      finish({ success: false, message: 'Manifest kode kosong — restore dibatalkan.' });
      return { success: false, message: status.lastResult!.message };
    }

    let written = 0;
    for (const f of manifest.files) {
      const abs = safeJoin(f.path);
      if (!abs) continue; // refuse paths outside the project root
      fs.mkdirSync(path.dirname(abs), { recursive: true });
      fs.writeFileSync(abs, f.content, 'utf8');
      written++;
    }

    finish({
      success: true,
      message: `Restore kode berhasil: ${written}/${manifest.fileCount} file ditulis ulang sesuai backup versi ${manifest.appVersion} (${meta.backedUpAt}). Server dev akan otomatis memuat ulang perubahan.`,
    });
    return { success: true, message: status.lastResult!.message };
  } catch (error) {
    const msg = 'Restore kode gagal: ' + (error instanceof Error ? error.message : String(error));
    finish({ success: false, message: msg });
    return { success: false, message: msg };
  }
}
"},{"path":"src/lib/db-persistent-sync.ts","content":"/**
 * Persistent DB sync — copies the live SQLite DB file to the persistent OSS mount.
 *
 * This module is intentionally kept SEPARATE from instrumentation.ts so that
 * Turbopack's static analyzer does not flag `fs` usage in the instrumentation
 * entrypoint (which is compiled for BOTH edge and nodejs runtimes).
 *
 * All functions here are ASYNC (fs.promises) and must only be called from the
 * Node.js runtime. They are non-blocking and safe to call from periodic timers.
 */

export async function syncLiveDbToPersistent(): Promise<{ copied: boolean; path?: string; error?: string }> {
  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    const liveDbPath = process.env.DATABASE_URL?.replace(/^file:/, '') || '/app/db/custom.db';
    const persistentDir = fs.existsSync('/app/upload') ? '/app/upload/db' : '/home/z/my-project/upload/db';
    const persistentDbPath = `${persistentDir}/custom.db`;

    if (!fs.existsSync(liveDbPath)) {
      return { copied: false, error: 'live DB not found' };
    }
    if (liveDbPath === persistentDbPath) {
      return { copied: false };
    }

    try {
      await fsp.mkdir(persistentDir, { recursive: true });
    } catch {
      // dir may already exist; ignore
    }
    // Async copy — does NOT block the event loop
    await fsp.copyFile(liveDbPath, persistentDbPath);
    return { copied: true, path: persistentDbPath };
  } catch (error) {
    return { copied: false, error: error instanceof Error ? error.message : String(error) };
  }
}

/**
 * Save a full JSON backup to auto_restore.json in BOTH persistent locations.
 * This ensures that after a pull-diff/restore, the data is saved as a restore
 * point that survives server resets.
 *
 * Called after:
 *   - pull-diff completes (restoreMissingFromOnlineBackup)
 *   - pull-full completes (restoreFromOnlineBackup)
 *   - restore-from-local completes (auto-restore API)
 *   - manual restore from backup file (backup POST API)
 *
 * This creates a "restore point" — the next server reset will restore from
 * this file instead of the deploy-time packaged DB.
 */
export async function saveRestorePoint(backupData: any): Promise<{ saved: boolean; paths: string[]; error?: string }> {
  const paths: string[] = [];
  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    const jsonStr = JSON.stringify(backupData, null, 2);

    // Save to multiple persistent locations for redundancy
    const locations = [
      '/home/z/my-project/upload/backups/auto_restore.json',
      '/home/z/my-project/db/auto_restore.json',
    ];
    // Also try /app/ paths (production)
    if (fs.existsSync('/app/upload')) {
      locations.push('/app/upload/backups/auto_restore.json');
    }
    if (fs.existsSync('/app/db')) {
      locations.push('/app/db/auto_restore.json');
    }

    for (const loc of locations) {
      try {
        // Ensure directory exists
        const dir = loc.substring(0, loc.lastIndexOf('/'));
        await fsp.mkdir(dir, { recursive: true });
        await fsp.writeFile(loc, jsonStr, 'utf8');
        paths.push(loc);
      } catch (e) {
        // Individual location failures are OK — at least one should succeed
        console.warn(`[saveRestorePoint] Failed to save to ${loc}:`, e instanceof Error ? e.message : String(e));
      }
    }

    // Also sync the live DB file to persistent storage
    const dbSync = await syncLiveDbToPersistent();
    if (dbSync.copied) {
      paths.push(dbSync.path!);
    }

    return { saved: paths.length > 0, paths };
  } catch (error) {
    return { saved: false, paths, error: error instanceof Error ? error.message : String(error) };
  }
}

// ===== Persistent GitHub count (file-based, survives server resets) =====
// The GitHub attendance count is stored in the DB Settings table, but that
// gets wiped on server reset. To ensure the count survives resets (so
// auto-sync can detect attendance drops), we also persist it to a file on
// the persistent OSS mount.

const PERSISTENT_GH_COUNT_PATHS = [
  '/home/z/my-project/upload/gh-count.json',
  '/app/upload/gh-count.json', // production path (may not exist in dev — write/read handles failure)
];

/**
 * Save the GitHub attendance count to a persistent file.
 * Called after every successful sync/push to GitHub.
 * This ensures the count survives server resets (DB Settings gets wiped,
 * but the file on the OSS mount persists).
 */
export async function savePersistentGhCount(count: number): Promise<void> {
  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    const data = JSON.stringify({ count, savedAt: new Date().toISOString() });
    const paths = PERSISTENT_GH_COUNT_PATHS;
    for (const p of paths) {
      try {
        const dir = p.substring(0, p.lastIndexOf('/'));
        await fsp.mkdir(dir, { recursive: true });
        await fsp.writeFile(p, data, 'utf8');
      } catch {
        // non-fatal
      }
    }
  } catch {}
}

/**
 * Read the GitHub attendance count from the persistent file.
 * Called when the DB Settings count is 0 (after server reset) to
 * restore the known GitHub count without needing to fetch meta.json.
 * Returns 0 if no file exists.
 */
export async function readPersistentGhCount(): Promise<number> {
  try {
    const fs = await import('fs');
    const paths = PERSISTENT_GH_COUNT_PATHS;
    for (const p of paths) {
      try {
        if (fs.existsSync(p)) {
          const content = await fs.promises.readFile(p, 'utf8');
          const data = JSON.parse(content);
          if (data.count && typeof data.count === 'number') {
            return data.count;
          }
        }
      } catch {
        // try next path
      }
    }
  } catch {}
  return 0;
}

// ===== Persistent sync status (file-based, survives server resets) =====
// Stores ALL sync-related settings so they can be restored on server startup.

const PERSISTENT_SYNC_STATUS_PATHS = [
  '/home/z/my-project/upload/sync-status.json',
  '/app/upload/sync-status.json',
];

/**
 * Save sync-related settings to a persistent file.
 * Called after every sync/pull operation.
 * This ensures sync status survives server resets.
 */
export async function savePersistentSyncStatus(settings: Record<string, string>): Promise<void> {
  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    const data = JSON.stringify({ settings, savedAt: new Date().toISOString() });
    for (const p of PERSISTENT_SYNC_STATUS_PATHS) {
      try {
        const dir = p.substring(0, p.lastIndexOf('/'));
        await fsp.mkdir(dir, { recursive: true });
        await fsp.writeFile(p, data, 'utf8');
      } catch {
        // non-fatal
      }
    }
  } catch {}
}

/**
 * Read sync-related settings from the persistent file.
 * Called on server startup to restore settings that were wiped by server reset.
 * Returns an empty object if no file exists.
 */
export async function readPersistentSyncStatus(): Promise<Record<string, string>> {
  try {
    const fs = await import('fs');
    for (const p of PERSISTENT_SYNC_STATUS_PATHS) {
      try {
        if (fs.existsSync(p)) {
          const content = await fs.promises.readFile(p, 'utf8');
          const data = JSON.parse(content);
          if (data.settings && typeof data.settings === 'object') {
            return data.settings;
          }
        }
      } catch {
        // try next path
      }
    }
  } catch {}
  return {};
}

/**
 * Restore persistent sync state to DB Settings on server startup.
 * This runs BEFORE auto-sync and periodic checks, ensuring the cached
 * GitHub count and sync status are available immediately.
 *
 * Called from startInstrumentationNode() on server startup.
 */
export async function restorePersistentSyncState(): Promise<{ restored: boolean; count?: number; settings?: number }> {
  try {
    const { db } = await import('./db');

    // 1. Restore GitHub attendance count from gh-count.json
    const ghCount = await readPersistentGhCount();
    let countRestored = false;
    if (ghCount > 0) {
      try {
        // Check if DB already has the count (it might if persistent DB was restored by start.sh)
        const existing = await db.settings.findUnique({ where: { key: 'online_attendance_count' } });
        const dbCount = existing ? parseInt(existing.value, 10) || 0 : 0;
        if (dbCount === 0) {
          // DB doesn't have the count — restore from file
          await db.settings.upsert({
            where: { key: 'online_attendance_count' },
            update: { value: String(ghCount) },
            create: { key: 'online_attendance_count', value: String(ghCount) },
          });
          countRestored = true;
          console.log(`[PersistentSync] Restored GitHub count from file: ${ghCount}`);
        }
      } catch {}
    }

    // 2. Restore sync status settings from sync-status.json
    const statusSettings = await readPersistentSyncStatus();
    let settingsRestored = 0;
    const SYNC_KEYS = [
      'online_last_sync_at',
      'online_last_pull_at',
      'online_last_sync_result',
      'online_last_pull_result',
      'online_attendance_count',
    ];
    for (const key of SYNC_KEYS) {
      if (statusSettings[key]) {
        try {
          const existing = await db.settings.findUnique({ where: { key } });
          if (!existing) {
            await db.settings.create({ data: { key, value: statusSettings[key] } });
            settingsRestored++;
          }
        } catch {}
      }
    }
    if (settingsRestored > 0) {
      console.log(`[PersistentSync] Restored ${settingsRestored} sync status settings from file`);
    }

    return { restored: countRestored || settingsRestored > 0, count: ghCount, settings: settingsRestored };
  } catch (error) {
    console.warn('[PersistentSync] Could not restore persistent state:', error instanceof Error ? error.message : String(error));
    return { restored: false };
  }
}
"},{"path":"src/lib/db.ts","content":"import { PrismaClient } from '@prisma/client'

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined
  pragmasApplied?: boolean
}

/**
 * Resolve the SQLite database URL.
 *
 * Priority:
 *   1. process.env.DATABASE_URL — set by the production start script
 *      (start.sh exports `file:/app/db/custom.db`) and by the dev `.env`
 *      (file:/home/z/my-project/upload/db/custom.db). Shell env vars are
 *      NOT overridden by Next.js `.env` loading, so production wins.
 *   2. Dev fallback — the persistent OSS mount path used in the sandbox.
 *
 * This MUST NOT be hardcoded to an absolute sandbox path, otherwise the
 * production deployment (which runs from /app/ with a packaged DB at
 * /app/db/custom.db) cannot find the database and silently creates an
 * empty one — causing "TOTAL: 0" on the deployed site.
 */
function resolveDbUrl(): string {
  const envUrl = process.env.DATABASE_URL
  if (envUrl && envUrl.trim()) return envUrl
  // Dev sandbox fallback (persistent OSS mount with full data)
  return 'file:/home/z/my-project/upload/db/custom.db'
}

const DATABASE_URL = resolveDbUrl()

const basePrisma = globalForPrisma.prisma ??
  new PrismaClient({
    log: ['error', 'warn'],
    datasources: {
      db: {
        url: DATABASE_URL,
      },
    },
  })

export const db = basePrisma

// Always cache to prevent connection leaks in both dev and production
globalForPrisma.prisma = db

/**
 * Configure SQLite pragmas on the live DB to PREVENT the "disk is full" issue.
 *
 * ROOT CAUSE on production:
 *   - SQLite default journal_mode = WAL (Write-Ahead Logging)
 *   - WAL creates a separate `custom.db-wal` file that grows with each write
 *   - On the FC container, the `/app/` filesystem has very limited space (~512MB)
 *   - As the WAL file grows (and never gets checkpointed because the disk is too
 *     full to do so), it eventually fills the disk → SQLITE_FULL (code 13) →
 *     "database or disk is full" → ALL WRITES FAIL (POST /api/attendance → 500)
 *     Reads still work because WAL doesn't need to grow for reads.
 *
 * FIX: Switch to journal_mode=DELETE — uses a small rollback journal that's
 * deleted after each commit. NO growing WAL file → disk never fills up from
 * journal files. Slightly slower writes (acceptable for attendance), but
 * much more reliable on limited disk containers.
 *
 * Also runs wal_checkpoint(TRUNCATE) to clean up any existing WAL file.
 *
 * Runs in BACKGROUND (non-blocking) so server startup isn't delayed.
 */
async function configureSqlitePragmas(prisma: PrismaClient): Promise<void> {
  const tried: string[] = [];
  try {
    // Switch from WAL → DELETE: eliminates the -wal file entirely.
    // This is THE critical fix for the disk-full issue.
    // NOTE: PRAGMA journal_mode=... RETURNS the new mode (e.g. "delete"),
    // so we must use $queryRawUnsafe (not $executeRawUnsafe, which fails with
    // "Execute returned results, which is not allowed in SQLite").
    await prisma.$queryRawUnsafe('PRAGMA journal_mode=DELETE');
    tried.push('journal_mode=DELETE');

    // Synchronous=NORMAL is safe with DELETE mode and ~2x faster than FULL.
    // This pragma returns nothing → $executeRawUnsafe works.
    await prisma.$executeRawUnsafe('PRAGMA synchronous=NORMAL');
    tried.push('synchronous=NORMAL');

    // Checkpoint and TRUNCATE any leftover WAL file from previous runs.
    // wal_checkpoint returns {busy, log, checkpointed} → use $queryRawUnsafe.
    try {
      await prisma.$queryRawUnsafe('PRAGMA wal_checkpoint(TRUNCATE)');
      tried.push('wal_checkpoint(TRUNCATE)');
    } catch {}

    // Foreign keys ON — data integrity (returns nothing)
    await prisma.$executeRawUnsafe('PRAGMA foreign_keys=ON');
    tried.push('foreign_keys=ON');

    // Larger cache = faster reads, lower CPU (negative = KB instead of pages)
    await prisma.$executeRawUnsafe('PRAGMA cache_size=-8192');
    tried.push('cache_size=8MB');

    console.log('[DB] SQLite pragmas configured: ' + tried.join(', '));
  } catch (e) {
    console.warn('[DB] Failed to configure some pragmas (' + tried.join(',') + '):',
      e instanceof Error ? e.message : String(e));
  }
}

// Run pragmas in BACKGROUND — don't block server startup.
// The first few requests might still use WAL mode (transient), but the pragmas
// kick in within ~100ms of server start. Use a separate flag so we don't try
// to re-apply pragmas on every module reload in dev (HMR).
if (!globalForPrisma.pragmasApplied) {
  globalForPrisma.pragmasApplied = true;
  configureSqlitePragmas(basePrisma).catch((e) => {
    console.warn('[DB] Pragma configuration failed:', e instanceof Error ? e.message : String(e));
  });
}
"},{"path":"src/lib/disk-cleanup.ts","content":"/**
 * Disk cleanup & recovery module.
 *
 * Provides aggressive auto-cleanup that ACTUALLY reclaims disk space when the
 * FC container's /app/ filesystem fills up. The previous "recovery" only
 * switched journal_mode and ran wal_checkpoint — but if the disk is ALREADY
 * full, the checkpoint fails too (it needs space to merge WAL into the DB).
 *
 * This module:
 *   1. Deletes old backup JSON files (keeps only last N)
 *   2. Force-deletes WAL/SHM files (they regenerate automatically)
 *   3. Deletes old log files
 *   4. VACUUMs the database (reclaims dead pages, shrinks DB file)
 *   5. Checks disk usage before/after to measure reclaimed space
 *
 * Called from:
 *   - src/app/api/attendance/route.ts on SQLITE_FULL error (auto-recovery)
 *   - src/lib/instrumentation-node.ts on startup + periodic check
 *   - Anywhere disk-full is detected
 */

import path from 'path';

/** Result of a cleanup operation — what was deleted and how much space was reclaimed. */
export interface CleanupResult {
  /** Total bytes reclaimed by the cleanup */
  bytesReclaimed: number;
  /** Number of files deleted */
  filesDeleted: number;
  /** List of file paths that were deleted (for logging) */
  deletedPaths: string[];
  /** Disk usage % BEFORE cleanup (0-100) */
  diskUsageBefore: number;
  /** Disk usage % AFTER cleanup (0-100) */
  diskUsageAfter: number;
  /** Whether VACUUM was run */
  vacuumed: boolean;
  /** Any errors encountered (non-fatal — best-effort cleanup) */
  errors: string[];
}

/** Get disk usage percentage for the filesystem containing the given path. */
export async function getDiskUsage(targetPath: string = '/app'): Promise<number> {
  try {
    const fs = await import('fs');
    // statfs is Linux-only; on macOS/other use stat
    try {
      const stats = await (fs.promises as any).statfs(targetPath);
      // stats.blocks (total), stats.bfree (free for unprivileged), stats.bavail (free for us)
      const total = stats.blocks * stats.bsize;
      const free = stats.bavail * stats.bsize;
      if (total === 0) return 0;
      const used = total - free;
      return Math.round((used / total) * 100);
    } catch {
      // statfs not available (macOS) — fall back to not-available
      return -1;
    }
  } catch {
    return -1;
  }
}

/** Get free disk space in bytes for the given path. */
async function getFreeDiskBytes(targetPath: string = '/app'): Promise<number> {
  try {
    const fs = await import('fs');
    const stats = await (fs.promises as any).statfs(targetPath);
    return stats.bavail * stats.bsize;
  } catch {
    return -1;
  }
}

/** Delete a file and return its size (bytes) if deletion succeeded, else 0. */
async function deleteFileAndGetSize(filePath: string): Promise<{ deleted: boolean; size: number }> {
  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    try {
      const stat = await fsp.stat(filePath);
      const size = stat.size;
      await fsp.unlink(filePath);
      return { deleted: true, size };
    } catch (e: any) {
      if (e.code === 'ENOENT') return { deleted: false, size: 0 };
      throw e;
    }
  } catch {
    return { deleted: false, size: 0 };
  }
}

/**
 * Delete old backup JSON files in /app/upload/ (or sandbox equivalent).
 * Keeps only the last N most recent files matching the pattern.
 *
 * Production has accumulated MANY backup_absensi_*.json files over weeks/months:
 *   backup_absensi_2026-09-22_1790048241005.json (13MB)
 *   backup_absensi_2026-09-18_1789771521162.json (11MB)
 *   ... (many more, totaling 50-100MB+)
 *
 * Each is a full snapshot of all attendance data. Keeping all of them
 * fills the disk. Keeping last 3 is plenty for restore points.
 */
export async function cleanupOldBackups(keepCount: number = 3): Promise<{ bytesReclaimed: number; filesDeleted: number; deletedPaths: string[] }> {
  const deletedPaths: string[] = [];
  let bytesReclaimed = 0;
  let filesDeleted = 0;

  try {
    const fs = await import('fs');
    const fsp = fs.promises;

    // Try both production and dev paths
    const candidateDirs = [
      '/app/upload',
      '/home/z/my-project/upload',
    ];

    for (const dir of candidateDirs) {
      if (!fs.existsSync(dir)) continue;

      // Find all backup_absensi_*.json files
      let entries: string[] = [];
      try {
        entries = await fsp.readdir(dir);
      } catch { continue; }

      const backupFiles = entries
        .filter(name => name.startsWith('backup_absensi_') && name.endsWith('.json'))
        .map(name => ({ name, path: path.join(dir, name), mtime: 0, size: 0 }));

      // Sort by modification time (newest first)
      for (const f of backupFiles) {
        try {
          const stat = await fsp.stat(f.path);
          f.mtime = stat.mtimeMs;
          f.size = stat.size;
        } catch {}
      }
      backupFiles.sort((a, b) => b.mtime - a.mtime);

      // Delete all but the last `keepCount`
      const toDelete = backupFiles.slice(keepCount);
      for (const f of toDelete) {
        const result = await deleteFileAndGetSize(f.path);
        if (result.deleted) {
          bytesReclaimed += result.size;
          filesDeleted++;
          deletedPaths.push(f.path);
        }
      }
    }

    // Also clean up the backups/ subdirectory (older backup files)
    const backupSubDirs = [
      '/app/upload/backups',
      '/home/z/my-project/upload/backups',
    ];
    for (const dir of backupSubDirs) {
      if (!fs.existsSync(dir)) continue;
      let entries: string[] = [];
      try {
        entries = await fsp.readdir(dir);
      } catch { continue; }

      const subBackups = entries
        .filter(name => (name.endsWith('.json') || name.endsWith('.tar')) && name !== 'auto_restore.json' && name !== 'deploy_seed.json')
        .map(name => ({ name, path: path.join(dir, name), mtime: 0, size: 0 }));

      for (const f of subBackups) {
        try {
          const stat = await fsp.stat(f.path);
          f.mtime = stat.mtimeMs;
          f.size = stat.size;
        } catch {}
      }
      subBackups.sort((a, b) => b.mtime - a.mtime);

      const toDelete = subBackups.slice(keepCount);
      for (const f of toDelete) {
        const result = await deleteFileAndGetSize(f.path);
        if (result.deleted) {
          bytesReclaimed += result.size;
          filesDeleted++;
          deletedPaths.push(f.path);
        }
      }
    }
  } catch {}

  return { bytesReclaimed, filesDeleted, deletedPaths };
}

/**
 * Force-delete WAL and SHM files for the live SQLite database.
 *
 * WARNING: This should only be called when no DB writes are in progress.
 * SQLite will recreate these files automatically on next access.
 *
 * WAL files can grow HUGE (hundreds of MB) when checkpoints fail due to
 * disk-full. Force-deleting them is the FASTEST way to reclaim space.
 *
 * NOTE: This requires the journal_mode to be DELETE (or MEMORY) — if it's
 * still WAL, deleting the WAL file may lose uncommitted transactions.
 * With journal_mode=DELETE (set in db.ts), there's no -wal file to delete,
 * but stale -wal files from previous runs may still exist.
 */
export async function forceDeleteWalFiles(): Promise<{ bytesReclaimed: number; filesDeleted: number; deletedPaths: string[] }> {
  const deletedPaths: string[] = [];
  let bytesReclaimed = 0;
  let filesDeleted = 0;

  try {
    const fs = await import('fs');
    const liveDbPath = process.env.DATABASE_URL?.replace(/^file:/, '') || '/app/db/custom.db';
    const dbDir = path.dirname(liveDbPath);

    // WAL and SHM files
    const walFiles = [
      `${liveDbPath}-wal`,
      `${liveDbPath}-shm`,
      `${liveDbPath}-journal`,
      // Also delete from persistent OSS location
      `/app/upload/db/custom.db-wal`,
      `/app/upload/db/custom.db-shm`,
      `/home/z/my-project/upload/db/custom.db-wal`,
      `/home/z/my-project/upload/db/custom.db-shm`,
    ];

    for (const file of walFiles) {
      if (fs.existsSync(file)) {
        const result = await deleteFileAndGetSize(file);
        if (result.deleted) {
          bytesReclaimed += result.size;
          filesDeleted++;
          deletedPaths.push(file);
        }
      }
    }
  } catch {}

  return { bytesReclaimed, filesDeleted, deletedPaths };
}

/**
 * Delete old log files (older than 7 days).
 * Logs can grow large over time and consume disk space.
 */
export async function cleanupOldLogs(): Promise<{ bytesReclaimed: number; filesDeleted: number; deletedPaths: string[] }> {
  const deletedPaths: string[] = [];
  let bytesReclaimed = 0;
  let filesDeleted = 0;

  try {
    const fs = await import('fs');
    const fsp = fs.promises;
    const logDirs = ['/app/logs', '/home/z/my-project/logs'];
    const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

    for (const dir of logDirs) {
      if (!fs.existsSync(dir)) continue;
      let entries: string[] = [];
      try {
        entries = await fsp.readdir(dir);
      } catch { continue; }

      for (const name of entries) {
        const filePath = path.join(dir, name);
        try {
          const stat = await fsp.stat(filePath);
          if (stat.mtimeMs < sevenDaysAgo) {
            await fsp.unlink(filePath);
            bytesReclaimed += stat.size;
            filesDeleted++;
            deletedPaths.push(filePath);
          }
        } catch {}
      }
    }
  } catch {}

  return { bytesReclaimed, filesDeleted, deletedPaths };
}

/**
 * Run VACUUM on the SQLite database.
 * VACUUM rebuilds the database file, reclaiming space from deleted rows
 * (dead pages). This can shrink a 20MB DB to 5MB if many rows were deleted.
 *
 * WARNING: VACUUM requires free disk space equal to ~2x the DB size during
 * the operation (it creates a temp copy). If disk is critically full,
 * VACUUM may fail. We check disk space first and skip if < 100MB free.
 *
 * Returns whether VACUUM succeeded and any error.
 */
export async function vacuumDatabase(): Promise<{ vacuumed: boolean; error?: string }> {
  try {
    // Check free disk space first — VACUUM needs ~2x DB size
    const freeBytes = await getFreeDiskBytes('/app');
    if (freeBytes >= 0 && freeBytes < 100 * 1024 * 1024) {
      // < 100MB free — VACUUM might fail. Skip it.
      return { vacuumed: false, error: 'insufficient free space for VACUUM' };
    }

    const { db } = await import('./db');
    // VACUUM is a special statement that doesn't return rows
    // Use $executeRawUnsafe (works because VACUUM returns no rows)
    await db.$executeRawUnsafe('VACUUM');
    return { vacuumed: true };
  } catch (e) {
    return { vacuumed: false, error: e instanceof Error ? e.message : String(e) };
  }
}

/**
 * Aggressive disk cleanup — runs ALL cleanup operations.
 * Called when disk-full is detected (auto-recovery) or periodically.
 *
 * Order of operations:
 *   1. Get disk usage BEFORE cleanup
 *   2. Delete old backup JSON files (keep last 3)
 *   3. Force-delete WAL/SHM files (regenerate automatically)
 *   4. Delete old log files (>7 days)
 *   5. VACUUM the database (reclaim dead pages)
 *   6. Get disk usage AFTER cleanup
 *   7. Return CleanupResult with reclaimed space
 */
export async function aggressiveCleanup(opts?: { vacuum?: boolean }): Promise<CleanupResult> {
  const errors: string[] = [];
  let totalBytesReclaimed = 0;
  let totalFilesDeleted = 0;
  const allDeletedPaths: string[] = [];
  const runVacuum = opts?.vacuum ?? true;

  const diskUsageBefore = await getDiskUsage('/app');

  // 1. Delete old backup files
  try {
    const result = await cleanupOldBackups(3);
    totalBytesReclaimed += result.bytesReclaimed;
    totalFilesDeleted += result.filesDeleted;
    allDeletedPaths.push(...result.deletedPaths);
  } catch (e) {
    errors.push(`cleanupOldBackups: ${e instanceof Error ? e.message : String(e)}`);
  }

  // 2. Force-delete WAL/SHM files
  try {
    const result = await forceDeleteWalFiles();
    totalBytesReclaimed += result.bytesReclaimed;
    totalFilesDeleted += result.filesDeleted;
    allDeletedPaths.push(...result.deletedPaths);
  } catch (e) {
    errors.push(`forceDeleteWalFiles: ${e instanceof Error ? e.message : String(e)}`);
  }

  // 3. Delete old log files
  try {
    const result = await cleanupOldLogs();
    totalBytesReclaimed += result.bytesReclaimed;
    totalFilesDeleted += result.filesDeleted;
    allDeletedPaths.push(...result.deletedPaths);
  } catch (e) {
    errors.push(`cleanupOldLogs: ${e instanceof Error ? e.message : String(e)}`);
  }

  // 4. VACUUM the database (only if requested and disk has space)
  let vacuumed = false;
  if (runVacuum) {
    try {
      const result = await vacuumDatabase();
      vacuumed = result.vacuumed;
      if (result.error && !result.vacuumed) {
        errors.push(`VACUUM: ${result.error}`);
      }
    } catch (e) {
      errors.push(`VACUUM: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  const diskUsageAfter = await getDiskUsage('/app');

  return {
    bytesReclaimed: totalBytesReclaimed,
    filesDeleted: totalFilesDeleted,
    deletedPaths: allDeletedPaths,
    diskUsageBefore,
    diskUsageAfter,
    vacuumed,
    errors,
  };
}

/**
 * Quick check — is the disk full enough to cause SQLite write failures?
 * Returns true if free disk space is less than 50MB.
 */
export async function isDiskCriticallyFull(): Promise<boolean> {
  const freeBytes = await getFreeDiskBytes('/app');
  if (freeBytes < 0) return false; // can't tell — assume not full
  return freeBytes < 50 * 1024 * 1024; // < 50MB
}
"},{"path":"src/lib/fetch.ts","content":"/**
 * Safe fetch helper that gracefully handles non-JSON responses.
 * Prevents "Unexpected token '<', '<!DOCTYPE'... is not valid JSON" errors
 * when the server returns HTML error pages instead of JSON.
 * Always adds Cache-Control: no-store to prevent browser caching.
 */
export async function safeFetchJson(url: string, options?: RequestInit & { timeoutMs?: number }): Promise<any> {
  try {
    const { timeoutMs, ...fetchOptions } = options || {};
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs || 30000);

    const res = await fetch(url, {
      ...fetchOptions,
      cache: 'no-store',
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      console.warn(`[safeFetch] ${options?.method || 'GET'} ${url} returned ${res.status}`);
      return null;
    }
    const contentType = res.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      return await res.json();
    }
    // If response is not JSON (e.g. HTML error page), return null
    console.warn(`[safeFetch] ${url} returned non-JSON response: ${contentType}`);
    return null;
  } catch (e) {
    if (e instanceof DOMException && e.name === 'AbortError') {
      console.warn(`[safeFetch] ${url} timed out`);
    } else {
      console.error(`[safeFetch] ${url} error:`, e);
    }
    return null;
  }
}
"},{"path":"src/lib/firebase-db.ts","content":"/**
 * Firestore adapter — drop-in replacement for Prisma's `db` object.
 *
 * Provides the SAME API as Prisma Client (db.model.findMany, db.model.upsert,
 * db.$transaction, etc.) so the 43 API routes only need to change ONE import:
 *
 *   SEBELUM:  import { db } from '@/lib/db'
 *   SESUDAH:  import { db } from '@/lib/firebase-db'
 *
 * All route code stays the same — the adapter translates Prisma queries to
 * Firestore queries internally.
 *
 * === Supported methods (per model) ===
 *
 *   findMany({ where, orderBy, include, select, take, skip })
 *   findUnique({ where })
 *   findFirst({ where })
 *   count({ where })
 *   create({ data })
 *   createMany({ data })
 *   update({ where, data })
 *   updateMany({ where, data })
 *   upsert({ where, update, create })
 *   delete({ where })
 *   deleteMany({ where })
 *   $transaction(callback | array)
 *
 * === Limitations vs Prisma ===
 *
 *   1. No nested includes (include: { student: { include: { class: true } } })
 *      — only 1-level includes supported (sufficient for current app)
 *   2. No $queryRawUnsafe (SQLite pragmas) — not needed in Firestore
 *   3. No relation cascade deletes (onDelete: Cascade) — handle manually
 *   4. orderBy with nested field (orderBy: { student: { name: 'asc' } })
 *      requires a separate query — adapter does a 2-step fetch
 *
 * === Model → Collection mapping ===
 *
 *   Prisma model        →  Firestore collection
 *   -------------------     --------------------
 *   class               →  classes
 *   student             →  students
 *   attendance          →  attendance
 *   academicActivity    →  activities
 *   waliKelas           →  waliKelas
 *   settings            →  settings
 *   academicHoliday     →  academicHolidays
 *   dateHoliday         →  dateHolidays
 *   weeklySchedule      →  weeklySchedules
 *   teacher             →  teachers
 *
 * === Document ID strategy ===
 *
 *   Models with @@unique or @unique constraints use composite keys as doc IDs:
 *   - attendance:    `${studentId}_${date}_${hour}`
 *   - activities:    `${classId}_${date}`
 *   - waliKelas:     classId (unique)
 *   - academicHoliday: dayOfWeek (unique)
 *   - dateHoliday:   date (unique)
 *   - weeklySchedule: `${classId}_${dayOfWeek}_${hour}`
 *   - teacher:       nickname (unique)
 *   - settings:      key (@id)
 *   - class, student: auto-id (cuid)
 */

import { firestoreDb, getFirestore } from './firebase';
import type * as admin from 'firebase-admin';
// Import Timestamp statically for Date conversion (avoids require() lint error)
import { firestore } from 'firebase-admin';

// ============================================================
// Type definitions
// ============================================================

type Firestore = admin.firestore.Firestore;
type QuerySnapshot = admin.firestore.QuerySnapshot;
type DocumentData = admin.firestore.DocumentData;
type WhereFilterOp = admin.firestore.WhereFilterOp;

type ModelName =
  | 'class'
  | 'student'
  | 'attendance'
  | 'academicActivity'
  | 'waliKelas'
  | 'settings'
  | 'academicHoliday'
  | 'dateHoliday'
  | 'weeklySchedule'
  | 'teacher';

interface WhereClause {
  [key: string]: unknown;
}

interface FindManyOptions {
  where?: WhereClause;
  orderBy?: Record<string, 'asc' | 'desc'> | Array<Record<string, 'asc' | 'desc'>>;
  take?: number;
  skip?: number;
  include?: Record<string, boolean>;
  select?: Record<string, boolean>;
}

interface FindUniqueOptions {
  where: WhereClause;
  include?: Record<string, boolean>;
  select?: Record<string, boolean>;
}

interface CreateOptions {
  data: Record<string, unknown>;
  include?: Record<string, boolean>;
  select?: Record<string, boolean>;
}

interface CreateManyOptions {
  data: Array<Record<string, unknown>>;
}

interface UpdateOptions {
  where: WhereClause;
  data: Record<string, unknown>;
  include?: Record<string, boolean>;
  select?: Record<string, boolean>;
}

interface UpdateManyOptions {
  where: WhereClause;
  data: Record<string, unknown>;
}

interface UpsertOptions {
  where: WhereClause;
  update: Record<string, unknown>;
  create: Record<string, unknown>;
  include?: Record<string, boolean>;
  select?: Record<string, boolean>;
}

interface DeleteOptions {
  where: WhereClause;
}

interface DeleteManyOptions {
  where: WhereClause;
}

interface CountOptions {
  where?: WhereClause;
}

// ============================================================
// Collection name mapping (Prisma model → Firestore collection)
// ============================================================

const COLLECTION_MAP: Record<ModelName, string> = {
  class: 'classes',
  student: 'students',
  attendance: 'attendance',
  academicActivity: 'activities',
  waliKelas: 'waliKelas',
  settings: 'settings',
  academicHoliday: 'academicHolidays',
  dateHoliday: 'dateHolidays',
  weeklySchedule: 'weeklySchedules',
  teacher: 'teachers',
};

/**
 * Get the Firestore collection name for a Prisma model name.
 */
function getCollectionName(model: ModelName): string {
  return COLLECTION_MAP[model] || model;
}

// ============================================================
// Document ID resolution
// ============================================================

/**
 * Resolve the document ID for a given model + where clause.
 * Returns undefined for non-unique lookups (findMany uses queries instead).
 *
 * Composite unique constraints (from Prisma schema):
 *   - attendance:    @@unique([studentId, date, hour])    → `${studentId}_${date}_${hour}`
 *   - academicActivity: @@unique([classId, date])         → `${classId}_${date}`
 *   - weeklySchedule: @@unique([classId, dayOfWeek, hour]) → `${classId}_${dayOfWeek}_${hour}`
 *
 * Single-field unique (@unique):
 *   - class.name, student.id (default), waliKelas.classId,
 *     academicHoliday.dayOfWeek, dateHoliday.date, teacher.nickname,
 *     settings.key (@id)
 */
function resolveDocId(model: ModelName, where: WhereClause): string | undefined {
  // Primary ID lookup (id field)
  if (where.id && typeof where.id === 'string') return where.id as string;

  switch (model) {
    case 'settings':
      // @id = key
      if (where.key) return String(where.key);
      break;

    case 'attendance':
      // @@unique([studentId, date, hour])
      if (where.studentId_date_hour) {
        const { studentId, date, hour } = where.studentId_date_hour as {
          studentId: string; date: string; hour: number;
        };
        return `${studentId}_${date}_${hour}`;
      }
      // Single-field lookups (NOT unique — but used for findUnique fallback)
      // If all three fields are present, construct the composite ID
      if (where.studentId && where.date && where.hour !== undefined) {
        return `${where.studentId}_${where.date}_${where.hour}`;
      }
      break;

    case 'academicActivity':
      // @@unique([classId, date])
      if (where.classId_date) {
        const { classId, date } = where.classId_date as { classId: string; date: string };
        return `${classId}_${date}`;
      }
      if (where.classId && where.date) {
        return `${where.classId}_${where.date}`;
      }
      break;

    case 'weeklySchedule':
      // @@unique([classId, dayOfWeek, hour])
      if (where.classId_dayOfWeek_hour) {
        const { classId, dayOfWeek, hour } = where.classId_dayOfWeek_hour as {
          classId: string; dayOfWeek: number; hour: number;
        };
        return `${classId}_${dayOfWeek}_${hour}`;
      }
      if (where.classId && where.dayOfWeek !== undefined && where.hour !== undefined) {
        return `${where.classId}_${where.dayOfWeek}_${where.hour}`;
      }
      break;

    case 'waliKelas':
      // @unique on classId
      if (where.classId) return String(where.classId);
      break;

    case 'academicHoliday':
      // @unique on dayOfWeek
      if (where.dayOfWeek !== undefined) return String(where.dayOfWeek);
      break;

    case 'dateHoliday':
      // @unique on date
      if (where.date) return String(where.date);
      break;

    case 'teacher':
      // @unique on nickname
      if (where.nickname) return String(where.nickname);
      break;

    case 'class':
      // @unique on name (but we use auto-id for primary)
      // For name lookup, use query — can't use as doc ID
      break;

    case 'student':
      // id is @id @default(cuid()) — use where.id
      break;
  }

  return undefined;
}

// ============================================================
// Where clause → Firestore query filters
// ============================================================

/**
 * Convert a Prisma where clause to Firestore query constraints.
 *
 * Prisma operators:
 *   { field: value }           → where('field', '==', value)
 *   { field: { gt: value } }   → where('field', '>', value)
 *   { field: { gte: value } }  → where('field', '>=', value)
 *   { field: { lt: value } }   → where('field', '<', value)
 *   { field: { lte: value } }  → where('field', '<=', value)
 *   { field: { in: [...] } }  → where('field', 'in', [...])
 *   { field: { not: value } } → where('field', '!=', value)
 *
 * Firestore limit: queries can only filter on ONE field with range operators
 * (>, >=, <, <=). Multiple equality filters are fine.
 */
function buildQuery(
  collection: admin.firestore.CollectionReference,
  where?: WhereClause
): admin.firestore.Query {
  let q: admin.firestore.Query = collection;

  if (!where) return q;

  for (const [field, value] of Object.entries(where)) {
    // Skip composite key fields (studentId_date_hour, classId_date, etc.)
    if (field.includes('_') && typeof value === 'object' && value !== null) {
      continue;
    }

    // Skip Prisma relation fields (e.g., where: { student: { id: ... } })
    // — these are handled by include, not by where
    if (typeof value === 'object' && value !== null && !Array.isArray(value) && !(value instanceof Date)) {
      // Check for Prisma operator objects: { gt, gte, lt, lte, in, not, contains }
      const opObj = value as Record<string, unknown>;
      if ('gt' in opObj) { q = q.where(field, '>' as WhereFilterOp, opObj.gt); continue; }
      if ('gte' in opObj) { q = q.where(field, '>=' as WhereFilterOp, opObj.gte); continue; }
      if ('lt' in opObj) { q = q.where(field, '<' as WhereFilterOp, opObj.lt); continue; }
      if ('lte' in opObj) { q = q.where(field, '<=' as WhereFilterOp, opObj.lte); continue; }
      if ('in' in opObj) { q = q.where(field, 'in' as WhereFilterOp, opObj.in); continue; }
      if ('not' in opObj) { q = q.where(field, '!=' as WhereFilterOp, opObj.not); continue; }
      if ('contains' in opObj) {
        // Firestore doesn't have a native "contains" operator.
        // For string contains, we'd need Algolia/Extension or client-side filter.
        // For now, skip (the route should handle this client-side).
        continue;
      }
      // If it's a relation object (e.g., { student: { select: ... } }), skip
      continue;
    }

    // Plain equality: { field: value }
    q = q.where(field, '==' as WhereFilterOp, value);
  }

  return q;
}

// ============================================================
// Data serialization (Date → ISO string and back)
// ============================================================

/**
 * Convert Firestore document data to app-level format.
 * Firestore Timestamp → ISO string (to match Prisma's DateTime serialization).
 */
function deserializeDoc(doc: admin.firestore.DocumentSnapshot): Record<string, unknown> | null {
  if (!doc.exists) return null;
  const data = doc.data() || {};

  // Convert Firestore Timestamps to ISO strings (Prisma returns Date objects
  // but JSON serialization converts them to ISO strings anyway)
  const result: Record<string, unknown> = { id: doc.id };
  for (const [key, value] of Object.entries(data)) {
    if (value && typeof value.toDate === 'function') {
      // Firestore Timestamp
      result[key] = value.toDate().toISOString();
    } else if (value && typeof value === 'object' && '_seconds' in value) {
      // Raw timestamp object
      result[key] = new Date(value._seconds * 1000).toISOString();
    } else {
      result[key] = value;
    }
  }
  return result;
}

/**
 * Prepare data for writing to Firestore.
 * Converts Date objects to Firestore Timestamps.
 */
function serializeData(data: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(data)) {
    if (value instanceof Date) {
      // Convert Date to Firestore Timestamp
      result[key] = firestore.Timestamp.fromDate(value);
    } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      // Recursively serialize nested objects (but not arrays)
      result[key] = serializeData(value as Record<string, unknown>);
    } else {
      result[key] = value;
    }
  }
  return result;
}

/**
 * Add createdAt/updatedAt timestamps if not present.
 * Prisma uses @default(now()) and @updatedAt — Firestore needs manual handling.
 */
function addTimestamps(
  data: Record<string, unknown>,
  isUpdate: boolean
): Record<string, unknown> {
  const now = new Date();
  const serialized = serializeData(data);
  if (!isUpdate && !serialized.createdAt) {
    serialized.createdAt = now.toISOString();
  }
  // Always update updatedAt
  serialized.updatedAt = now.toISOString();
  return serialized;
}

// ============================================================
// Model adapter class
// ============================================================

class ModelAdapter {
  constructor(private model: ModelName) {}

  private get collection(): admin.firestore.CollectionReference {
    const db = getFirestore();
    return db.collection(getCollectionName(this.model));
  }

  // ===== findMany =====
  async findMany(options: FindManyOptions = {}): Promise<Record<string, unknown>[]> {
    let q = buildQuery(this.collection, options.where);

    // orderBy
    if (options.orderBy) {
      const orderBys = Array.isArray(options.orderBy) ? options.orderBy : [options.orderBy];
      for (const ob of orderBys) {
        for (const [field, direction] of Object.entries(ob)) {
          // Skip nested orderBy (e.g., { student: { name: 'asc' } })
          // — would need a separate query + client-side sort
          if (field.includes('.')) continue;
          q = q.orderBy(field, direction as 'asc' | 'desc');
        }
      }
    }

    // take (limit)
    if (options.take) q = q.limit(options.take);

    // skip (offset) — Firestore doesn't have native offset, use startAfter
    // For simplicity, use offset() (works but loads skipped docs — OK for small skip)
    if (options.skip) q = (q as admin.firestore.Query).offset(options.skip);

    const snapshot: QuerySnapshot = await q.get();
    let results = snapshot.docs.map(d => deserializeDoc(d)).filter(Boolean) as Record<string, unknown>[];

    // Handle includes (1-level only — like Prisma's include: { student: true })
    if (options.include) {
      results = await this.addIncludes(results, options.include);
    }

    // Handle select (filter fields)
    if (options.select) {
      results = results.map(r => this.applySelect(r, options.select!));
    }

    return results;
  }

  // ===== findUnique =====
  async findUnique(options: FindUniqueOptions): Promise<Record<string, unknown> | null> {
    const docId = resolveDocId(this.model, options.where);
    if (docId) {
      const doc = await this.collection.doc(docId).get();
      let result = deserializeDoc(doc);
      if (!result) return null;
      if (options.include) {
        const arr = await this.addIncludes([result], options.include);
        result = arr[0];
      }
      if (options.select) {
        result = this.applySelect(result, options.select);
      }
      return result;
    }

    // Fallback: if no doc ID resolved, use findFirst
    return this.findFirst({ where: options.where, include: options.include, select: options.select });
  }

  // ===== findFirst =====
  async findFirst(options: FindManyOptions = {}): Promise<Record<string, unknown> | null> {
    const results = await this.findMany({ ...options, take: 1 });
    return results[0] || null;
  }

  // ===== count =====
  async count(options: CountOptions = {}): Promise<number> {
    const q = buildQuery(this.collection, options.where);
    const snapshot: QuerySnapshot = await q.get();
    // For large collections, use aggregate count (Firestore supports this since 2023)
    // snapshot.size() loads all docs — for very large collections, use:
    //   const count = await db.collection('attendance').count().get();
    // But for compatibility, use size()
    return snapshot.size;
  }

  // ===== create =====
  async create(options: CreateOptions): Promise<Record<string, unknown>> {
    const data = addTimestamps(options.data, false);
    const docId = resolveDocId(this.model, options.data as WhereClause)
      || this.collection.doc().id; // auto-generate ID
    await this.collection.doc(docId).set(data);
    const result = { id: docId, ...data } as Record<string, unknown>;
    if (options.include) {
      const arr = await this.addIncludes([result], options.include);
      return arr[0];
    }
    if (options.select) {
      return this.applySelect(result, options.select);
    }
    return result;
  }

  // ===== createMany =====
  async createMany(options: CreateManyOptions): Promise<{ count: number }> {
    const db = getFirestore();
    const batchSize = 450; // Firestore batch limit is 500
    let totalCreated = 0;

    for (let i = 0; i < options.data.length; i += batchSize) {
      const batch = db.batch();
      const chunk = options.data.slice(i, i + batchSize);
      for (const item of chunk) {
        const data = addTimestamps(item, false);
        const docId = resolveDocId(this.model, item as WhereClause) || this.collection.doc().id;
        const ref = this.collection.doc(docId);
        batch.set(ref, data);
      }
      await batch.commit();
      totalCreated += chunk.length;
    }

    return { count: totalCreated };
  }

  // ===== update =====
  async update(options: UpdateOptions): Promise<Record<string, unknown>> {
    const docId = resolveDocId(this.model, options.where);
    if (!docId) {
      throw new Error(`Cannot resolve doc ID for update on ${this.model}: ${JSON.stringify(options.where)}`);
    }
    const data = addTimestamps(options.data, true);
    const ref = this.collection.doc(docId);
    await ref.update(data);
    const doc = await ref.get();
    let result = deserializeDoc(doc);
    if (result && options.include) {
      const arr = await this.addIncludes([result], options.include);
      result = arr[0];
    }
    if (result && options.select) {
      result = this.applySelect(result, options.select);
    }
    return result || { id: docId, ...data };
  }

  // ===== updateMany =====
  async updateMany(options: UpdateManyOptions): Promise<{ count: number }> {
    const q = buildQuery(this.collection, options.where);
    const snapshot: QuerySnapshot = await q.get();
    if (snapshot.empty) return { count: 0 };

    const db = getFirestore();
    const batchSize = 450;
    const data = addTimestamps(options.data, true);
    let totalUpdated = 0;

    for (let i = 0; i < snapshot.docs.length; i += batchSize) {
      const batch = db.batch();
      const chunk = snapshot.docs.slice(i, i + batchSize);
      for (const doc of chunk) {
        batch.update(doc.ref, data);
      }
      await batch.commit();
      totalUpdated += chunk.length;
    }

    return { count: totalUpdated };
  }

  // ===== upsert =====
  async upsert(options: UpsertOptions): Promise<Record<string, unknown>> {
    const docId = resolveDocId(this.model, options.where);
    if (!docId) {
      throw new Error(`Cannot resolve doc ID for upsert on ${this.model}: ${JSON.stringify(options.where)}`);
    }
    const ref = this.collection.doc(docId);
    const doc = await ref.get();

    if (doc.exists) {
      // Update path
      const data = addTimestamps(options.update, true);
      await ref.update(data);
    } else {
      // Create path
      const data = addTimestamps(options.create, false);
      await ref.set(data);
    }

    const newDoc = await ref.get();
    let result = deserializeDoc(newDoc);
    if (result && options.include) {
      const arr = await this.addIncludes([result], options.include);
      result = arr[0];
    }
    if (result && options.select) {
      result = this.applySelect(result, options.select);
    }
    return result || { id: docId };
  }

  // ===== delete =====
  async delete(options: DeleteOptions): Promise<Record<string, unknown>> {
    const docId = resolveDocId(this.model, options.where);
    if (!docId) {
      throw new Error(`Cannot resolve doc ID for delete on ${this.model}: ${JSON.stringify(options.where)}`);
    }
    const ref = this.collection.doc(docId);
    const doc = await ref.get();
    const result = deserializeDoc(doc);
    await ref.delete();
    return result || { id: docId };
  }

  // ===== deleteMany =====
  async deleteMany(options: DeleteManyOptions): Promise<{ count: number }> {
    const q = buildQuery(this.collection, options.where);
    const snapshot: QuerySnapshot = await q.get();
    if (snapshot.empty) return { count: 0 };

    const db = getFirestore();
    const batchSize = 450;
    let totalDeleted = 0;

    for (let i = 0; i < snapshot.docs.length; i += batchSize) {
      const batch = db.batch();
      const chunk = snapshot.docs.slice(i, i + batchSize);
      for (const doc of chunk) {
        batch.delete(doc.ref);
      }
      await batch.commit();
      totalDeleted += chunk.length;
    }

    return { count: totalDeleted };
  }

  // ===== Helper: addIncludes (1-level relations) =====
  private async addIncludes(
    results: Record<string, unknown>[],
    include: Record<string, boolean>
  ): Promise<Record<string, unknown>[]> {
    if (results.length === 0) return results;

    for (const [relation, enabled] of Object.entries(include)) {
      if (!enabled) continue;

      // Map relation name to model + foreign key
      const { model: relModel, fk } = this.getRelationInfo(relation);
      if (!relModel || !fk) continue;

      // Collect all foreign keys from results
      const foreignKeys = new Set<string>();
      for (const r of results) {
        const fkValue = r[fk];
        if (typeof fkValue === 'string') foreignKeys.add(fkValue);
      }
      if (foreignKeys.size === 0) continue;

      // Batch fetch related docs (Firestore 'in' query — max 10 per query)
      const fkArray = Array.from(foreignKeys);
      const relCollection = getCollectionName(relModel as ModelName);
      const db = getFirestore();

      // Firestore 'in' query supports max 10 values — chunk if needed
      const relatedDocs: Record<string, Record<string, unknown>> = {};
      for (let i = 0; i < fkArray.length; i += 10) {
        const chunk = fkArray.slice(i, i + 10);
        const q = db.collection(relCollection).where('id', 'in', chunk);
        // Note: 'id' field doesn't work in Firestore — need to query by doc ID
        // Instead, fetch each doc by ID
        for (const id of chunk) {
          const doc = await db.collection(relCollection).doc(id).get();
          if (doc.exists) {
            relatedDocs[id] = deserializeDoc(doc)!;
          }
        }
      }

      // Attach related data to results
      for (const r of results) {
        const fkValue = r[fk] as string;
        if (fkValue && relatedDocs[fkValue]) {
          r[relation] = relatedDocs[fkValue];
        }
      }
    }

    return results;
  }

  // ===== Helper: getRelationInfo =====
  private getRelationInfo(relation: string): { model?: string; fk?: string } {
    // Map relation names to their target model + foreign key field
    const relations: Record<string, { model: string; fk: string }> = {
      // From Attendance
      student: { model: 'student', fk: 'studentId' },
      class: { model: 'class', fk: 'classId' },
      // From Student
      attendance: { model: 'attendance', fk: 'studentId' }, // reverse — needs special handling
      // From Class
      students: { model: 'student', fk: 'classId' },
      // From AcademicActivity
      // (class relation already covered above)
      // From WeeklySchedule
      // (class relation already covered above)
      // From WaliKelas
      // (class relation already covered above)
    };
    return relations[relation] || {};
  }

  // ===== Helper: applySelect =====
  private applySelect(
    data: Record<string, unknown>,
    select: Record<string, boolean>
  ): Record<string, unknown> {
    const result: Record<string, unknown> = { id: data.id };
    for (const [field, enabled] of Object.entries(select)) {
      if (enabled && field in data) {
        result[field] = data[field];
      }
    }
    return result;
  }
}

// ============================================================
// Transaction support
// ============================================================

/**
 * Firestore batch transaction.
 *
 * Prisma's $transaction supports two forms:
 *   1. Array of promises:  db.$transaction([promise1, promise2])
 *   2. Callback:            db.$transaction(async (tx) => { await tx.model.create() })
 *
 * Firestore equivalent:
 *   1. Array → use writeBatch() — but only supports set/update/delete (no reads)
 *   2. Callback → use runTransaction() — supports reads + writes
 *
 * For the adapter, we support BOTH forms.
 */
async function $transaction<T>(
  arg: Promise<any>[] | ((tx: TransactionContext) => Promise<T>)
): Promise<T> {
  const db = getFirestore();

  // Form 2: Callback (interactive transaction)
  if (typeof arg === 'function') {
    return db.runTransaction(async (tx) => {
      const ctx = new TransactionContext(tx, db);
      return arg(ctx);
    });
  }

  // Form 1: Array of promises (just await all — not truly atomic in Firestore)
  // For true atomicity, routes should use Form 2 (callback) instead
  const results = await Promise.all(arg);
  return results as T;
}

/**
 * Transaction context — provides a `db`-like interface inside transactions.
 * Limited to set/update/delete (Firestore transaction API).
 */
class TransactionContext {
  constructor(
    private tx: admin.firestore.Transaction,
    private db: Firestore
  ) {}

  // Provides db.model.create() etc. inside transaction
  // (limited — Firestore transactions only support get/set/update/delete)
  get class() { return this.createModelOps('class'); }
  get student() { return this.createModelOps('student'); }
  get attendance() { return this.createModelOps('attendance'); }
  get academicActivity() { return this.createModelOps('academicActivity'); }
  get waliKelas() { return this.createModelOps('waliKelas'); }
  get settings() { return this.createModelOps('settings'); }
  get academicHoliday() { return this.createModelOps('academicHoliday'); }
  get dateHoliday() { return this.createModelOps('dateHoliday'); }
  get weeklySchedule() { return this.createModelOps('weeklySchedule'); }
  get teacher() { return this.createModelOps('teacher'); }

  private createModelOps(model: ModelName) {
    const collection = this.db.collection(getCollectionName(model));
    const txRef = this.tx;
    return {
      async create({ data }: CreateOptions) {
        const docId = resolveDocId(model, data as WhereClause) || collection.doc().id;
        const serialized = addTimestamps(data, false);
        txRef.set(collection.doc(docId), serialized);
        return { id: docId, ...serialized };
      },
      async update({ where, data }: UpdateOptions) {
        const docId = resolveDocId(model, where);
        if (!docId) throw new Error(`Cannot resolve doc ID in transaction for ${model}`);
        const serialized = addTimestamps(data, true);
        txRef.update(collection.doc(docId), serialized);
        return { id: docId, ...serialized };
      },
      async upsert({ where, update, create: createData }: UpsertOptions) {
        const docId = resolveDocId(model, where);
        if (!docId) throw new Error(`Cannot resolve doc ID in transaction for ${model}`);
        const ref = collection.doc(docId);
        const doc = await txRef.get(ref);
        if (doc.exists) {
          const serialized = addTimestamps(update, true);
          txRef.update(ref, serialized);
          return { id: docId, ...serialized };
        } else {
          const serialized = addTimestamps(createData, false);
          txRef.set(ref, serialized);
          return { id: docId, ...serialized };
        }
      },
      async delete({ where }: DeleteOptions) {
        const docId = resolveDocId(model, where);
        if (!docId) throw new Error(`Cannot resolve doc ID in transaction for ${model}`);
        txRef.delete(collection.doc(docId));
        return { id: docId };
      },
    };
  }
}

// ============================================================
// Main db object — drop-in replacement for Prisma's db
// ============================================================

export const db = {
  // Models (Prisma model names → adapter instances)
  class: new ModelAdapter('class'),
  student: new ModelAdapter('student'),
  attendance: new ModelAdapter('attendance'),
  academicActivity: new ModelAdapter('academicActivity'),
  waliKelas: new ModelAdapter('waliKelas'),
  settings: new ModelAdapter('settings'),
  academicHoliday: new ModelAdapter('academicHoliday'),
  dateHoliday: new ModelAdapter('dateHoliday'),
  weeklySchedule: new ModelAdapter('weeklySchedule'),
  teacher: new ModelAdapter('teacher'),

  // Transaction support
  $transaction,

  // Raw query support — NOT NEEDED for Firestore (no pragmas, no VACUUM)
  // But provide stubs so existing code doesn't crash at import time
  $queryRawUnsafe: async (_sql: string) => {
    console.warn('[Firebase-DB] $queryRawUnsafe is a no-op (Firestore has no SQL pragmas)');
    return [];
  },
  $executeRawUnsafe: async (_sql: string) => {
    console.warn('[Firebase-DB] $executeRawUnsafe is a no-op (Firestore has no SQL pragmas)');
    return 0;
  },
};

export type Database = typeof db;
