 *
 * Method 2 — key file path (recommended for local dev):
 *   FIREBASE_KEY_PATH=/path/to/absensi-firebase-key.json
 *
 * If neither is set, the module logs a warning and Firestore operations
 * will throw. This is intentional — fail fast so misconfiguration is visible.
 */

import admin from 'firebase-admin';

const globalForFirebase = globalThis as unknown as {
  firebaseApp: admin.app.App | undefined;
  firebaseInitError: string | undefined;
};

interface ServiceAccountCreds {
  projectId: string;
  clientEmail: string;
  privateKey: string;
}

/**
 * Resolve Firebase credentials from environment.
 * Priority: FIREBASE_KEY_PATH > individual FIREBASE_* env vars
 */
function getCredentials(): ServiceAccountCreds | undefined {
  // Method 1: Use key file path (preferred for production — file is mounted)
  const keyPath = process.env.FIREBASE_KEY_PATH;
  if (keyPath) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const key = require(keyPath);
      if (key.project_id && key.client_email && key.private_key) {
        return {
          projectId: key.project_id,
          clientEmail: key.client_email,
          privateKey: key.private_key,
        };
      }
      console.warn('[Firebase] Key file missing required fields:', keyPath);
    } catch (e) {
      console.warn('[Firebase] Could not load key file at', keyPath, ':', e instanceof Error ? e.message : String(e));
    }
  }

  // Method 2: Use individual env vars
  const projectId = process.env.FIREBASE_PROJECT_ID;
  const clientEmail = process.env.FIREBASE_CLIENT_EMAIL;
  const privateKey = process.env.FIREBASE_PRIVATE_KEY;

  if (projectId && clientEmail && privateKey) {
    // Private key from env var has literal \n — convert to real newlines
    return {
      projectId,
      clientEmail,
      privateKey: privateKey.replace(/\\n/g, '\n'),
    };
  }

  return undefined;
}

/**
 * Initialize Firebase Admin SDK ONCE per process.
 * Cached in globalThis to survive HMR in dev.
 */
function initializeFirebase(): admin.app.App | undefined {
  if (globalForFirebase.firebaseApp) return globalForFirebase.firebaseApp;
  if (globalForFirebase.firebaseInitError) return undefined;

  try {
    const credentials = getCredentials();
    if (!credentials) {
      const msg = '[Firebase] No credentials found. Set FIREBASE_KEY_PATH or FIREBASE_PROJECT_ID + FIREBASE_CLIENT_EMAIL + FIREBASE_PRIVATE_KEY in .env';
      console.warn(msg);
      globalForFirebase.firebaseInitError = msg;
      return undefined;
    }

    globalForFirebase.firebaseApp = admin.initializeApp({
      credential: admin.cert({
        projectId: credentials.projectId,
        clientEmail: credentials.clientEmail,
        privateKey: credentials.privateKey,
      }),
      projectId: credentials.projectId,
    });

    // Configure Firestore settings for better performance
    const db = globalForFirebase.firebaseApp.firestore();
    db.settings({
      // PreferRecent means reads prefer cached data when offline
      // (not needed for server-side, but harmless)
      ignoreUndefinedProperties: true,
    });

    console.log('[Firebase] Admin SDK initialized for project:', credentials.projectId);
    return globalForFirebase.firebaseApp;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[Firebase] Initialization failed:', msg);
    globalForFirebase.firebaseInitError = msg;
    return undefined;
  }
}

// Initialize on module load
initializeFirebase();

export const firebaseApp = globalForFirebase.firebaseApp;
export const firestoreDb = globalForFirebase.firebaseApp?.firestore();

/**
 * Get the Firestore instance (throws if not initialized).
 * Use this in API routes to ensure Firebase is available.
 */
export function getFirestore(): admin.firestore.Firestore {
  if (!firestoreDb) {
    throw new Error(
      'Firebase Firestore not initialized. ' +
      (globalForFirebase.firebaseInitError || 'Check FIREBASE_* env vars.')
    );
  }
  return firestoreDb;
}

/**
 * Check if Firebase is available (non-throwing).
 * Useful for feature-flagging during migration.
 */
export function isFirebaseAvailable(): boolean {
  return firestoreDb !== undefined;
}
"},{"path":"src/lib/generate-rekap-pdf.ts","content":"import PDFDocument from 'pdfkit';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTH_NAMES = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];

type DayStatus = 'Hadir' | 'Terlambat' | 'Alfa' | 'Sakit' | 'Izin';

// Status symbols are drawn programmatically using PDFKit vector API (see drawStatusSymbol)

const STATUS_COLORS: Record<DayStatus, [number, number, number]> = {
  Hadir: [5, 150, 105],
  Terlambat: [234, 88, 12],
  Alfa: [220, 38, 38],
  Sakit: [8, 145, 178],
  Izin: [202, 138, 4],
};

const KETERANGAN_ORDER: DayStatus[] = ['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];

// F4 paper (Indonesian standard): 215mm x 330mm
const PAGE_W = 609.55;
const PAGE_H = 935.55;
const ML = 42.55;
const MR = 35.45;
const MT = 28.35;
const MB = 28.35;
const CW = PAGE_W - ML - MR;

// Table column widths (in points, matching template twips)
// 7 columns: Hari | Tanggal | Masuk | Terlambat | Alfa | Sakit | Izin
// (Hari and Tanggal are now SEPARATE columns — no longer merged)
const COL_W = [50, 112, 71.65, 70.9, 67.8, 66.85, 63.8];
const TOTAL_COL_W = COL_W.reduce((a, b) => a + b, 0);
const TABLE_LEFT = ML + (CW - TOTAL_COL_W) / 2;

const ROW_H = 22;
const HEADER_H = 20;
const TOTAL_ROW_H = 24;
const MAX_ROWS_PER_PAGE = 22;
const HEADER_BG = '#99FF33';

// Vertical centering helper
function vCenter(rowY: number, rowH: number, fontSize: number): number {
  return rowY + (rowH - fontSize * 0.75) / 2;
}

function drawStatusSymbol(doc: PDFKit.PDFDocument, status: DayStatus, cx: number, cy: number, size: number) {
  // cx, cy = center of the cell, size = half-width of the symbol
  const rgb = STATUS_COLORS[status];
  const colorArr: [number, number, number] = [rgb[0], rgb[1], rgb[2]];
  const halfSize = size / 2;

  switch (status) {
    case 'Hadir':
      // Green checkmark - draw a check shape with lines
      doc.strokeColor(colorArr).lineWidth(2.5).lineJoin('round').lineCap('round');
      doc.moveTo(cx - halfSize * 0.5, cy)
        .lineTo(cx - halfSize * 0.1, cy + halfSize * 0.4)
        .lineTo(cx + halfSize * 0.5, cy - halfSize * 0.4)
        .stroke();
      break;
    case 'Terlambat':
      // Orange clock - draw a circle with two clock hands
      doc.circle(cx, cy, halfSize * 0.5).strokeColor(colorArr).lineWidth(1.5).stroke();
      doc.strokeColor(colorArr).lineWidth(1.5).lineCap('round');
      // Hour hand (pointing up)
      doc.moveTo(cx, cy).lineTo(cx, cy - halfSize * 0.35).stroke();
      // Minute hand (pointing right)
      doc.moveTo(cx, cy).lineTo(cx + halfSize * 0.3, cy).stroke();
      break;
    case 'Alfa':
      // Red X mark - draw two crossing lines
      doc.strokeColor(colorArr).lineWidth(2.5).lineCap('round');
      doc.moveTo(cx - halfSize * 0.4, cy - halfSize * 0.4)
        .lineTo(cx + halfSize * 0.4, cy + halfSize * 0.4).stroke();
      doc.moveTo(cx + halfSize * 0.4, cy - halfSize * 0.4)
        .lineTo(cx - halfSize * 0.4, cy + halfSize * 0.4).stroke();
      break;
    case 'Sakit':
      // Blue medical cross (+)
      doc.strokeColor(colorArr).lineWidth(2.5).lineCap('round');
      doc.moveTo(cx - halfSize * 0.4, cy).lineTo(cx + halfSize * 0.4, cy).stroke();
      doc.moveTo(cx, cy - halfSize * 0.4).lineTo(cx, cy + halfSize * 0.4).stroke();
      break;
    case 'Izin':
      // Yellow envelope/letter - draw a rectangle with a V flap
      doc.strokeColor(colorArr).lineWidth(1.5).lineJoin('round');
      const w = halfSize * 0.8, h = halfSize * 0.6;
      doc.rect(cx - w, cy - h * 0.5, w * 2, h * 1.2).stroke();
      // V flap on top
      doc.moveTo(cx - w, cy - h * 0.5)
        .lineTo(cx, cy + h * 0.2)
        .lineTo(cx + w, cy - h * 0.5).stroke();
      break;
  }
}

function formatDateIndo(dateStr: string): string {
  const [y, m, d] = dateStr.split('-').map(Number);
  return `${d} ${MONTH_NAMES[m - 1]} ${y}`;
}

export interface DayResultData {
  date: string;
  dayName: string;
  status: DayStatus | null;
}

export interface HolidayInfo {
  date: string;
  dayName: string;
  name: string;
}

export function generateRekapPdf(
  student: { name: string; nisn: string; gender: string },
  classData: { name: string },
  dayResults: DayResultData[],
  logoBuf: Buffer | null,
  qrBuf: Buffer | null,
  holidays: HolidayInfo[] = [],
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: [PAGE_W, PAGE_H],
      margins: { top: MT, bottom: MB, left: ML, right: MR },
      bufferPages: true,
      info: {
        Title: `Rekap Absensi - ${student.name}`,
        Author: 'MTs Al Ishlah',
      },
    });


    const chunks: Uint8Array[] = [];
    doc.on('data', (chunk: Uint8Array) => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    // ====== KOP (header) ======
    const kopTop = MT + 5;
    const kopLineW = TOTAL_COL_W;

    // School logo on the left side of header
    const LOGO_W = 74;
    const LOGO_H = 72;
    let y = kopTop + 8;
    if (logoBuf) {
      const kopTextH = 14 + 16 + 11 + 11 + 11 + 11 + 12;
      const logoY = kopTop + (kopTextH - LOGO_H) / 2 + 8;
      try {
        doc.image(logoBuf, TABLE_LEFT + 2, logoY, { width: LOGO_W, height: LOGO_H });
      } catch { /* skip */ }
    }

    // Top border line
    doc.moveTo(TABLE_LEFT, kopTop).lineTo(TABLE_LEFT + kopLineW, kopTop)
      .strokeColor('#000000').lineWidth(1.5).stroke();

    // Kop text
    const kopTextLeft = TABLE_LEFT;
    const kopTextW = kopLineW;

    doc.font('Helvetica').fontSize(9).fillColor('#000000');
    doc.text('YAYASAN LEMBAGA PENDIDIKAN', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 14;

    doc.font('Helvetica-Bold').fontSize(13);
    doc.text('MADRASAH TSANAWIYAH AL ISHLAH', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 16;

    doc.font('Helvetica').fontSize(7).fillColor('#444444');
    doc.text('NSM : 121235060089     NPSN : 20581159     Nomor AHU-0013757.AH.01.04.Tahun2019', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 11;

    doc.text('Akta Notaris : Fibrianto Bimo Setiawan S.H., M.Kn. No. 08-20-2019', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 11;

    doc.text('Email : mtsalishlah89@gmail.com     Web : http://mtsalishlah.sch.id', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 11;

    doc.text('Alamat : Rt.012/Rw.002 Dsn. Dlopo \u2013 Ds. Karangrejo \u2013 Kec. Ngasem \u2013 Kab. Kediri \u2013 Jawa Timur', kopTextLeft, y, { width: kopTextW, align: 'center' });
    y += 18;

    // Bottom border line (double line)
    doc.moveTo(TABLE_LEFT, y).lineTo(TABLE_LEFT + kopLineW, y)
      .strokeColor('#000000').lineWidth(1.5).stroke();
    y += 3;
    doc.moveTo(TABLE_LEFT, y).lineTo(TABLE_LEFT + kopLineW, y)
      .strokeColor('#000000').lineWidth(1.5).stroke();
    y += 12;

    // ====== TITLE ======
    doc.font('Helvetica-Bold').fontSize(14).fillColor('#000000');
    doc.text('REKAPITULASI ABSENSI SISWA', ML, y, { width: CW, align: 'center' });
    y += 22;

    // ====== STUDENT INFO (borderless table, aligned with table/kop) ======
    // Left edge = TABLE_LEFT, total width = TOTAL_COL_W
    // Layout: [Label1] [:] [Value1] | [Label2] [:] [Value2]
    // Row 1: Nama : studentName    Kelas : className
    // Row 2: NISN  : nisnValue      Jenis Kelamin : genderValue
    const infoFS = 12;
    const infoRowH = 20;
    const infoHalfW = TOTAL_COL_W / 2;

    // Left section column positions (start at TABLE_LEFT)
    const lLabelW = 55;  // width for "Nama", "NISN"
    const lColonW = 12;  // width for ":"
    // Right column (Kelas, Jenis Kelamin) AND signature block — all left-aligned.
    // The block must be wide enough to fit "Rohmat Agung W., S.Pd.I" (Helvetica-Bold 12
    // = ~141.6pt) on a SINGLE line, with a small safety margin so PDFKit does
    // not wrap it. The block is shifted so its right edge almost touches the
    // right margin (PAGE_W - MR). Because the block is wider than before, its
    // left edge (rStartX) moves further LEFT, which is the requested shift.
    // All text inside is left-aligned and shares the same left edge so the
    // whole column stays vertically aligned.
    const SIGN_BLOCK_W = 160; // fits "Rohmat Agung W., S.Pd.I" + safety padding (no wrap)
    const rStartX = (PAGE_W - MR) - SIGN_BLOCK_W - 2;
    // Info-row layout inside the block: [Label][ : ][Value]
    // Labels ("Kelas", "Jenis Kelamin") are left-aligned at rStartX.
    const rLabelW = 80;  // width for "Jenis Kelamin" (longest label)
    const rColonW = 10;  // width for ":"

    doc.font('Helvetica').fontSize(infoFS).fillColor('#000000');

    // Row 1
    const r1vc = vCenter(y, infoRowH, infoFS);
    // Left: Nama | : | student.name
    doc.text('Nama', TABLE_LEFT, r1vc, { width: lLabelW, align: 'left' });
    doc.text(':', TABLE_LEFT + lLabelW, r1vc, { width: lColonW, align: 'left' });
    doc.text(student.name, TABLE_LEFT + lLabelW + lColonW, r1vc, { width: infoHalfW - lLabelW - lColonW, align: 'left' });
    // Right: Kelas | : | classData.name
    doc.text('Kelas', rStartX, r1vc, { width: rLabelW, align: 'left' });
    doc.text(':', rStartX + rLabelW, r1vc, { width: rColonW, align: 'left' });
    doc.text(classData.name, rStartX + rLabelW + rColonW, r1vc, { width: SIGN_BLOCK_W - rLabelW - rColonW, align: 'left' });
    y += infoRowH;

    // Row 2
    const r2vc = vCenter(y, infoRowH, infoFS);
    // Left: NISN | : | nisn
    doc.text('NISN', TABLE_LEFT, r2vc, { width: lLabelW, align: 'left' });
    doc.text(':', TABLE_LEFT + lLabelW, r2vc, { width: lColonW, align: 'left' });
    doc.text(student.nisn || '-', TABLE_LEFT + lLabelW + lColonW, r2vc, { width: infoHalfW - lLabelW - lColonW, align: 'left' });
    // Right: Jenis Kelamin | : | gender
    doc.text('Jenis Kelamin', rStartX, r2vc, { width: rLabelW, align: 'left' });
    doc.text(':', rStartX + rLabelW, r2vc, { width: rColonW, align: 'left' });
    doc.text(student.gender || '-', rStartX + rLabelW + rColonW, r2vc, { width: SIGN_BLOCK_W - rLabelW - rColonW, align: 'left' });
    y += infoRowH + 5;

    // ====== TABLE ======
    const tableTop = y;
    const colX: number[] = [];
    let runX = TABLE_LEFT;
    for (const w of COL_W) { colX.push(runX); runX += w; }

    // Paginate
    const numDataRows = dayResults.length;
    const pages: number[][] = [];
    for (let i = 0; i < numDataRows; i += MAX_ROWS_PER_PAGE) {
      pages.push(Array.from({ length: Math.min(MAX_ROWS_PER_PAGE, numDataRows - i) }, (_, j) => i + j));
    }

    const totals: Record<DayStatus, number> = { Hadir: 0, Terlambat: 0, Alfa: 0, Sakit: 0, Izin: 0 };
    for (const r of dayResults) { if (r.status) totals[r.status]++; }

    for (let pi = 0; pi < pages.length; pi++) {
      if (pi > 0) doc.addPage({ size: [PAGE_W, PAGE_H], margins: { top: MT, bottom: MB, left: ML, right: MR } });

      const pRows = pages[pi];
      const cTableTop = pi === 0 ? tableTop : MT + 10;
      const cHeaderEnd = cTableTop + HEADER_H * 2;
      const cDataStartY = cHeaderEnd;
      const isLastPage = pi === pages.length - 1;
      const cTableBottom = cDataStartY + pRows.length * ROW_H + (isLastPage ? TOTAL_ROW_H : 0);

      // Green background for header rows
      doc.rect(TABLE_LEFT + 0.5, cTableTop + 0.5, TOTAL_COL_W - 1, HEADER_H * 2 - 1)
        .fillColor(HEADER_BG).fill();

      // Draw outer border
      doc.rect(TABLE_LEFT, cTableTop, TOTAL_COL_W, cTableBottom - cTableTop)
        .strokeColor('#000000').lineWidth(1).stroke();

      // Header row separator (after row 0) - only for Keterangan columns (cols 2-6)
      doc.moveTo(colX[2], cTableTop + HEADER_H).lineTo(TABLE_LEFT + TOTAL_COL_W, cTableTop + HEADER_H).stroke();

      // Sub-header row separator (after row 1)
      doc.moveTo(TABLE_LEFT, cHeaderEnd).lineTo(TABLE_LEFT + TOTAL_COL_W, cHeaderEnd).stroke();

      // Vertical lines for all columns
      for (let ci = 1; ci < COL_W.length; ci++) {
        doc.moveTo(colX[ci], cTableTop).lineTo(colX[ci], cTableBottom).stroke();
      }

      // Data row separators
      for (let r = 0; r < pRows.length; r++) {
        const ry = cDataStartY + (r + 1) * ROW_H;
        doc.moveTo(TABLE_LEFT, ry).lineTo(TABLE_LEFT + TOTAL_COL_W, ry).stroke();
      }

      // Total row separators (thicker)
      if (isLastPage) {
        const totalRY = cDataStartY + pRows.length * ROW_H;
        doc.moveTo(TABLE_LEFT, totalRY).lineTo(TABLE_LEFT + TOTAL_COL_W, totalRY).lineWidth(1.5).stroke();
        doc.lineWidth(1);
        doc.moveTo(TABLE_LEFT, totalRY + TOTAL_ROW_H).lineTo(TABLE_LEFT + TOTAL_COL_W, totalRY + TOTAL_ROW_H).lineWidth(1.5).stroke();
        doc.lineWidth(1);
      }

      // Remove vertical lines in merged header cells
      // Erase vertical lines for merged "Keterangan" (cols 3-6 in row 0)
      doc.strokeColor(HEADER_BG).lineWidth(2);
      for (let ci = 3; ci <= 6; ci++) {
        doc.moveTo(colX[ci], cTableTop).lineTo(colX[ci], cTableTop + HEADER_H).stroke();
      }
      doc.strokeColor('#000000').lineWidth(1);

      // ====== HEADER ROW 1 (Hari | Tanggal | Keterangan spanning 5 cols) ======
      // Hari and Tanggal are now SEPARATE columns, each spanning both header rows.
      doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
      const mergedVC = vCenter(cTableTop, HEADER_H * 2, 9);
      // "Hari" centered vertically across 2 header rows
      doc.text('Hari', colX[0] + 2, mergedVC, { width: COL_W[0] - 4, align: 'center' });
      // "Tanggal" centered vertically across 2 header rows (separate column now)
      doc.text('Tanggal', colX[1] + 2, mergedVC, { width: COL_W[1] - 4, align: 'center' });
      // "Keterangan" in row 0 only
      const h1VC = vCenter(cTableTop, HEADER_H, 9);
      const ketW = colX[6] + COL_W[6] - colX[2];
      doc.text('Keterangan', colX[2] + 2, h1VC, { width: ketW - 4, align: 'center' });

      // ====== HEADER ROW 2 (Masuk, Terlambat, Alfa, Sakit, Izin) - BOLD ======
      doc.font('Helvetica-Bold').fontSize(9);
      const h2VC = vCenter(cTableTop + HEADER_H, HEADER_H, 9);
      // Sub-headers
      for (let j = 0; j < 5; j++) {
        const labels = ['Masuk', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];
        doc.text(labels[j], colX[j + 2] + 2, h2VC, { width: COL_W[j + 2] - 4, align: 'center' });
      }

      // ====== DATA ROWS ======
      for (let r = 0; r < pRows.length; r++) {
        const di = pRows[r];
        const { date, dayName, status } = dayResults[di];
        const ry = cDataStartY + r * ROW_H;
        const vc = vCenter(ry, ROW_H, 9);

        doc.font('Helvetica').fontSize(9).fillColor('#000000');
        doc.text(dayName, colX[0] + 2, vc, { width: COL_W[0] - 4, align: 'center' });
        doc.text(formatDateIndo(date), colX[1] + 2, vc, { width: COL_W[1] - 4, align: 'center' });

        // Status columns - use drawn shapes instead of Unicode symbols
        for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
          const kStatus = KETERANGAN_ORDER[j];
          const ci = j + 2;
          const cellCx = colX[ci] + COL_W[ci] / 2; // center X of cell
          const cellCy = ry + ROW_H / 2; // center Y of row
          if (status === kStatus) {
            drawStatusSymbol(doc, kStatus, cellCx, cellCy, 16);
          } else {
            // Empty/unused cell - draw a light dash
            doc.font('Helvetica').fontSize(9).fillColor('#e0e0e0');
            doc.text('\u2013', colX[ci] + 2, vc, { width: COL_W[ci] - 4, align: 'center' });
          }
        }
      }

      // ====== TOTAL ROW ======
      if (isLastPage) {
        const totalRY = cDataStartY + pRows.length * ROW_H;
        const totalVC = vCenter(totalRY, TOTAL_ROW_H, 9);

        // "Total" label MERGED across Hari + Tanggal columns (col 0 + col 1)
        const totalLabelW = COL_W[0] + COL_W[1];
        doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
        doc.text('Total', colX[0] + 2, totalVC, { width: totalLabelW - 4, align: 'center' });

        // Erase the vertical line between col 0 and col 1 in the total row
        // so the two cells visually merge into one
        doc.strokeColor('#FFFFFF').lineWidth(2);
        doc.moveTo(colX[1], totalRY).lineTo(colX[1], totalRY + TOTAL_ROW_H).stroke();
        doc.strokeColor('#000000').lineWidth(1);

        for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
          const kStatus = KETERANGAN_ORDER[j];
          const ci = j + 2;
          const val = totals[kStatus];
          // ALL total numbers are bold (per user request) — no gray/faded zeros
          doc.font('Helvetica-Bold').fontSize(10).fillColor('#000000');
          doc.text(String(val), colX[ci] + 2, totalVC, { width: COL_W[ci] - 4, align: 'center' });
        }
      }
    }

    // ====== SIGNATURE + QR CODE (borderless table, left-aligned, aligned with Kelas/Jenis Kelamin) ======
    const lastPi = pages.length - 1;
    const lastPRows = pages[lastPi];
    const lastTableTop = lastPi === 0 ? tableTop : MT + 10;
    const actualTableBottom = lastTableTop + HEADER_H * 2 + lastPRows.length * ROW_H + TOTAL_ROW_H;

    let signY = actualTableBottom + 25;
    if (signY + 180 > PAGE_H - MB) {
      doc.addPage({ size: [PAGE_W, PAGE_H], margins: { top: MT, bottom: MB, left: ML, right: MR } });
      signY = MT + 10;
    }

    // Signature block — left-aligned, shifted right so the block's right edge
    // almost touches the right margin (PAGE_W - MR). Shares the same left
    // edge (rStartX) as Kelas/Jenis Kelamin so the whole right column is
    // vertically aligned. Block width = SIGN_BLOCK_W (fits the widest line,
    // "Rohmat Agung W., S.Pd.I").
    const signX = rStartX;
    const signW = SIGN_BLOCK_W;

    doc.font('Helvetica').fontSize(12).fillColor('#000000');
    doc.text('Mengetahui', signX, signY, { width: signW, align: 'left' });
    signY += 18;
    doc.text('Kepala Madrasah,', signX, signY, { width: signW, align: 'left' });
    signY += 10;

    // QR Code left-aligned under signature text (same left edge as the text)
    if (qrBuf) {
      const qrSize = 68;
      try {
        doc.image(qrBuf, signX, signY, { width: qrSize, height: qrSize });
      } catch { /* skip */ }
    }
    signY += 75;

    // Principal name with underline, left-aligned (same left edge)
    doc.font('Helvetica-Bold').fontSize(12).fillColor('#000000');
    const nameText = 'Rohmat Agung W., S.Pd.I';
    doc.text(nameText, signX, signY, { width: signW, align: 'left' });
    const nameW = doc.widthOfString(nameText);
    doc.moveTo(signX, signY + 14).lineTo(signX + nameW, signY + 14)
      .strokeColor('#000000').lineWidth(0.75).stroke();

    // ====== HOLIDAY NOTES — left-aligned after signature, same left margin as table ======
    // Shows manual date holidays (e.g. "Selasa, 25 Agustus 2026 = Maulid Nabi Muhammad")
    if (holidays.length > 0) {
      let holidayY = signY + 30; // below the principal name underline
      // Ensure we don't overflow the page — if too low, add a new page
      if (holidayY > PAGE_H - MB - 60) {
        doc.addPage();
        holidayY = MT + 10;
      }

      // Title
      doc.font('Helvetica-Bold').fontSize(10).fillColor('#000000');
      doc.text('Keterangan Hari Libur:', ML, holidayY, { width: TABLE_LEFT + TOTAL_COL_W - ML, align: 'left' });
      holidayY += 16;

      // Each holiday entry
      doc.font('Helvetica').fontSize(9).fillColor('#333333');
      for (const h of holidays) {
        const dateStr = formatDateIndo(h.date);
        const entry = `${h.dayName}, ${dateStr} = ${h.name}`;
        doc.text(entry, ML, holidayY, { width: TABLE_LEFT + TOTAL_COL_W - ML, align: 'left' });
        holidayY += 14;
      }
    }

    doc.end();
  });
}
"},{"path":"src/lib/google-sheets-v4.ts","content":"/**
 * Google Sheets Integration via Apps Script Webhook
 *
 * Uses a Google Apps Script web app deployed as a webhook.
 * The Apps Script handles all sheet reading/writing using SpreadsheetApp service.
 * No Service Account credentials needed — just the webhook URL.
 *
 * Synced data (NOT attendance — attendance stays on GitHub):
 * - Max hour per tanggal
 * - Libur akademik (weekly + date holidays)
 * - Data guru (teachers)
 * - Wali kelas
 * - Jadwal mingguan (weekly schedule)
 * - Identitas siswa (students)
 *
 * The Apps Script webhook receives POST with { action, data } and returns JSON.
 * Actions: "push" (write to sheets), "pull" (read from sheets), "test" (connection test),
 *          "pushAttendance" (write per-class attendance sheets),
 *          "pullAttendance" (read per-class attendance sheets),
 *          "countAttendance" (count attendance rows across class sheets).
 */

import { db } from './db';
import { isStudentExcluded, filterExcludedStudents } from './student-blocklist';

const WEBHOOK_URL_KEY = 'gsheets_webhook_url';
const SPREADSHEET_URL_KEY = 'gsheets_spreadsheet_url';

// Permanent default webhook URL — the Apps Script web app deployed by the user.
// Used as fallback when DB Settings doesn't have a webhook URL.
const DEFAULT_WEBHOOK_URL = 'https://script.google.com/macros/s/AKfycbxvIFW4oLCowwUM63MuzGLt2A9JVDgCY0iNQQLWGtqiZOPk_I_6qtLDgLzGng61Xrg/exec';

/**
 * Get the Apps Script webhook URL from DB Settings, falling back to the permanent default.
 */
export async function getGSheetsConfig(): Promise<{ webhookUrl: string | null; spreadsheetUrl: string | null }> {
  try {
    const [webhookSetting, spreadsheetSetting] = await Promise.all([
      db.settings.findUnique({ where: { key: WEBHOOK_URL_KEY } }),
      db.settings.findUnique({ where: { key: SPREADSHEET_URL_KEY } }),
    ]);
    // Use DB-stored webhook URL, or fall back to the permanent default
    return {
      webhookUrl: webhookSetting?.value || DEFAULT_WEBHOOK_URL,
      spreadsheetUrl: spreadsheetSetting?.value || null,
    };
  } catch {
    return { webhookUrl: DEFAULT_WEBHOOK_URL, spreadsheetUrl: null };
  }
}

/**
 * Save the Apps Script webhook URL to DB Settings.
 */
export async function setGSheetsConfig(config: { webhookUrl: string; spreadsheetUrl?: string }): Promise<void> {
  await db.settings.upsert({
    where: { key: WEBHOOK_URL_KEY },
    update: { value: config.webhookUrl },
    create: { key: WEBHOOK_URL_KEY, value: config.webhookUrl },
  });
  if (config.spreadsheetUrl) {
    await db.settings.upsert({
      where: { key: SPREADSHEET_URL_KEY },
      update: { value: config.spreadsheetUrl },
      create: { key: SPREADSHEET_URL_KEY, value: config.spreadsheetUrl },
    });
  }
}

/**
 * Get public config for UI display.
 */
export async function getGSheetsConfigPublic(): Promise<any> {
  const config = await getGSheetsConfig();
  return {
    configured: !!config.webhookUrl,
    webhookUrl: config.webhookUrl,
    webhookUrlMasked: config.webhookUrl
      ? config.webhookUrl.substring(0, 40) + '...' + config.webhookUrl.substring(config.webhookUrl.length - 20)
      : null,
    spreadsheetUrl: config.spreadsheetUrl,
  };
}

/**
 * Test the webhook connection by sending a "test" action.
 */
export async function testGSheetsConnection(): Promise<{ ok: boolean; message: string; sheetNames?: string[] }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { ok: false, message: 'Webhook URL belum dikonfigurasi.' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'test' }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        return {
          ok: true,
          message: `Terhubung! ${data.sheetNames?.length || 0} sheet: ${(data.sheetNames || []).join(', ')}`,
          sheetNames: data.sheetNames,
        };
      }
      return { ok: false, message: data.message || `HTTP ${res.status}: ${res.statusText}` };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    return { ok: false, message: `Gagal terhubung: ${e instanceof Error ? e.message : String(e)}` };
  }
}

/**
 * Push ALL syncable data to Google Sheets via Apps Script webhook.
 * Called after user-initiated saves (via scheduleAutoSync).
 * Does NOT sync attendance — attendance stays on GitHub.
 */
export async function pushToGSheets(): Promise<{ success: boolean; message: string }> {
  const { tryStartOperation, endOperation, recordResult } = await import('./operation-lock');
  if (!tryStartOperation('gsheet-sync', 'G-Sheet Sync: Pushing data ke Google Sheets...')) {
    return { success: false, message: 'Operasi lain sedang berjalan. Coba lagi nanti.' };
  }
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      recordResult('gsheet-sync', false, 'Google Sheets belum dikonfigurasi.');
      return { success: false, message: 'Google Sheets belum dikonfigurasi.' };
    }

    // Collect non-attendance data types to sync
    // NOTE: maxHour is NOT included here — it's synced separately via pushSingleMaxHourToGSheets()
    // only when the user explicitly changes it (taps max hour button).
    const [holidays, dateHolidays, teachers, waliKelas, schedules, students, classes] = await Promise.all([
      db.academicHoliday.findMany(),
      db.dateHoliday.findMany(),
      db.teacher.findMany(),
      db.waliKelas.findMany(),
      db.weeklySchedule.findMany(),
      db.student.findMany(),
      db.class.findMany(),
    ]);

    // Layer 6 (blocklist): deleted students must never be pushed to G-Sheet —
    // otherwise a later pull would re-insert them into the DB.
    const safeStudents = filterExcludedStudents(students);

    const classMap = new Map(classes.map(c => [c.id, c.name]));
    const dayNames = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

    // Build the payload — NO maxHour (synced separately on user tap only)
    const payload = {
      action: 'push',
      data: {
        holidays: holidays.map(h => ({
          dayOfWeek: dayNames[h.dayOfWeek] || String(h.dayOfWeek),
          name: h.name || '',
          isActive: h.isActive,
        })),
        dateHolidays: dateHolidays.map(h => ({
          date: h.date,
          name: h.name || '',
        })),
        teachers: teachers.map(t => ({
          nickname: t.nickname || '',
          fullName: t.fullName || '',
        })),
        waliKelas: waliKelas.map(w => ({
          classId: w.classId,
          className: classMap.get(w.classId) || '',
          name: w.name || '',
        })),
        schedules: schedules.map(s => ({
          classId: s.classId,
          className: classMap.get(s.classId) || '',
          dayOfWeek: dayNames[s.dayOfWeek] || String(s.dayOfWeek),
          hour: s.hour,
          teacher: s.teacher || '',
        })),
        students: safeStudents.map(s => ({
          id: s.id,
          name: s.name,
          nisn: s.nisn || '',
          gender: s.gender || '',
          whatsapp: s.whatsapp || '',
          classId: s.classId,
          className: classMap.get(s.classId) || '',
        })),
      },
    };

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000); // 30s max (was 60s)
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        // Update last sync timestamp
        const now = new Date().toISOString();
        await db.settings.upsert({ where: { key: 'gsheets_last_sync_at' }, update: { value: now }, create: { key: 'gsheets_last_sync_at', value: now } });
        const successMsg = data.message || `Push berhasil! ${teachers.length} guru, ${safeStudents.length} siswa.`;
        await db.settings.upsert({
          where: { key: 'gsheets_last_sync_result' },
          update: { value: JSON.stringify({ success: true, message: successMsg, timestamp: now }) },
          create: { key: 'gsheets_last_sync_result', value: JSON.stringify({ success: true, message: successMsg, timestamp: now }) },
        });
        recordResult('gsheet-sync', true, successMsg);
        return { success: true, message: successMsg };
      }
      const failMsg = data.message || `HTTP ${res.status}`;
      recordResult('gsheet-sync', false, failMsg);
      return { success: false, message: failMsg };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Push error:', msg);
    const now = new Date().toISOString();
    try {
      await db.settings.upsert({
        where: { key: 'gsheets_last_sync_result' },
        update: { value: JSON.stringify({ success: false, message: msg, timestamp: now }) },
        create: { key: 'gsheets_last_sync_result', value: JSON.stringify({ success: false, message: msg, timestamp: now }) },
      });
    } catch {}
    recordResult('gsheet-sync', false, `Gagal push: ${msg}`);
    return { success: false, message: `Gagal push: ${msg}` };
  } finally {
    endOperation('gsheet-sync');
  }
}

/**
 * Push a SINGLE max hour change to Google Sheets.
 * Called ONLY when the user explicitly taps/clicks a max hour button.
 * Uses a targeted merge — only updates the specific date's row in the sheet.
 */
export async function pushSingleMaxHourToGSheets(date: string, maxHour: number): Promise<{ success: boolean; message: string }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { success: false, message: 'G-Sheet belum dikonfigurasi.' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'pushSingleMaxHour',
          data: { date, maxHour },
        }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        return { success: true, message: `Max hour ${date} = ${maxHour} tersinkron ke G-Sheet.` };
      }
      return { success: false, message: data.message || `HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Single max hour push error:', msg);
    return { success: false, message: `Gagal sync max hour: ${msg}` };
  }
}

/**
 * REPLACE date holidays and max hours on G-Sheet with sandbox data.
 * Unlike pushToGSheets (which MERGES), this CLEARS the old data and
 * writes ONLY the new data — old entries that aren't in the sandbox
 * are DELETED.
 *
 * Requires the G-Sheet webhook to support the "replaceDateHolidaysAndMaxHours"
 * action. If the deployed webhook doesn't support it yet, the push will fail
 * with "Unknown action" — the user needs to redeploy the Apps Script with
 * the updated code (see APPS_SCRIPT_CODE constant).
 *
 * @param dateHolidays - Array of { date: string, name: string }
 * @param maxHours - Array of { date: string, maxHour: number }
 */
export async function replaceDateHolidaysAndMaxHours(
  dateHolidays: { date: string; name: string }[],
  maxHours: { date: string; maxHour: number }[]
): Promise<{ success: boolean; message: string }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { success: false, message: 'G-Sheet belum dikonfigurasi.' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'replaceDateHolidaysAndMaxHours',
          data: {
            dateHolidays: dateHolidays.map(h => ({
              date: h.date,
              name: h.name || '',
            })),
            maxHour: maxHours.map(m => ({
              date: m.date,
              maxHour: m.maxHour,
            })),
          },
        }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        return { success: true, message: data.message || `Replace berhasil! ${dateHolidays.length} libur, ${maxHours.length} max hour.` };
      }
      return { success: false, message: data.message || `HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Replace error:', msg);
    return { success: false, message: `Gagal replace: ${msg}` };
  }
}

/**
 * Pull data FROM Google Sheets via Apps Script webhook.
 * Called on server reset or when data difference is detected.
 * Does NOT fetch attendance — attendance uses GitHub pull-diff.
 */
export async function pullFromGSheets(): Promise<{ success: boolean; message: string; restored?: any }> {
  const { tryStartOperation, endOperation, recordResult } = await import('./operation-lock');
  if (!tryStartOperation('gsheet-pull', 'G-Sheet Pull: Mengambil data dari Google Sheets...')) {
    return { success: false, message: 'Operasi lain sedang berjalan. Coba lagi nanti.' };
  }
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      recordResult('gsheet-pull', false, 'Google Sheets belum dikonfigurasi.');
      return { success: false, message: 'Google Sheets belum dikonfigurasi.' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000); // 30s max (was 60s)
    let data: any;
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'pull' }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      data = await res.json().catch(() => ({}));
      if (!res.ok || !data.success) {
        const failMsg = data.message || `HTTP ${res.status}`;
        recordResult('gsheet-pull', false, failMsg);
        return { success: false, message: failMsg };
      }
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }

    const d = data.data || {};
    const dayNameMap: Record<string, number> = { Ahad: 0, Senin: 1, Selasa: 2, Rabu: 3, Kamis: 4, Jumat: 5, Sabtu: 6 };
    let restored = { maxHours: 0, holidays: 0, dateHolidays: 0, teachers: 0, waliKelas: 0, schedules: 0, students: 0 };

    // Helper: G-Sheet/Apps Script may return dates as ISO strings (e.g.
    // "2026-07-29T17:00:00.000Z") because SpreadsheetApp auto-converts date
    // strings to Date objects. We must extract just the YYYY-MM-DD part,
    // otherwise the pull creates DUPLICATE entries with the wrong date
    // (e.g., "2026-07-29T17:00:00.000Z" alongside existing "2026-07-30").
    //
    // TIMEZONE FIX: Google Sheets converts date strings like "2026-07-30"
    // to Date objects at midnight. When serialized to JSON, the Date becomes
    // "2026-07-29T17:00:00.000Z" (midnight UTC+7 = 17:00 UTC of the prev day).
    // The old normalizeDate extracted "2026-07-29" (WRONG — should be 07-30).
    // The fix: parse the ISO string and add the Jakarta UTC+7 offset (7 hours)
    // to recover the original date.
    const normalizeDate = (raw: any): string | null => {
      if (!raw) return null;
      const s = typeof raw === 'string' ? raw : String(raw);
      const tIdx = s.indexOf('T');
      if (tIdx > 0) {
        // ISO date string (e.g., "2026-07-29T17:00:00.000Z")
        // Parse as Date, add 7 hours (Jakarta UTC+7) to recover original date
        try {
          const d = new Date(s);
          const jakartaOffsetMs = 7 * 60 * 60 * 1000; // UTC+7
          const jakartaDate = new Date(d.getTime() + jakartaOffsetMs);
          const yyyy = jakartaDate.getUTCFullYear();
          const mm = String(jakartaDate.getUTCMonth() + 1).padStart(2, '0');
          const dd = String(jakartaDate.getUTCDate()).padStart(2, '0');
          return `${yyyy}-${mm}-${dd}`;
        } catch {
          // Fallback: extract date part before 'T'
          return s.substring(0, tIdx);
        }
      }
      // Already YYYY-MM-DD (or other string format) — return as-is
      return s;
    };

    // 1. Max Hour
    if (Array.isArray(d.maxHour)) {
      for (const m of d.maxHour) {
        const normDate = normalizeDate(m.date);
        if (normDate) {
          const key = `max_hours_${normDate}`;
          const value = String(Math.max(0, Math.min(8, parseInt(m.maxHour, 10) || 8)));
          await db.settings.upsert({ where: { key }, update: { value }, create: { key, value } });
          restored.maxHours++;
        }
      }
    }

    // 2. Holidays (weekly)
    if (Array.isArray(d.holidays)) {
      for (const h of d.holidays) {
        const dayOfWeek = typeof h.dayOfWeek === 'string' ? dayNameMap[h.dayOfWeek] : h.dayOfWeek;
        if (dayOfWeek !== undefined && dayOfWeek !== null) {
          await db.academicHoliday.upsert({
            where: { dayOfWeek },
            update: { name: h.name || '', isActive: h.isActive !== false },
            create: { dayOfWeek, name: h.name || '', isActive: h.isActive !== false },
          });
          restored.holidays++;
        }
      }
    }

    // 3. Date Holidays
    if (Array.isArray(d.dateHolidays)) {
      for (const h of d.dateHolidays) {
        const normDate = normalizeDate(h.date);
        if (normDate) {
          await db.dateHoliday.upsert({
            where: { date: normDate },
            update: { name: h.name || '' },
            create: { date: normDate, name: h.name || '' },
          });
          restored.dateHolidays++;
        }
      }
    }

    // 4. Teachers
    if (Array.isArray(d.teachers)) {
      for (const t of d.teachers) {
        const nickname = t.nickname != null ? String(t.nickname) : '';
        if (nickname) {
          await db.teacher.upsert({
            where: { nickname },
            update: { fullName: t.fullName || nickname },
            create: { nickname, fullName: t.fullName || nickname },
          });
          restored.teachers++;
        }
      }
    }

    // 5. Wali Kelas
    if (Array.isArray(d.waliKelas)) {
      for (const w of d.waliKelas) {
        const classId = w.classId != null ? String(w.classId) : '';
        if (classId && w.name) {
          await db.waliKelas.upsert({
            where: { classId },
            update: { name: String(w.name) },
            create: { classId, name: String(w.name) },
          });
          restored.waliKelas++;
        }
      }
    }

    // 6. Schedules
    if (Array.isArray(d.schedules)) {
      // Pre-load local classes to resolve classId from className if missing
      const localClasses = await db.class.findMany();
      const classIdByName = new Map(localClasses.map(c => [c.name, c.id]));
      const schedulesByClass: Map<string, { dayOfWeek: number; hour: number; teacher: string }[]> = new Map();
      for (const s of d.schedules) {
        const dayOfWeek = typeof s.dayOfWeek === 'string' ? dayNameMap[s.dayOfWeek] : s.dayOfWeek;
        // Coerce classId to String; fall back to className lookup if missing
        let classId = s.classId != null ? String(s.classId) : '';
        if (!classId && s.className) classId = classIdByName.get(String(s.className)) || '';
        if (classId && dayOfWeek !== undefined && dayOfWeek !== null && s.hour) {
          if (!schedulesByClass.has(classId)) schedulesByClass.set(classId, []);
          schedulesByClass.get(classId)!.push({ dayOfWeek, hour: parseInt(s.hour, 10) || 1, teacher: s.teacher || '' });
        }
      }
      for (const [classId, scheds] of schedulesByClass) {
        await db.weeklySchedule.deleteMany({ where: { classId } });
        await db.weeklySchedule.createMany({ data: scheds.map(s => ({ classId, dayOfWeek: s.dayOfWeek, hour: s.hour, teacher: s.teacher })) });
        restored.schedules += scheds.length;
      }
    }

    // 7. Students — FULL REPLACE from G-Sheet (G-Sheet is source of truth)
    // Delete students NOT in G-Sheet, then upsert all G-Sheet students.
    // Also delete attendance records of deleted students (orphaned attendance).
    //
    // CRITICAL: G-Sheet/Apps Script may return `nisn` and `whatsapp` as NUMBERS
    // (e.g., 3138165323) instead of strings. Prisma's schema requires String.
    // Without String() coercion, EVERY student upsert fails silently with
    // "Argument `nisn`: Invalid value provided. Expected String, provided Int."
    // and `restored.students` stays at 0 even though G-Sheet has 137 students.
    if (Array.isArray(d.students)) {
      // Pre-load local classes to resolve classId from className if missing
      const localClasses = await db.class.findMany();
      const classIdByName = new Map(localClasses.map(c => [c.name, c.id]));

      // Get current local student IDs
      const localStudents = await db.student.findMany({ select: { id: true } });
      const localStudentIds = new Set(localStudents.map(s => s.id));

      // Build G-Sheet student set (coerce id to string for reliable matching)
      const gsheetStudentIds = new Set<string>();
      for (const s of d.students) {
        const sid = s.id != null ? String(s.id) : '';
        const sname = s.name != null ? String(s.name) : '';
        let cid = s.classId != null ? String(s.classId) : '';
        if (!cid && s.className) cid = classIdByName.get(String(s.className)) || '';
        if (sname && cid && sid) {
          gsheetStudentIds.add(sid);
        }
      }

      // Find deleted students (in local DB, NOT in G-Sheet)
      const deletedStudentIds: string[] = [];
      for (const id of localStudentIds) {
        if (!gsheetStudentIds.has(id)) {
          deletedStudentIds.push(id);
        }
      }

      // Delete attendance records of deleted students
      if (deletedStudentIds.length > 0) {
        const deleteResult = await db.attendance.deleteMany({
          where: { studentId: { in: deletedStudentIds } },
        });
        console.log(`[GSheets Pull] Deleted ${deleteResult.count} attendance records of ${deletedStudentIds.length} deleted students`);
        restored.deletedAttendance = deleteResult.count;
      }

      // Delete the deleted students from DB
      if (deletedStudentIds.length > 0) {
        await db.student.deleteMany({ where: { id: { in: deletedStudentIds } } });
        console.log(`[GSheets Pull] Deleted ${deletedStudentIds.length} students not in G-Sheet`);
        restored.deletedStudents = deletedStudentIds.length;
      }

      // Upsert students from G-Sheet
      let upsertFailCount = 0;
      for (const s of d.students) {
        // Layer 6 (blocklist): never re-insert a deleted student from G-Sheet.
        if (isStudentExcluded(s?.id != null ? String(s.id) : null)) {
          console.warn('[GSheets Pull] Skipped blocklisted student from G-Sheet:', s?.name);
          continue;
        }
        const sname = s.name != null ? String(s.name) : '';
        let cid = s.classId != null ? String(s.classId) : '';
        if (!cid && s.className) cid = classIdByName.get(String(s.className)) || '';
        if (sname && cid) {
          // If no ID from G-Sheet, generate one (cuid-style)
          const studentId = (s.id != null ? String(s.id) : '') || `cls_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
          // CRITICAL: coerce nisn/whatsapp/gender to String — G-Sheet returns them as numbers
          const nisnStr = s.nisn != null && s.nisn !== '' ? String(s.nisn) : '';
          const whatsappStr = s.whatsapp != null && s.whatsapp !== '' ? String(s.whatsapp) : '';
          const genderStr = s.gender != null && s.gender !== '' ? String(s.gender) : '';
          // Ensure whatsapp starts with leading "0" if it's a phone number that
          // got stripped by Apps Script's number coercion (e.g., 85707517724 → "085707517724")
          const normalizedWhatsapp = (() => {
            if (!whatsappStr) return '';
            // If it's all digits and doesn't start with "0" or "+", prepend "0"
            if (/^\d+$/.test(whatsappStr) && !whatsappStr.startsWith('0') && !whatsappStr.startsWith('+')) {
              return '0' + whatsappStr;
            }
            return whatsappStr;
          })();
          try {
            await db.student.upsert({
              where: { id: studentId },
              update: {
                name: sname,
                nisn: nisnStr,
                gender: genderStr,
                whatsapp: normalizedWhatsapp,
                classId: cid,
              },
              create: {
                id: studentId,
                name: sname,
                nisn: nisnStr,
                gender: genderStr,
                whatsapp: normalizedWhatsapp,
                classId: cid,
              },
            });
            restored.students++;
          } catch (e) {
            upsertFailCount++;
            // Upsert might fail if ID doesn't exist and classId FK fails
            console.warn('[GSheets Pull] Student upsert failed:', sname, e instanceof Error ? e.message : String(e));
          }
        } else {
          console.warn('[GSheets Pull] Student skipped (missing name or classId):', JSON.stringify(s).substring(0, 200));
        }
      }
      if (upsertFailCount > 0) {
        console.warn(`[GSheets Pull] ${upsertFailCount} student(s) failed to upsert out of ${d.students.length} from G-Sheet`);
      }
    }

    // 8. Recalculate attendance count after student deletion
    const realAttendanceCount = await db.attendance.count();
    console.log(`[GSheets Pull] Real attendance count after cleanup: ${realAttendanceCount}`);
    restored.realAttendanceCount = realAttendanceCount;

    // 9. Cleanup ISO-date contamination from previous buggy pulls.
    // Previous versions of this function created duplicate entries with ISO
    // dates like "2026-07-29T17:00:00.000Z" alongside the correct "2026-07-30".
    // Remove the ISO-format duplicates now that we normalize on insert.
    try {
      // 9a. Remove ISO-format max_hours_* settings (keep the plain-date version)
      const allMaxHourSettings = await db.settings.findMany({
        where: { key: { startsWith: 'max_hours_' } },
      });
      const isoSettings = allMaxHourSettings.filter(s => s.key.includes('T'));
      let removedSettings = 0;
      for (const s of isoSettings) {
        // Extract the plain date part (YYYY-MM-DD)
        const plainDate = s.key.replace('max_hours_', '').substring(0, 10);
        const plainKey = `max_hours_${plainDate}`;
        // If the plain-date version exists OR this ISO version is redundant, delete it
        const hasPlain = allMaxHourSettings.some(x => x.key === plainKey);
        if (hasPlain) {
          // Plain version exists — delete the ISO duplicate
          await db.settings.delete({ where: { key: s.key } });
          removedSettings++;
        } else {
          // Plain version doesn't exist — rename the ISO key to plain date
          await db.settings.update({ where: { key: s.key }, data: { key: plainKey } });
          removedSettings++;
        }
      }
      if (removedSettings > 0) {
        console.log(`[GSheets Pull] Cleaned up ${removedSettings} ISO-format max_hours_* settings`);
        restored.cleanedIsoSettings = removedSettings;
      }

      // 9b. Remove ISO-format dateHolidays (keep the plain-date version)
      const allDateHols = await db.dateHoliday.findMany();
      const isoHols = allDateHols.filter(h => h.date.includes('T'));
      let removedHols = 0;
      for (const h of isoHols) {
        const plainDate = h.date.substring(0, 10);
        const hasPlain = allDateHols.some(x => x.date === plainDate);
        if (hasPlain) {
          // Plain version exists — delete the ISO duplicate
          await db.dateHoliday.delete({ where: { id: h.id } });
          removedHols++;
        } else {
          // Plain version doesn't exist — rename the ISO date to plain date
          try {
            await db.dateHoliday.update({ where: { id: h.id }, data: { date: plainDate } });
            removedHols++;
          } catch {
            // Update might fail if there's a unique constraint conflict
            await db.dateHoliday.delete({ where: { id: h.id } });
            removedHols++;
          }
        }
      }
      if (removedHols > 0) {
        console.log(`[GSheets Pull] Cleaned up ${removedHols} ISO-format dateHolidays`);
        restored.cleanedIsoHolidays = removedHols;
      }
    } catch (e) {
      console.warn('[GSheets Pull] Cleanup of ISO-format entries failed:', e instanceof Error ? e.message : String(e));
    }

    const now = new Date().toISOString();
    await db.settings.upsert({ where: { key: 'gsheets_last_pull_at' }, update: { value: now }, create: { key: 'gsheets_last_pull_at', value: now } });
    const msg = `Pull berhasil: ${restored.maxHours} max hour, ${restored.holidays} libur, ${restored.dateHolidays} date libur, ${restored.teachers} guru, ${restored.waliKelas} wali, ${restored.schedules} jadwal, ${restored.students} siswa${restored.deletedStudents ? `, ${restored.deletedStudents} siswa dihapus` : ''}${restored.deletedAttendance ? `, ${restored.deletedAttendance} absensi yatim dihapus` : ''}${restored.cleanedIsoSettings ? `, ${restored.cleanedIsoSettings} max_hour ISO dibersihkan` : ''}${restored.cleanedIsoHolidays ? `, ${restored.cleanedIsoHolidays} libur ISO dibersihkan` : ''}. Real attendance: ${restored.realAttendanceCount}`;
    await db.settings.upsert({
      where: { key: 'gsheets_last_pull_result' },
      update: { value: JSON.stringify({ success: true, message: msg, timestamp: now }) },
      create: { key: 'gsheets_last_pull_result', value: JSON.stringify({ success: true, message: msg, timestamp: now }) },
    });

    recordResult('gsheet-pull', true, msg);
    return { success: true, message: msg, restored };
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Pull error:', msg);
    recordResult('gsheet-pull', false, `Gagal pull: ${msg}`);
    return { success: false, message: `Gagal pull: ${msg}` };
  } finally {
    endOperation('gsheet-pull');
  }
}

/**
 * Delete attendance records of deleted students from GitHub chunks.
 * This rebuilds GitHub chunks WITHOUT records whose studentId no longer exists
 * in the local DB. Also updates meta.json with the real attendance count.
 *
 * Called after pullFromGSheets() to sync the cleanup to GitHub.
 */
export async function cleanDeletedStudentsFromGitHub(): Promise<{ success: boolean; message: string; deletedFromGitHub?: number }> {
  try {
    // Import the deduplication function which rebuilds all chunks from local DB
    // This effectively removes any attendance records that were deleted locally
    // (because the rebuilt chunks will only contain records that still exist in the DB)
    const { deduplicateAndRepairMeta } = await import('./online-backup');
    const result = await deduplicateAndRepairMeta();

    if (result.success) {
      return {
        success: true,
        message: `GitHub cleanup berhasil! ${result.message}`,
        deletedFromGitHub: result.details?.duplicatesRemoved || 0,
      };
    }
    return { success: false, message: result.message };
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] GitHub cleanup error:', msg);
    return { success: false, message: `Gagal cleanup GitHub: ${msg}` };
  }
}

/**
 * Get Google Sheets sync health/status for UI display.
 */
export async function getGSheetsHealth(): Promise<any> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { configured: false, status: 'unconfigured', statusLabel: 'Belum dikonfigurasi' };
    }

    let lastSyncAt: string | null = null;
    let lastPullAt: string | null = null;
    let lastResult: any = null;
    let lastPullResult: any = null;
    try {
      const [syncAt, pullAt, syncRes, pullRes] = await Promise.all([
        db.settings.findUnique({ where: { key: 'gsheets_last_sync_at' } }),
        db.settings.findUnique({ where: { key: 'gsheets_last_pull_at' } }),
        db.settings.findUnique({ where: { key: 'gsheets_last_sync_result' } }),
        db.settings.findUnique({ where: { key: 'gsheets_last_pull_result' } }),
      ]);
      lastSyncAt = syncAt?.value || null;
      lastPullAt = pullAt?.value || null;
      if (syncRes?.value) lastResult = JSON.parse(syncRes.value);
      if (pullRes?.value) lastPullResult = JSON.parse(pullRes.value);
    } catch {}

    let minutesAgo: number | null = null;
    if (lastSyncAt) {
      minutesAgo = Math.floor((Date.now() - new Date(lastSyncAt).getTime()) / 60000);
    }

    let status: string;
    let statusLabel: string;
    let statusColor: string;
    if (lastResult && !lastResult.success) {
      status = 'error';
      statusLabel = 'Sinkronisasi terakhir gagal';
      statusColor = 'red';
    } else if (minutesAgo !== null && minutesAgo > 60) {
      status = 'stale';
      statusLabel = `Last sync: ${minutesAgo} menit lalu`;
      statusColor = 'yellow';
    } else {
      status = 'synced';
      statusLabel = minutesAgo !== null ? `Last sync: ${minutesAgo} menit lalu` : 'Tersinkron';
      statusColor = 'green';
    }

    return {
      configured: true,
      status,
      statusLabel,
      statusColor,
      lastSyncAt,
      lastPullAt,
      lastResult,
      lastPullResult,
      minutesAgo,
    };
  } catch {
    return { configured: false, status: 'error', statusLabel: 'Error' };
  }
}

// ===== ATTENDANCE sync (per-class sheets) =====

// Class-to-sheet-name mapping (matches the sheet tabs in the Google Spreadsheet)
const CLASS_SHEET_NAMES: Record<string, string> = {
  '7 Tahfidz': '7 Tahfidz',
  '8 Tahfidz': '8 Tahfidz',
  '8 Bahasa': '8 Bahasa',
  '9 Tahfidz': '9 Tahfidz',
  '9 Kitab': '9 Kitab',
  '9 Bahasa': '9 Bahasa',
};

/**
 * Push attendance data to Google Sheets (per class).
 * Each class gets its own sheet tab with columns: Date, Hour, StudentName, StudentId, Status.
 * Called after user saves attendance (via scheduleAutoSync) — NOT during restore/pull.
 */
export async function pushAttendanceToGSheets(): Promise<{ success: boolean; message: string }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { success: false, message: 'Google Sheets belum dikonfigurasi.' };
    }

    // Get all classes + students
    const classes = await db.class.findMany();
    const students = await db.student.findMany();
    const studentMap = new Map(students.map(s => [s.id, s]));

    // CRITICAL: Only push RECENT attendance records (last 30 days).
    // Previously pushed ALL 40000+ records → 10MB+ payload → OOM crash.
    // Now only pushes records from the last 30 days (~6000 records, ~1.5MB).
    // The G-Sheet retains older data — we only need to sync recent changes.
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    const cutoffDate = thirtyDaysAgo.toISOString().split('T')[0]; // YYYY-MM-DD

    const attendance = await db.attendance.findMany({
      select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true },
      where: { date: { gte: cutoffDate } },
      take: 5000, // Safety cap: max 5000 records per push
    });

    // Group attendance by class
    const attendanceByClass: Record<string, { date: string; hour: number; studentName: string; studentId: string; status: string }[]> = {};
    for (const a of attendance) {
      const cls = classes.find(c => c.id === a.classId);
      if (!cls) continue;
      const sheetName = CLASS_SHEET_NAMES[cls.name];
      if (!sheetName) continue;
      if (!attendanceByClass[sheetName]) attendanceByClass[sheetName] = [];
      const student = studentMap.get(a.studentId);
      attendanceByClass[sheetName].push({
        date: a.date,
        hour: a.hour,
        studentName: student?.name || 'Unknown',
        studentId: a.studentId,
        status: a.status,
      });
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 120000); // 2 min for large data
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'pushAttendance', data: attendanceByClass }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        const now = new Date().toISOString();
        await db.settings.upsert({
          where: { key: 'gsheets_last_attendance_sync_at' },
          update: { value: now },
          create: { key: 'gsheets_last_attendance_sync_at', value: now },
        });
        return { success: true, message: data.message || `Attendance push berhasil! ${attendance.length} records.` };
      }
      return { success: false, message: data.message || `HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Attendance push error:', msg);
    return { success: false, message: `Gagal push attendance: ${msg}` };
  }
}

/**
 * Pull attendance data FROM Google Sheets.
 * Fetches all class sheets and upserts attendance records.
 * Called on server reset or when G-Sheet count > local count.
 */
export async function pullAttendanceFromGSheets(): Promise<{ success: boolean; message: string; restored?: any }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { success: false, message: 'Google Sheets belum dikonfigurasi.' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 120000);
    let data: any;
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'pullAttendance' }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      data = await res.json().catch(() => ({}));
      if (!res.ok || !data.success) {
        return { success: false, message: data.message || `HTTP ${res.status}` };
      }
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }

    const classData = data.data || {};
    const classes = await db.class.findMany();
    const students = await db.student.findMany();
    // Build student lookup by name + classId
    const studentByName = new Map(students.map(s => [`${s.name}_${s.classId}`, s]));

    let restored = { totalRecords: 0, classesProcessed: 0, skipped: 0 };
    let setSkipFlag = false;
    try { const { setSkipAutoSync } = await import('./auto-sync'); setSkipAutoSync(true); setSkipFlag = true; } catch {}

    for (const [sheetName, records] of Object.entries(classData)) {
      // Find class by sheet name
      const cls = classes.find(c => CLASS_SHEET_NAMES[c.name] === sheetName);
      if (!cls) continue;

      const attRecords = records as any[];
      for (const r of attRecords) {
        if (!r.date || !r.hour || !r.status) { restored.skipped++; continue; }
        // Find student by name + classId
        const student = studentByName.get(`${r.studentName}_${cls.id}`);
        if (!student) { restored.skipped++; continue; }

        const date = r.date;
        const hour = parseInt(r.hour, 10) || 1;
        // Upsert by studentId_date_hour
        try {
          await db.attendance.upsert({
            where: { studentId_date_hour: { studentId: student.id, date, hour } },
            update: { status: r.status },
            create: { studentId: student.id, classId: cls.id, date, hour, status: r.status },
          });
          restored.totalRecords++;
        } catch { restored.skipped++; }
      }
      restored.classesProcessed++;
    }

    if (setSkipFlag) { try { const { setSkipAutoSync } = await import('./auto-sync'); setSkipAutoSync(false); } catch {} }

    const now = new Date().toISOString();
    await db.settings.upsert({
      where: { key: 'gsheets_last_attendance_pull_at' },
      update: { value: now },
      create: { key: 'gsheets_last_attendance_pull_at', value: now },
    });

    return {
      success: true,
      message: `Attendance pull dari G-Sheet berhasil! ${restored.totalRecords} records dipulihkan, ${restored.skipped} di-skip, ${restored.classesProcessed} kelas.`,
      restored,
    };
  } catch (e) {
    try { const { setSkipAutoSync } = await import('./auto-sync'); setSkipAutoSync(false); } catch {}
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[GSheets] Attendance pull error:', msg);
    return { success: false, message: `Gagal pull attendance: ${msg}` };
  }
}

/**
 * Count total attendance records across all class sheets in Google Sheets.
 * Used to compare with local DB count and trigger pull-diff if G-Sheet > local.
 */
export async function countGSheetsAttendance(): Promise<{ count: number; error?: string }> {
  try {
    const config = await getGSheetsConfig();
    if (!config.webhookUrl) {
      return { count: 0, error: 'not configured' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'countAttendance' }),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        return { count: data.totalCount || 0 };
      }
      return { count: 0, error: data.message || `HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  } catch (e) {
    return { count: 0, error: e instanceof Error ? e.message : String(e) };
  }
}

