function pushData(ss, data) {
  var results = {};

  // MERGE logic: write header if sheet is empty, then APPEND new rows.
  // Does NOT clear existing data — only updates/overwrites rows by key.
  // This ensures data in G-Sheet is NOT lost on server reset.

  if (data.maxHour) {
    var sheet = getOrCreateSheet(ss, SHEET_TABS.maxHour);
    ensureHeader(sheet, ['Date', 'MaxHour']);
    var existing = readSheetAsMap(sheet, 0); // key column = Date (col A)
    for (var i = 0; i < data.maxHour.length; i++) {
      existing[data.maxHour[i].date] = [data.maxHour[i].date, data.maxHour[i].maxHour];
    }
    var rows = Object.values(existing);
    sheet.clear();
    sheet.getRange(1, 1, 1, 2).setValues([['Date', 'MaxHour']]);
    if (rows.length > 0) sheet.getRange(2, 1, rows.length, 2).setValues(rows);
    results.maxHour = rows.length;
  }

  if (data.holidays) {
    var sheet = getOrCreateSheet(ss, SHEET_TABS.holidays);
    ensureHeader(sheet, ['DayOfWeek', 'Name', 'IsActive']);
    var existing = readSheetAsMap(sheet, 0);
    for (var i = 0; i < data.holidays.length; i++) {
      existing[data.holidays[i].dayOfWeek] = [data.holidays[i].dayOfWeek, data.holidays[i].name, data.holidays[i].isActive ? 'true' : 'false'];
    }
    var rows = Object.values(existing);
    sheet.clear();
    sheet.getRange(1, 1, 1, 3).setValues([['DayOfWeek', 'Name', 'IsActive']]);
    if (rows.length > 0) sheet.getRange(2, 1, rows.length, 3).setValues(rows);
    results.holidays = rows.length;
  }

