  if (data.teachers) {
    var sheet = getOrCreateSheet(ss, SHEET_TABS.teachers);
    ensureHeader(sheet, ['Nickname', 'FullName']);
    var existing = readSheetAsMap(sheet, 0);
    for (var i = 0; i < data.teachers.length; i++) {
      existing[data.teachers[i].nickname] = [data.teachers[i].nickname, data.teachers[i].fullName];
    }
    var rows = Object.values(existing);
    sheet.clear();
    sheet.getRange(1, 1, 1, 2).setValues([['Nickname', 'FullName']]);
    if (rows.length > 0) sheet.getRange(2, 1, rows.length, 2).setValues(rows);
