    ensureHeader(sheet, ['ClassId', 'ClassName', 'DayOfWeek', 'Hour', 'Teacher']);
    // For schedules, key = ClassId + DayOfWeek + Hour (composite key)
    var existing = readSheetAsMap(sheet, -1, ['ClassId', 'DayOfWeek', 'Hour']);
    for (var i = 0; i < data.schedules.length; i++) {
