// REPLACE mode: clears the sheet COMPLETELY and writes ONLY the new data.
// Unlike pushData (which MERGES), this DELETES old entries that aren't in
// the new data. Used to fix corrupted/outdated G-Sheet data.
// IMPORTANT: Sets the Date column to TEXT format ('@') BEFORE writing,
// so Google Sheets stores dates as plain strings — NOT as Date objects.
// This prevents the timezone offset bug where "2026-06-30" gets stored as
// a Date and read back as "2026-06-29T17:00:00.000Z" (shifted -1 day
// due to UTC+7 timezone).
function replaceDateHolidaysAndMaxHours(ss, data) {
  var results = {};

  // 1. REPLACE date holidays (clear + write new)
  if (data.dateHolidays) {
    var sheet = getOrCreateSheet(ss, SHEET_TABS.dateHolidays);
    sheet.clear();
    // Set the ENTIRE sheet to TEXT format — prevents Google Sheets from
    // auto-converting date strings to Date objects (which causes timezone shift)
    sheet.getRange(1, 1, Math.max(data.dateHolidays.length + 1, 100), 2).setNumberFormat('@');
    sheet.getRange(1, 1, 1, 2).setValues([['Date', 'Name']]);
    if (data.dateHolidays.length > 0) {
      var rows = [];
      for (var i = 0; i < data.dateHolidays.length; i++) {
        rows.push([data.dateHolidays[i].date, data.dateHolidays[i].name]);
      }
      sheet.getRange(2, 1, rows.length, 2).setValues(rows);
    }
    results.dateHolidays = data.dateHolidays.length;
  }

  // 2. REPLACE max hours (clear + write new)
  if (data.maxHour) {
    var sheet = getOrCreateSheet(ss, SHEET_TABS.maxHour);
    sheet.clear();
    // Set the ENTIRE sheet to TEXT format — prevents timezone shift on dates
    sheet.getRange(1, 1, Math.max(data.maxHour.length + 1, 100), 2).setNumberFormat('@');
    sheet.getRange(1, 1, 1, 2).setValues([['Date', 'MaxHour']]);
    if (data.maxHour.length > 0) {
      var rows = [];
      for (var i = 0; i < data.maxHour.length; i++) {
        rows.push([data.maxHour[i].date, String(data.maxHour[i].maxHour)]);
      }
      sheet.getRange(2, 1, rows.length, 2).setValues(rows);
    }
    results.maxHour = data.maxHour.length;
  }

  return ContentService.createTextOutput(JSON.stringify({
    success: true,
    message: 'Replace berhasil! Old data cleared, new data written. ' + JSON.stringify(results)
  })).setMimeType(ContentService.MimeType.JSON);
}

// Helper: ensure sheet has a header row
function ensureHeader(sheet, headers) {
  if (sheet.getLastRow() === 0) {
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
  }
}

// Helper: read sheet into a map keyed by a column value (or composite key)
function readSheetAsMap(sheet, keyCol, compositeCols) {
  var map = {};
  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return map;
  var lastCol = sheet.getLastColumn();
  var values = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
  for (var i = 0; i < values.length; i++) {
    var row = values[i];
    var key;
    if (compositeCols) {
      // Find column indices for composite key
      var headerRow = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
      var keyParts = [];
      for (var c = 0; c < compositeCols.length; c++) {
        var colIdx = headerRow.indexOf(compositeCols[c]);
        if (colIdx >= 0) keyParts.push(row[colIdx]);
      }
      key = keyParts.join('|');
    } else {
      key = String(row[keyCol]);
    }
    if (key) map[key] = row;
  }
  return map;
}

// Push a single max hour row — merge with existing sheet data
function pushSingleMaxHour(ss, data) {
  var sheet = getOrCreateSheet(ss, SHEET_TABS.maxHour);
  ensureHeader(sheet, ['Date', 'MaxHour']);

  // Read existing data into a map keyed by Date
  var existing = readSheetAsMap(sheet, 0);

  // Update or add the single row
  existing[data.date] = [data.date, data.maxHour];

  // Write back all rows (merged)
  var rows = Object.values(existing);
  sheet.clear();
  sheet.getRange(1, 1, 1, 2).setValues([['Date', 'MaxHour']]);
  if (rows.length > 0) sheet.getRange(2, 1, rows.length, 2).setValues(rows);

  return ContentService.createTextOutput(JSON.stringify({
    success: true,
    message: 'Max hour ' + data.date + ' = ' + data.maxHour + ' updated (merge).'
  })).setMimeType(ContentService.MimeType.JSON);
}

function pullData(ss) {
  var data = {};

  data.maxHour = readSheet(ss, SHEET_TABS.maxHour, ['date', 'maxHour']);
  data.holidays = readSheet(ss, SHEET_TABS.holidays, ['dayOfWeek', 'name', 'isActive']);
  data.dateHolidays = readSheet(ss, SHEET_TABS.dateHolidays, ['date', 'name']);
