function readSheet(ss, tabName, keys) {
  try {
    var sheet = ss.getSheetByName(tabName);
    if (!sheet) return [];
    var lastRow = sheet.getLastRow();
    if (lastRow < 2) return [];
    var values = sheet.getRange(2, 1, lastRow - 1, keys.length).getValues();
    return values.map(function(row) {
      var obj = {};
      for (var i = 0; i < keys.length; i++) {
        obj[keys[i]] = row[i];
      }
      return obj;
    }).filter(function(r) { return r[keys[0]]; });
  } catch (e) {
    return [];
  }
}

function getOrCreateSheet(ss, name) {
  // Try exact match first
  var sheet = ss.getSheetByName(name);
  if (sheet) return sheet;
  // Try case-insensitive match (in case the tab name has different casing)
  var sheets = ss.getSheets();
  for (var i = 0; i < sheets.length; i++) {
    if (sheets[i].getName().toLowerCase() === name.toLowerCase()) {
      return sheets[i];
    }
  }
  // Not found — create new sheet with the exact name
  sheet = ss.insertSheet(name);
  return sheet;
}

// ===== Attendance per-class sheets =====

var ATTENDANCE_CLASS_SHEETS = ['7 Tahfidz', '8 Tahfidz', '8 Bahasa', '9 Tahfidz', '9 Kitab', '9 Bahasa'];
var ATTENDANCE_HEADERS = ['Date', 'Hour', 'StudentName', 'StudentId', 'Status'];

function pushAttendance(ss, data) {
  try {
    var results = {};
    var totalPushed = 0;

    // data is an object: { '7 Tahfidz': [{date, hour, studentName, studentId, status}, ...], ... }
    for (var i = 0; i < ATTENDANCE_CLASS_SHEETS.length; i++) {
      var sheetName = ATTENDANCE_CLASS_SHEETS[i];
      var sheet = getOrCreateSheet(ss, sheetName);
      sheet.clear();
      sheet.getRange(1, 1, 1, ATTENDANCE_HEADERS.length).setValues([ATTENDANCE_HEADERS]);

      var rows = (data && data[sheetName]) ? data[sheetName] : [];
      var mapped = rows.map(function(r) {
        return [r.date, r.hour, r.studentName, r.studentId, r.status];
      });
      if (mapped.length > 0) {
        sheet.getRange(2, 1, mapped.length, ATTENDANCE_HEADERS.length).setValues(mapped);
      }
      results[sheetName] = mapped.length;
      totalPushed += mapped.length;
    }

    return ContentService.createTextOutput(JSON.stringify({
      success: true,
      message: 'Attendance push berhasil! ' + totalPushed + ' records across ' + ATTENDANCE_CLASS_SHEETS.length + ' class sheets.',
