    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function pullAttendance(ss) {
  try {
    var data = {};

    for (var i = 0; i < ATTENDANCE_CLASS_SHEETS.length; i++) {
      var sheetName = ATTENDANCE_CLASS_SHEETS[i];
      var sheet = ss.getSheetByName(sheetName);
      if (!sheet) { data[sheetName] = []; continue; }
      var lastRow = sheet.getLastRow();
      if (lastRow < 2) { data[sheetName] = []; continue; }
      var values = sheet.getRange(2, 1, lastRow - 1, ATTENDANCE_HEADERS.length).getValues();
      data[sheetName] = values.map(function(row) {
        return {
          date: row[0],
          hour: row[1],
          studentName: row[2],
          studentId: row[3],
          status: row[4]
        };
      }).filter(function(r) { return r.date && r.status; });
