// Progress callback — set by the API route to track chunk sync progress
let progressCallback: ((current: number, total: number, label: string) => void) | null = null;

// Sync pause flag — set to true when reset/restore is in progress
let _isSyncPaused = false;

// Sync cancel flag — set to true when user clicks STOP. The running sync/pull loop checks this
// before sending each chunk and aborts early if true.
let _isSyncCancelled = false;

export function setSyncProgressCallback(cb: ((current: number, total: number, label: string) => void) | null) {
  progressCallback = cb;
}

export function pauseSync(pause: boolean) {
  _isSyncPaused = pause;
  if (pause) {
    console.log('[Sync] Auto-sync PAUSED (reset/restore in progress)');
  } else {
    console.log('[Sync] Auto-sync RESUMED');
  }
}

/** Signal the running sync/pull to stop as soon as possible (between chunks). */
export function cancelSync() {
  _isSyncCancelled = true;
  console.log('[Sync] Cancel requested — will stop after current chunk completes');
}

/** Reset the cancel flag — call this at the START of any new sync/pull operation. */
function resetCancelFlag() {
  _isSyncCancelled = false;
}

function isCancelled() {
  return _isSyncCancelled;
}

function reportProgress(current: number, total: number, label: string) {
  if (progressCallback) progressCallback(current, total, label);
}

const SPREADSHEET_ID = '10qr4FBMKSuIiZ9esT3EaX50BnsmBME_fYgrzO9-MPSI';
const SPREADSHEET_URL = `https://docs.google.com/spreadsheets/d/${SPREADSHEET_ID}/edit`;
const SCRIPT_URL_KEY = 'google_apps_script_webhook_url';
const LAST_SYNC_KEY = 'last_sync_at';

const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbyQR97_0iTeeS9p9N3sjzz3fI2feixNVdxfKfJMXCMeZYM6gp5v6pfnK7Y18OrzAg/exec';

// Validate that the URL looks like a real Google Apps Script web app URL
const APPS_SCRIPT_URL_PATTERN = /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/;

export function validateAppsScriptUrl(url: string): { valid: boolean; error?: string } {
  if (!url || url.trim().length === 0) {
    return { valid: false, error: 'URL tidak boleh kosong' };
  }
  if (!url.startsWith('https://script.google.com/macros/s/')) {
    return { valid: false, error: 'URL harus dimulai dengan https://script.google.com/macros/s/' };
  }
  if (!url.endsWith('/exec')) {
    return { valid: false, error: 'URL harus diakhiri dengan /exec' };
  }
  if (!APPS_SCRIPT_URL_PATTERN.test(url)) {
    return { valid: false, error: 'Format URL tidak valid. Contoh: https://script.google.com/macros/s/XXXXX/exec' };
  }
  return { valid: true };
}

export function getSpreadsheetId() {
  return SPREADSHEET_ID;
