// Get the Apps Script webhook URL from settings, fallback to hardcoded URL
export async function getScriptUrl(): Promise<string | null> {
  try {
    const setting = await db.settings.findUnique({
      where: { key: SCRIPT_URL_KEY },
    });
    if (setting?.value && validateAppsScriptUrl(setting.value).valid) {
      return setting.value;
    }
    // Fallback to hardcoded URL
    return APPS_SCRIPT_URL;
  } catch (error) {
    console.error('Error getting script URL:', error);
    return APPS_SCRIPT_URL;
  }
}

// Save the Apps Script webhook URL to settings
export async function setScriptUrl(url: string): Promise<void> {
