    create: { key: SCRIPT_URL_KEY, value: url },
  });
}

// Get last sync timestamp
async function getLastSyncAt(): Promise<string | null> {
  try {
    const setting = await db.settings.findUnique({ where: { key: LAST_SYNC_KEY } });
    return setting?.value || null;
  } catch { return null; }
}

// Save last sync timestamp
async function setLastSyncAt(iso: string): Promise<void> {
