// Test the Apps Script web app connection
export async function testAppsScriptConnection(url: string): Promise<{
  success: boolean;
  message: string;
}> {
  try {
    const validation = validateAppsScriptUrl(url);
    if (!validation.valid) {
      return { success: false, message: validation.error || 'URL tidak valid' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    const response = await fetch(url, {
      method: 'GET',
      signal: controller.signal,
      redirect: 'follow',
    });
    clearTimeout(timeout);

    if (!response.ok) {
      if (response.status === 404) {
        return {
          success: false,
          message: 'URL Apps Script tidak ditemukan (404). Pastikan deployment web app sudah dibuat.',
        };
      }
      return {
        success: false,
        message: `Gagal menghubungi Apps Script (HTTP ${response.status}). Pastikan web app di-deploy dengan akses "Anyone".`,
      };
    }

    const result = await response.json().catch(() => null);
    if (result && (result.status === 'ready' || result.status === 'ok')) {
      return { success: true, message: 'Koneksi berhasil! Apps Script siap menerima data.' };
    }
    return { success: true, message: 'Koneksi berhasil. Apps Script merespon.' };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Apps Script tidak merespon dalam 15 detik.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    return { success: false, message: `Gagal menghubungi Apps Script: ${message}` };
  }
}

/**
 * Generate COMPRESSED backup payload.
 * - Classes: only id + name (NO nested relations)
 * - Attendance: no createdAt/updatedAt (biggest data set)
 * - Activities: no createdAt/updatedAt
 * - Other tables: minimal fields
 *
 * This reduces payload from ~11MB to ~2.4MB for 15K attendance records.
 */
export async function generateCompressedPayload(): Promise<any> {
  const [classes, students, attendance, activities, holidays, dateHolidays, waliKelas, schedules, settings] =
    await Promise.all([
      db.class.findMany({ select: { id: true, name: true } }),
      db.student.findMany(),
      db.attendance.findMany({ select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true } }),
      db.academicActivity.findMany({ select: { id: true, classId: true, date: true, status: true } }),
      db.academicHoliday.findMany(),
      db.dateHoliday.findMany({ select: { id: true, date: true, name: true } }),
      db.waliKelas.findMany({ select: { id: true, classId: true, name: true } }),
      db.weeklySchedule.findMany({ select: { id: true, classId: true, dayOfWeek: true, hour: true, teacher: true } }),
      db.settings.findMany({ select: { key: true, value: true } }),
    ]);

  return {
    version: 3,
    exportedAt: new Date().toISOString(),
    appName: 'ABSENSI SISWA MTs Al ISHLAH',
    compressed: true,
    data: { classes, students, attendance, activities, holidays, dateHolidays, waliKelas, schedules, settings },
  };
}

/**
 * Generate INCREMENTAL payload - only new records since lastSyncAt.
 * Returns null if no new data.
