      mode: 'merge',
      exportedAt: new Date().toISOString(),
      appName: 'ABSENSI SISWA MTs Al ISHLAH',
      compressed: true,
      data: {
        classes: newClasses,
        students: newStudents,
        attendance: newAttendance,
        activities: newActivities,
        dateHolidays: newDateHolidays,
        academicHolidays: newAcademicHolidays,
        waliKelas: newWaliKelas,
        schedules: newSchedules,
      },
    },
    counts,
  };
}

/**
 * Send sync data to Google Sheets via Apps Script webhook.
 * MANUAL sync (from UI button): FULL sync — sends ALL data (classes, students,
 *   attendance, holidays, settings, schedules, etc.) in chunks.
 * AUTO sync (triggerAutoSync): INCREMENTAL — only sends NEW records since last sync.
 */
export async function syncToGoogleSheets(options?: { incremental?: boolean }): Promise<{
  success: boolean;
  message: string;
}> {
  try {
    // Reset cancel flag at the start of a new sync
    resetCancelFlag();

    const scriptUrl = await getScriptUrl();
    if (!scriptUrl) {
      return {
        success: false,
        message: 'URL Apps Script belum dikonfigurasi.',
      };
    }

    // Check if auto-sync is skipped (during restore/reset)
    if (_isSyncPaused) {
      console.log('[Sync] Auto-sync is PAUSED (reset/restore in progress). Skipping.');
      return { success: false, message: 'Sync di-pause karena reset/restore sedang berjalan.' };
    }

    // If incremental mode (auto-sync), only send new records
    // If full mode (manual sync), send ALL data
    const useIncremental = options?.incremental === true;

    let payloadData: any;
    let syncType: string;

    if (useIncremental) {
      // AUTO-SYNC: incremental (only new records since last sync)
      const incremental = await generateIncrementalPayload();
      if (!incremental) {
        return { success: true, message: 'Tidak ada data baru untuk disinkronkan.' };
      }
      const { payload, counts } = incremental;
      const totalNew = Object.values(counts).reduce((a, b) => a + b, 0);
      if (totalNew === 0) {
        return { success: true, message: 'Tidak ada data baru untuk disinkronkan.' };
      }
      payloadData = payload;
      syncType = 'incremental';
      console.log(`[Sync] Incremental auto-sync: ${JSON.stringify(counts)}`);
    } else {
      // MANUAL SYNC: full (all data)
      payloadData = await generateCompressedPayload();
      syncType = 'full';
      console.log(`[Sync] Full manual sync: ${payloadData.data?.attendance?.length || 0} attendance records`);
    }

    const payload = payloadData;

    // Chunk attendance
    const CHUNK_SIZE = 100;
    const attendanceRecords = payload.data?.attendance || [];
    const otherData = { ...payload };
    if (otherData.data) delete otherData.data.attendance;

    const nonAttendanceCount = (Object.keys(payload.data || {}).length - 1); // all keys minus attendance
    const totalChunks = Math.ceil(attendanceRecords.length / CHUNK_SIZE) + (nonAttendanceCount > 0 ? 1 : 0);
    let chunkIndex = 0;
    let totalSynced = 0;

    // 1. Send metadata (non-attendance data) — mode: 'merge' (no overwrite)
    if (nonAttendanceCount > 0) {
      reportProgress(0, totalChunks, 'Meta data (kelas, siswa, hari libur...)');
      const metaPayload = {
        ...otherData,
        mode: 'merge',
        chunk: { index: 0, total: totalChunks, type: 'meta' },
      };
      console.log(`[Sync] Meta chunk: ${Math.round(JSON.stringify(metaPayload).length / 1024)} KB`);

      const controller = new AbortController();
      // Meta chunk can be slow (clearContents + setValue on large sheet) — allow 120s
      const timeout = setTimeout(() => controller.abort(), 120000);
      try {
        const response = await fetch(scriptUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(metaPayload),
          signal: controller.signal,
        });
        clearTimeout(timeout);
        const result = await response.json().catch(() => ({}));
        if (!response.ok && !result.success) {
          console.warn('[Sync] Meta chunk failed:', result.message || response.status);
        } else {
          console.log('[Sync] Meta chunk sent (chunked mode v7)');
        }
      } catch (e) {
        clearTimeout(timeout);
        console.warn('[Sync] Meta chunk error:', e instanceof Error ? e.message : String(e));
      }
    }

    // 2. Send new attendance in chunks of 100
    for (let i = 0; i < attendanceRecords.length; i += CHUNK_SIZE) {
      // Check if user clicked STOP — abort the loop early
      if (isCancelled()) {
        console.log(`[Sync] Cancelled by user at chunk ${chunkIndex}/${totalChunks}. Synced ${totalSynced} records so far.`);
        return {
          success: false,
          message: `Sync dihentikan oleh user. ${totalSynced} absensi telah tersinkron sebelum stop.`,
        };
      }
      chunkIndex++;
      const chunk = attendanceRecords.slice(i, i + CHUNK_SIZE);
      reportProgress(chunkIndex, totalChunks, `Absensi chunk ${chunkIndex}/${totalChunks - (nonAttendanceCount > 0 ? 1 : 0)} (${chunk.length} records)`);
      const chunkPayload = {
        version: 4,
        mode: 'merge',
        chunk: { index: chunkIndex, total: totalChunks, type: 'attendance' },
        data: { attendance: chunk },
      };
      console.log(`[Sync] Attendance chunk ${chunkIndex}: ${chunk.length} records, ${Math.round(JSON.stringify(chunkPayload).length / 1024)} KB`);

      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 60000);
      try {
        const response = await fetch(scriptUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(chunkPayload),
          signal: controller.signal,
        });
        clearTimeout(timeout);
        const result = await response.json().catch(() => ({}));
        if (response.ok || result.success) {
          totalSynced += chunk.length;
        } else {
          console.warn(`[Sync] Chunk ${chunkIndex} failed:`, result.message || response.status);
        }
      } catch (e) {
        clearTimeout(timeout);
        console.warn(`[Sync] Chunk ${chunkIndex} error:`, e instanceof Error ? e.message : String(e));
      }

      if (i + CHUNK_SIZE < attendanceRecords.length) {
        await new Promise(r => setTimeout(r, 500));
      }
    }

    // Update last sync timestamp + attendance count
    const now = new Date().toISOString();
    await db.settings.upsert({
      where: { key: LAST_SYNC_KEY },
      update: { value: now },
      create: { key: LAST_SYNC_KEY, value: now },
    });
    await db.settings.upsert({
      where: { key: 'gsheet_attendance_count' },
      update: { value: String(attendanceRecords.length) },
      create: { key: 'gsheet_attendance_count', value: String(attendanceRecords.length) },
    });

    return {
      success: true,
      message: `Sync berhasil! ${payload.data?.classes?.length || 0} kelas, ${payload.data?.students?.length || 0} siswa, ${totalSynced} absensi, ${payload.data?.academicHolidays?.length || 0} hari libur mingguan, ${payload.data?.dateHolidays?.length || 0} hari libur tanggal, ${payload.data?.settings?.length || 0} pengaturan (termasuk max hours) — dalam ${chunkIndex} chunk`,
    };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Sync melebihi batas waktu. Coba lagi.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('Error syncing to Google Sheets:', error);
    return { success: false, message: `Gagal sync: ${message}` };
  }
}

/**
 * Restore data FROM Google Sheets (pull all data back).
 * G-Sheet returns data in chunks (meta + attendance chunks).
 * We fetch all chunks, assemble, then restore to DB.
 * Also handles old single-response format.
 */
export async function restoreFromGoogleSheets(): Promise<{
  success: boolean;
  message: string;
  restored?: any;
}> {
  try {
    // Reset cancel flag at the start of a new pull
    resetCancelFlag();

    const scriptUrl = await getScriptUrl();
    if (!scriptUrl) {
      return { success: false, message: 'URL Apps Script belum dikonfigurasi.' };
    }

    setSkipAutoSync(true);
    pauseSync(true);

    // Step 1: Fetch first chunk (meta or full backup)
    reportProgress(0, 1, 'Mengambil data dari G-Sheet...');
    const metaController = new AbortController();
    const metaTimeout = setTimeout(() => metaController.abort(), 60000);
    let metaResponse: Response;
    try {
      metaResponse = await fetch(scriptUrl + '?action=restore', {
        method: 'GET',
        signal: metaController.signal,
        redirect: 'follow',
      });
    } finally {
      clearTimeout(metaTimeout);
    }

    const metaText = await metaResponse.text();
    if (metaText.trimStart().startsWith('<!') || metaText.trimStart().startsWith('<html')) {
      return { success: false, message: 'Apps Script mengembalikan HTML. Deploy ulang dengan akses "Anyone".' };
    }

    let metaResult: any;
    try {
      metaResult = JSON.parse(metaText);
    } catch {
      return { success: false, message: `Response bukan JSON valid. Response: "${metaText.substring(0, 100)}"` };
    }

    if (metaResult.status === 'error') {
      return { success: false, message: `Apps Script error: ${metaResult.error || metaResult.message}` };
    }

    // Extract backup data
    const metaBackup = metaResult.backup || metaResult;
    const metaData = metaBackup.data || metaBackup;
    const chunkInfo = metaBackup.chunk || metaResult.chunk;
    // The new Apps Script v7 returns totalChunks at the top level
    const totalChunks = metaResult.totalChunks || chunkInfo?.total || 1;

    // Assemble data from the first chunk (meta chunk 0)
    const assembledData: any = {
      classes: metaData.classes || [],
      students: metaData.students || [],
      settings: metaData.settings || [],
      schedules: metaData.schedules || [],
      waliKelas: metaData.waliKelas || [],
      academicHolidays: metaData.academicHolidays || metaData.holidays || [],
      dateHolidays: metaData.dateHolidays || [],
      activities: metaData.activities || [],
      attendance: metaData.attendance || [],
      teachers: metaData.teachers || [],
    };

    console.log(`[Pull] First response: ${assembledData.classes.length} classes, chunk total: ${totalChunks}`);

    // If chunk 0 has no classes (meta chunk was aborted/failed), try to find meta data
    // in another chunk by re-fetching chunk 0 explicitly
    if (assembledData.classes.length === 0 && totalChunks > 1) {
      console.log('[Pull] Chunk 0 has no classes — re-fetching chunk 0 explicitly...');
      const retryController = new AbortController();
      const retryTimeout = setTimeout(() => retryController.abort(), 60000);
      try {
        const retryRes = await fetch(scriptUrl + '?action=restore&chunk=0', {
          method: 'GET', signal: retryController.signal, redirect: 'follow',
        });
        clearTimeout(retryTimeout);
        const retryText = await retryRes.text();
        if (retryText && retryText.trim() && !retryText.trimStart().startsWith('{status')) {
          const retryResult = JSON.parse(retryText);
          const retryBackup = retryResult.backup || retryResult;
          const retryData = retryBackup.data || retryBackup;
          if (retryData.classes && retryData.classes.length > 0) {
            assembledData.classes = retryData.classes;
            assembledData.students = retryData.students || [];
            assembledData.settings = retryData.settings || [];
            assembledData.schedules = retryData.schedules || [];
            assembledData.waliKelas = retryData.waliKelas || [];
            assembledData.academicHolidays = retryData.academicHolidays || retryData.holidays || [];
            assembledData.dateHolidays = retryData.dateHolidays || [];
            assembledData.activities = retryData.activities || [];
            assembledData.teachers = retryData.teachers || [];
            console.log(`[Pull] Re-fetched chunk 0: ${assembledData.classes.length} classes, ${assembledData.students.length} students`);
          }
        }
      } catch (e) {
        clearTimeout(retryTimeout);
        console.warn('[Pull] Re-fetch chunk 0 error:', e instanceof Error ? e.message : String(e));
      }
    }

    // Step 2: Fetch remaining chunks (1 to totalChunks-1)
    // The first chunk (index 0) is the META chunk — it has classes/students/settings but NO attendance.
    // Chunks 1..totalChunks-1 are ATTENDANCE chunks.
    // We need to fetch ALL of them to get the complete attendance data.
    if (totalChunks > 1) {
      // If first response was an attendance chunk (old format), fetch chunk 0 (meta) first
      if (chunkInfo?.type === 'attendance' && chunkInfo?.index !== 0) {
        reportProgress(0, totalChunks, 'Mengambil meta data dari G-Sheet...');
        const c0Controller = new AbortController();
        const c0Timeout = setTimeout(() => c0Controller.abort(), 60000);
        try {
          const c0Res = await fetch(scriptUrl + '?action=restore&chunk=0', {
            method: 'GET', signal: c0Controller.signal, redirect: 'follow',
          });
          clearTimeout(c0Timeout);
          const c0Text = await c0Res.text();
          const c0Result = JSON.parse(c0Text);
          const c0Backup = c0Result.backup || c0Result;
          const c0Data = c0Backup.data || c0Backup;
          // Merge meta data
          if (c0Data.classes) assembledData.classes = c0Data.classes;
          if (c0Data.students) assembledData.students = c0Data.students;
          if (c0Data.settings) assembledData.settings = c0Data.settings;
          if (c0Data.schedules) assembledData.schedules = c0Data.schedules;
          if (c0Data.waliKelas) assembledData.waliKelas = c0Data.waliKelas;
          if (c0Data.academicHolidays) assembledData.academicHolidays = c0Data.academicHolidays;
          if (c0Data.holidays) assembledData.academicHolidays = c0Data.holidays;
          if (c0Data.dateHolidays) assembledData.dateHolidays = c0Data.dateHolidays;
          if (c0Data.activities) assembledData.activities = c0Data.activities;
          if (c0Data.teachers) assembledData.teachers = c0Data.teachers;
          console.log(`[Pull] Meta chunk: ${assembledData.classes.length} classes, ${assembledData.students.length} students`);
        } catch (e) {
          clearTimeout(c0Timeout);
          console.warn('[Pull] Meta chunk error:', e instanceof Error ? e.message : String(e));
        }
      }

      // Fetch all remaining chunks (1 to totalChunks-1) — these are attendance chunks
      // The first chunk (index 0) was already received in the initial response
      for (let c = 1; c < totalChunks; c++) {
        // Check if user clicked STOP — abort the loop early
        if (isCancelled()) {
          console.log(`[Pull] Cancelled by user at chunk ${c}/${totalChunks}. Got ${assembledData.attendance.length} attendance so far.`);
          setSkipAutoSync(false);
          pauseSync(false);
          return {
            success: false,
            message: `Pull dihentikan oleh user. ${assembledData.attendance.length} absensi telah diambil sebelum stop (data belum direstore ke DB).`,
          };
        }
        reportProgress(c, totalChunks, `Mengambil absensi chunk ${c}/${totalChunks - 1} dari G-Sheet...`);

        // Skip if it's the chunk we already got from initial response (old format)
        if (chunkInfo?.index === c && chunkInfo?.type === 'attendance') {
          console.log(`[Pull] Chunk ${c} already received in initial response, skipping`);
          continue;
        }

        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 60000);
        try {
          const res = await fetch(scriptUrl + `?action=restore&chunk=${c}`, {
            method: 'GET', signal: controller.signal, redirect: 'follow',
          });
          clearTimeout(timeout);
          const text = await res.text();
          // New Apps Script v7 returns the chunk directly (no wrapper)
          // Old Apps Script returned {status:"ok", backup:{...}}
          let chunkData: any;
          try {
            const parsed = JSON.parse(text);
            // If it has a .backup or .data wrapper, unwrap it
            if (parsed.backup) {
              chunkData = parsed.backup.data || parsed.backup;
            } else if (parsed.data) {
              chunkData = parsed.data;
            } else if (parsed.status === 'error') {
              console.warn(`[Pull] Chunk ${c} error:`, parsed.error || parsed.message);
              continue;
            } else {
              // New format: the chunk IS the data object
              chunkData = parsed.data || parsed;
            }
          } catch {
            console.warn(`[Pull] Chunk ${c} parse error, skipping`);
            continue;
          }
          if (chunkData.attendance && Array.isArray(chunkData.attendance)) {
            assembledData.attendance.push(...chunkData.attendance);
          }
          console.log(`[Pull] Chunk ${c}: +${chunkData.attendance?.length || 0} (total: ${assembledData.attendance.length})`);
        } catch (e) {
          clearTimeout(timeout);
          console.warn(`[Pull] Chunk ${c} error:`, e instanceof Error ? e.message : String(e));
        }
      }
    }

    reportProgress(totalChunks, totalChunks, 'Memulihkan data ke database...');

    if (!assembledData.classes || assembledData.classes.length === 0) {
      return { success: false, message: 'Tidak ada data classes di G-Sheet. Lakukan SYNC dulu.' };
    }

    console.log(`[Pull] Total: ${assembledData.classes.length} classes, ${assembledData.students.length} students, ${assembledData.attendance.length} attendance`);

    // Step 3: Restore to DB
    const scriptUrlValue = scriptUrl;
    const TX_TIMEOUT = 300_000;

    try {
      const restoreResult = await db.$transaction(async (tx) => {
        await tx.attendance.deleteMany();
        await tx.weeklySchedule.deleteMany();
        await tx.teacher.deleteMany();
        await tx.academicActivity.deleteMany();
        await tx.dateHoliday.deleteMany();
        await tx.waliKelas.deleteMany();
        await tx.student.deleteMany();
        await tx.class.deleteMany();
        await tx.academicHoliday.deleteMany();
        await tx.settings.deleteMany();

        if (assembledData.classes?.length > 0) {
          await tx.class.createMany({ data: assembledData.classes.map((cls: any) => ({
            id: cls.id, name: cls.name,
            createdAt: cls.createdAt ? new Date(cls.createdAt) : undefined,
            updatedAt: cls.updatedAt ? new Date(cls.updatedAt) : undefined,
          })) });
        }
        if (assembledData.students?.length > 0) {
          await tx.student.createMany({ data: assembledData.students.map((s: any) => ({
            id: s.id, name: s.name, nisn: s.nisn || '', gender: s.gender || '',
            whatsapp: s.whatsapp || '', classId: s.classId,
            createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
            updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
          })) });
        }
        if (assembledData.attendance?.length > 0) {
          const CS = 500;
          for (let i = 0; i < assembledData.attendance.length; i += CS) {
            const chunk = assembledData.attendance.slice(i, i + CS);
            await tx.attendance.createMany({ data: chunk.map((a: any) => ({
              id: a.id, studentId: a.studentId, classId: a.classId,
              date: a.date, hour: a.hour, status: a.status,
            })) });
          }
        }
        if (assembledData.activities?.length > 0) {
          await tx.academicActivity.createMany({ data: assembledData.activities.map((a: any) => ({
            id: a.id, classId: a.classId, date: a.date, status: a.status || 'Masuk',
          })) });
        }
        if (assembledData.academicHolidays?.length > 0) {
          await tx.academicHoliday.createMany({ data: assembledData.academicHolidays.map((h: any) => ({
            id: h.id, dayOfWeek: h.dayOfWeek, name: h.name || '', isActive: h.isActive !== false,
          })) });
        }
        if (assembledData.dateHolidays?.length > 0) {
          await tx.dateHoliday.createMany({ data: assembledData.dateHolidays.map((dh: any) => ({
            id: dh.id, date: dh.date, name: dh.name || '',
          })) });
        }
        if (assembledData.waliKelas?.length > 0) {
          await tx.waliKelas.createMany({ data: assembledData.waliKelas.map((w: any) => ({
            id: w.id, classId: w.classId, name: w.name || '',
          })) });
        }
        if (assembledData.schedules?.length > 0) {
          const CS = 500;
          for (let i = 0; i < assembledData.schedules.length; i += CS) {
            const chunk = assembledData.schedules.slice(i, i + CS);
            await tx.weeklySchedule.createMany({ data: chunk.map((s: any) => ({
              id: s.id, classId: s.classId, dayOfWeek: s.dayOfWeek, hour: s.hour, teacher: s.teacher || '',
            })) });
          }
        }
        if (assembledData.teachers?.length > 0) {
          await tx.teacher.createMany({ data: assembledData.teachers.map((t: any) => ({
            id: t.id, nickname: t.nickname, fullName: t.fullName || '',
          })) });
        }
        for (const setting of (assembledData.settings || [])) {
          if (setting.key === SCRIPT_URL_KEY) continue;
          try { await tx.settings.create({ data: { key: setting.key, value: setting.value } }); } catch {}
        }
        await tx.settings.upsert({
          where: { key: SCRIPT_URL_KEY },
          update: { value: scriptUrlValue },
          create: { key: SCRIPT_URL_KEY, value: scriptUrlValue },
        });

        return {
          classes: assembledData.classes.length,
          students: assembledData.students.length,
          attendance: assembledData.attendance.length,
          activities: assembledData.activities.length,
        };
      }, { timeout: TX_TIMEOUT });

      return { success: true, message: `Data berhasil di-pull dari G-Sheet! (${restoreResult.classes} kelas, ${restoreResult.students} siswa, ${restoreResult.attendance} absensi)`, restored: restoreResult };
    } finally {
      setSkipAutoSync(false);
      pauseSync(false);
    }
  } catch (error) {
    setSkipAutoSync(false);
    pauseSync(false);
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Gagal mengambil data.' };
    }
    const msg = error instanceof Error ? error.message : 'Unknown error';
    console.error('Error restoring from Google Sheets:', error);
    return { success: false, message: `Gagal pull: ${msg}` };
  }
}


/**
 * Auto-sync trigger: pushes data to Google Sheets after DB writes.
 * Called by auto-sync.ts debouncer (3s after last write).
 * If sync fails, logs error but doesn't block app.
 */

export async function checkBackup(): Promise<{
  success: boolean;
  message: string;
  info?: { hasBackup: boolean; version: string; exportedAt: string; size: string; classes: number; students: number; attendance: number; };
}> {
  try {
    const scriptUrl = await getScriptUrl();
    if (!scriptUrl) return { success: false, message: 'URL Apps Script belum dikonfigurasi.' };
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);
    const response = await fetch(scriptUrl + '?action=check', { method: 'GET', signal: controller.signal, redirect: 'follow' });
    const responseText = await response.text();
    clearTimeout(timeout);
    if (responseText.trimStart().startsWith('<!') || responseText.trimStart().startsWith('<html')) return { success: false, message: 'Apps Script mengembalikan HTML.' };
    let result: any;
    try { result = JSON.parse(responseText); } catch { return { success: false, message: 'Response bukan JSON.' }; }
    if (result.status === 'error') return { success: false, message: `Error: ${result.error || result.message || 'Unknown'}` };
    if (result.hasBackup) {
      const sizeStr = result.totalChunks ? `${result.totalChunks} chunks (${result.chunksStored || result.totalChunks} tersimpan)` : (result.size || '?');
      return { success: true, message: `Backup tersedia: ${result.version || '?'}, ${sizeStr}, ${result.exportedAt || '?'}`, info: { hasBackup: true, version: result.version || '?', exportedAt: result.exportedAt || 'unknown', size: sizeStr, classes: result.classes || 0, students: result.students || 0, attendance: result.attendance || 0 } };
    }
    return { success: true, message: 'Belum ada backup. Lakukan SYNC dulu.' };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') return { success: false, message: 'Timeout saat mengecek backup.' };
    return { success: false, message: `Gagal mengecek backup: ${error instanceof Error ? error.message : 'Unknown'}` };
  }
}

export async function generateClassCSV(className: string): Promise<string> {
  const cls = await db.class.findFirst({ where: { name: className }, include: { students: { orderBy: { name: 'asc' } }, waliKelas: { select: { name: true } } } });
  if (!cls) throw new Error(`Kelas "${className}" tidak ditemukan`);
  const lines: string[] = [];
  lines.push('No,Nama,NISN,Gender,WhatsApp');
  for (let i = 0; i < cls.students.length; i++) {
    const s = cls.students[i];
    lines.push(`${i + 1},"${s.name}","${s.nisn}","${s.gender}","${s.whatsapp}"`);
  }
  const attendanceRecords = await db.attendance.findMany({ where: { classId: cls.id }, include: { student: { select: { name: true } } }, orderBy: [{ date: 'asc' }, { hour: 'asc' }] });
  const activities = await db.academicActivity.findMany({ where: { classId: cls.id }, orderBy: { date: 'asc' } });
  const activityMap = new Map<string, string>();
  for (const act of activities) activityMap.set(act.date, act.status);
  const dateMap = new Map<string, Map<number, Array<[string, string]>>>();
  for (const rec of attendanceRecords) { if (!dateMap.has(rec.date)) dateMap.set(rec.date, new Map()); const hm = dateMap.get(rec.date)!; if (!hm.has(rec.hour)) hm.set(rec.hour, []); hm.get(rec.hour)!.push([rec.student.name, rec.status]); }
  const sortedDates = Array.from(dateMap.keys()).sort();
  for (const date of sortedDates) {
    const activityStatus = activityMap.get(date) ?? 'Masuk';
    lines.push(`--- Absensi ${date} (Wali Kelas: ${cls.waliKelas?.name ?? '-'}) Status: ${activityStatus} ---`);
    const hm = dateMap.get(date)!;
    const sortedHours = Array.from(hm.keys()).sort((a, b) => a - b);
    for (const hour of sortedHours) { const records = hm.get(hour)!; const parts = records.map(([name, status]) => `${name}=${status}`); lines.push(`Jam ${hour}: ${parts.join(', ')}`); }
  }
  return lines.join('\n');
}

export async function generateAllCSV(): Promise<Record<string, string>> {
  const classes = await db.class.findMany({ orderBy: { name: 'asc' }, select: { name: true } });
  const result: Record<string, string> = {};
  for (const cls of classes) result[cls.name] = await generateClassCSV(cls.name);
  return result;
}

// Mutex: prevent concurrent Google Sheets auto-sync runs.
// Without this, rapid DB writes could trigger multiple concurrent syncs,
// each loading thousands of records and making API calls → memory exhaustion.
let _googleSyncRunning = false;

export async function triggerAutoSync() {
  // MUTEX: Skip if a previous sync is still running.
  if (_googleSyncRunning) {
    console.log('[AutoSync] Already running — skipping');
    return;
  }

  // GLOBAL LOCK: Don't start if a pull/restore is running.
  const { tryStartOperation, endOperation, recordResult } = await import('./operation-lock');
  if (!tryStartOperation('auto-sync', 'Auto-Sync ke Google Sheets')) {
    console.log('[AutoSync GS] Blocked — another operation is running');
    return;
  }

  _googleSyncRunning = true;
  try {
    console.log('[AutoSync] Triggering incremental push to Google Sheets...');
    const result = await syncToGoogleSheets({ incremental: true });
    if (result.success) {
      // Update last sync timestamp
      const now = new Date().toISOString();
      await db.settings.upsert({
        where: { key: LAST_SYNC_KEY },
        update: { value: now },
        create: { key: LAST_SYNC_KEY, value: now },
      });
      // Store current attendance count for reset detection
      const attCount = await db.attendance.count();
      await db.settings.upsert({
        where: { key: 'gsheet_attendance_count' },
        update: { value: String(attCount) },
        create: { key: 'gsheet_attendance_count', value: String(attCount) },
      });
      console.log('[AutoSync] Push berhasil:', result.message, '| attendance count:', attCount);
      recordResult('auto-sync', true, result.message);
    } else {
      console.warn('[AutoSync] Push gagal:', result.message);
      recordResult('auto-sync', false, result.message);
    }
  } catch (error) {
    console.error('[AutoSync] Error:', error);
    recordResult('auto-sync', false, error instanceof Error ? error.message : 'Unknown');
  } finally {
    _googleSyncRunning = false;
    endOperation('auto-sync');
  }
}

/**
 * Detect if a data reset occurred by comparing current DB attendance count
 * with the count stored in Settings (last known G-Sheet attendance count).
 * If DB has significantly fewer attendance records than G-Sheet, trigger pull.
 *
 * Returns true if a pull was triggered, false otherwise.
 */
export async function detectAndRecoverFromReset(): Promise<boolean> {
  try {
    const classCount = await db.class.count();
    const studentCount = await db.student.count();
    const attendanceCount = await db.attendance.count();

    // Case 1: DB is completely empty → definitely a reset
    if (classCount === 0) {
      console.log('[ResetDetection] DB empty (0 classes) — triggering pull from Google Sheets...');
      const result = await restoreFromGoogleSheets();
      console.log('[ResetDetection] Pull result:', result.success ? 'BERHASIL' : 'GAGAL', result.message);
      return result.success;
    }

    // Case 2: Check stored G-Sheet attendance count from last sync
    const gsheetCountSetting = await db.settings.findUnique({
      where: { key: 'gsheet_attendance_count' },
    });

    if (gsheetCountSetting) {
      const gsheetCount = parseInt(gsheetCountSetting.value, 10);
      if (!isNaN(gsheetCount) && gsheetCount > 0) {
        // If DB attendance is less than 50% of G-Sheet count → reset suspected
        if (attendanceCount < gsheetCount * 0.5) {
          console.log(`[ResetDetection] Attendance dropped: DB=${attendanceCount} vs G-Sheet=${gsheetCount} (< 50%) — triggering pull...`);
          const result = await restoreFromGoogleSheets();
          console.log('[ResetDetection] Pull result:', result.success ? 'BERHASIL' : 'GAGAL', result.message);
          return result.success;
        }
      }
    }

    // Case 3: Have classes + students but 0 attendance (suspicious if we've synced before)
    const lastSync = await db.settings.findUnique({ where: { key: LAST_SYNC_KEY } });
    if (lastSync && classCount > 0 && studentCount > 0 && attendanceCount === 0) {
      console.log('[ResetDetection] 0 attendance despite having classes + prior sync — triggering pull...');
      const result = await restoreFromGoogleSheets();
      console.log('[ResetDetection] Pull result:', result.success ? 'BERHASIL' : 'GAGAL', result.message);
      return result.success;
    }

    return false;
  } catch (error) {
    console.error('[ResetDetection] Error:', error);
    return false;
  }
}
"},{"path":"src/lib/instrumentation-node.ts","content":"/**
 * Node.js-only instrumentation logic.
 *
 * This module is dynamically imported by instrumentation.ts ONLY when
 * process.env.NEXT_RUNTIME === 'nodejs'. It contains all Node.js-specific
 * APIs (fs, setImmediate, setInterval, fetch with long timeouts) that
 * Turbopack would otherwise flag as Edge Runtime violations.
 *
 * Keeping this in a separate module ensures instrumentation.ts stays
 * Edge-clean and produces zero Turbopack warnings.
 */

// CRITICAL: Install global unhandled rejection/exception handlers.
// In a containerized environment (Alibaba FC), unhandled promise rejections
// can crash the Node.js process → container restart → 502 Bad Gateway.
// These handlers log the error but DON'T crash the process, keeping the
// server alive even when individual operations fail.
if (!process.env._INSTRUMENTATION_HANDLERS_INSTALLED) {
  process.env._INSTRUMENTATION_HANDLERS_INSTALLED = '1';
  process.on('unhandledRejection', (reason, promise) => {
    console.error('[Instrumentation] UNHANDLED REJECTION (suppressed):', reason);
  });
  process.on('uncaughtException', (error) => {
    console.error('[Instrumentation] UNCAUGHT EXCEPTION (suppressed):', error.message);
    // Log the stack but DON'T exit — keep the server alive
    if (error.stack) console.error(error.stack.split('\n').slice(0, 5).join('\n'));
  });
  console.log('[Instrumentation] Global error handlers installed (unhandledRejection + uncaughtException)');
}

export async function startInstrumentationNode() {
  const baseUrl = (process.env.AUTORESTORE_SELF_URL || 'http://localhost:3000/api/auto-restore').replace('/api/auto-restore', '');

  // Detect environment: only enable auto-sync/auto-pull on PRODUCTION
  const nodeEnv = process.env.NODE_ENV || '';
  const selfUrl = process.env.AUTORESTORE_SELF_URL || '';
  const isProduction = (nodeEnv === 'production') ||
    (selfUrl.includes('mtss-alishlah-absensi') && !selfUrl.includes('preview-chat'));

  if (!isProduction) {
    console.log('[Instrumentation] PREVIEW/SANDBOX environment (NODE_ENV=' + nodeEnv + ') — auto-sync and auto-pull DISABLED.');
    console.log('[Instrumentation] Only production site (NODE_ENV=production) syncs to GitHub.');
  } else {
    console.log('[Instrumentation] Production environment (NODE_ENV=production) — auto-sync and auto-pull ENABLED.');
  }

  // ===== CRITICAL: BLOCK AUTO-SYNC ON STARTUP (server reset recovery) =====
  // On server reset, the local DB is restored from packaged/persistent DB which
  // may have STALE data. If auto-sync runs BEFORE pull-diff completes, it would
  // PUSH the stale local data to GitHub → OVERWRITE GitHub's good data → DATA LOSS.
  //
  // SOLUTION (user's request):
  //   1. setSkipAutoSync(true) IMMEDIATELY on startup — block ALL auto-sync/push
  //   2. Run PULL-DIFF IMMEDIATELY (not after 30s) — restore missing data from GitHub
  //   3. After pull-diff completes → setSkipAutoSync(false) — resume normal operation
  //
  // This ensures: on server reset, data is PULLED from GitHub first (never pushed).
  if (isProduction) {
    const { setSkipAutoSync } = await import('./auto-sync');
    setSkipAutoSync(true);
    console.log('[Instrumentation] 🔒 AUTO-SYNC BLOCKED on startup — server reset recovery mode. Pull-diff will run FIRST.');
  }

  // ===== 0. STARTUP DISK CLEANUP — run ONCE on server startup =====
  // This is CRITICAL for production: the FC container's /app/ disk is small
  // and accumulates old backup JSON files, WAL files, and dead DB pages over
  // time. Without cleanup, the disk fills up → SQLITE_FULL → all writes fail.
  // Running cleanup on startup ensures we start with a clean disk.
  setImmediate(() => {
    import('./disk-cleanup')
      .then(async ({ aggressiveCleanup, getDiskUsage }) => {
        const before = await getDiskUsage('/app');
        console.log(`[Instrumentation] Startup disk cleanup starting. Disk usage: ${before}%`);
        const result = await aggressiveCleanup({ vacuum: true });
        const after = await getDiskUsage('/app');
        console.log(
          `[Instrumentation] Startup disk cleanup complete: reclaimed ${(result.bytesReclaimed / 1024 / 1024).toFixed(2)}MB ` +
          `across ${result.filesDeleted} files. Disk usage: ${before}% → ${after}%. ` +
          `VACUUM: ${result.vacuumed ? 'OK' : 'skipped'}. Errors: ${result.errors.length}`
        );
      })
      .catch((e) => console.warn('[Instrumentation] Startup disk cleanup failed:', e instanceof Error ? e.message : String(e)));
  });

  // ===== ALL STARTUP WORK IS NON-BLOCKING =====
  // Previously, restorePersistentSyncState() was awaited, blocking the server
  // from starting. Now ALL work is deferred to setImmediate so the server
  // starts listening immediately and instrumentation runs in background.

  // 0. Restore persistent sync state (background, non-blocking)
  setImmediate(() => {
    import('./db-persistent-sync')
      .then(({ restorePersistentSyncState }) => restorePersistentSyncState())
      .then((result) => {
        if (result.restored) {
          console.log(`[Instrumentation] Persistent sync state restored: count=${result.count}, settings=${result.settings}`);
        } else {
          console.log('[Instrumentation] No persistent sync state to restore');
        }
      })
      .catch((e) => console.warn('[Instrumentation] Could not restore persistent sync state:', e instanceof Error ? e.message : String(e)));
  });

  // ===== 1. AUTO-RESTORE FROM LOCAL BACKUP =====
  // This runs FIRST (before GitHub pull-diff) because it's faster — reads from
  // local JSON file (auto_restore.json on persistent OSS mount).
  // If local restore succeeds, most data is already recovered.
  // If local restore fails or data is incomplete, pull-diff from GitHub
  // (step 1c below) will fetch the remaining missing records.
  const localRestorePromise = (async () => {
    try {
      const res = await fetch(baseUrl + '/api/auto-restore', { method: 'POST', signal: AbortSignal.timeout(15000) });
      const data = await res.json().catch(() => ({}));
      console.log('[Instrumentation] Local restore:', data.success ? 'BERHASIL' : 'skipped', data.message || '');
      return data;
    } catch (e) {
      console.log('[Instrumentation] Local restore skipped:', e instanceof Error ? e.message : String(e));
      return { success: false };
    }
  })();
  // ===== 1b+1c. SERVER RESET RECOVERY: G-SHEET PULL → GitHub PULL-DIFF =====
  // FLOW:
  //   1. setSkipAutoSync(true) — block ALL sync
  //   2. Local restore (fast — JSON file)
  //   3. G-Sheet PULL (BEFORE GitHub pull-diff) — non-attendance data
  //      → Fetch: students, max hour, holidays, date holidays, teachers,
  //        wali kelas, schedules FROM G-Sheet
  //   4. GitHub pull-diff (AFTER G-Sheet pull) — attendance records
  //   5. setSkipAutoSync(false) — resume normal operation
  if (isProduction) {
    setImmediate(async () => {
      console.log('[Instrumentation] 🔄 Server reset: local restore → G-Sheet pull → GitHub pull-diff...');
      try {
        // Step 1: Wait for local restore
        await localRestorePromise;
        console.log('[Instrumentation] Local restore completed.');

        // Step 2: Check GitHub chunk count for bloat detection
        let shouldSkipPullDiff = false;
        try {
          const { db } = await import('./db');
          const localCount = await db.attendance.count();
          // Import the shared chunk-size constant so this stays in sync with online-backup.ts
          const { RECORDS_PER_CHUNK } = await import('./online-backup');
          const expectedChunks = Math.ceil(localCount / RECORDS_PER_CHUNK) + 5;
          const { getConfig } = await import('./online-backup');
          const config = await getConfig();
          if (config) {
            const GITHUB_API = 'https://api.github.com';
            const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
              headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
              signal: AbortSignal.timeout(15000),
            });
            if (listRes.ok) {
              const files = await listRes.json();
              if (Array.isArray(files)) {
                const actualChunks = files.filter((f: any) => f.name?.match(/^chunk-\d+\.json$/)).length;
                console.log(`[Instrumentation] GitHub chunks: ${actualChunks}, expected: ~${expectedChunks}`);
                if (actualChunks > expectedChunks * 2) {
                  console.warn(`[Instrumentation] ⚠️ Chunk bloat (${actualChunks} > 2×${expectedChunks}). SKIP pull-diff.`);
                  shouldSkipPullDiff = true;
                }
              }
            }
          }
        } catch (e) {
          console.warn('[Instrumentation] Chunk count check failed:', e instanceof Error ? e.message : String(e));
        }

        // Step 3: G-Sheet PULL (BEFORE GitHub pull-diff)
        // Fetch: students, max hour, holidays, date holidays, teachers, wali kelas, schedules
        try {
          const { pullFromGSheets, getGSheetsConfig } = await import('./google-sheets-v4');
          const gsConfig = await getGSheetsConfig();
          if (gsConfig) {
            console.log('[Instrumentation] 📊 G-Sheet pull (BEFORE GitHub pull-diff)...');
            const gsResult = await pullFromGSheets();
            console.log('[Instrumentation] G-Sheet pull:', gsResult.success ? 'BERHASIL' : 'GAGAL', gsResult.message || '');
            // Notification popup shown via SyncNotification (gsheet-pull is NOT in HIDDEN_OPS)

            if (gsResult.success && gsResult.restored?.deletedStudents > 0) {
              console.log('[Instrumentation] Deleted students — cleaning GitHub chunks...');
              try {
                const { cleanDeletedStudentsFromGitHub } = await import('./google-sheets-v4');
                const cleanup = await cleanDeletedStudentsFromGitHub();
                console.log('[Instrumentation] GitHub cleanup:', cleanup.success ? 'BERHASIL' : 'GAGAL', cleanup.message || '');
              } catch (e) {
                console.warn('[Instrumentation] GitHub cleanup failed:', e instanceof Error ? e.message : String(e));
              }
            }
          } else {
            console.log('[Instrumentation] G-Sheet not configured — skipping pull');
          }
        } catch (e) {
          console.warn('[Instrumentation] G-Sheet pull failed:', e instanceof Error ? e.message : String(e));
        }

        // Step 4: GitHub pull-diff (AFTER G-Sheet pull) — attendance records
        if (shouldSkipPullDiff) {
          console.log('[Instrumentation] ⏭️ Pull-diff SKIPPED (chunk bloat). Run Dedup All + Repair Meta.');
        } else {
          console.log('[Instrumentation] Starting GitHub pull-diff (after G-Sheet pull)...');
          const pullRes = await fetch(baseUrl + '/api/online-backup', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'restore-diff' }),
            signal: AbortSignal.timeout(300000),
          });
          const pullData = await pullRes.json().catch(() => ({}));
          console.log('[Instrumentation] GitHub pull-diff:', pullData.success ? 'BERHASIL' : 'GAGAL', pullData.message || '');
        }
      } catch (e) {
        console.warn('[Instrumentation] Server reset recovery failed:', e instanceof Error ? e.message : String(e));
      } finally {
        try {
          const { setSkipAutoSync } = await import('./auto-sync');
          setSkipAutoSync(false);
          console.log('[Instrumentation] ✅ AUTO-SYNC RESUMED — server reset recovery complete.');
        } catch (e) {
          console.error('[Instrumentation] Could not resume auto-sync:', e instanceof Error ? e.message : String(e));
          setTimeout(async () => {
            try { const { setSkipAutoSync } = await import('./auto-sync'); setSkipAutoSync(false); } catch {}
          }, 10000);
        }
      }
    });
  }
  // ===== 2. PERIODIC CHECK (every 5 min): backup + reset detection + auto-pull =====
  const backupUrl = baseUrl + '/api/backup';
  const classesUrl = baseUrl + '/api/classes';
  const attCountUrl = baseUrl + '/api/attendance/count';
  const onlineBackupUrl = baseUrl + '/api/online-backup';
  const CHECK_INTERVAL = 2 * 60 * 1000; // 2 minutes

  let lastAttCount = 0;
  let pullInProgress = false;
  let onlinePullInProgress = false;
  // CRITICAL: Mutex to prevent concurrent periodic checks.
  // Without this, if a check takes longer than CHECK_INTERVAL (e.g. due to
  // network latency on self-fetches), the next setInterval fires and starts
  // ANOTHER concurrent check. Multiple concurrent checks each make 5+ HTTP
  // calls + DB operations → memory exhaustion → container OOM crash → 502.
  let _periodicCheckRunning = false;
  // COOLDOWN: After pull-diff runs, don't trigger another pull-diff from the
  // count comparison for at least 30 minutes. This prevents the cycle where
  // GitHub meta.json count > local count (due to duplicates in chunks) keeps
  // triggering pull-diff every 5 minutes even though no data is missing.
  // The cooldown is ONLY for count-based triggers — >50% drop triggers bypass it.
  let _lastPullDiffTime = 0;
  const PULL_DIFF_COOLDOWN = 30 * 60 * 1000; // 30 minutes

  const triggerPull = async (reason: string) => {
    if (!isProduction) {
      console.log('[Instrumentation] Pull skipped (preview chat environment)');
      return;
    }
    if (pullInProgress) {
      console.log('[Instrumentation] Pull already in progress, skipping');
      return;
    }
    pullInProgress = true;
    console.log(`[Instrumentation] RESET DETECTED: ${reason}`);

    try {
      const localRes = await fetch(baseUrl + '/api/auto-restore', {
        method: 'POST', signal: AbortSignal.timeout(30000),
      });
      const localData = await localRes.json().catch(() => ({}));
      if (localData.success) {
        console.log('[Instrumentation] Local restore berhasil');
        pullInProgress = false;
        return;
      }
    } catch (e) {
      console.log('[Instrumentation] Local restore failed:', e instanceof Error ? e.message : String(e));
    }

    // If local restore failed, the online restore (triggerOnlineRestore) will
    // be called separately by the periodic check logic.
    pullInProgress = false;
  };

  const triggerOnlineRestore = async (reason: string) => {
    if (!isProduction) {
      console.log('[Instrumentation] Online restore skipped (preview chat environment)');
      return;
    }
    if (onlinePullInProgress) {
      console.log('[Instrumentation] Online pull already in progress, skipping');
      return;
    }
    onlinePullInProgress = true;
    console.log(`[Instrumentation] ONLINE RESTORE TRIGGERED (diff mode): ${reason}`);
    try {
      const pullRes = await fetch(onlineBackupUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'restore-diff' }),
        signal: AbortSignal.timeout(120000),
      });
      const pullData = await pullRes.json().catch(() => ({}));
      console.log('[Instrumentation] Online JSON restore-diff:', pullData.success ? 'BERHASIL' : 'GAGAL', pullData.message || '');
      // Set cooldown timestamp — prevents count-based pull-diff re-triggering
      // for 30 minutes after this run. This stops the cycle where GitHub meta.json
      // count > local count (due to duplicates) keeps triggering pull-diff.
      _lastPullDiffTime = Date.now();
    } catch (e) {
      console.warn('[Instrumentation] Online JSON restore-diff error:', e instanceof Error ? e.message : String(e));
    }
    onlinePullInProgress = false;
  };

  const isDateHoliday = async (dateStr: string): Promise<{ isHoliday: boolean; reason: string }> => {
    try {
      const dateHolidayRes = await fetch(`${baseUrl}/api/date-holidays?date=${dateStr}`, { signal: AbortSignal.timeout(5000) }).catch(() => null);
      if (dateHolidayRes && dateHolidayRes.ok) {
        const holidayData = await dateHolidayRes.json().catch(() => null);
        if (holidayData && (holidayData.id || holidayData.date)) {
          return { isHoliday: true, reason: `Date holiday: ${holidayData.name || 'unknown'}` };
        }
        if (holidayData?.isHoliday || holidayData?.holiday) {
          return { isHoliday: true, reason: `Date holiday: ${holidayData.name || holidayData.holiday?.name || 'unknown'}` };
        }
      }
    } catch {}

    try {
      const date = new Date(dateStr + 'T00:00:00');
      const dayOfWeek = date.getDay();
      const holidaysRes = await fetch(`${baseUrl}/api/holidays`, { signal: AbortSignal.timeout(5000) }).catch(() => null);
      if (holidaysRes && holidaysRes.ok) {
        const holidays = await holidaysRes.json().catch(() => []);
        if (Array.isArray(holidays)) {
          const weeklyHoliday = holidays.find((h: any) => h.dayOfWeek === dayOfWeek && h.isActive !== false);
          if (weeklyHoliday) {
            return { isHoliday: true, reason: `Weekly holiday: ${weeklyHoliday.name || 'day ' + dayOfWeek}` };
          }
        }
      }
    } catch {}

    return { isHoliday: false, reason: '' };
  };

  const findLastNonHolidayDate = async (todayStr: string): Promise<string | null> => {
    const today = new Date(todayStr + 'T00:00:00');
    for (let i = 1; i <= 30; i++) {
      const checkDate = new Date(today);
      checkDate.setDate(checkDate.getDate() - i);
      const checkStr = checkDate.toISOString().split('T')[0];
      const { isHoliday } = await isDateHoliday(checkStr);
      if (!isHoliday) {
        return checkStr;
      }
    }
    return null;
  };

  const doPeriodicCheck = async () => {
    // CRITICAL: Skip periodic check during server reset recovery.
    // The startup pull-diff is running (setSkipAutoSync=true).
    // Running periodic check now would:
    //   - Make redundant API calls to GitHub (pull-diff already handles this)
    //   - Risk triggering pull-diff again (double pull)
    //   - Risk pushing stale data if _skipSync check is missed somewhere
    // Wait until pull-diff completes → setSkipAutoSync(false) → periodic check resumes.
    try {
      const { isAutoSyncSkipped } = await import('./auto-sync');
      if (isAutoSyncSkipped()) {
        console.log('[Instrumentation] Periodic check skipped — server reset recovery in progress (pull-diff running). Will resume after recovery completes.');
        return;
      }
    } catch {}

    // MUTEX: Skip if a previous check is still running.
    // This prevents concurrent checks from stacking up and exhausting memory.
    if (_periodicCheckRunning) {
      console.log('[Instrumentation] Periodic check already running — skipping this cycle');
      return;
    }
    _periodicCheckRunning = true;

    try {
    // 2a. Sync DB to persistent storage — NON-BLOCKING
    // Delegated to a separate module using async fs.promises.copyFile.
    // Previously used fs.copyFileSync inline which BLOCKED the event loop
    // for hundreds of ms every 2 min on a 9MB+ DB file → ERR_INVALID_RESPONSE.
    setImmediate(() => {
      import('./db-persistent-sync')
        .then(async ({ syncLiveDbToPersistent, savePersistentSyncStatus, savePersistentGhCount }) => {
          // 1. Sync the DB file to persistent OSS
          const result = await syncLiveDbToPersistent();
          if (result.copied) {
            console.log(`[Instrumentation] Live DB synced to persistent OSS: ${result.path}`);
          }
          // 2. Save sync status settings to persistent file (survives server resets)
          try {
            const { db } = await import('./db');
            const syncKeys = [
              'online_last_sync_at',
              'online_last_pull_at',
              'online_last_sync_result',
              'online_last_pull_result',
              'online_attendance_count',
            ];
            const settings: Record<string, string> = {};
            for (const key of syncKeys) {
              const s = await db.settings.findUnique({ where: { key } });
              if (s) settings[key] = s.value;
            }
            if (Object.keys(settings).length > 0) {
              await savePersistentSyncStatus(settings);
            }
            // 3. Also save the count separately (for quick read on startup)
            const countSetting = settings['online_attendance_count'];
            if (countSetting) {
              const count = parseInt(countSetting, 10) || 0;
              if (count > 0) await savePersistentGhCount(count);
            }

            // 4. PERIODIC WAL CHECKPOINT — keep the -wal file small.
            // Even with journal_mode=DELETE (set in db.ts), if a previous server
            // run used WAL mode, the -wal file may still exist and grow.
            // wal_checkpoint(TRUNCATE) forces SQLite to merge WAL contents back
            // into the main DB and TRUNCATE the -wal file to 0 bytes.
            // This is the PREVENTION for the production "disk is full" issue.
            // Use $queryRawUnsafe because wal_checkpoint RETURNS rows.
            try {
              await db.$queryRawUnsafe('PRAGMA wal_checkpoint(TRUNCATE)');
            } catch (e) {
              // Non-fatal — might fail if WAL doesn't exist or is busy
            }
          } catch {}
        })
        .catch(() => {
          // non-fatal — persistent sync is best-effort
        });
    });

    // 2b. Get current time in Jakarta (GMT+7)
    const now = new Date();
    const utc = now.getTime() + now.getTimezoneOffset() * 60000;
    const jakarta = new Date(utc + 7 * 3600000);
    const jakartaHour = jakarta.getHours();
    const jakartaMinute = jakarta.getMinutes();
    const isAfter0730 = (jakartaHour > 7) || (jakartaHour === 7 && jakartaMinute >= 30);

    // DIRECT DB QUERIES — no self-fetch HTTP calls.
    // Previously used fetch('/api/classes'), fetch('/api/attendance/count') etc.
    // which are HTTP roundtrips to localhost:3000 (the same server).
    // When the server is busy, these self-fetches queue up and create a cascade
    // of timeouts → periodic check takes 30-60s → server appears unresponsive.
    // Direct DB queries complete in <10ms.
    try {
      const { db } = await import('./db');
      const classCount = await db.class.count();
      if (classCount === 0) {
        await triggerPull('0 classes in DB');
        await triggerOnlineRestore('0 classes in DB (online)');
        return;
      }

      const attCount = await db.attendance.count();

      if (attCount === 0) {
        await triggerPull('0 attendance records');
        await triggerOnlineRestore('0 attendance records (online)');
        return;
      }

      if (lastAttCount > 0 && attCount < lastAttCount * 0.5) {
        console.log(`[Instrumentation] Attendance dropped: ${attCount} vs last ${lastAttCount} (< 50%)`);
        await triggerPull(`attendance dropped ${lastAttCount} → ${attCount}`);
        await triggerOnlineRestore(`attendance dropped ${lastAttCount} → ${attCount} (online)`);
        lastAttCount = attCount;
        return;
      }
      lastAttCount = attCount;

      // AUTO PULL-DIFF: If local count < cached GitHub count, trigger pull-diff.
      // Uses CACHED count (from DB Settings or persistent file) — NO live API call.
      // The auto-sync path (triggerOnlineAutoSync) already does the live GitHub fetch.
      if (isProduction && attCount > 0) {
        try {
          const { fetchGhAttendanceCountRealtime } = await import('./online-backup');
          const { count: ghAttCount, error: ghError } = await fetchGhAttendanceCountRealtime();

          if (!ghError && ghAttCount > attCount) {
            // COOLDOWN CHECK
            const timeSinceLastPullDiff = Date.now() - _lastPullDiffTime;
            if (_lastPullDiffTime > 0 && timeSinceLastPullDiff < PULL_DIFF_COOLDOWN) {
              const minLeft = Math.ceil((PULL_DIFF_COOLDOWN - timeSinceLastPullDiff) / 60000);
              console.log(`[Instrumentation] Count: local (${attCount}) < GitHub (${ghAttCount}), cooldown active (${minLeft} min left). Skipping.`);
            } else {
              console.log(`[Instrumentation] AUTO PULL-DIFF: local (${attCount}) < GitHub (${ghAttCount})`);
              await triggerOnlineRestore(`local (${attCount}) < GitHub (${ghAttCount})`);
              return;
            }
          }
        } catch {}
      }

      // NOTE: G-Sheet attendance sync REMOVED — attendance stays on GitHub only.
      // G-Sheet integration remains for non-attendance data (max hour, holidays,
      // teachers, wali kelas, schedules, students) via pushToGSheets/pullFromGSheets.

      // SKIP completeness check — it makes additional self-fetch HTTP calls
      // that can timeout. The completeness check is non-essential for stability.
      // If attendance is incomplete, the dashboard already shows a warning.
      console.log(`[Instrumentation] Health OK: ${classCount} classes, ${attCount} attendance${isAfter0730 ? ', post-07:30' : ''}`);
    } catch (e) {
      console.log('[Instrumentation] Health check skipped:', e instanceof Error ? e.message : String(e));
    }

    // ===== DISK USAGE CHECK + AUTO-CLEANUP =====
    // Run on every periodic check (every 5 min). If disk usage > 70%,
    // run aggressive cleanup to prevent SQLITE_FULL errors from happening.
    // This is the PREVENTION mechanism — the attendance route's cleanup+retry
    // is the RECOVERY mechanism.
    try {
      const { getDiskUsage, aggressiveCleanup } = await import('./disk-cleanup');
      const diskUsage = await getDiskUsage('/app');
      if (diskUsage >= 0) {
        if (diskUsage >= 70) {
          console.warn(`[Instrumentation] Disk usage ${diskUsage}% — running auto-cleanup...`);
          const cleanup = await aggressiveCleanup({ vacuum: diskUsage >= 85 });
          const afterUsage = await getDiskUsage('/app');
          console.log(
            `[Instrumentation] Auto-cleanup: reclaimed ${(cleanup.bytesReclaimed / 1024 / 1024).toFixed(2)}MB, ` +
            `${cleanup.filesDeleted} files deleted. Disk: ${diskUsage}% → ${afterUsage}%. ` +
            `VACUUM: ${cleanup.vacuumed ? 'OK' : 'skipped'}`
          );
        } else {
          // Just log disk usage for monitoring
          console.log(`[Instrumentation] Disk usage: ${diskUsage}%`);
        }
      }
    } catch (e) {
      // Non-fatal — disk check is best-effort
    }
    } finally {
      // Always release the mutex, even if the check threw an error
      _periodicCheckRunning = false;
    }
  };

  // Increased from 2 min to 5 min to reduce load on the FC container.
  // The 2-min interval was too aggressive — with network latency, checks
  // could stack up and cause memory exhaustion.
  const CHECK_INTERVAL_ACTUAL = 5 * 60 * 1000; // 5 minutes
  setTimeout(doPeriodicCheck, 30000);
  setInterval(doPeriodicCheck, CHECK_INTERVAL_ACTUAL);
  console.log(`[Instrumentation] Periodic check scheduled every ${CHECK_INTERVAL_ACTUAL / 60000} minutes`);
}
