// Number of attendance records per GitHub chunk file.
// Tuned to balance between:
//   - Fewer chunks = fewer GitHub API calls (rate limit: 5000/hour authenticated)
//   - Smaller file size = safer Content API upload (GitHub limit: 1 MB per file)
// At ~237 bytes per record, 300 records ≈ 70 KB per chunk (well under 1 MB limit).
// For 55,441 records: 300/chunk = 185 chunks (vs 555 chunks at 100/chunk) — 67% fewer.
export const RECORDS_PER_CHUNK = 300;
// Cap to prevent rate-limit exhaustion during pull-diff (max chunks to fetch in one pass).
// With 300 records/chunk and 55k records → ~185 chunks, well under this cap.
const MAX_CHUNKS_CAP = 600;

// Progress callback
let progressCallback: ((current: number, total: number, label: string) => void) | null = null;

// Pause flag — set to true when reset/restore is in progress
let _isSyncPaused = false;

// Cancel flag — set to true when user clicks STOP
let _isSyncCancelled = false;

const GITHUB_API = 'https://api.github.com';
const BACKUP_DIR = 'backup';
const META_FILE = `${BACKUP_DIR}/meta.json`;
const CHUNK_PREFIX = `${BACKUP_DIR}/chunk-`;
const LAST_SYNC_KEY = 'online_last_sync_at';
const ATTENDANCE_COUNT_KEY = 'online_attendance_count';

export function setOnlineSyncProgressCallback(cb: ((current: number, total: number, label: string) => void) | null) {
  progressCallback = cb;
}

export function pauseOnlineSync(pause: boolean) {
  _isSyncPaused = pause;
  if (pause) {
    console.log('[OnlineBackup] Sync PAUSED (reset/restore in progress)');
  } else {
    console.log('[OnlineBackup] Sync RESUMED');
  }
}

export function cancelOnlineSync() {
  _isSyncCancelled = true;
  console.log('[OnlineBackup] Cancel requested — will stop after current chunk');
}

function resetCancelFlag() {
  _isSyncCancelled = false;
}

function isCancelled() {
  return _isSyncCancelled;
}

// Module-level progress updater — set by restoreMissingFromOnlineBackup
// to report progress to the operation-lock module (for SyncNotification UI)
let _opLockProgressUpdater: ((current: number, total: number, label: string) => void) | null = null;

function reportProgress(current: number, total: number, label: string) {
  if (progressCallback) progressCallback(current, total, label);
  // Also update operation-lock progress for SyncNotification UI
  if (_opLockProgressUpdater) {
    try { _opLockProgressUpdater(current, total, label); } catch {}
  }
}

