// ===== GitHub API helpers =====
// (exported for reuse by the code-backup module — /api/code-backup)

export interface GitHubConfig {
  token: string;
  owner: string;
  repo: string;
  branch: string;
}

export async function githubPutFile(config: GitHubConfig, path: string, content: string, message: string, sha?: string): Promise<{ sha?: string }> {
  // URL-encode the path (but keep slashes for nested paths)
  const encodedPath = path.split('/').map(encodeURIComponent).join('/');
  const url = `${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/${encodedPath}`;

  const doPut = async (shaToUse?: string): Promise<{ sha?: string }> => {
    const body: any = {
      message,
      content: Buffer.from(content, 'utf-8').toString('base64'),
      branch: config.branch,
    };
    if (shaToUse) body.sha = shaToUse;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 120000);
    try {
      const res = await fetch(url, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${config.token}`,
          'Accept': 'application/vnd.github+json',
          'X-GitHub-Api-Version': '2022-11-28',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
      clearTimeout(timeout);
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        const errMsg = data.message || res.statusText || '';
        // 422 "sha wasn't supplied" means the file EXISTS but we didn't provide its sha.
        // This happens when the caller passed undefined sha due to a transient error in
        // the preceding githubGetFile (e.g. network/rate-limit caused the GET to throw,
        // and the caller's catch block assumed "file doesn't exist").
        // SELF-HEALING: fetch the current sha and retry the PUT once.
        if (res.status === 422 && /sha/i.test(errMsg)) {
          throw new Error(`__RETRY_WITH_SHA__:${errMsg}`);
        }
        throw new Error(`GitHub API ${res.status}: ${errMsg}`);
      }
      return { sha: data.content?.sha };
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  };

  try {
    return await doPut(sha);
  } catch (e) {
    // Self-heal: if 422 "sha wasn't supplied", fetch the current sha and retry once
    if (e instanceof Error && e.message.startsWith('__RETRY_WITH_SHA__')) {
      console.warn(`[githubPutFile] 422 sha missing — auto-fetching current sha for ${path} and retrying...`);
      try {
        const existing = await githubGetFile(config, path);
        if (existing && existing.sha) {
          console.log(`[githubPutFile] Retrieved sha ${existing.sha.substring(0, 8)} — retrying PUT`);
          return await doPut(existing.sha);
        }
        // File genuinely doesn't exist (404) — retry without sha (create new)
        console.log(`[githubPutFile] File not found on retry — creating new`);
        return await doPut(undefined);
      } catch (retryErr) {
        throw new Error(`GitHub API 422 (sha retry failed): ${retryErr instanceof Error ? retryErr.message : String(retryErr)}`);
      }
    }
    throw e;
  }
}

export async function githubGetFile(config: GitHubConfig, path: string): Promise<{ content: string; sha: string } | null> {
  // URL-encode the path (but keep slashes for nested paths)
  const encodedPath = path.split('/').map(encodeURIComponent).join('/');
  const url = `${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/${encodedPath}?ref=${encodeURIComponent(config.branch)}`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60000);
  try {
    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${config.token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
      signal: controller.signal,
    });
    clearTimeout(timeout);
    if (res.status === 404) return null;
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(`GitHub API ${res.status}: ${data.message || res.statusText}`);
    }
    const data = await res.json();
    // GitHub returns content as base64
    const content = Buffer.from(data.content, 'base64').toString('utf-8');
    return { content, sha: data.sha };
  } catch (e) {
    clearTimeout(timeout);
    throw e;
  }
}

export async function githubDeleteFile(config: GitHubConfig, path: string, sha: string, message: string): Promise<void> {
  const encodedPath = path.split('/').map(encodeURIComponent).join('/');
  const url = `${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/${encodedPath}`;
  const body = { message, sha, branch: config.branch };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60000);
  try {
    await fetch(url, {
      method: 'DELETE',
      headers: {
        'Authorization': `Bearer ${config.token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    clearTimeout(timeout);
  } catch {
    clearTimeout(timeout);
  }
}

// Keys that contain secrets — NEVER push these to GitHub
const SENSITIVE_KEY_PREFIXES = ['github_', 'online_', 'gsheets_'];

function filterSensitiveSettings(settings: any[]): any[] {
  return settings.filter((s: any) => {
    if (!s.key) return false;
    for (const prefix of SENSITIVE_KEY_PREFIXES) {
      if (s.key.startsWith(prefix)) return false;
    }
    return true;
  });
}

