async function generateCompressedPayload(): Promise<any> {
  const [classes, students, attendance, activities, holidays, dateHolidays, waliKelas, schedules, settings, teachers] =
    await Promise.all([
      db.class.findMany({ select: { id: true, name: true, createdAt: true, updatedAt: true } }),
      db.student.findMany(),
      db.attendance.findMany({ select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true, createdAt: true } }),
      db.academicActivity.findMany({ select: { id: true, classId: true, date: true, status: true, createdAt: true } }),
      db.academicHoliday.findMany(),
      db.dateHoliday.findMany({ select: { id: true, date: true, name: true, createdAt: true } }),
      db.waliKelas.findMany({ select: { id: true, classId: true, name: true, createdAt: true } }),
      db.weeklySchedule.findMany({ select: { id: true, classId: true, dayOfWeek: true, hour: true, teacher: true, createdAt: true } }),
      db.settings.findMany({ select: { key: true, value: true } }),
      db.teacher.findMany({ select: { id: true, nickname: true, fullName: true, createdAt: true } }),
    ]);

  // Filter out sensitive settings (tokens, API keys) to prevent GitHub secret scanner blocks
  const safeSettings = filterSensitiveSettings(settings);

  // Layer 5 (blocklist): deleted students + their attendance must never be
  // uploaded to GitHub — otherwise pull-diff would re-insert them locally.
  const safeStudents = filterExcludedStudents(students);
  const safeAttendance = filterExcludedAttendance(attendance);

  return {
    version: 3,
    exportedAt: new Date().toISOString(),
    appName: 'ABSENSI SISWA MTs Al ISHLAH',
    compressed: true,
    data: { classes, students: safeStudents, attendance: safeAttendance, activities, holidays, dateHolidays, waliKelas, schedules, settings: safeSettings, teachers },
  };
}

async function generateIncrementalPayload(): Promise<{ payload: any; counts: Record<string, number> } | null> {
  const lastSyncAt = await getLastSyncAt();

  // If lastSyncAt is null, we can't do incremental — return null to skip
  // This prevents returning ALL records (which would create duplicate chunks)
  if (!lastSyncAt) {
    console.log('[OnlineBackup Incremental] No lastSyncAt — skipping incremental. Run FULL sync first to establish baseline.');
    return null;
  }

  const since = lastSyncAt;

  const [newAttendanceRaw, newStudentsRaw, newClasses, newActivities, newDateHolidays, newWaliKelas, newSchedules, newAcademicHolidays, newTeachers] =
    await Promise.all([
      db.attendance.findMany({
        where: { createdAt: { gt: new Date(since) } },
        select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true, createdAt: true },
      }),
      db.student.findMany({ where: { createdAt: { gt: new Date(since) } } }),
      db.class.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, name: true, createdAt: true, updatedAt: true } }),
      db.academicActivity.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, classId: true, date: true, status: true, createdAt: true } }),
      db.dateHoliday.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, date: true, name: true, createdAt: true } }),
      db.waliKelas.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, classId: true, name: true, createdAt: true } }),
      db.weeklySchedule.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, classId: true, dayOfWeek: true, hour: true, teacher: true, createdAt: true } }),
      db.academicHoliday.findMany(),
      db.teacher.findMany({ where: { createdAt: { gt: new Date(since) } }, select: { id: true, nickname: true, fullName: true, createdAt: true } }),
    ]);

  // Layer 5 (blocklist): never upload deleted students or their attendance.
  const newAttendance = filterExcludedAttendance(newAttendanceRaw);
  const newStudents = filterExcludedStudents(newStudentsRaw);

  // SAFETY: If incremental returns too many records (> 500 AND > 10% of total DB),
  // lastSyncAt is likely wrong — skip to prevent duplicate chunks
  const totalAttCount = await db.attendance.count();
  if (newAttendance.length > 500 && newAttendance.length > totalAttCount * 0.1) {
    console.warn(`[OnlineBackup Incremental] SAFETY: ${newAttendance.length} records (>10% of ${totalAttCount}) — skipping to prevent duplicates.`);
    return null;
  }

  const counts = {
    classes: newClasses.length,
    students: newStudents.length,
    attendance: newAttendance.length,
    activities: newActivities.length,
    dateHolidays: newDateHolidays.length,
    academicHolidays: newAcademicHolidays.length,
    waliKelas: newWaliKelas.length,
    schedules: newSchedules.length,
    teachers: newTeachers.length,
  };

  const totalNew = Object.values(counts).reduce((a, b) => a + b, 0);
  if (totalNew === 0) return null;

  return {
    payload: {
      version: 3,
      mode: 'merge',
      exportedAt: new Date().toISOString(),
      appName: 'ABSENSI SISWA MTs Al ISHLAH',
      compressed: true,
      data: {
        classes: newClasses,
        students: newStudents,
        attendance: newAttendance,
        activities: newActivities,
        dateHolidays: newDateHolidays,
        academicHolidays: newAcademicHolidays,
        waliKelas: newWaliKelas,
        schedules: newSchedules,
        teachers: newTeachers,
      },
    },
    counts,
  };
}

async function getLastSyncAt(): Promise<string | null> {
  const setting = await db.settings.findUnique({ where: { key: LAST_SYNC_KEY } });
  return setting?.value || null;
}

// ===== SYNC (push to GitHub) =====

/**
 * Sync data to GitHub repo.
 * - Incremental mode (auto-sync): only new records since last sync
 * - Full mode (manual sync): all data, chunked
 */
export async function syncToOnlineBackup(options?: { incremental?: boolean }): Promise<{ success: boolean; message: string }> {
  try {
    // Manual sync is ALLOWED in BOTH sandbox and production — user can
    // trigger it from the UI in any environment. Automatic auto-sync
    // (via instrumentation-node on startup) is still production-only.
    resetCancelFlag();

    const config = await getConfig();
    if (!config) {
      return { success: false, message: 'GitHub backup belum dikonfigurasi. Set token + owner + repo di pengaturan.' };
    }

    if (_isSyncPaused) {
      console.log('[OnlineBackup] Sync is PAUSED. Skipping.');
      return { success: false, message: 'Sync di-pause karena reset/restore sedang berjalan.' };
    }

    const useIncremental = options?.incremental === true;

    let payload: any;
    let totalSynced = 0;

    if (useIncremental) {
      const incremental = await generateIncrementalPayload();
      if (!incremental) {
        return { success: true, message: 'Tidak ada data baru untuk disinkronkan.' };
      }
      const totalNew = Object.values(incremental.counts).reduce((a, b) => a + b, 0);
      if (totalNew === 0) {
        return { success: true, message: 'Tidak ada data baru untuk disinkronkan.' };
      }
      payload = incremental.payload;
      totalSynced = incremental.counts.attendance || 0;
      console.log(`[OnlineBackup] Incremental sync: ${JSON.stringify(incremental.counts)}`);
    } else {
      payload = await generateCompressedPayload();
      const attCount = payload.data?.attendance?.length || 0;
      console.log(`[OnlineBackup] Full sync: ${attCount} attendance records`);
    }

    // Chunk attendance into RECORDS_PER_CHUNK-record chunks (300 records each)
    const CHUNK_SIZE = RECORDS_PER_CHUNK;
    const attendanceRecords = payload.data?.attendance || [];
    const otherData = { ...payload };
    if (otherData.data) delete otherData.data.attendance;

    if (useIncremental) {
      // ===== INCREMENTAL SYNC: APPEND to existing chunks =====
      // RULES:
      // 1. Fetch existing meta.json to get current chunk count + total attendance
      // 2. Fetch the LAST chunk to see how full it is
      // 3. Append new records to the last chunk (if < RECORDS_PER_CHUNK records)
      // 4. If last chunk is full (RECORDS_PER_CHUNK records) → create new chunk
      // 5. Update meta.json: attendanceCount = existingCount + NEW records only (not total in chunk)
      // 6. totalChunks = (number of attendance chunks) + 1 (for meta)

      console.log(`[OnlineBackup Incremental] New attendance to sync: ${attendanceRecords.length} records`);

      // Get existing meta.json
      let existingTotalChunks = 1; // includes meta (chunk 0)
      let existingAttendanceCount = 0;
      let lastChunkIndex = 0; // last attendance chunk index (1-based)
      let lastChunkAttendance: any[] = [];
      let lastChunkSha: string | undefined = undefined;
      let metaSha: string | undefined = undefined;
      let existingMetaData: any = null; // existing meta data (classes, students, etc.)

      try {
        const existingMeta = await githubGetFile(config, META_FILE);
        if (existingMeta) {
          metaSha = existingMeta.sha;
          const meta = JSON.parse(existingMeta.content);
          existingTotalChunks = meta.meta?.totalChunks || meta.chunk?.total || 1;
          existingAttendanceCount = meta.meta?.attendanceCount || 0;
          existingMetaData = meta.data || null; // preserve existing classes/students/settings
          // lastChunkIndex = totalChunks - 1 (since chunk 0 is meta, chunks 1..N-1 are attendance)
          lastChunkIndex = existingTotalChunks > 1 ? existingTotalChunks - 1 : 0;
          console.log(`[OnlineBackup Incremental] Existing meta: totalChunks=${existingTotalChunks}, attendanceCount=${existingAttendanceCount}, lastChunkIndex=${lastChunkIndex}`);

          // Fetch the last chunk to see how full it is
          if (lastChunkIndex > 0) {
            const lastChunkPath = `${CHUNK_PREFIX}${lastChunkIndex}.json`;
            try {
              const lastChunkFile = await githubGetFile(config, lastChunkPath);
              if (lastChunkFile) {
                const lastChunkData = JSON.parse(lastChunkFile.content);
                lastChunkAttendance = lastChunkData.data?.attendance || [];
                lastChunkSha = lastChunkFile.sha;
                console.log(`[OnlineBackup Incremental] Last chunk (${lastChunkIndex}): ${lastChunkAttendance.length} records (SHA: ${lastChunkSha?.substring(0, 8)})`);
              } else {
                // Chunk doesn't exist (404) — meta.json totalChunks is inflated
                // Need to find the ACTUAL last chunk by listing the backup folder
                console.warn(`[OnlineBackup Incremental] Last chunk ${lastChunkIndex} not found — meta.json totalChunks may be inflated. Finding actual last chunk...`);
                const GITHUB_API = 'https://api.github.com';
                const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
                  headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
                  signal: AbortSignal.timeout(15000),
                });
                if (listRes.ok) {
                  const files = await listRes.json();
                  if (Array.isArray(files)) {
                    // Find the highest chunk-N.json number
                    let actualLastChunk = 0;
                    for (const f of files) {
                      const match = f.name?.match(/^chunk-(\d+)\.json$/);
                      if (match) {
                        const num = parseInt(match[1], 10);
                        if (num > actualLastChunk) actualLastChunk = num;
                      }
                    }
                    console.log(`[OnlineBackup Incremental] Actual last chunk on GitHub: ${actualLastChunk} (meta said ${lastChunkIndex})`);
                    lastChunkIndex = actualLastChunk;
                    existingTotalChunks = actualLastChunk + 1; // +1 for meta

                    // Now fetch the ACTUAL last chunk
                    if (lastChunkIndex > 0) {
                      const actualLastPath = `${CHUNK_PREFIX}${lastChunkIndex}.json`;
                      try {
                        const actualLastFile = await githubGetFile(config, actualLastPath);
                        if (actualLastFile) {
                          const actualLastData = JSON.parse(actualLastFile.content);
                          lastChunkAttendance = actualLastData.data?.attendance || [];
                          lastChunkSha = actualLastFile.sha;
                          console.log(`[OnlineBackup Incremental] Actual last chunk (${lastChunkIndex}): ${lastChunkAttendance.length} records`);
                        }
                      } catch {}
                    }

                    // Fix attendanceCount: count actual records (not the inflated meta value)
                    // We can't count all records without fetching all chunks, so estimate from file count
                    const actualFileCount = files.filter((f: any) => f.name?.startsWith('chunk-')).length;
                    const estimatedAttCount = actualFileCount * RECORDS_PER_CHUNK; // max possible
                    if (existingAttendanceCount > estimatedAttCount) {
                      console.warn(`[OnlineBackup Incremental] attendanceCount ${existingAttendanceCount} exceeds max possible ${estimatedAttCount} — capping`);
                      existingAttendanceCount = estimatedAttCount;
                    }
                  }
                }
              }
            } catch (e) {
              console.warn('[OnlineBackup Incremental] Could not fetch last chunk:', e instanceof Error ? e.message : String(e));
            }
          }
        }
      } catch {
        // meta.json doesn't exist yet — first sync
        console.log('[OnlineBackup Incremental] No existing meta.json — starting fresh');
      }

      // Deduplicate: filter out records that already exist in the last chunk
      // Use composite key (studentId_date_hour) to detect true duplicates, not just ID
      const existingKeys = new Set(lastChunkAttendance.map((r: any) => `${r.studentId}_${r.date}_${r.hour}`));
      const trulyNewRecords = attendanceRecords.filter((r: any) => !existingKeys.has(`${r.studentId}_${r.date}_${r.hour}`));
      console.log(`[OnlineBackup Incremental] After dedup: ${trulyNewRecords.length} truly new records (was ${attendanceRecords.length})`);

      if (trulyNewRecords.length === 0) {
        console.log('[OnlineBackup Incremental] No new records to sync — skipping');
        return { success: true, message: 'Tidak ada data baru untuk disinkronkan (semua sudah ada).' };
      }

      let recordsToDistribute = [...trulyNewRecords];
      const chunksToPush: { index: number; attendance: any[]; sha?: string }[] = [];

      // Step 1: Fill the last existing chunk (if it has room < CHUNK_SIZE)
      if (lastChunkAttendance.length < CHUNK_SIZE && lastChunkIndex > 0 && recordsToDistribute.length > 0) {
        const spaceInLastChunk = CHUNK_SIZE - lastChunkAttendance.length;
        const fillCount = Math.min(spaceInLastChunk, recordsToDistribute.length);
        const fillRecords = recordsToDistribute.splice(0, fillCount);
        // DEDUPLICATE: filter out records already in the last chunk by (studentId, date, hour)
        const existingKeys = new Set(lastChunkAttendance.map((r: any) => `${r.studentId}_${r.date}_${r.hour}`));
        const trulyNewFill = fillRecords.filter((r: any) => !existingKeys.has(`${r.studentId}_${r.date}_${r.hour}`));
        if (trulyNewFill.length < fillRecords.length) {
          console.log(`[OnlineBackup Incremental] Dedup: removed ${fillRecords.length - trulyNewFill.length} duplicate records from fill`);
        }
        const updatedLastChunk = [...lastChunkAttendance, ...trulyNewFill];
        if (trulyNewFill.length > 0) {
          chunksToPush.push({ index: lastChunkIndex, attendance: updatedLastChunk, sha: lastChunkSha });
          console.log(`[OnlineBackup Incremental] Appended ${trulyNewFill.length} new records to chunk ${lastChunkIndex} (now ${updatedLastChunk.length} records total)`);
        }
      }

      // Step 2: Create new chunks for remaining records (RECORDS_PER_CHUNK each)
      // DEDUPLICATE across new chunks too
      const allChunkKeys = new Set<string>();
      let newChunkIndex = lastChunkIndex > 0 ? lastChunkIndex + 1 : 1;
      while (recordsToDistribute.length > 0) {
        const chunk = recordsToDistribute.splice(0, CHUNK_SIZE);
        // Filter out duplicates within this batch
        const dedupedChunk = chunk.filter((r: any) => {
          const key = `${r.studentId}_${r.date}_${r.hour}`;
          if (allChunkKeys.has(key)) return false;
          allChunkKeys.add(key);
          return true;
        });
        if (dedupedChunk.length > 0) {
          chunksToPush.push({ index: newChunkIndex, attendance: dedupedChunk });
          console.log(`[OnlineBackup Incremental] New chunk ${newChunkIndex}: ${dedupedChunk.length} records`);
          newChunkIndex++;
        }
      }

      // Calculate final totals:
      // - newChunkIndex is now the NEXT index after the last created/updated chunk
      // - totalChunks = (last attendance chunk index) + 1 (for meta)
      // - If we only updated the last chunk (no new chunks), totalChunks = lastChunkIndex + 1
      // - If we created new chunks, totalChunks = newChunkIndex (since newChunkIndex = lastCreatedIndex + 1)
      const lastCreatedOrUpdatedIndex = chunksToPush.length > 0 ? chunksToPush[chunksToPush.length - 1].index : lastChunkIndex;
      const finalTotalChunks = Math.max(lastCreatedOrUpdatedIndex + 1, existingTotalChunks);

      // attendanceCount = existing + truly new (after dedup by studentId_date_hour)
      const newAttendanceCount = existingAttendanceCount + trulyNewRecords.length;

      console.log(`[OnlineBackup Incremental] Final: totalChunks=${finalTotalChunks}, attendanceCount=${newAttendanceCount} (was ${existingAttendanceCount}, added ${trulyNewRecords.length})`);

      // 1. Update meta.json
      // Merge: existing meta data (classes, students, settings, etc.) + new data from incremental payload
      // This ensures meta.json always has COMPLETE data, not just the incremental changes
      const mergedData = {
        // Start with existing meta data (preserves classes, students, settings, schedules, etc.)
        ...(existingMetaData || {}),
        // Override with new data from incremental payload (if any new classes/students/settings were added)
        ...otherData.data,
      };
      // Remove attendance from meta (it's in chunks, not in meta)
      delete mergedData.attendance;

      if (isCancelled()) {
        return { success: false, message: 'Sync dihentikan oleh user.' };
      }
      reportProgress(0, chunksToPush.length + 1, 'Meta data (kelas, siswa, pengaturan...)');
      const metaPayload = {
        version: 3,
        exportedAt: new Date().toISOString(),
        appName: 'ABSENSI SISWA MTs Al ISHLAH',
        compressed: true,
        data: mergedData,
        chunk: { index: 0, total: finalTotalChunks, type: 'meta' },
        meta: {
          totalChunks: finalTotalChunks,
          attendanceCount: newAttendanceCount,
          incremental: true,
          exportedAt: new Date().toISOString(),
        },
      };
      const metaContent = JSON.stringify(metaPayload);
      console.log(`[OnlineBackup Incremental] Meta: ${Math.round(metaContent.length / 1024)} KB, totalChunks=${finalTotalChunks}, attendance=${newAttendanceCount}`);
      try {
        await githubPutFile(config, META_FILE, metaContent, `backup: meta (total=${finalTotalChunks}, attendance=${newAttendanceCount})`, metaSha);
        console.log('[OnlineBackup Incremental] Meta.json updated');
      } catch (e) {
        const errMsg = e instanceof Error ? e.message : String(e);
        console.error('[OnlineBackup Incremental] Meta FAILED:', errMsg);
        return { success: false, message: `Gagal update meta.json: ${errMsg}` };
      }

      // 2. Push/update chunks
      let chunkPushIndex = 0;
      for (const chunkData of chunksToPush) {
        if (isCancelled()) {
          return { success: false, message: `Sync dihentikan. ${totalSynced} records synced.` };
        }
        chunkPushIndex++;
        reportProgress(chunkPushIndex, chunksToPush.length + 1, `Absensi chunk ${chunkData.index}/${finalTotalChunks - 1} (${chunkData.attendance.length} records)`);
        const chunkPayload = {
          version: 4,
          mode: 'merge',
          chunk: { index: chunkData.index, total: finalTotalChunks, type: 'attendance' },
          data: { attendance: chunkData.attendance },
        };
        const chunkContent = JSON.stringify(chunkPayload);
        const chunkPath = `${CHUNK_PREFIX}${chunkData.index}.json`;
        console.log(`[OnlineBackup Incremental] Chunk ${chunkData.index}: ${chunkData.attendance.length} records, ${Math.round(chunkContent.length / 1024)} KB`);

        try {
          await githubPutFile(config, chunkPath, chunkContent, `backup: chunk ${chunkData.index} (${chunkData.attendance.length} records)`, chunkData.sha);
        } catch (e) {
          console.warn(`[OnlineBackup Incremental] Chunk ${chunkData.index} error:`, e instanceof Error ? e.message : String(e));
        }

        if (chunkPushIndex < chunksToPush.length) {
          await new Promise(r => setTimeout(r, 200));
        }
      }

      // totalSynced = number of truly NEW records (not total in chunks)
      totalSynced = trulyNewRecords.length;

      // Update last sync timestamp + attendance count
      const now = new Date().toISOString();
      try {
        await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
        await db.settings.upsert({
          where: { key: ATTENDANCE_COUNT_KEY },
          update: { value: String(newAttendanceCount) },
          create: { key: ATTENDANCE_COUNT_KEY, value: String(newAttendanceCount) },
        });
        // Also save to persistent file (survives server resets)
        try {
          const { savePersistentGhCount } = await import('./db-persistent-sync');
          await savePersistentGhCount(newAttendanceCount);
        } catch {}
      } catch {}

      return {
        success: true,
        message: `Incremental sync berhasil! ${trulyNewRecords.length} absensi baru ditambahkan. Total: ${newAttendanceCount} absensi dalam ${finalTotalChunks - 1} chunk.`,
      };
    }

    // ===== FULL SYNC (manual): replace all data =====
    const totalChunks = Math.ceil(attendanceRecords.length / CHUNK_SIZE) + 1; // +1 for meta

    // 1. Push meta chunk (chunk-0.json) — contains all non-attendance data + first attendance chunk if small
    if (isCancelled()) {
      return { success: false, message: 'Sync dihentikan oleh user.' };
    }
    reportProgress(0, totalChunks, 'Meta data (kelas, siswa, pengaturan...)');
    // CRITICAL: Filter sensitive settings from full sync meta
    const fullSyncData = { ...otherData.data };
    if (fullSyncData.settings) {
      fullSyncData.settings = filterSensitiveSettings(fullSyncData.settings);
    }
    const metaPayload = {
      version: 3,
      exportedAt: new Date().toISOString(),
      appName: 'ABSENSI SISWA MTs Al ISHLAH',
      compressed: true,
      data: fullSyncData,
      chunk: { index: 0, total: totalChunks, type: 'meta' },
      meta: {
        totalChunks,
        attendanceCount: attendanceRecords.length,
        incremental: false,
        exportedAt: new Date().toISOString(),
      },
    };
    const metaContent = JSON.stringify(metaPayload);
    console.log(`[OnlineBackup] Meta chunk: ${Math.round(metaContent.length / 1024)} KB`);
    try {
      // Get existing SHA (if file exists) for update — use proper error handling
      let existingSha: string | undefined = undefined;
      try {
        const existing = await githubGetFile(config, META_FILE);
        if (existing) {
          existingSha = existing.sha;
          console.log('[OnlineBackup] Meta file exists, will update (SHA:', existingSha?.substring(0, 8) + ')');
        } else {
          console.log('[OnlineBackup] Meta file does not exist, will create new');
        }
      } catch (e) {
        // Non-404 error (e.g. auth) — log but don't stop, try to create new
        console.warn('[OnlineBackup] Meta file GET error (non-404):', e instanceof Error ? e.message : String(e));
      }
      await githubPutFile(config, META_FILE, metaContent, `backup: meta chunk (total=${totalChunks})`, existingSha);
      console.log('[OnlineBackup] Meta chunk pushed successfully');
    } catch (e) {
      const errMsg = e instanceof Error ? e.message : String(e);
      console.error('[OnlineBackup] Meta chunk FAILED — cannot continue without meta:', errMsg);
      return {
        success: false,
        message: `Gagal mengunggah meta.json ke GitHub: ${errMsg}. Sync dibatalkan. Periksa token/izin repo.`,
      };
    }

    // 2. Push attendance chunks
    let chunkIndex = 0;
    for (let i = 0; i < attendanceRecords.length; i += CHUNK_SIZE) {
      if (isCancelled()) {
        console.log(`[OnlineBackup] Cancelled at chunk ${chunkIndex}/${totalChunks - 1}. Synced ${totalSynced} records.`);
        return { success: false, message: `Sync dihentikan oleh user. ${totalSynced} absensi telah tersinkron sebelum stop.` };
      }
      chunkIndex++;
      const chunk = attendanceRecords.slice(i, i + CHUNK_SIZE);
      reportProgress(chunkIndex, totalChunks, `Absensi chunk ${chunkIndex}/${totalChunks - 1} (${chunk.length} records)`);
      const chunkPayload = {
        version: 4,
        mode: useIncremental ? 'merge' : 'full',
        chunk: { index: chunkIndex, total: totalChunks, type: 'attendance' },
        data: { attendance: chunk },
      };
      const chunkContent = JSON.stringify(chunkPayload);
      const chunkPath = `${CHUNK_PREFIX}${chunkIndex}.json`;
      console.log(`[OnlineBackup] Chunk ${chunkIndex}: ${chunk.length} records, ${Math.round(chunkContent.length / 1024)} KB`);

      try {
        let chunkSha: string | undefined = undefined;
        try {
          const existing = await githubGetFile(config, chunkPath);
          if (existing) chunkSha = existing.sha;
        } catch (e) {
          // Non-404 error — log but don't stop, try to create new
          console.warn(`[OnlineBackup] Chunk ${chunkIndex} GET error (non-404):`, e instanceof Error ? e.message : String(e));
        }
        await githubPutFile(config, chunkPath, chunkContent, `backup: attendance chunk ${chunkIndex}/${totalChunks - 1}`, chunkSha);
        totalSynced += chunk.length;
      } catch (e) {
        console.warn(`[OnlineBackup] Chunk ${chunkIndex} error:`, e instanceof Error ? e.message : String(e));
      }

      // Small delay to avoid rate limiting
      if (i + CHUNK_SIZE < attendanceRecords.length) {
        await new Promise(r => setTimeout(r, 200));
      }
    }

    // 3. NO MASS CLEANUP in full sync — REMOVED per user request.
    // Previously, full sync deleted ALL chunks beyond the current total
    // ("cleanup: old chunk N (full sync)"). This caused DATA LOSS when the
    // local DB was missing data that GitHub had (e.g., after a server reset,
    // the full sync rebuilt chunks from the local DB and deleted the GitHub
    // chunks that had data the local DB didn't — destroying Oct 3-13 data
    // on 2026-10-13 when chunks 207-238 were deleted).
    //
    // Full sync is now APPEND/OVERWRITE-ONLY:
    //   - Existing chunks are overwritten with new data (githubPutFile with sha)
    //   - New chunks are created if local has MORE data than GitHub
    //   - Old chunks beyond the new total REMAIN on GitHub (not deleted)
    //   - Pull-diff fetches ALL chunks and deduplicates locally, so users
    //     still see correct data even with leftover old chunks
    //
    // The ONLY way to do mass chunk deletion is the manual DEDUP CHUNK button
    // (deduplicateAndRepairMeta), which requires explicit user action.
    // Auto-sync and full sync NEVER delete chunks.

    // 4. Update last sync timestamp + attendance count
    const now = new Date().toISOString();
    await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
    await db.settings.upsert({
      where: { key: ATTENDANCE_COUNT_KEY },
      update: { value: String(attendanceRecords.length) },
      create: { key: ATTENDANCE_COUNT_KEY, value: String(attendanceRecords.length) },
    });
    // Also save to persistent file (survives server resets)
    try {
      const { savePersistentGhCount } = await import('./db-persistent-sync');
      await savePersistentGhCount(attendanceRecords.length);
    } catch {}

    return {
      success: true,
      message: `Sync berhasil! ${payload.data?.classes?.length || 0} kelas, ${payload.data?.students?.length || 0} siswa, ${totalSynced} absensi, ${payload.data?.academicHolidays?.length || 0} hari libur mingguan, ${payload.data?.dateHolidays?.length || 0} hari libur tanggal, ${payload.data?.teachers?.length || 0} guru, ${payload.data?.waliKelas?.length || 0} wali kelas, ${payload.data?.schedules?.length || 0} jadwal, ${payload.data?.settings?.length || 0} pengaturan (termasuk max hour) — dalam ${chunkIndex} chunk`,
    };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Sync melebihi batas waktu.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('[OnlineBackup] Sync error:', error);
    return { success: false, message: `Gagal sync: ${message}` };
  }
}

/**
 * Repair meta.json only — useful when chunks exist in GitHub but meta.json is missing/corrupt.
 * This pushes ONLY the meta file (classes, students, settings, etc.) without re-pushing all attendance.
 *
 * The totalChunks and attendanceCount are determined by FETCHING ALL CHUNKS from GitHub
 * and counting actual files + actual attendance records. This ensures meta.json reflects
 * the TRUE state of the GitHub repo, not the local DB (which may differ after a deploy/reset).
 */
export async function repairMetaFile(): Promise<{ success: boolean; message: string }> {
  try {
    const config = await getConfig();
    if (!config) {
      return { success: false, message: 'GitHub backup belum dikonfigurasi.' };
    }

    // Generate full payload to get all non-attendance data (classes, students, settings, etc.)
    const payload = await generateCompressedPayload();

    // Step 1: List all files in the backup/ directory to find chunk files
    const GITHUB_API = 'https://api.github.com';
    let totalChunks = 1;
    let chunkFiles: { name: string; path: string }[] = [];
    try {
      const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
        headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
        signal: AbortSignal.timeout(15000),
      });
      if (listRes.ok) {
        const files = await listRes.json();
        if (Array.isArray(files)) {
          chunkFiles = files.filter((f: any) => f.name?.startsWith('chunk-') && f.name?.endsWith('.json'));
          totalChunks = chunkFiles.length + 1; // +1 for meta
          console.log(`[OnlineBackup Repair] Found ${chunkFiles.length} chunk files in repo. totalChunks=${totalChunks}`);
        }
      }
    } catch (e) {
      console.warn('[OnlineBackup Repair] Could not list repo files:', e instanceof Error ? e.message : String(e));
    }

    // Step 2: Fetch ALL chunks and count ACTUAL attendance records.
    // This ensures meta.json attendanceCount matches the real data in GitHub,
    // not the local DB count (which could be different after deploy/reset).
    let attendanceCount = 0;
    let chunksSucceeded = 0;
    let chunksFailed = 0;
    const PARALLEL_BATCH = 5;
    console.log(`[OnlineBackup Repair] Fetching ${chunkFiles.length} chunks to count attendance records (parallel x${PARALLEL_BATCH})...`);

    for (let i = 0; i < chunkFiles.length; i += PARALLEL_BATCH) {
      const batch = chunkFiles.slice(i, i + PARALLEL_BATCH);
      const results = await Promise.all(
        batch.map(async (f) => {
          try {
            const chunkFile = await githubGetFile(config, f.path);
            if (!chunkFile) return { count: 0, ok: false };
            const chunkData = JSON.parse(chunkFile.content);
            const att = chunkData.data?.attendance || [];
            return { count: Array.isArray(att) ? att.length : 0, ok: true };
          } catch {
            return { count: 0, ok: false };
          }
        })
      );
      for (const r of results) {
        if (r.ok) {
          chunksSucceeded++;
          attendanceCount += r.count;
        } else {
          chunksFailed++;
        }
      }
    }

    console.log(`[OnlineBackup Repair] Counted ${attendanceCount} attendance records from ${chunksSucceeded} chunks (${chunksFailed} failed)`);

    // If we couldn't fetch ANY chunks, fall back to local DB count as last resort
    if (chunksSucceeded === 0 && chunksFailed > 0) {
      const localCount = payload.data?.attendance?.length || 0;
      console.warn(`[OnlineBackup Repair] All chunk fetches failed — using local DB count (${localCount}) as fallback`);
      attendanceCount = localCount;
    }

    // Build meta payload (without attendance data — only metadata)
    const otherData = { ...payload };
    if (otherData.data) delete otherData.data.attendance;
    const metaPayload = {
      ...otherData,
      chunk: { index: 0, total: totalChunks, type: 'meta' },
      meta: {
        totalChunks,
        attendanceCount,
        incremental: false,
        exportedAt: new Date().toISOString(),
        repaired: true,
      },
    };
    const metaContent = JSON.stringify(metaPayload);
    console.log(`[OnlineBackup Repair] Meta chunk: ${Math.round(metaContent.length / 1024)} KB, totalChunks=${totalChunks}, attendanceCount=${attendanceCount}`);

    // Push meta.json
    // Fetch existing sha FIRST. If the file exists, we MUST supply its sha to GitHub
    // (otherwise GitHub returns 422 "sha wasn't supplied").
    // Only treat 404/null as "file doesn't exist" — other errors must propagate.
    let existingSha: string | undefined = undefined;
    try {
      const existing = await githubGetFile(config, META_FILE);
      if (existing) {
        existingSha = existing.sha;
        console.log('[OnlineBackup Repair] Meta file exists, updating (SHA:', existingSha?.substring(0, 8) + ')');
      } else {
        console.log('[OnlineBackup Repair] Meta file does not exist (404) — creating new');
      }
    } catch (e) {
      // Non-404 error (network, rate limit, 500, etc.) — DON'T assume file doesn't exist.
      // If we proceed without sha and the file actually exists, GitHub returns 422.
      // Instead, propagate the error so the user knows to retry.
      const msg = e instanceof Error ? e.message : String(e);
      console.error('[OnlineBackup Repair] Failed to fetch existing meta (non-404):', msg);
      return {
        success: false,
        message: `Gagal mengecek meta.json yang ada: ${msg}. Coba lagi dalam beberapa saat.`,
      };
    }
    await githubPutFile(config, META_FILE, metaContent, `repair: meta.json (totalChunks=${totalChunks})`, existingSha);
    console.log('[OnlineBackup Repair] Meta.json pushed successfully');

    return {
      success: true,
      message: `Meta.json berhasil diperbaiki! ${totalChunks - 1} chunk absensi ditemukan, ${attendanceCount} record absensi dihitung dari GitHub. PULL sekarang seharusnya berfungsi.`,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('[OnlineBackup Repair] Error:', error);
    return { success: false, message: `Gagal repair meta: ${message}` };
  }
}

/**
 * Deduplicate chunks and repair meta.json.
 *
 * This function:
 * 1. Fetches ALL chunk files from GitHub
 * 2. Collects all attendance records and deduplicates by composite key (studentId_date_hour)
 * 3. Identifies duplicate chunks (chunks whose records all appear elsewhere)
 * 4. Rewrites remaining chunks with only unique records
 * 5. Deletes extra/duplicate chunks from GitHub
 * 6. Updates meta.json with the correct totalChunks and attendanceCount
 *
 * After this operation:
 * - Each chunk contains only unique records (no duplicates within or across chunks)
 * - No two chunks have the same content
 * - meta.json reflects the actual state of the GitHub repo
 */
export async function deduplicateAndRepairMeta(): Promise<{ success: boolean; message: string; details?: any }> {
  try {
    const config = await getConfig();
    if (!config) {
      return { success: false, message: 'GitHub backup belum dikonfigurasi.' };
    }

    const GITHUB_API = 'https://api.github.com';
    const CHUNK_SIZE = RECORDS_PER_CHUNK;

    // Step 1: List all files in backup/ directory
    reportProgress(0, 1, 'Mengambil daftar chunk dari GitHub...');
    let chunkFiles: { name: string; path: string; sha: string }[] = [];
    try {
      const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
        headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
        signal: AbortSignal.timeout(15000),
      });
      if (listRes.ok) {
        const files = await listRes.json();
        if (Array.isArray(files)) {
          chunkFiles = files
            .filter((f: any) => f.name?.startsWith('chunk-') && f.name?.endsWith('.json'))
            .map((f: any) => ({ name: f.name, path: f.path, sha: f.sha }))
            .sort((a: any, b: any) => {
              // Sort by chunk index number
              const aNum = parseInt(a.name.match(/chunk-(\d+)\.json/)?.[1] || '0');
              const bNum = parseInt(b.name.match(/chunk-(\d+)\.json/)?.[1] || '0');
              return aNum - bNum;
            });
        }
      }
    } catch (e) {
      return { success: false, message: `Gagal mengambil daftar chunk: ${e instanceof Error ? e.message : String(e)}` };
    }

    console.log(`[OnlineBackup Dedup] Found ${chunkFiles.length} chunk files in GitHub repo`);

    // Step 2: Fetch ALL chunks and collect attendance records
    // Use a Map to deduplicate by composite key (studentId_date_hour)
    const uniqueRecords = new Map<string, any>(); // key -> record
    let totalRecordsFetched = 0;
    let duplicateRecordsRemoved = 0;
    const chunkContents: { index: number; path: string; sha: string; records: any[] }[] = [];
    let chunksSucceeded = 0;
    let chunksFailed = 0;
    const PARALLEL_BATCH = 5;

    reportProgress(0, chunkFiles.length + 1, `Mengambil ${chunkFiles.length} chunk (parallel x${PARALLEL_BATCH})...`);

    for (let i = 0; i < chunkFiles.length; i += PARALLEL_BATCH) {
      if (isCancelled()) {
        return { success: false, message: 'Deduplication dibatalkan oleh user.' };
      }
      const batch = chunkFiles.slice(i, i + PARALLEL_BATCH);
      const batchResults = await Promise.all(
        batch.map(async (f) => {
          try {
            const chunkFile = await githubGetFile(config, f.path);
            if (!chunkFile) return { file: f, records: [], ok: false };
            const chunkData = JSON.parse(chunkFile.content);
            const att = chunkData.data?.attendance || [];
            return { file: f, records: Array.isArray(att) ? att : [], ok: true, sha: chunkFile.sha };
          } catch {
            return { file: f, records: [], ok: false };
          }
        })
      );
      for (const r of batchResults) {
        const chunkIndex = parseInt(r.file.name.match(/chunk-(\d+)\.json/)?.[1] || '0');
        if (r.ok) {
          chunksSucceeded++;
          chunkContents.push({ index: chunkIndex, path: r.file.path, sha: r.sha, records: r.records });
          for (const rec of r.records) {
            totalRecordsFetched++;
            const key = `${rec.studentId}_${rec.date}_${rec.hour}`;
            if (uniqueRecords.has(key)) {
              duplicateRecordsRemoved++;
            } else {
              uniqueRecords.set(key, rec);
            }
          }
        } else {
          chunksFailed++;
        }
      }
      reportProgress(i + PARALLEL_BATCH, chunkFiles.length + 1, `Mengambil chunk ${Math.min(i + PARALLEL_BATCH, chunkFiles.length)}/${chunkFiles.length}...`);
    }

    const uniqueAttendance = Array.from(uniqueRecords.values());
    console.log(`[OnlineBackup Dedup] Fetched ${totalRecordsFetched} records from ${chunksSucceeded} chunks. Unique: ${uniqueAttendance.length}, Duplicates removed: ${duplicateRecordsRemoved}`);

    if (chunksSucceeded === 0) {
      return { success: false, message: `Gagal mengambil semua chunk dari GitHub (${chunksFailed} gagal).` };
    }

    // Step 2.5: Filter out records of deleted students (students no longer in local DB)
    // This removes attendance records whose studentId doesn't exist in the local Student table.
    // This is called after pullFromGSheets() deletes orphaned attendance locally —
    // the GitHub chunks still have those records, so we need to filter them out here.
    let deletedStudentRecords = 0;
    try {
      const localStudentIds = new Set((await db.student.findMany({ select: { id: true } })).map(s => s.id));
      if (localStudentIds.size > 0) {
        const beforeFilter = uniqueAttendance.length;
        // Filter unique records: only keep records whose studentId exists in local DB
        const filteredRecords = uniqueAttendance.filter((rec: any) => {
          if (rec.studentId && localStudentIds.has(rec.studentId)) return true;
          deletedStudentRecords++;
          return false;
        });
        // Replace uniqueRecords map values with filtered set
        uniqueAttendance.length = 0; // clear array
        for (const rec of filteredRecords) {
          uniqueAttendance.push(rec);
        }
        if (deletedStudentRecords > 0) {
          console.log(`[OnlineBackup Dedup] Filtered ${deletedStudentRecords} records of deleted students (before: ${beforeFilter}, after: ${uniqueAttendance.length})`);
        }
      }
    } catch (e) {
      console.warn('[OnlineBackup Dedup] Could not filter deleted student records:', e instanceof Error ? e.message : String(e));
    }

    // Step 3: Build new chunks from unique records
    const newChunkCount = Math.ceil(uniqueAttendance.length / CHUNK_SIZE);
    const newChunks: { index: number; attendance: any[] }[] = [];
    for (let i = 0; i < uniqueAttendance.length; i += CHUNK_SIZE) {
      const chunkIndex = Math.floor(i / CHUNK_SIZE) + 1; // chunks start at 1
      const chunkAttendance = uniqueAttendance.slice(i, i + CHUNK_SIZE);
      newChunks.push({ index: chunkIndex, attendance: chunkAttendance });
    }

    console.log(`[OnlineBackup Dedup] New chunk plan: ${newChunkCount} chunks (was ${chunkFiles.length}), ${uniqueAttendance.length} unique records`);

    // Step 4: Determine which chunks need to be pushed, kept, or deleted
    const chunksToPush: { index: number; attendance: any[]; sha?: string }[] = [];
    const chunksToDelete: { path: string; sha: string; index: number }[] = [];

    // Build a map of existing chunk contents for comparison
    const existingChunksMap = new Map<number, { records: any[]; path: string; sha: string }>();
    for (const c of chunkContents) {
      existingChunksMap.set(c.index, { records: c.records, path: c.path, sha: c.sha });
    }

    // For each new chunk, check if an existing chunk already has the exact same records
    let chunksUnchanged = 0;
    for (const newChunk of newChunks) {
      const existing = existingChunksMap.get(newChunk.index);
      if (existing) {
        // Compare: if same record count and all keys match, skip (no push needed)
        const existingKeys = new Set(existing.records.map((r: any) => `${r.studentId}_${r.date}_${r.hour}`));
        const newKeys = new Set(newChunk.attendance.map((r: any) => `${r.studentId}_${r.date}_${r.hour}`));
        if (existing.records.length === newChunk.attendance.length && [...existingKeys].every(k => newKeys.has(k))) {
          chunksUnchanged++;
          existingChunksMap.delete(newChunk.index); // Mark as "kept" (don't delete)
          continue;
        }
        // Content differs — need to push (update with existing sha)
        chunksToPush.push({ index: newChunk.index, attendance: newChunk.attendance, sha: existing.sha });
        existingChunksMap.delete(newChunk.index); // Mark as "updated" (don't delete)
      } else {
        // No existing chunk at this index — create new
        chunksToPush.push({ index: newChunk.index, attendance: newChunk.attendance });
      }
    }

    // Any remaining existing chunks (not matched above) are extra and should be deleted
    for (const [index, existing] of existingChunksMap) {
      chunksToDelete.push({ path: existing.path, sha: existing.sha, index });
    }

    console.log(`[OnlineBackup Dedup] Plan: ${chunksUnchanged} unchanged, ${chunksToPush.length} to push, ${chunksToDelete.length} to delete`);

    // Step 5: Push new/updated chunks
    reportProgress(chunkFiles.length, chunkFiles.length + chunksToPush.length + chunksToDelete.length + 1, `Mengupload ${chunksToPush.length} chunk...`);
    let pushSucceeded = 0;
    let pushFailed = 0;
    for (let i = 0; i < chunksToPush.length; i++) {
      if (isCancelled()) {
        return { success: false, message: `Deduplication dibatalkan. ${pushSucceeded} chunk diupload, ${chunksToDelete.length - 0} chunk belum dihapus.` };
      }
      const cd = chunksToPush[i];
      const chunkPayload = {
        version: 4,
        mode: 'merge',
        chunk: { index: cd.index, total: newChunkCount + 1, type: 'attendance' },
        data: { attendance: cd.attendance },
      };
      try {
        await githubPutFile(config, `${CHUNK_PREFIX}${cd.index}.json`, JSON.stringify(chunkPayload), `dedup: chunk ${cd.index} (${cd.attendance.length} records)`, cd.sha);
        pushSucceeded++;
      } catch (e) {
        pushFailed++;
        console.warn(`[OnlineBackup Dedup] Failed to push chunk ${cd.index}:`, e instanceof Error ? e.message : String(e));
      }
      reportProgress(chunkFiles.length + i + 1, chunkFiles.length + chunksToPush.length + chunksToDelete.length + 1, `Mengupload chunk ${cd.index}/${newChunkCount}...`);
    }

    // Step 6: Delete extra chunks
    reportProgress(chunkFiles.length + chunksToPush.length, chunkFiles.length + chunksToPush.length + chunksToDelete.length + 1, `Menghapus ${chunksToDelete.length} chunk duplikat...`);
    let deleteSucceeded = 0;
    let deleteFailed = 0;
    for (let i = 0; i < chunksToDelete.length; i++) {
      if (isCancelled()) break;
      const cd = chunksToDelete[i];
      try {
        await githubDeleteFile(config, cd.path, cd.sha, `dedup: delete duplicate chunk ${cd.index}`);
        deleteSucceeded++;
      } catch (e) {
        deleteFailed++;
        console.warn(`[OnlineBackup Dedup] Failed to delete chunk ${cd.index}:`, e instanceof Error ? e.message : String(e));
      }
      reportProgress(chunkFiles.length + chunksToPush.length + i + 1, chunkFiles.length + chunksToPush.length + chunksToDelete.length + 1, `Menghapus chunk ${cd.index}...`);
    }

    // Step 7: Update meta.json with correct count
    reportProgress(chunkFiles.length + chunksToPush.length + chunksToDelete.length, chunkFiles.length + chunksToPush.length + chunksToDelete.length + 1, 'Mengupdate meta.json...');
    const finalTotalChunks = newChunkCount + 1; // +1 for meta
    const payload = await generateCompressedPayload();
    const otherData = { ...payload };
    if (otherData.data) delete otherData.data.attendance;
    const metaPayload = {
      ...otherData,
      chunk: { index: 0, total: finalTotalChunks, type: 'meta' },
      meta: {
        totalChunks: finalTotalChunks,
        attendanceCount: uniqueAttendance.length,
        incremental: false,
        exportedAt: new Date().toISOString(),
        deduplicated: true,
      },
    };

    let metaSha: string | undefined = undefined;
    try {
      const existingMeta = await githubGetFile(config, META_FILE);
      if (existingMeta) metaSha = existingMeta.sha;
    } catch {}
    await githubPutFile(config, META_FILE, JSON.stringify(metaPayload), `dedup: meta (totalChunks=${finalTotalChunks}, attendance=${uniqueAttendance.length})`, metaSha);

    _healthCache = null;
    console.log(`[OnlineBackup Dedup] Done! Final: ${finalTotalChunks} chunks, ${uniqueAttendance.length} unique records. Pushed: ${pushSucceeded}, Deleted: ${deleteSucceeded}`);

    const details = {
      chunksBefore: chunkFiles.length,
      chunksAfter: finalTotalChunks,
      chunksUnchanged,
      chunksPushed: pushSucceeded,
      chunksDeleted: deleteSucceeded,
      recordsBefore: totalRecordsFetched,
      recordsAfter: uniqueAttendance.length,
      duplicatesRemoved: duplicateRecordsRemoved,
      deletedStudentRecords,
      pushFailed,
      deleteFailed,
    };

    return {
      success: true,
      message: `Deduplication berhasil! ${chunkFiles.length} → ${finalTotalChunks} chunk, ${totalRecordsFetched} → ${uniqueAttendance.length} record (${duplicateRecordsRemoved} duplikat dihapus). ${pushSucceeded} chunk diupload, ${deleteSucceeded} chunk duplikat dihapus.`,
      details,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('[OnlineBackup Dedup] Error:', error);
    return { success: false, message: `Gagal deduplicate: ${message}` };
  }
}

// ===== RESTORE (pull from GitHub) =====

export async function restoreFromOnlineBackup(): Promise<{ success: boolean; message: string; restored?: any }> {
  try {
    // Manual pull (full restore) is ALLOWED in BOTH sandbox and production.
    resetCancelFlag();

    const config = await getConfig();
    if (!config) {
      return { success: false, message: 'GitHub backup belum dikonfigurasi.' };
    }

    setSkipAutoSync(true);
    pauseOnlineSync(true);

    // Step 1: Fetch meta file
    reportProgress(0, 1, 'Mengambil meta data dari GitHub...');
    let metaFile: { content: string; sha: string } | null = null;
    let metaError: string | null = null;
    try {
      metaFile = await githubGetFile(config, META_FILE);
    } catch (e) {
      metaError = e instanceof Error ? e.message : String(e);
      console.error('[OnlineBackup Restore] Error fetching meta:', metaError);
    }
    if (metaError) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: `Gagal mengambil meta dari GitHub: ${metaError}. Periksa token/izin repo.` };
    }
    if (!metaFile) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: 'Belum ada backup online. Klik SYNC dulu untuk mengunggah data ke GitHub (termasuk pengaturan, hari libur, nama guru, jadwal mingguan, max hour).' };
    }

    let metaResult: any;
    try {
      metaResult = JSON.parse(metaFile.content);
    } catch {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: 'Meta file rusak (bukan JSON valid).' };
    }

    const metaData = metaResult.data || metaResult;
    const totalChunks = metaResult.meta?.totalChunks || metaResult.chunk?.total || 1;

    // Assemble data from meta
    const assembledData: any = {
      classes: metaData.classes || [],
      students: metaData.students || [],
      settings: metaData.settings || [],
      schedules: metaData.schedules || [],
      waliKelas: metaData.waliKelas || [],
      academicHolidays: metaData.academicHolidays || metaData.holidays || [],
      dateHolidays: metaData.dateHolidays || [],
      activities: metaData.activities || [],
      attendance: [],
      teachers: metaData.teachers || [],
    };

    console.log(`[OnlineBackup Pull] Meta: ${assembledData.classes.length} classes, total chunks: ${totalChunks}`);

    // Step 2: Fetch attendance chunks (1 to totalChunks-1)
    let fullChunksSucceeded = 0;
    let fullChunksFailed = 0;
    for (let c = 1; c < totalChunks; c++) {
      if (isCancelled()) {
        console.log(`[OnlineBackup Pull] Cancelled at chunk ${c}/${totalChunks - 1}. Got ${assembledData.attendance.length} attendance.`);
        setSkipAutoSync(false);
        pauseOnlineSync(false);
        return {
          success: false,
          message: `Pull dihentikan oleh user. ${assembledData.attendance.length} absensi telah diambil (belum direstore).`,
        };
      }
      reportProgress(c, totalChunks, `Mengambil absensi chunk ${c}/${totalChunks - 1} dari GitHub...`);

      const chunkPath = `${CHUNK_PREFIX}${c}.json`;
      try {
        let chunkFile: { content: string; sha: string } | null = null;
        try {
          chunkFile = await githubGetFile(config, chunkPath);
          fullChunksSucceeded++;
        } catch (e) {
          fullChunksFailed++;
          console.warn(`[OnlineBackup Pull] Chunk ${c} fetch error:`, e instanceof Error ? e.message : String(e));
          continue;
        }
        if (!chunkFile) {
          fullChunksFailed++;
          console.warn(`[OnlineBackup Pull] Chunk ${c} not found (404), skipping`);
          continue;
        }
        const chunkData = JSON.parse(chunkFile.content);
        const chunkAttendance = chunkData.data?.attendance || [];
        if (Array.isArray(chunkAttendance)) {
          assembledData.attendance.push(...chunkAttendance);
        }
        console.log(`[OnlineBackup Pull] Chunk ${c}: +${chunkAttendance.length} (total: ${assembledData.attendance.length})`);
      } catch (e) {
        fullChunksFailed++;
        console.warn(`[OnlineBackup Pull] Chunk ${c} parse error:`, e instanceof Error ? e.message : String(e));
      }
    }

    console.log(`[OnlineBackup Pull] Chunks: ${fullChunksSucceeded} ok, ${fullChunksFailed} failed`);

    // If ALL chunks failed, report error
    if (totalChunks > 1 && fullChunksSucceeded === 0) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return {
        success: false,
        message: `Gagal mengambil SEMUA chunk dari GitHub (${fullChunksFailed} chunk gagal). Periksa token/izin repo GitHub.`,
      };
    }

    reportProgress(totalChunks, totalChunks, 'Memulihkan data ke database...');

    if (!assembledData.classes || assembledData.classes.length === 0) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: 'Tidak ada data classes di backup online. Lakukan SYNC dulu.' };
    }

    console.log(`[OnlineBackup Pull] Total: ${assembledData.classes.length} classes, ${assembledData.students.length} students, ${assembledData.attendance.length} attendance`);

    // Step 3: Restore to DB
    const restoreResult = await db.$transaction(async (tx) => {
      await tx.attendance.deleteMany();
      await tx.weeklySchedule.deleteMany();
      await tx.teacher.deleteMany();
      await tx.academicActivity.deleteMany();
      await tx.dateHoliday.deleteMany();
      await tx.waliKelas.deleteMany();
      await tx.student.deleteMany();
      await tx.class.deleteMany();
      await tx.academicHoliday.deleteMany();
      await tx.settings.deleteMany();

      if (assembledData.classes?.length > 0) {
        try {
          await tx.class.createMany({ data: assembledData.classes.map((cls: any) => ({
            id: cls.id, name: cls.name,
            createdAt: cls.createdAt ? new Date(cls.createdAt) : undefined,
            updatedAt: cls.updatedAt ? new Date(cls.updatedAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.students?.length > 0) {
        try {
          // Layer 4 (blocklist): filter deleted students BEFORE DB write.
          const restoreStudents = filterExcludedStudents(assembledData.students);
          await tx.student.createMany({ data: restoreStudents.map((s: any) => ({
            id: s.id, name: s.name, nisn: s.nisn || '', gender: s.gender || '',
            whatsapp: s.whatsapp || '', classId: s.classId,
            createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
            updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.attendance?.length > 0) {
        const CS = 500;
        const restoreAttendance = filterExcludedAttendance(assembledData.attendance);
        for (let i = 0; i < restoreAttendance.length; i += CS) {
          const chunk = restoreAttendance.slice(i, i + CS);
          // Use upsert per record to handle unique constraint on (studentId, date, hour)
          // This Prisma version doesn't support skipDuplicates in createMany
          for (const a of chunk) {
            try {
              await tx.attendance.upsert({
                where: { studentId_date_hour: { studentId: a.studentId, date: a.date, hour: a.hour } },
                update: { status: a.status, classId: a.classId },
                create: {
                  id: a.id, studentId: a.studentId, classId: a.classId,
                  date: a.date, hour: a.hour, status: a.status,
                  createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
                },
              });
            } catch { /* skip if still fails */ }
          }
        }
      }
      if (assembledData.teachers?.length > 0) {
        try {
          await tx.teacher.createMany({ data: assembledData.teachers.map((t: any) => ({
            id: t.id, nickname: t.nickname || '', fullName: t.fullName || t.nickname || '',
            createdAt: t.createdAt ? new Date(t.createdAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.waliKelas?.length > 0) {
        try {
          await tx.waliKelas.createMany({ data: assembledData.waliKelas.map((w: any) => ({
            id: w.id, classId: w.classId, name: w.name,
            createdAt: w.createdAt ? new Date(w.createdAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.schedules?.length > 0) {
        try {
          await tx.weeklySchedule.createMany({ data: assembledData.schedules.map((s: any) => ({
            id: s.id, classId: s.classId, dayOfWeek: s.dayOfWeek, hour: s.hour, teacher: s.teacher || '',
            createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.academicHolidays?.length > 0) {
        try {
          await tx.academicHoliday.createMany({ data: assembledData.academicHolidays.map((h: any) => ({
            id: h.id, dayOfWeek: h.dayOfWeek, name: h.name || '',
            isActive: h.isActive !== undefined ? h.isActive : true,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.dateHolidays?.length > 0) {
        try {
          await tx.dateHoliday.createMany({ data: assembledData.dateHolidays.map((h: any) => ({
            id: h.id, date: h.date, name: h.name || '',
            createdAt: h.createdAt ? new Date(h.createdAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.activities?.length > 0) {
        try {
          await tx.academicActivity.createMany({ data: assembledData.activities.map((a: any) => ({
            id: a.id, classId: a.classId, date: a.date, status: a.status || '',
            createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
          })) });
        } catch { /* skip duplicates */ }
      }
      if (assembledData.settings?.length > 0) {
        try {
          await tx.settings.createMany({ data: assembledData.settings.filter((s: any) => s.key && !s.key.startsWith('github_') && !s.key.startsWith('online_')).map((s: any) => ({
            key: s.key, value: s.value || '',
          })) });
        } catch { /* skip duplicates */ }
      }

      return {
        classes: assembledData.classes?.length || 0,
        students: assembledData.students?.length || 0,
        attendance: assembledData.attendance?.length || 0,
        teachers: assembledData.teachers?.length || 0,
        schedules: assembledData.schedules?.length || 0,
        waliKelas: assembledData.waliKelas?.length || 0,
        academicHolidays: assembledData.academicHolidays?.length || 0,
        dateHolidays: assembledData.dateHolidays?.length || 0,
        activities: assembledData.activities?.length || 0,
        settings: assembledData.settings?.length || 0,
      };
    });

    setSkipAutoSync(false);
    pauseOnlineSync(false);

    // Store pull result for health tracking
    const pullNow = new Date().toISOString();
    try {
      await db.settings.upsert({ where: { key: 'online_last_pull_at' }, update: { value: pullNow }, create: { key: 'online_last_pull_at', value: pullNow } });
      await db.settings.upsert({
        where: { key: 'online_last_pull_result' },
        update: { value: JSON.stringify({ success: true, message: `Full restore: ${restoreResult.attendance} absensi`, timestamp: pullNow }) },
        create: { key: 'online_last_pull_result', value: JSON.stringify({ success: true, message: `Full restore: ${restoreResult.attendance} absensi`, timestamp: pullNow }) },
      });
    } catch {}

    return {
      success: true,
      message: `Restore berhasil! ${restoreResult.classes} kelas, ${restoreResult.students} siswa, ${restoreResult.attendance} absensi, ${restoreResult.academicHolidays} hari libur mingguan, ${restoreResult.dateHolidays} hari libur tanggal, ${restoreResult.teachers} guru, ${restoreResult.waliKelas} wali kelas, ${restoreResult.schedules} jadwal, ${restoreResult.settings} pengaturan (termasuk max hour)`,
      restored: restoreResult,
    };
  } catch (error) {
    setSkipAutoSync(false);
    pauseOnlineSync(false);
    // Store pull failure
    try {
      const pullNow = new Date().toISOString();
      await db.settings.upsert({ where: { key: 'online_last_pull_at' }, update: { value: pullNow }, create: { key: 'online_last_pull_at', value: pullNow } });
      await db.settings.upsert({
        where: { key: 'online_last_pull_result' },
        update: { value: JSON.stringify({ success: false, message: error instanceof Error ? error.message : 'Unknown', timestamp: pullNow }) },
        create: { key: 'online_last_pull_result', value: JSON.stringify({ success: false, message: error instanceof Error ? error.message : 'Unknown', timestamp: pullNow }) },
      });
    } catch {}
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Restore melebihi batas waktu.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('[OnlineBackup] Restore error:', error);
    return { success: false, message: `Gagal restore: ${message}` };
  }
}

// ===== DIFF-BASED RESTORE (only restore missing records — much faster) =====

/**
 * Compare local DB with GitHub backup, then restore ONLY the missing records.
 * This is much faster than a full restore (no DELETE + re-CREATE of all data).
 *
 * Process:
 * 1. Fetch meta.json from GitHub (classes, students, settings, schedules, etc.)
 * 2. Fetch all attendance chunks from GitHub
 * 3. Compare with local DB:
 *    - For each table, find IDs that exist in GitHub but NOT in local DB
 *    - Only insert the missing records
 * 4. Skip tables where local DB already has all records (no changes needed)
 *
 * This avoids the expensive DELETE ALL + CREATE ALL pattern.
 */
export async function restoreMissingFromOnlineBackup(): Promise<{ success: boolean; message: string; restored?: any }> {
  // GLOBAL LOCK: Prevent concurrent operations.
  const { tryStartOperation, endOperation, updateProgress: updateOpProgress, recordResult } = await import('./operation-lock');
  if (!tryStartOperation('pull-diff', 'Pull Diff dari GitHub')) {
    return { success: false, message: 'Operasi lain sedang berjalan. Tidak bisa memulai pull diff sekarang.' };
  }

  // Set up progress reporting to BOTH the old callback AND the operation-lock
  _opLockProgressUpdater = updateOpProgress;

  try {
    // Manual pull-diff is ALLOWED in BOTH sandbox and production — user can
    // trigger it from the UI in any environment. Automatic startup pull-diff
    // (via instrumentation-node) is still production-only.
    resetCancelFlag();

    const config = await getConfig();
    if (!config) {
      return { success: false, message: 'GitHub backup belum dikonfigurasi.' };
    }

    setSkipAutoSync(true);
    pauseOnlineSync(true);

    // Step 1: Fetch meta file
    reportProgress(0, 1, 'Mengambil meta data dari GitHub (mode diff)...');
    let metaFile: { content: string; sha: string } | null = null;
    let metaError: string | null = null;
    try {
      metaFile = await githubGetFile(config, META_FILE);
    } catch (e) {
      metaError = e instanceof Error ? e.message : String(e);
      console.error('[OnlineBackup DiffRestore] Error fetching meta:', metaError);
    }
    if (metaError) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: `Gagal mengambil meta dari GitHub: ${metaError}. Periksa token/izin repo.` };
    }
    if (!metaFile) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: 'Belum ada backup online. Klik SYNC dulu.' };
    }

    let metaResult: any;
    try {
      metaResult = JSON.parse(metaFile.content);
    } catch {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      return { success: false, message: 'Meta file rusak (bukan JSON valid).' };
    }

    const metaData = metaResult.data || metaResult;
    let totalChunks = metaResult.meta?.totalChunks || metaResult.chunk?.total || 1;
    let ghAttendanceCount = metaResult.meta?.attendanceCount || 0;

    // SAFETY: Cap totalChunks at a reasonable number to prevent fetching non-existent chunks
    // If meta.json says 725 chunks but only 412 files exist, we don't want to fetch 313 non-existent chunks
    // The actual file count will be checked from the GitHub API in getSyncHealth
    // For diff pull, we cap at MAX_CHUNKS_CAP chunks (180,000 records at 300/chunk) which is more than enough
    if (totalChunks > MAX_CHUNKS_CAP) {
      console.warn(`[OnlineBackup DiffPull] WARNING: meta.json says totalChunks=${totalChunks} but capping at ${MAX_CHUNKS_CAP} to prevent rate limit`);
      totalChunks = MAX_CHUNKS_CAP;
      // Also cap attendanceCount to match
      ghAttendanceCount = Math.min(ghAttendanceCount, (MAX_CHUNKS_CAP - 1) * RECORDS_PER_CHUNK);
    }

    // GitHub backup data (meta has classes, students, settings, etc.)
    const ghClasses: any[] = metaData.classes || [];
    const ghStudents: any[] = metaData.students || [];
    const ghSettings: any[] = metaData.settings || [];
    const ghSchedules: any[] = metaData.schedules || [];
    const ghWaliKelas: any[] = metaData.waliKelas || [];
    const ghAcademicHolidays: any[] = metaData.academicHolidays || metaData.holidays || [];
    const ghDateHolidays: any[] = metaData.dateHolidays || [];
    const ghActivities: any[] = metaData.activities || [];
    const ghTeachers: any[] = metaData.teachers || [];
    let ghAttendance: any[] = [];

    console.log(`[OnlineBackup DiffPull] Meta: ${ghClasses.length} classes, ${ghStudents.length} students, total chunks: ${totalChunks}, GitHub attendance: ${ghAttendanceCount}`);

    // Step 2: Get local attendance count for logging/comparison
    let localAttCount = 0;
    try {
      localAttCount = await db.attendance.count();
    } catch {}

    // ===== STREAMING PULL-DIFF =====
    // Process ONE chunk at a time: fetch → compare → insert → free.
    // Uses ACTUAL chunk count from GitHub API (NOT meta.json totalChunks which can be wrong).
    // Meta.json might say 500 chunks but GitHub actually has 575 — we list REAL files.

    // Step A: List ALL actual chunk files from GitHub API
    let actualChunkFiles: { name: string; path: string }[] = [];
    try {
      const GITHUB_API = 'https://api.github.com';
      const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
        headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
        signal: AbortSignal.timeout(15000),
      });
      if (listRes.ok) {
        const files = await listRes.json();
        if (Array.isArray(files)) {
          actualChunkFiles = files.filter((f: any) => f.name?.match(/^chunk-\d+\.json$/));
          console.log(`[OnlineBackup DiffPull] GitHub API: found ${actualChunkFiles.length} ACTUAL chunk files (meta.json said ${totalChunks - 1})`);
        }
      }
    } catch (e) {
      console.warn(`[OnlineBackup DiffPull] Could not list GitHub files: ${e instanceof Error ? e.message : String(e)}`);
    }

    // If GitHub API listing failed, fall back to meta.json totalChunks
    if (actualChunkFiles.length === 0) {
      console.log(`[OnlineBackup DiffPull] GitHub API listing failed — using meta.json totalChunks=${totalChunks}`);
      for (let i = 1; i < totalChunks; i++) {
        actualChunkFiles.push({ name: `chunk-${i}.json`, path: `${CHUNK_PREFIX}${i}.json` });
      }
    }

    // Early exit: if local >= meta.json's attendanceCount, skip
    // meta.json's count is the AUTHORITATIVE count — it's updated by syncToOnlineBackup
    // after every push with the exact local DB count. If local >= meta count, we have
    // everything GitHub says it has — no need to stream through chunks.
    // Fallback: if meta count is 0/unavailable, use chunks × 10 (clearly-broken floor)
    // — only skips if local is clearly already populated.
    const expectedMin = ghAttendanceCount > 0 ? ghAttendanceCount : Math.max(0, (actualChunkFiles.length - 1) * 10);
    console.log(`[OnlineBackup DiffPull] Local=${localAttCount}, GitHub(meta)=${ghAttendanceCount}, actualChunks=${actualChunkFiles.length}, expectedMin=${expectedMin}`);
    if (localAttCount >= expectedMin && expectedMin > 0) {
      setSkipAutoSync(false);
      pauseOnlineSync(false);
      console.log(`[OnlineBackup DiffPull] SKIP — local=${localAttCount} >= expectedMin=${expectedMin}. Data complete.`);
      recordResult('pull-diff', true, `Data lokal sudah lengkap (${localAttCount} >= ${expectedMin} expected dari ${actualChunkFiles.length} chunk).`);
      return {
        success: true,
        message: `Data lokal sudah lengkap! ${localAttCount} >= ${expectedMin} (expected dari ${actualChunkFiles.length} chunk GitHub).`,
        restored: { missing: 0, total: localAttCount, githubAttendance: ghAttendanceCount, localAttendance: localAttCount },
      };
    }

    // Step B: Get local attendance keys for comparison
    const localRecords = await db.attendance.findMany({ select: { studentId: true, date: true, hour: true } });
    const localKeys = new Set(localRecords.map(r => `${r.studentId}_${r.date}_${r.hour}`));
    const localStudentIds = new Set((await db.student.findMany({ select: { id: true } })).map(s => s.id));
    console.log(`[OnlineBackup DiffPull] Local keys: ${localKeys.size}. Streaming through ${actualChunkFiles.length} chunks...`);

    // Step C: Process each chunk — fetch, filter, insert, free
    let totalMissing = 0;
    let totalInserted = 0;
    let chunksSucceeded = 0;
    let chunksFailed = 0;
    let consecutive404s = 0;

    for (let ci = 0; ci < actualChunkFiles.length; ci++) {
      const chunkFile = actualChunkFiles[ci];
      if (isCancelled()) {
        console.log(`[OnlineBackup DiffPull] Cancelled at chunk ${ci + 1}/${actualChunkFiles.length}.`);
        break;
      }

      reportProgress(ci + 1, actualChunkFiles.length + 1, `Memproses chunk ${ci + 1}/${actualChunkFiles.length}...`);

      // Fetch 1 chunk
      let chunkDataRaw: { content: string; sha: string } | null = null;
      try {
        chunkDataRaw = await githubGetFile(config, chunkFile.path);
      } catch (e) {
        chunksFailed++;
        consecutive404s++;
        if (consecutive404s >= 5) {
          console.warn(`[OnlineBackup DiffPull] 5 consecutive failures at chunk ${ci + 1} — stopping.`);
          break;
        }
        continue;
      }
      if (!chunkDataRaw) {
        chunksFailed++;
        consecutive404s++;
        if (consecutive404s >= 5) break;
        continue;
      }
      consecutive404s = 0;
      chunksSucceeded++;

      // Parse chunk
      let chunkAttendance: any[] = [];
      try {
        const chunkData = JSON.parse(chunkDataRaw.content);
        chunkAttendance = chunkData.data?.attendance || [];
      } catch {
        chunksFailed++;
        continue;
      }

      // Filter: keep only records NOT in local DB AND whose student exists
      // AND whose student is not blocklisted (Layer 4).
      const missing = chunkAttendance.filter((a: any) => {
        if (!a.studentId || !localStudentIds.has(a.studentId)) return false;
        if (isStudentExcluded(a.studentId)) return false;
        const key = `${a.studentId}_${a.date}_${a.hour}`;
        return !localKeys.has(key);
      });

      if (missing.length > 0) {
        totalMissing += missing.length;
        // INSERT immediately — batch of 50, with delay
        const BATCH = 50;
        for (let i = 0; i < missing.length; i += BATCH) {
          const batch = missing.slice(i, i + BATCH);
          try {
            await db.attendance.createMany({
              data: batch.map((a: any) => ({
                id: a.id, studentId: a.studentId, classId: a.classId,
                date: a.date, hour: a.hour, status: a.status,
                createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
              })),
            });
            totalInserted += batch.length;
            for (const a of batch) localKeys.add(`${a.studentId}_${a.date}_${a.hour}`);
          } catch {
            for (const a of batch) {
              try {
                await db.attendance.create({
                  data: { id: a.id, studentId: a.studentId, classId: a.classId, date: a.date, hour: a.hour, status: a.status, createdAt: a.createdAt ? new Date(a.createdAt) : undefined },
                });
                totalInserted++;
                localKeys.add(`${a.studentId}_${a.date}_${a.hour}`);
              } catch {}
            }
          }
          if (i + BATCH < missing.length) await new Promise(r => setTimeout(r, 50));
        }
        console.log(`[OnlineBackup DiffPull] Chunk ${ci + 1}/${actualChunkFiles.length}: ${missing.length} missing, ${totalInserted} inserted total`);
      }

      // Free chunk data
      chunkAttendance = [];
      chunkDataRaw = null;
    }

    console.log(`[OnlineBackup DiffPull] Done: ${chunksSucceeded}/${actualChunkFiles.length} chunks, ${totalMissing} missing, ${totalInserted} inserted.`);

    // Step D: Insert missing non-attendance data from meta
    const localClassIds = new Set((await db.class.findMany({ select: { id: true } })).map(x => x.id));
    const localStudentIds2 = new Set((await db.student.findMany({ select: { id: true } })).map(x => x.id));
    const localTeacherIds = new Set((await db.teacher.findMany({ select: { id: true } })).map(x => x.id));
    let nonAttInserted = 0;
    const missingClasses = ghClasses.filter((c: any) => !localClassIds.has(c.id));
    if (missingClasses.length > 0) { try { await db.class.createMany({ data: missingClasses.map((c: any) => ({ id: c.id, name: c.name, createdAt: c.createdAt ? new Date(c.createdAt) : undefined, updatedAt: c.updatedAt ? new Date(c.updatedAt) : undefined })) }); nonAttInserted += missingClasses.length; } catch {} }
    // Layer 4 (blocklist): deleted students must never be re-inserted by pull-diff.
    const missingStudents = filterExcludedStudents(ghStudents.filter((s: any) => !localStudentIds2.has(s.id)));
    if (missingStudents.length > 0) { try { await db.student.createMany({ data: missingStudents.map((s: any) => ({ id: s.id, name: s.name, nisn: s.nisn || '', gender: s.gender || '', whatsapp: s.whatsapp || '', classId: s.classId, createdAt: s.createdAt ? new Date(s.createdAt) : undefined, updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined })) }); nonAttInserted += missingStudents.length; } catch {} }
    const missingTeachers = ghTeachers.filter((t: any) => !localTeacherIds.has(t.id));
    if (missingTeachers.length > 0) { try { await db.teacher.createMany({ data: missingTeachers.map((t: any) => ({ id: t.id, nickname: t.nickname, fullName: t.fullName || '', createdAt: t.createdAt ? new Date(t.createdAt) : undefined, updatedAt: t.updatedAt ? new Date(t.updatedAt) : undefined })) }); nonAttInserted += missingTeachers.length; } catch {} }

    // Done — DO NOT update meta.json count
    ghAttendance = [];
    setSkipAutoSync(false);
    pauseOnlineSync(false);
    recordResult('pull-diff', true, `${totalInserted + nonAttInserted} data dipulihkan dari ${chunksSucceeded} chunk`);
    console.log('[OnlineBackup DiffPull] NOT updating meta.json count — GitHub count must reflect actual chunk data.');
    try { const { syncLiveDbToPersistent } = await import('./db-persistent-sync'); await syncLiveDbToPersistent(); } catch {}
    return {
      success: true,
      message: `Pull diff berhasil! ${totalInserted} absensi, ${nonAttInserted} data lain dipulihkan dari ${chunksSucceeded}/${actualChunkFiles.length} chunk GitHub.`,
      restored: { missingAttendance: totalMissing, totalInserted: totalInserted + nonAttInserted, chunksProcessed: chunksSucceeded, totalChunks: actualChunkFiles.length },
    };
  } catch (error) {
    setSkipAutoSync(false);
    pauseOnlineSync(false);
    // Store pull failure
    try {
      const pullNow = new Date().toISOString();
      await db.settings.upsert({ where: { key: 'online_last_pull_at' }, update: { value: pullNow }, create: { key: 'online_last_pull_at', value: pullNow } });
      await db.settings.upsert({
        where: { key: 'online_last_pull_result' },
        update: { value: JSON.stringify({ success: false, message: error instanceof Error ? error.message : 'Unknown', timestamp: pullNow }) },
        create: { key: 'online_last_pull_result', value: JSON.stringify({ success: false, message: error instanceof Error ? error.message : 'Unknown', timestamp: pullNow }) },
      });
    } catch {}
    if (error instanceof DOMException && error.name === 'AbortError') {
      recordResult('pull-diff', false, 'Timeout');
      return { success: false, message: 'Timeout: Pull diff melebihi batas waktu.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    console.error('[OnlineBackup DiffPull] Error:', error);
    recordResult('pull-diff', false, message);
    return { success: false, message: `Gagal pull diff: ${message}` };
  } finally {
    _opLockProgressUpdater = null;
    endOperation('pull-diff');
  }
}

// ===== AUTO-SYNC (triggered after DB writes) =====

// Mutex: prevent concurrent auto-sync runs
let _autoSyncRunning = false;
// Cooldown: After pull-diff is triggered from auto-sync, don't trigger it again
// for 30 minutes. This prevents the cycle where GitHub count > local count
// (due to duplicates) keeps triggering pull-diff on every DB write.
let _lastAutoSyncPullDiffTime = 0;
const AUTO_SYNC_PULL_DIFF_COOLDOWN = 30 * 60 * 1000; // 30 minutes
// Cooldown for edit-triggered FULL syncs. Full sync makes ~370 API calls,
// so running it on every edit would hit GitHub's 5000/hour rate limit.
// 10-minute cooldown = max 6 full syncs/hour = 2220 calls (well under 5000).
let _lastEditSyncTime = 0;
const EDIT_SYNC_COOLDOWN = 10 * 60 * 1000; // 10 minutes

export async function triggerOnlineAutoSync() {
  // ============================================================
  // STOP AUTO-SYNC IF NO NEW DATA (user's explicit request)
  // ============================================================
  // "STOP AUTO SYNC jika tidak ada data baru"
  //
  // Check FIRST (before any lock, before any GitHub API call):
  //   - Query NEW records: createdAt > lastSyncAt
  //   - If 0 new records → STOP immediately (return, no lock, no API calls)
  //
  // This saves GitHub API rate limit budget and prevents unnecessary
  // full syncs triggered by edits (which are NOT "data baru").
  //
  // Edits are NOT synced via auto-sync — they would need a manual sync.
  // ============================================================
  try {
    const lastSyncAt = await getLastSyncAt();
    if (lastSyncAt) {
      const since = new Date(lastSyncAt);
      const newRecordsCount = await db.attendance.count({
        where: { createdAt: { gt: since } },
      });
      if (newRecordsCount === 0) {
        // STOP — no new data to sync. Don't acquire lock, don't make API calls.
        // BUT update lastSyncAt so the status shows "recently checked" (not "5 days ago")
        console.log('[OnlineBackup AutoSync] STOP — no new records since lastSyncAt. Auto-sync skipped.');
        const now = new Date().toISOString();
        try {
          await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
        } catch {}
        return;
      }
      console.log(`[OnlineBackup AutoSync] ${newRecordsCount} new records detected since lastSyncAt — proceeding with sync.`);
    } else {
      // No lastSyncAt — first sync after deploy. Need full sync to establish baseline.
      console.log('[OnlineBackup AutoSync] No lastSyncAt — first sync. Full sync needed to establish baseline.');
    }
  } catch (e) {
    console.warn('[OnlineBackup AutoSync] Pre-check failed:', e instanceof Error ? e.message : String(e));
    // If pre-check fails, proceed to the normal flow (safer to sync than to skip)
  }

  // CRITICAL: Skip auto-sync during server reset recovery.
  // On server reset, the local DB is restored from packaged/persistent DB which
  // may have STALE data. If auto-sync runs BEFORE pull-diff completes, it would
  // PUSH the stale local data to GitHub → OVERWRITE GitHub's good data → DATA LOSS.
  // The instrumentation sets setSkipAutoSync(true) on startup and clears it
  // AFTER pull-diff completes. This check is belt-and-suspenders safety.
  const { isAutoSyncSkipped } = await import('./auto-sync');
  if (isAutoSyncSkipped()) {
    console.log('[OnlineBackup AutoSync] Skipped — reset recovery in progress (setSkipAutoSync=true). Pull-diff will restore data first.');
    return;
  }

  // Prevent concurrent auto-sync runs — if one is already in progress, skip
  if (_autoSyncRunning) {
    console.log('[OnlineBackup AutoSync] Already running — skipping');
    return;
  }

  // GLOBAL LOCK: Don't start auto-sync if a pull/restore is running.
  // When pull-diff/pull-full/restore-local is running, auto-sync must be BLOCKED
  // to prevent data conflicts and crashes.
  const { tryStartOperation, endOperation, recordResult } = await import('./operation-lock');
  if (!tryStartOperation('auto-sync', 'Auto-Sync ke GitHub')) {
    console.log('[OnlineBackup AutoSync] Blocked — another operation is running');
    return;
  }

  _autoSyncRunning = true;

  try {
    const localAttCount = await db.attendance.count();

    // REAL-TIME FETCH: Always get the actual GitHub count from meta.json.
    // This does NOT use cached DB Settings or deploy-time data.
    // Has a 30-second short-lived cache to prevent duplicate API calls
    // within the same operation cycle.
    // Also updates DB Settings + persistent file with the fresh count.
    const { count: ghAttCount, error: ghError } = await fetchGhAttendanceCountRealtime();
    if (ghError) {
      console.warn(`[OnlineBackup AutoSync] Could not fetch realtime GitHub count: ${ghError}`);
    }

    console.log(`[OnlineBackup AutoSync] Local: ${localAttCount}, GitHub (realtime): ${ghAttCount}${ghError ? ` (error: ${ghError})` : ''}`);

    // CRITICAL: STOP auto-sync when local attendance < GitHub count.
    // This happens after: fresh deploy (local has deploy-time data, GitHub has more),
    // server reset (local lost data), or any data loss scenario.
    // Pushing now would overwrite GitHub's good data with reduced local data.
    // Instead, SKIP the push and trigger pull-diff to restore missing records first.
    //
    // COOLDOWN: If pull-diff was triggered recently (within 30 min), don't trigger
    // it again. This prevents the cycle where GitHub count > local count (due to
    // duplicates in chunks) keeps triggering pull-diff on every DB write.
    // After pull-diff runs and finds 0 missing records, it updates the cached count
    // to match local, so future auto-syncs won't see a drop. But as a safety net,
    // the cooldown prevents repeated pull-diff triggers even if the cache update fails.
    if (ghAttCount > 0 && localAttCount < ghAttCount) {
      const timeSinceLastPullDiff = Date.now() - _lastAutoSyncPullDiffTime;
      if (_lastAutoSyncPullDiffTime > 0 && timeSinceLastPullDiff < AUTO_SYNC_PULL_DIFF_COOLDOWN) {
        const minLeft = Math.ceil((AUTO_SYNC_PULL_DIFF_COOLDOWN - timeSinceLastPullDiff) / 60000);
        console.log(`[OnlineBackup AutoSync] local (${localAttCount}) < GitHub (${ghAttCount}), but pull-diff cooldown active (${minLeft} min left). Skipping.`);
        recordResult('auto-sync', false, `Cooldown pull-diff aktif (${minLeft} min). Local (${localAttCount}) < GitHub (${ghAttCount}).`);
        return;
      }
      console.warn(`[OnlineBackup AutoSync] ⚠️ ATTENDANCE DROPPED: local=${localAttCount} < GitHub=${ghAttCount}. Auto-sync STOPPED. Triggering pull-diff to restore missing records.`);
      _lastAutoSyncPullDiffTime = Date.now();
      recordResult('auto-sync', false, `Diblokir: local (${localAttCount}) < GitHub (${ghAttCount}). Pull-diff akan dijalankan.`);
      // Trigger pull-diff immediately in the background to restore missing data
      setImmediate(() => {
        restoreMissingFromOnlineBackup().catch((e) => {
          console.warn('[OnlineBackup AutoSync] Auto pull-diff after drop failed:', e instanceof Error ? e.message : String(e));
        });
      });
      return;
    }

    // ===== EDIT DETECTION REMOVED =====
    // User's explicit request: "STOP AUTO SYNC jika tidak ada data baru"
    // Auto-sync should ONLY run for NEW records (createdAt > lastSyncAt).
    // Edits (updatedAt changes) are NOT "data baru" — they should NOT trigger
    // auto-sync. The edit detection block that was here caused FULL SYNCs
    // (370 API calls) on every auto-sync trigger when any record was edited,
    // which was too expensive and against the user's request.
    //
    // If the user wants to sync edits to GitHub, they can do a MANUAL sync
    // via the "Sync" button in the UI (which calls /api/online-backup directly).
    //
    // The pre-check at the top of this function already ensures auto-sync
    // STOPS if there are 0 new records. So if we reach this point, there ARE
    // new records to push.

    // If local <= GitHub (cached count) and no drop detected, nothing to push.
    // The pre-check at the top already ensures we only reach here if there ARE
    // new records (createdAt > lastSyncAt). But if local <= GitHub (count-based),
    // the new records might already be on GitHub from a previous sync.
    // In that case, just update lastSyncAt and skip the push.
    if (localAttCount <= ghAttCount) {
      console.log('[OnlineBackup AutoSync] Local <= GitHub — new records may already be synced. Updating lastSyncAt only.');
      const now = new Date().toISOString();
      await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
      recordResult('auto-sync', true, 'Tidak ada data baru untuk disinkronkan.');
      return;
    }

    // ===== PUSH ONLY TRULY NEW RECORDS (not all data) =====
    // User's request: "autosync hanya sync data baru yang belum ada pada github,
    // bukan semua data"
    //
    // NEW behavior (CORRECT): query records where createdAt > lastSyncAt.
    // These are the TRULY new records that were inserted AFTER the last sync.
    // Push ONLY these — no duplicates, no unnecessary data.
    const lastSyncAtForPush = await getLastSyncAt();
    if (!lastSyncAtForPush) {
      // No lastSyncAt — need full sync to establish baseline
      console.log('[OnlineBackup AutoSync] No lastSyncAt — running FULL sync to establish baseline');
      const fullResult = await syncToOnlineBackup({ incremental: false });
      recordResult('auto-sync', fullResult.success, fullResult.message);
      return;
    }

    const sinceDate = new Date(lastSyncAtForPush);
    // Get the TRULY new records (created after last sync)
    const newAttendance = await db.attendance.findMany({
      where: { createdAt: { gt: sinceDate } },
      select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true, createdAt: true },
      orderBy: { createdAt: 'asc' }, // oldest first (so they append in order)
    });

    console.log(`[OnlineBackup AutoSync] Found ${newAttendance.length} truly new records (createdAt > lastSyncAt). Pushing ONLY these — not all data.`);

    if (newAttendance.length === 0) {
      // No new records to push — this shouldn't happen (pre-check caught it)
      // but handle it just in case
      console.log('[OnlineBackup AutoSync] No new records to push — done');
      // Update lastSyncAt to prevent re-checking the same records
      const now = new Date().toISOString();
      await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
      recordResult('auto-sync', true, 'Tidak ada data baru untuk disinkronkan.');
      return;
    }

      // Get config for GitHub API calls
      const ghConfig = await getConfig();
      if (!ghConfig) {
        console.log('[OnlineBackup AutoSync] No config — skipping');
        _autoSyncRunning = false;
        return;
      }

      // Fetch the last chunk from GitHub to see what's already there
      let lastChunkIndex = 0;
      let lastChunkAttendance: any[] = [];
      let lastChunkSha: string | undefined = undefined;
      let metaSha: string | undefined = undefined;
      let existingTotalChunks = 1;
      let existingAttendanceCount = 0;
      let existingMetaData: any = null;

      try {
        const existingMeta = await githubGetFile(ghConfig, META_FILE);
        if (existingMeta) {
          metaSha = existingMeta.sha;
          const meta = JSON.parse(existingMeta.content);
          existingTotalChunks = meta.meta?.totalChunks || 1;
          existingAttendanceCount = meta.meta?.attendanceCount || 0;
          existingMetaData = meta.data || null;
          lastChunkIndex = existingTotalChunks > 1 ? existingTotalChunks - 1 : 0;

          if (lastChunkIndex > 0) {
            try {
              const lastChunkFile = await githubGetFile(ghConfig, `${CHUNK_PREFIX}${lastChunkIndex}.json`);
              if (lastChunkFile) {
                const lastChunkData = JSON.parse(lastChunkFile.content);
                lastChunkAttendance = lastChunkData.data?.attendance || [];
                lastChunkSha = lastChunkFile.sha;
              } else {
                // Chunk doesn't exist — find actual last chunk
                const GITHUB_API = 'https://api.github.com';
                const listRes = await fetch(`${GITHUB_API}/repos/${ghConfig.owner}/${ghConfig.repo}/contents/backup?ref=${encodeURIComponent(ghConfig.branch)}&per_page=1000`, {
                  headers: { 'Authorization': `Bearer ${ghConfig.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
                  signal: AbortSignal.timeout(15000),
                });
                if (listRes.ok) {
                  const files = await listRes.json();
                  if (Array.isArray(files)) {
                    let actualLast = 0;
                    for (const f of files) {
                      const m = f.name?.match(/^chunk-(\d+)\.json$/);
                      if (m) { const n = parseInt(m[1]); if (n > actualLast) actualLast = n; }
                    }
                    lastChunkIndex = actualLast;
                    existingTotalChunks = actualLast + 1;
                    if (lastChunkIndex > 0) {
                      const actualFile = await githubGetFile(ghConfig, `${CHUNK_PREFIX}${lastChunkIndex}.json`);
                      if (actualFile) {
                        const d = JSON.parse(actualFile.content);
                        lastChunkAttendance = d.data?.attendance || [];
                        lastChunkSha = actualFile.sha;
                      }
                    }
                  }
                }
              }
            } catch {}
          }
        }
      } catch {}

      // Dedup: only push records NOT already in the last chunk(s).
      // Fetch the last 2 chunks for more thorough duplicate prevention.
      // New records are always at the end, so checking the last 2 chunks catches
      // all recently-synced records without needing to fetch all 400+ chunks.
      const existingKeys = new Set<string>();
      // Add last chunk keys
      for (const r of lastChunkAttendance) {
        existingKeys.add(`${r.studentId}_${r.date}_${r.hour}`);
      }
      // Also fetch and add second-to-last chunk keys for extra safety
      if (lastChunkIndex > 1) {
        try {
          const prevChunkFile = await githubGetFile(ghConfig, `${CHUNK_PREFIX}${lastChunkIndex - 1}.json`);
          if (prevChunkFile) {
            const prevChunkData = JSON.parse(prevChunkFile.content);
            const prevAtt = prevChunkData.data?.attendance || [];
            for (const r of prevAtt) {
              existingKeys.add(`${r.studentId}_${r.date}_${r.hour}`);
            }
            console.log(`[OnlineBackup AutoSync] Dedup: also checked chunk ${lastChunkIndex - 1} (${prevAtt.length} records)`);
          }
        } catch {}
      }
      // Also dedup within the records being pushed (in case of duplicates in local query)
      const seenInPush = new Set<string>();
      const trulyNew = newAttendance.filter((r: any) => {
        const key = `${r.studentId}_${r.date}_${r.hour}`;
        if (existingKeys.has(key)) return false; // already in GitHub
        if (seenInPush.has(key)) return false; // duplicate within this batch
        seenInPush.add(key);
        return true;
      });
      console.log(`[OnlineBackup AutoSync] After dedup: ${trulyNew.length} truly new records to push (checked ${existingKeys.size} existing keys from last 2 chunks)`);

      if (trulyNew.length === 0) {
        // All records already exist — just update meta.json count
        console.log('[OnlineBackup AutoSync] All records already in GitHub — updating meta count only');
        const newCount = existingAttendanceCount > localAttCount ? existingAttendanceCount : localAttCount;
        const mergedData = { ...(existingMetaData || {}) };
        delete mergedData.attendance;
        if (mergedData.settings) mergedData.settings = filterSensitiveSettings(mergedData.settings);
        const metaPayload = {
          version: 3, exportedAt: new Date().toISOString(), appName: 'ABSENSI SISWA MTs Al ISHLAH', compressed: true,
          data: mergedData,
          chunk: { index: 0, total: existingTotalChunks, type: 'meta' },
          meta: { totalChunks: existingTotalChunks, attendanceCount: newCount, incremental: true, exportedAt: new Date().toISOString() },
        };
        try {
          await githubPutFile(ghConfig, META_FILE, JSON.stringify(metaPayload), `meta: update count to ${newCount}`, metaSha);
        } catch {}
        _healthCache = null;
        const now = new Date().toISOString();
        await db.settings.upsert({ where: { key: LAST_SYNC_KEY }, update: { value: now }, create: { key: LAST_SYNC_KEY, value: now } });
        await db.settings.upsert({ where: { key: ATTENDANCE_COUNT_KEY }, update: { value: String(newCount) }, create: { key: ATTENDANCE_COUNT_KEY, value: String(newCount) } });
        // Also save to persistent file (survives server resets)
        try { const { savePersistentGhCount } = await import('./db-persistent-sync'); await savePersistentGhCount(newCount); } catch {}
        await db.settings.upsert({ where: { key: 'online_last_sync_result' }, update: { value: JSON.stringify({ success: true, message: 'Meta count updated', timestamp: now }) }, create: { key: 'online_last_sync_result', value: JSON.stringify({ success: true, message: 'Meta count updated', timestamp: now }) } });
        return;
      }

      // ===== DELEGATE TO syncToOnlineBackup (incremental) =====
      // ROOT CAUSE of chunk duplication: triggerOnlineAutoSync had its OWN chunk
      // creation logic that deduped against only the last 5 chunks. If a record
      // existed in chunk-100 but not in the last 5, it was pushed again as "new"
      // → DUPLICATE in a different chunk → chunk bloat (575 → 1000+).
      //
      // FIX: Remove the OWN push logic entirely. Delegate to syncToOnlineBackup()
      // which has proper incremental sync with meta.json-based chunk management.
      // syncToOnlineBackup uses the SAME GitHub API listing for lastChunkIndex
      // and properly tracks totalChunks in meta.json.
      console.log(`[OnlineBackup AutoSync] Delegating to syncToOnlineBackup (incremental) for ${trulyNew.length} records...`);
      const syncResult = await syncToOnlineBackup({ incremental: true });
      console.log(`[OnlineBackup AutoSync] syncToOnlineBackup result: ${syncResult.success ? 'OK' : 'FAIL'} — ${syncResult.message}`);
      recordResult('auto-sync', syncResult.success, syncResult.message);
      return;

    // This point should never be reached — all cases (drop, equal, greater) are
    // handled above with early returns. If we get here, it's a no-op.
    console.log('[OnlineBackup AutoSync] No action needed (all cases handled above)');
    recordResult('auto-sync', true, 'Tidak ada aksi yang diperlukan.');
  } catch (error) {
    console.error('[OnlineBackup AutoSync] Error:', error);
    recordResult('auto-sync', false, error instanceof Error ? error.message : 'Unknown');
  } finally {
    _autoSyncRunning = false;
    endOperation('auto-sync');
  }
}

// ===== REAL-TIME GitHub count fetch (no cache, always fresh) =====

// Short-lived cache (30 seconds) to prevent duplicate API calls within the same
// periodic check cycle. This is NOT a long-term cache — it expires quickly so
// the next check always gets fresh data.
let _realtimeGhCountCache: { count: number; timestamp: number } | null = null;
const REALTIME_GH_COUNT_TTL = 120 * 1000; // 2 minutes (was 30s) — reduces GitHub API calls

/**
 * Fetch the ACTUAL GitHub attendance count from meta.json in real-time.
 * This does NOT use the cached DB Settings value or the persistent file.
 *
 * Use this when you need the TRUE current GitHub count for comparison
 * (e.g., drop detection, periodic check, auto-sync).
 *
 * Has a 30-second short-lived cache to prevent duplicate API calls within
 * the same operation cycle (e.g., periodic check calling health + auto-sync).
 *
 * Returns 0 if:
 * - Not configured
 * - meta.json doesn't exist
 * - Network/API error
 */
export async function fetchGhAttendanceCountRealtime(): Promise<{ count: number; error?: string }> {
  // Check short-lived cache
  if (_realtimeGhCountCache && (Date.now() - _realtimeGhCountCache.timestamp) < REALTIME_GH_COUNT_TTL) {
    return { count: _realtimeGhCountCache.count };
  }

  try {
    const config = await getConfig();
    if (!config) {
      return { count: 0, error: 'not configured' };
    }

    const metaFile = await githubGetFile(config, META_FILE);
    if (!metaFile) {
      return { count: 0, error: 'meta.json not found' };
    }

    const meta = JSON.parse(metaFile.content);
    let count = meta.meta?.attendanceCount || 0;

    // CRITICAL: meta.json's attendanceCount IS the real count.
    // It's updated by syncToOnlineBackup after every push with the exact local DB count.
    // Do NOT override it with chunk-based estimates.
    //
    // The chunk count check below is ONLY for detecting CORRUPT meta.json
    // (where count is clearly wrong — e.g., 0 when there are 575 chunks).
    //
    // NOTE: We can NOT assume all chunks have RECORDS_PER_CHUNK records each —
    // existing chunks created before the chunk-size change (e.g., 100→300) will
    // still have the old size until a full rebuild is triggered. So the minimum
    // check uses a small per-chunk floor (10 records/chunk) — only clearly
    // broken meta (count=0 or absurdly low) triggers the override.
    try {
      const GITHUB_API = 'https://api.github.com';
      const listRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}&per_page=1000`, {
        headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
        signal: AbortSignal.timeout(15000),
      });
      if (listRes.ok) {
        const files = await listRes.json();
        if (Array.isArray(files)) {
          const actualChunks = files.filter((f: any) => f.name?.match(/^chunk-\d+\.json$/)).length;
          // Use a permissive floor — only flag meta as corrupt if count is way below
          // chunks × 10 (clearly broken). Otherwise trust meta.json's count.
          // This handles both pre-migration (100/chunk) and post-migration (300/chunk) states.
          const expectedMin = Math.max(0, (actualChunks - 1) * 10);
          // Only override if meta.json count is CLEARLY broken (less than minimum possible)
          if (count < expectedMin) {
            console.warn(`[OnlineBackup] meta.json count=${count} < expectedMin=${expectedMin} (from ${actualChunks} chunks). Meta is corrupt — using expectedMin.`);
            count = expectedMin;
          } else {
            // meta.json count is valid (>= expectedMin) — use it as-is, DON'T override
            console.log(`[OnlineBackup] meta.json count=${count} is valid (>= expectedMin=${expectedMin} from ${actualChunks} chunks). Using meta count.`);
          }
        }
      }
    } catch {}

    // Update short-lived cache
    _realtimeGhCountCache = { count, timestamp: Date.now() };

    // Also update the long-term cache (DB Settings + persistent file)
    // so that other code paths benefit from the fresh data
    if (count > 0) {
      try {
        await db.settings.upsert({
          where: { key: ATTENDANCE_COUNT_KEY },
          update: { value: String(count) },
          create: { key: ATTENDANCE_COUNT_KEY, value: String(count) },
        });
        const { savePersistentGhCount } = await import('./db-persistent-sync');
        await savePersistentGhCount(count);
      } catch {}
    }

    return { count };
  } catch (e) {
    return { count: 0, error: e instanceof Error ? e.message : String(e) };
  }
}

/**
 * Clear the short-lived realtime cache.
 * Call this after sync/pull operations to ensure the next read gets fresh data.
 */
export function clearRealtimeGhCountCache() {
  _realtimeGhCountCache = null;
}

// ===== CACHED sync health (for UI display, 10-min cache) =====

// Cache for getSyncHealth — prevents hitting GitHub API too often (rate limit protection)
// GitHub authenticated rate limit: 5,000 req/hour. Unauthenticated: 60/hour.
// We cache for 5 minutes to avoid exceeding the limit.
let _healthCache: { result: any; timestamp: number } | null = null;
const HEALTH_CACHE_TTL = 60 * 1000; // 1 minute — short cache since we now fetch realtime from GitHub

/**
 * Get sync health status for dashboard display.
 * Tracks BOTH sync (push) and pull (restore) operations.
 * Also reads GitHub meta.json for latest backup info (file count, attendance count).
 * CACHED for 5 minutes to avoid GitHub API rate limits.
 */
export async function getSyncHealth(): Promise<any> {
  // Return cached result if still fresh
  if (_healthCache && (Date.now() - _healthCache.timestamp) < HEALTH_CACHE_TTL) {
    return _healthCache.result;
  }

  const result = await _getSyncHealthUncached();
  _healthCache = { result, timestamp: Date.now() };
  return result;
}

/** Clear the health cache — call after sync/pull to get fresh data */
export function clearHealthCache() {
  _healthCache = null;
  // Also clear the realtime count cache so next read gets fresh data
  _realtimeGhCountCache = null;
}

async function _getSyncHealthUncached(): Promise<any> {
  try {
    const config = await getConfig();
    if (!config) {
      return {
        configured: false,
        lastSyncAt: null,
        lastPullAt: null,
        lastResult: null,
        lastPullResult: null,
        isHealthy: false,
        status: 'unconfigured',
        statusLabel: 'Belum dikonfigurasi',
        statusColor: 'gray',
        minutesAgo: null,
        githubInfo: null,
      };
    }

    // Get last sync/pull time + results from DB
    let lastSyncAt: string | null = null;
    let lastPullAt: string | null = null;
    let lastResult: { success: boolean; message: string; timestamp: string } | null = null;
    let lastPullResult: { success: boolean; message: string; timestamp: string } | null = null;
    try {
      const lastSyncSetting = await db.settings.findUnique({ where: { key: LAST_SYNC_KEY } });
      lastSyncAt = lastSyncSetting?.value || null;

      const lastResultSetting = await db.settings.findUnique({ where: { key: 'online_last_sync_result' } });
      if (lastResultSetting?.value) {
        try { lastResult = JSON.parse(lastResultSetting.value); } catch {}
      }

      const lastPullSetting = await db.settings.findUnique({ where: { key: 'online_last_pull_at' } });
      lastPullAt = lastPullSetting?.value || null;

      const lastPullResultSetting = await db.settings.findUnique({ where: { key: 'online_last_pull_result' } });
      if (lastPullResultSetting?.value) {
        try { lastPullResult = JSON.parse(lastPullResultSetting.value); } catch {}
      }
    } catch {
      // DB may be unavailable after reset
    }

    // GitHub info — use CACHED data from DB only (NO GitHub API calls)
    // This prevents blocking the event loop which causes ERR_INVALID_RESPONSE
    // GitHub info is only updated when user opens the "JSON Backup Online" panel
    let githubInfo: {
      totalChunks: number;
      attendanceCount: number;
      classes: number;
      students: number;
      exportedAt: string | null;
      fileCount: number;
    } | null = null;
    let connected = true; // Assume connected (can't check without GitHub API call)
    let rateLimited = false;
    let ghExportedAt: string | null = null;

    // REAL-TIME GitHub info: fetch actual count from meta.json
    // This does NOT use cached DB Settings — always gets fresh data from GitHub.
    // Has a 30-second short-lived cache to prevent duplicate API calls.
    try {
      const { count: ghAttCount, error: ghError } = await fetchGhAttendanceCountRealtime();
      if (ghAttCount > 0) {
        githubInfo = {
          totalChunks: Math.ceil(ghAttCount / RECORDS_PER_CHUNK) + 1,
          attendanceCount: ghAttCount,
          classes: 0,
          students: 0,
          exportedAt: lastSyncAt,
          fileCount: Math.ceil(ghAttCount / RECORDS_PER_CHUNK),
        };
        connected = true;
        rateLimited = false;
      } else if (ghError && ghError.includes('rate limit')) {
        connected = false;
        rateLimited = true;
      } else if (ghError && ghError !== 'not configured' && ghError !== 'meta.json not found') {
        connected = false;
      }
    } catch {}

    // Use lastSyncAt as ghExportedAt fallback
    if (!ghExportedAt && lastSyncAt) {
      ghExportedAt = lastSyncAt;
    }

    // Fallback: if DB has no lastSyncAt, use GitHub meta.json exportedAt
    if (!lastSyncAt && ghExportedAt) {
      lastSyncAt = ghExportedAt;
    }

    // Calculate minutes since last sync
    let minutesAgo: number | null = null;
    if (lastSyncAt) {
      const diff = Date.now() - new Date(lastSyncAt).getTime();
      minutesAgo = Math.floor(diff / 60000);
    }

    // Determine health status
    let status: 'synced' | 'error' | 'stale' | 'disconnected' | 'unconfigured' | 'pulling';
    let statusLabel: string;
    let statusColor: 'green' | 'red' | 'yellow' | 'gray' | 'cyan';
    let isHealthy = false;

    if (!connected && rateLimited) {
      status = 'error';
      statusLabel = 'GitHub API rate limit exceeded — coba lagi nanti';
      statusColor = 'red';
    } else if (!connected) {
      status = 'disconnected';
      statusLabel = 'Token GitHub tidak valid/kadaluwarsa';
      statusColor = 'red';
    } else if (lastPullResult && !lastPullResult.success && lastPullAt) {
      // Last pull failed
      status = 'error';
      statusLabel = `Pull error: ${lastPullResult.message.substring(0, 40)}`;
      statusColor = 'red';
    } else if (lastPullAt) {
      // Pull was done — show pull status if more recent than sync
      const pullMinutes = Math.floor((Date.now() - new Date(lastPullAt).getTime()) / 60000);
      const syncMinutes = lastSyncAt ? Math.floor((Date.now() - new Date(lastSyncAt).getTime()) / 60000) : Infinity;
      if (pullMinutes < syncMinutes) {
        status = 'synced';
        isHealthy = true;
        if (pullMinutes < 1) {
          statusLabel = 'Pulled: baru saja';
        } else if (pullMinutes < 60) {
          statusLabel = `Pulled: ${pullMinutes} menit lalu`;
        } else {
          statusLabel = `Pulled: ${Math.floor(pullMinutes / 60)} jam lalu`;
        }
        statusColor = 'cyan';
      } else {
        // Sync was more recent
        if (lastResult && !lastResult.success) {
          status = 'error';
          statusLabel = `Sync error: ${lastResult.message.substring(0, 40)}`;
          statusColor = 'red';
        } else if (minutesAgo !== null && minutesAgo > 60 * 24) {
          status = 'stale';
          statusLabel = `Last sync: ${Math.floor(minutesAgo / (60 * 24))} hari lalu`;
          statusColor = 'yellow';
        } else {
          status = 'synced';
          isHealthy = true;
          if (minutesAgo !== null) {
            if (minutesAgo < 1) statusLabel = 'Synced: baru saja';
            else if (minutesAgo < 60) statusLabel = `Synced: ${minutesAgo} menit lalu`;
            else statusLabel = `Synced: ${Math.floor(minutesAgo / 60)} jam lalu`;
          } else {
            statusLabel = 'Synced';
          }
          statusColor = 'green';
        }
      }
    } else if (!lastSyncAt) {
      status = 'stale';
      statusLabel = 'Belum pernah sync';
      statusColor = 'yellow';
    } else if (lastResult && !lastResult.success) {
      status = 'error';
      statusLabel = `Error: ${lastResult.message.substring(0, 50)}`;
      statusColor = 'red';
    } else if (minutesAgo !== null && minutesAgo > 60 * 24) {
      status = 'stale';
      statusLabel = `Last sync: ${Math.floor(minutesAgo / (60 * 24))} hari lalu`;
      statusColor = 'yellow';
    } else {
      status = 'synced';
      isHealthy = true;
      if (minutesAgo !== null) {
        if (minutesAgo < 1) statusLabel = 'Synced: baru saja';
        else if (minutesAgo < 60) statusLabel = `Synced: ${minutesAgo} menit lalu`;
        else statusLabel = `Synced: ${Math.floor(minutesAgo / 60)} jam lalu`;
      } else {
        statusLabel = 'Synced';
      }
      statusColor = 'green';
    }

    return {
      configured: true,
      lastSyncAt,
      lastPullAt,
      lastResult,
      lastPullResult,
      isHealthy,
      status,
      statusLabel,
      statusColor,
      minutesAgo,
      githubInfo,
    };
  } catch (error) {
    return {
      configured: false,
      lastSyncAt: null,
      lastPullAt: null,
      lastResult: null,
      lastPullResult: null,
      isHealthy: false,
      status: 'unconfigured',
      statusLabel: 'Error: ' + (error instanceof Error ? error.message : 'Unknown'),
      statusColor: 'red',
      minutesAgo: null,
      githubInfo: null,
    };
  }
}

export async function checkOnlineBackup(): Promise<{ success: boolean; message: string; info?: any }> {
  try {
    const config = await getConfig();
    if (!config) return { success: false, message: 'GitHub backup belum dikonfigurasi.' };

    const metaFile = await githubGetFile(config, META_FILE).catch(() => null);
    if (!metaFile) return { success: true, message: 'Belum ada backup online.' };

    const meta = JSON.parse(metaFile.content);
    const totalChunks = meta.meta?.totalChunks || 1;
    const exportedAt = meta.exportedAt || meta.meta?.exportedAt || 'unknown';
    const classes = meta.data?.classes?.length || 0;
    const students = meta.data?.students?.length || 0;
    const attendanceCount = meta.meta?.attendanceCount || 0;

    return {
      success: true,
      message: `Backup tersedia: ${totalChunks} chunks, ${classes} kelas, ${students} siswa, ${attendanceCount} absensi. Exported: ${exportedAt}`,
      info: { totalChunks, exportedAt, classes, students, attendance: attendanceCount },
    };
  } catch (error) {
    return { success: false, message: `Gagal cek backup: ${error instanceof Error ? error.message : 'Unknown'}` };
  }
}

// ===== RESET DETECTION =====

/**
 * Detect if a data reset occurred by checking:
 * 1. 0 classes in DB
 * 2. 0 attendance records
 * 3. Attendance dropped >50% since last sync
 * 4. 0% completeness after 07:30 WIB (except holidays)
 *
 * If reset detected → pause sync → auto-restore from online backup
 */
export async function detectResetAndAutoRestore(): Promise<boolean> {
  try {
    const classCount = await db.class.count();
    const studentCount = await db.student.count();
    const attendanceCount = await db.attendance.count();

    // Case 1: DB is completely empty
    if (classCount === 0) {
      console.log('[OnlineBackup ResetDetection] DB empty (0 classes) — triggering restore...');
      pauseOnlineSync(true);
      const result = await restoreFromOnlineBackup();
      console.log('[OnlineBackup ResetDetection] Restore:', result.success ? 'BERHASIL' : 'GAGAL', result.message);
      pauseOnlineSync(false);
      return result.success;
    }

    // Case 2: Check stored attendance count
    const storedCountSetting = await db.settings.findUnique({ where: { key: ATTENDANCE_COUNT_KEY } });
    if (storedCountSetting) {
      const storedCount = parseInt(storedCountSetting.value, 10);
      if (!isNaN(storedCount) && storedCount > 0 && attendanceCount < storedCount * 0.5) {
        console.log(`[OnlineBackup ResetDetection] Attendance dropped: DB=${attendanceCount} vs backup=${storedCount} (< 50%)`);
        pauseOnlineSync(true);
        const result = await restoreFromOnlineBackup();
        pauseOnlineSync(false);
        return result.success;
      }
    }

    // Case 3: Have classes + students but 0 attendance (if we've synced before)
    const lastSync = await getLastSyncAt();
    if (lastSync && classCount > 0 && studentCount > 0 && attendanceCount === 0) {
      console.log('[OnlineBackup ResetDetection] 0 attendance despite having classes — triggering restore...');
      pauseOnlineSync(true);
      const result = await restoreFromOnlineBackup();
      pauseOnlineSync(false);
      return result.success;
    }

    return false;
  } catch (error) {
    console.error('[OnlineBackup ResetDetection] Error:', error);
    pauseOnlineSync(false);
    return false;
  }
}

/**
 * Check attendance completeness for today.
 * If 0% completeness AND not a holiday AND after 07:30 WIB → reset detected.
 * Returns true if reset detected, false otherwise.
 */
export async function checkCompletenessReset(): Promise<{ reset: boolean; reason: string }> {
  try {
    const now = new Date();
    const utc = now.getTime() + now.getTimezoneOffset() * 60000;
    const jakarta = new Date(utc + 7 * 3600000);
    const jakartaHour = jakarta.getHours();
    const jakartaMinute = jakarta.getMinutes();
    const isAfter0730 = (jakartaHour > 7) || (jakartaHour === 7 && jakartaMinute >= 30);

    if (!isAfter0730) return { reset: false, reason: 'Before 07:30 WIB' };

    const today = jakarta.toISOString().split('T')[0];

    // Check if today is a holiday
    const dateHoliday = await db.dateHoliday.findFirst({ where: { date: today } });
    if (dateHoliday) return { reset: false, reason: `Holiday: ${dateHoliday.name}` };

    // Check if today is an academic holiday (weekly)
    const dayOfWeek = jakarta.toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase();
    const academicHoliday = await db.academicHoliday.findFirst({ where: { dayOfWeek } });
    if (academicHoliday) return { reset: false, reason: `Academic holiday: ${academicHoliday.name}` };

    // Check completeness
    const compRes = await fetch(`http://localhost:3000/api/attendance-completeness?date=${today}`, { signal: AbortSignal.timeout(10000) }).catch(() => null);
    if (!compRes) return { reset: false, reason: 'Completeness check failed' };
    const compData = await compRes.json().catch(() => null);
    if (!compData?.classes || !Array.isArray(compData.classes)) return { reset: false, reason: 'No completeness data' };

    const totalScheduled = compData.classes.reduce((s: number, c: any) => s + (c.totalScheduled || 0), 0);
    const totalFilled = compData.classes.reduce((s: number, c: any) => s + (c.totalFilled || 0), 0);
    const pct = totalScheduled > 0 ? Math.round((totalFilled / totalScheduled) * 100) : 0;

    if (totalScheduled > 0 && pct === 0) {
      return { reset: true, reason: `Completeness 0% after 07:30 WIB (scheduled=${totalScheduled}, filled=${totalFilled})` };
    }

    return { reset: false, reason: `Completeness ${pct}% (scheduled=${totalScheduled}, filled=${totalFilled})` };
  } catch (error) {
    return { reset: false, reason: `Error: ${error instanceof Error ? error.message : 'Unknown'}` };
  }
}
"},{"path":"src/lib/operation-lock.ts","content":"/**
 * Global Operation Lock — ensures only ONE sync/restore operation runs at a time.
 *
 * Prevents crashes caused by concurrent operations:
 *   - When autosync runs → pull-diff/pull-full/restore-local BLOCKED
 *   - When pull-diff/pull-full runs → autosync/restore-local BLOCKED
 *   - When restore-local runs → autosync/pull-diff/pull-full BLOCKED
 *   - When gsheet-sync/gsheet-pull runs → all other ops BLOCKED (and vice versa)
 *
 * This is a MODULE-LEVEL singleton (shared across all requests in the same
 * Node.js process). It uses simple boolean flags — no async locks needed
 * because Node.js is single-threaded.
 *
 * The lock is NON-BLOCKING: if an operation is already running, callers
 * get `false` from `tryStartOperation()` and must handle the rejection
 * gracefully (skip, queue, or warn the user).
 */

export type OperationType =
  | 'auto-sync'     // Debounced auto-sync after DB writes (push to GitHub)
  | 'sync'          // Manual full sync (push to GitHub)
  | 'pull-diff'     // Manual/auto pull-diff (restore missing from GitHub)
  | 'pull-full'     // Manual full pull/restore (overwrite all from GitHub)
  | 'restore-local' // Restore from local backup file (auto_restore.json)
  | 'gsheet-sync'   // G-Sheet push — sync local data to Google Sheets
  | 'gsheet-pull'   // G-Sheet pull — restore data from Google Sheets
  | null;

export interface OperationState {
  current: OperationType;
  startedAt: string | null;
  label: string;          // Human-readable label for UI
  progress: {             // Progress info for UI
    current: number;
    total: number;
    percentage: number;
    label: string;
  } | null;
}

// Module-level state (singleton per process)
let _currentOp: OperationType = null;
let _startedAt: string | null = null;
let _label: string = '';
let _progress: OperationState['progress'] = null;

// History of last results for each operation type
interface OpResult { success: boolean; message: string; timestamp: string; }
const _lastResults: Partial<Record<Exclude<OperationType, null>, OpResult>> = {};

/**
 * Get the current operation state (for API/UI polling)
 */
export function getOperationState(): OperationState {
  return {
    current: _currentOp,
    startedAt: _startedAt,
    label: _label,
    progress: _progress,
  };
}

/**
 * Get last results for all operation types (for UI display)
 */
export function getLastResults(): Partial<Record<Exclude<OperationType, null>, OpResult>> {
  return { ..._lastResults };
}

/**
 * Try to start an operation. Returns true if successful, false if blocked.
 *
 * Usage:
 *   if (!tryStartOperation('pull-diff', 'Pull diff from GitHub')) {
 *     return { success: false, message: 'Cannot start: another operation is running' };
 *   }
 *   try {
 *     // ... do the work ...
 *     recordResult('pull-diff', true, 'Success message');
 *   } catch (e) {
 *     recordResult('pull-diff', false, e.message);
 *   } finally {
 *     endOperation('pull-diff');
 *   }
 */
export function tryStartOperation(op: Exclude<OperationType, null>, label?: string): boolean {
  if (_currentOp !== null) {
    console.warn(`[OperationLock] Cannot start "${op}" — "${_currentOp}" is already running`);
    return false;
  }
  _currentOp = op;
  _startedAt = new Date().toISOString();
  _label = label || op;
  _progress = null;
  console.log(`[OperationLock] Started: ${op} (${_label})`);
  return true;
}

/**
 * End the current operation. Only ends if the op matches (preaccidental double-end).
 */
export function endOperation(op: Exclude<OperationType, null>): void {
  if (_currentOp === op) {
    console.log(`[OperationLock] Ended: ${op} (ran for ${_startedAt ? Date.now() - new Date(_startedAt).getTime() : '?'}ms)`);
    _currentOp = null;
    _startedAt = null;
    _label = '';
    _progress = null;
  }
}

/**
 * Update progress for the current operation (for UI polling)
 */
export function updateProgress(current: number, total: number, label: string): void {
  if (_currentOp === null) return;
  _progress = {
    current,
    total,
    percentage: total > 0 ? Math.round((current / total) * 100) : 0,
    label,
  };
}

/**
 * Record the result of an operation (for lastResults history)
 */
export function recordResult(op: Exclude<OperationType, null>, success: boolean, message: string): void {
  _lastResults[op] = {
    success,
    message: message.substring(0, 500), // truncate long messages
    timestamp: new Date().toISOString(),
  };
}

/**
 * Check if a specific operation type is currently running.
 */
export function isOperationRunning(op: Exclude<OperationType, null>): boolean {
  return _currentOp === op;
}

/**
 * Check if ANY operation is currently running.
 */
export function isAnyOperationRunning(): boolean {
  return _currentOp !== null;
}
"},{"path":"src/lib/pdf-fonts.ts","content":"import fs from 'fs';
import path from 'path';

let patched = false;
const fontCache: Record<string, string> = {};

/**
 * Patches fs.readFileSync so pdfkit can find its standard font .afm files
 * even when __dirname resolves incorrectly in Next.js/Turbopack.
 */
export function ensurePdfFonts() {
  if (patched) return;

  // Find the actual pdfkit data directory
  let pdfkitDataDir: string | null = null;
  try {
    const pdfkitEntryPath = require.resolve('pdfkit');
    // pdfkit entry points to js/pdfkit.js, so data is at ../data relative to js/
    const jsDir = path.dirname(pdfkitEntryPath);
    pdfkitDataDir = path.join(jsDir, 'data');
    if (!fs.existsSync(pdfkitDataDir)) {
      // Try alternative: pdfkit entry might be pdfkit.js directly in the package root
      pdfkitDataDir = path.join(path.dirname(jsDir), 'js', 'data');
    }
    if (!fs.existsSync(pdfkitDataDir)) {
      pdfkitDataDir = path.join(path.dirname(jsDir), 'data');
    }
  } catch {
    // Fallback: use known project path
    pdfkitDataDir = path.join(process.cwd(), 'node_modules', 'pdfkit', 'js', 'data');
  }

  if (!pdfkitDataDir || !fs.existsSync(pdfkitDataDir)) {
    console.error('[pdf-fonts] WARNING: Could not locate pdfkit data directory');
    return;
  }

  // Pre-load all .afm files into cache
  try {
    const files = fs.readdirSync(pdfkitDataDir);
    for (const file of files) {
      if (file.endsWith('.afm')) {
        fontCache[file] = fs.readFileSync(path.join(pdfkitDataDir, file), 'utf8');
      }
    }
  } catch (e) {
    console.error('[pdf-fonts] WARNING: Failed to read font files:', e);
    return;
  }

  // Save original
  const origReadFileSync = fs.readFileSync;

  // Patch fs.readFileSync
  (fs as any).readFileSync = function(filePath: string, ...args: any[]) {
    const filename = path.basename(filePath);
    if (filename.endsWith('.afm') && fontCache[filename]) {
      return fontCache[filename];
    }
    return origReadFileSync.call(fs, filePath, ...args);
  };

  patched = true;
  console.log('[pdf-fonts] Patched fs.readFileSync for', Object.keys(fontCache).length, 'font files from', pdfkitDataDir);
}
"},{"path":"src/lib/rekap-guru-data.ts","content":"/**
 * REKAP GURU — SHARED DATA ENGINE (single source of truth)
 *
 * Used by:
 *  - /api/check-absensi/rekap-guru      (JSON for the web UI)
 *  - /api/recap/rekap-guru-pdf          (PDF download, groupBy = date | teacher)
 *  - /api/recap/rekap-guru-excel        (Excel download, groupBy = date | teacher)
 *
 * Having ONE engine guarantees that the web view, preview, print, PDF and
 * Excel exports always agree on the same school-day window, the same
 * "belum mengisi" detection and the same grouping semantics:
 *
 *  - KELOMPOK PER TANGGAL → one table per school day
 *    (rows: NO | NAMA GURU | KELAS | JAM KE-)
 *  - KELOMPOK PER GURU   → one table per teacher name
 *    (rows: NO | TANGGAL | KELAS | JAM KE-)
 */

import { db } from '@/lib/db';
import { resolveTeacherNameWithMap } from '@/lib/teacher-names';

export const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
export const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

// Guard against unbounded range-mode queries (a full year is 365 days).
export const MAX_RANGE_DAYS = 400;

export type RekapGroupBy = 'date' | 'teacher';

export function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export function formatDateIndo(dateStr: string): string {
  const [y, m, d] = dateStr.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
}

export function formatDDMMYYYY(dateStr: string): string {
  const d = parseDate(dateStr);
  return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
}

// Strict calendar validation for YYYY-MM-DD strings (rejects e.g. 2025-02-30
// or 2025-13-01 which JS Date would silently roll over).
export function isValidDateStr(dateStr: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const [y, m, d] = dateStr.split('-').map(Number);
  const dt = new Date(y, m - 1, d);
  return dt.getFullYear() === y && dt.getMonth() === m - 1 && dt.getDate() === d;
}

// ---------------- Data shapes (identical to the JSON API contract) ----------------

export interface RekapGuruTeacherEntry {
  fullName: string;
  classId: string;
  className: string;
  hours: number[];
}

/** KELOMPOK PER TANGGAL — one table per school day. */
export interface RekapGuruDay {
  date: string;
  dayName: string;
  formattedDate: string;
  teachers: RekapGuruTeacherEntry[];
}

export interface RekapGuruTeacherGroupEntry {
  date: string;
  dayName: string;
  formattedDate: string;
  className: string;
  classId: string;
  hours: number[];
}

/** KELOMPOK PER GURU — one table per teacher name. */
export interface RekapGuruTeacherGroup {
  fullName: string;
  totalMissed: number;
  entries: RekapGuruTeacherGroupEntry[];
}

export interface RekapGuruHoliday {
  date: string;
  dayName: string;
  name: string;
}

export interface RekapGuruComputation {
  schoolDays: string[];
  /** ascending by date (chronological) */
  daysAsc: RekapGuruDay[];
  /** newest first (selected/recent date at top) — used by the web UI + PDF */
  daysNewestFirst: RekapGuruDay[];
  /** sorted by totalMissed DESC, then fullName ASC */
  teacherGroups: RekapGuruTeacherGroup[];
  /** date holidays inside the window, ascending */
  holidays: RekapGuruHoliday[];
}

/**
 * Core computation shared by every rekap-guru consumer.
 *
 * School-day rules (identical across all consumers):
 *  - Sunday (Ahad) is an EFFECTIVE school day.
 *  - Friday (academic weekly holiday) + per-date holidays are excluded.
 *  - Per-class "Libur" academic activities and per-date max_hours settings
 *    are respected, so a jam that does not exist is never reported missing.
 */
export async function computeRekapGuruData(windowStart: string, windowEnd: string): Promise<RekapGuruComputation> {
  // Weekly + per-date holidays.
  const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
  const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
  const dateHolidays = await db.dateHoliday.findMany();
  const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));

  const schoolDays: string[] = [];
  const startD = parseDate(windowStart);
  const endD = parseDate(windowEnd);
  const cur = new Date(startD);
  while (cur <= endD) {
    const dow = cur.getDay();
    const ds = formatDateStr(cur);
    if (!holidayDays.has(dow) && !dateHolidaySet.has(ds)) {
      schoolDays.push(ds);
    }
    cur.setDate(cur.getDate() + 1);
  }

  // Weekly schedules for the relevant days of week.
  const dayOfWeeks = new Set(schoolDays.map(ds => parseDate(ds).getDay()));
  const schedules = await db.weeklySchedule.findMany({
    where: { dayOfWeek: { in: [...dayOfWeeks] } },
  });

  // Classes (active = not Libur + has students).
  const classes = await db.class.findMany({
    include: { _count: { select: { students: true } } },
  });
  const classNameMap = new Map<string, string>();
  for (const cls of classes) {
    classNameMap.set(cls.id, cls.name);
  }
  const activeClassIds = new Set<string>();
  for (const cls of classes) {
    if (!cls.name.toLowerCase().includes('libur') && cls._count.students > 0) {
      activeClassIds.add(cls.id);
    }
  }
  const activeSchedules = schedules.filter(s => activeClassIds.has(s.classId));

  // Attendance records → filled set keyed by (classId:date:hour).
  const allAttendance = await db.attendance.findMany({
    where: { date: { in: schoolDays } },
    select: { classId: true, date: true, hour: true },
  });
  const filledSet = new Set<string>();
  for (const r of allAttendance) {
    filledSet.add(`${r.classId}:${r.date}:${r.hour}`);
  }

  // Per-date max hours settings (key: max_hours_YYYY-MM-DD, default 8).
  const maxHoursSettings = await db.settings.findMany({
    where: { key: { startsWith: 'max_hours_' } },
  });
  const maxHoursByDate: Record<string, number> = {};
  for (const s of maxHoursSettings) {
    const datePart = s.key.replace('max_hours_', '');
    const n = parseInt(s.value, 10);
    if (!isNaN(n)) maxHoursByDate[datePart] = n;
  }

  // Academic activities → per-class Libur dates.
  const activities = await db.academicActivity.findMany({
    where: { date: { in: schoolDays } },
    select: { classId: true, date: true, status: true },
  });
  const liburClassDate = new Set<string>();
  for (const a of activities) {
    if (a.status === 'Libur') liburClassDate.add(`${a.classId}:${a.date}`);
  }

  // Teacher name map (DB → static fallback).
  const teacherRows = await db.teacher.findMany();
  const teacherMap: Record<string, string> = {};
  for (const t of teacherRows) {
    teacherMap[t.nickname] = t.fullName;
  }

  // Build per-day tables (ascending) + per-teacher aggregation.
  const daysAsc: RekapGuruDay[] = [];
  const teacherAgg = new Map<string, { totalMissed: number; entries: RekapGuruTeacherGroupEntry[] }>();

  for (const ds of schoolDays) {
    const dow = parseDate(ds).getDay();
    const dObj = parseDate(ds);
    const dayName = DAY_NAMES[dow];
    const formattedDate = `${dayName}, ${dObj.getDate()} ${MONTHS[dObj.getMonth()]} ${dObj.getFullYear()}`;

    const maxHours = maxHoursByDate[ds] ?? 8;

    // Collect missed (teacher, class, hour) for this specific day.
    const teacherClassMap = new Map<string, { fullName: string; classId: string; className: string; hours: Set<number> }>();
    for (const sched of activeSchedules) {
      if (sched.dayOfWeek !== dow) continue;
      if (liburClassDate.has(`${sched.classId}:${ds}`)) continue;
      if (sched.hour > maxHours) continue;
      const teacher = sched.teacher.trim();
      if (!teacher) continue;
      const filled = filledSet.has(`${sched.classId}:${ds}:${sched.hour}`);
      if (!filled) {
        const key = `${teacher}|${sched.classId}`;
        let entry = teacherClassMap.get(key);
        if (!entry) {
          entry = {
            fullName: resolveTeacherNameWithMap(teacher, teacherMap),
            classId: sched.classId,
            className: classNameMap.get(sched.classId) || sched.classId,
            hours: new Set<number>(),
          };
          teacherClassMap.set(key, entry);
        }
        entry.hours.add(sched.hour);
      }
    }

    const teachers: RekapGuruTeacherEntry[] = [];
    for (const entry of teacherClassMap.values()) {
      const hours = [...entry.hours].sort((a, b) => a - b);
      teachers.push({
        fullName: entry.fullName,
        classId: entry.classId,
        className: entry.className,
        hours,
      });
      // Always aggregate per-teacher (cheap; consumers pick what they need).
      let group = teacherAgg.get(entry.fullName);
      if (!group) {
        group = { totalMissed: 0, entries: [] };
        teacherAgg.set(entry.fullName, group);
      }
      group.totalMissed += hours.length;
      group.entries.push({
        date: ds,
        dayName,
        formattedDate,
        className: entry.className,
        classId: entry.classId,
        hours,
      });
    }
    teachers.sort((a, b) => {
      const c = a.fullName.localeCompare(b.fullName);
      if (c !== 0) return c;
      return a.className.localeCompare(b.className);
    });

    daysAsc.push({ date: ds, dayName, formattedDate, teachers });
  }

  // Teacher groups: entries chronological, groups by totalMissed DESC then name.
  const teacherGroups: RekapGuruTeacherGroup[] = [];
  for (const [fullName, group] of teacherAgg) {
    group.entries.sort((a, b) => {
      const c = a.date.localeCompare(b.date);
      if (c !== 0) return c;
      return a.className.localeCompare(b.className);
    });
    teacherGroups.push({ fullName, totalMissed: group.totalMissed, entries: group.entries });
  }
  teacherGroups.sort((a, b) => {
    if (b.totalMissed !== a.totalMissed) return b.totalMissed - a.totalMissed;
    return a.fullName.localeCompare(b.fullName);
  });

  // Holidays inside the window (for PDF/Excel footnotes).
  const holidaysInWindow: RekapGuruHoliday[] = [];
  for (const dh of dateHolidays) {
    if (dh.date >= windowStart && dh.date <= windowEnd) {
      holidaysInWindow.push({
        date: dh.date,
        dayName: DAY_NAMES[parseDate(dh.date).getDay()],
        name: dh.name,
      });
    }
  }
  holidaysInWindow.sort((a, b) => a.date.localeCompare(b.date));

  return {
    schoolDays,
    daysAsc,
    daysNewestFirst: [...daysAsc].reverse(),
    teacherGroups,
    holidays: holidaysInWindow,
  };
}
"},{"path":"src/lib/student-blocklist.ts","content":"/**
 * STUDENT BLOCKLIST — 6-layer protection
 *
 * Students listed here were deliberately deleted by the admin (13 November 2026).
 * They must NEVER come back through any path:
 *
 *   Layer 1 — GET /api/students            : filtered out of class rosters (UI never shows them)
 *   Layer 2 — POST /api/students           : creation with these IDs rejected
 *   Layer 3 — Auto-restore (local JSON)    : filtered before DB write
 *   Layer 4 — Online backup pull (GitHub)  : filtered in restoreFromOnlineBackup / restoreMissing / pull-diff
 *   Layer 5 — Online backup sync (export)  : filtered before upload so they never re-enter GitHub
 *   Layer 6 — G-Sheet sync                 : filtered in Google Sheets import
 *
 * Any new restore/import path MUST call isStudentExcluded() / filterExcludedStudents().
 */

export const EXCLUDED_STUDENT_IDS: readonly string[] = [
  'cms7m44nv001vrh0aonx0a63w', // Ahmad Fauzan Asfiya
  'cms7m44pd002trh0ad1uq6pt7', // Naylun Nihaya
] as const;

/** Returns true if the student ID is blocklisted. */
export function isStudentExcluded(studentId?: string | null): boolean {
  if (!studentId) return false;
  return (EXCLUDED_STUDENT_IDS as readonly string[]).includes(studentId);
}

/** Filters an array of student-like objects, removing blocklisted IDs. */
export function filterExcludedStudents<T extends { id?: string; studentId?: string }>(items: T[]): T[] {
  if (!Array.isArray(items)) return items;
  return items.filter((s) => !isStudentExcluded(s?.id) && !isStudentExcluded(s?.studentId));
}

/** Removes attendance records that reference blocklisted students. */
export function filterExcludedAttendance<T extends { studentId?: string }>(items: T[]): T[] {
  if (!Array.isArray(items)) return items;
  return items.filter((a) => !isStudentExcluded(a?.studentId));
}
