export function resolveTeacherName(nickname: string): string {
  const trimmed = nickname.trim();
  if (!trimmed) return trimmed;
  return TEACHER_NAME_MAP[trimmed] || trimmed;
}

/**
 * Resolve a teacher nickname using a DB-fetched map, falling back to the static
 * map, then to the raw nickname. Used by APIs that have already loaded the
 * Teacher table into a plain object map.
 */
export function resolveTeacherNameWithMap(
  nickname: string,
  dbMap: Record<string, string>,
): string {
  const trimmed = nickname.trim();
  if (!trimmed) return trimmed;
  const dbVal = dbMap[trimmed];
  if (dbVal && dbVal.trim()) return dbVal;
  return TEACHER_NAME_MAP[trimmed] || trimmed;
}
"},{"path":"src/lib/utils.ts","content":"import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"
import { NextResponse } from "next/server"

/** Get today's date string (YYYY-MM-DD) in Asia/Jakarta timezone (GMT+7) */
export function getJakartaToday(): string {
  const now = new Date()
  const utcMs = now.getTime() + now.getTimezoneOffset() * 60000
  const jakarta = new Date(utcMs + 7 * 3600000)
  const y = jakarta.getFullYear()
  const m = String(jakarta.getMonth() + 1).padStart(2, '0')
  const d = String(jakarta.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

/** Parse YYYY-MM-DD string to UTC Date (timezone-safe) */
function parseDateUTC(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number)
  return new Date(Date.UTC(y, m - 1, d))
}

/** Get day of week (0=Sun..6=Sat) from YYYY-MM-DD string, timezone-safe */
export function getDayOfWeekUTC(dateStr: string): number {
  return parseDateUTC(dateStr).getUTCDay()
}

/** Format a date string for display using Jakarta timezone */
export function formatDateJakarta(dateStr: string): string {
  const d = parseDateUTC(dateStr)
  const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu']
  const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember']
  return `${days[d.getUTCDay()]}, ${d.getUTCDate()} ${months[d.getUTCMonth()]} ${d.getUTCFullYear()}`
}

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** JSON response with no-cache headers — prevents stale data across devices/users */
export function noCacheJson(data: unknown, status = 200) {
  return NextResponse.json(data, {
    status,
    headers: {
      'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
      'Pragma': 'no-cache',
      'Expires': '0',
    },
  })
}
"},{"path":"src/lib/wa-notification.ts","content":"/**
 * WhatsApp notification helper.
 *
 * Sends a WhatsApp message to a target phone number via a configurable WA
 * gateway. The gateway URL and token are read from environment variables
 * (WA_GATEWAY_URL, WA_GATEWAY_TOKEN). If not set, the message is logged
 * to the console only (no actual send) — useful for dev/testing.
 *
 * Supported gateways (set WA_GATEWAY_URL accordingly):
 *   - Fonnte:   https://api.fonnte.com/send  (body: { target, message, token })
 *   - Wablas:   https://console.wablas.com/api/send-message
 *   - Any gateway that accepts { target, message } JSON POST
 */

const WA_TARGET_NUMBER = '081615260385';
const WA_GATEWAY_URL = process.env.WA_GATEWAY_URL || '';
const WA_GATEWAY_TOKEN = process.env.WA_GATEWAY_TOKEN || '';

export interface WhatsAppResult {
  sent: boolean;
  reason?: string;
  gatewayResponse?: unknown;
}

/**
 * Send a WhatsApp message to the configured target number.
 * Falls back to console.log if no gateway is configured.
 */
export async function sendWhatsAppMessage(message: string, targetNumber?: string): Promise<WhatsAppResult> {
  const target = targetNumber || WA_TARGET_NUMBER;

  // No gateway configured — log only (dev/test mode)
  if (!WA_GATEWAY_URL) {
    console.log('[WhatsApp] (no gateway configured — logging only)');
    console.log('[WhatsApp] To:', target);
    console.log('[WhatsApp] Message:', message);
    return { sent: false, reason: 'WA_GATEWAY_URL not configured — message logged only' };
  }

  try {
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (WA_GATEWAY_TOKEN) {
      headers['Authorization'] = `Bearer ${WA_GATEWAY_TOKEN}`;
      headers['token'] = WA_GATEWAY_TOKEN;
    }

    const body: Record<string, unknown> = {
      target,
      message,
    };

    const res = await fetch(WA_GATEWAY_URL, {
      method: 'POST',
      headers,
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(15000),
    });

    if (!res.ok) {
      const text = await res.text().catch(() => '');
      console.error('[WhatsApp] Gateway returned', res.status, text);
      return { sent: false, reason: `Gateway HTTP ${res.status}: ${text.slice(0, 200)}` };
    }

    const data = await res.json().catch(() => ({}));
    console.log('[WhatsApp] Message sent to', target, '— gateway response:', JSON.stringify(data).slice(0, 200));
    return { sent: true, gatewayResponse: data };
  } catch (error) {
    console.error('[WhatsApp] Send error:', error);
    return { sent: false, reason: error instanceof Error ? error.message : 'Unknown error' };
  }
}

/**
 * Format a date string (YYYY-MM-DD) into Indonesian day name + date.
 * Returns: { dayName, formattedDate }
 */
export function formatIndoDate(dateStr: string): { dayName: string; formattedDate: string } {
  const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
  const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
  const [y, m, d] = dateStr.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  const dayName = DAY_NAMES[date.getDay()];
  const formattedDate = `${d} ${MONTHS[m - 1]} ${y}`;
  return { dayName, formattedDate };
}

/**
 * Build the WA notification message for a teacher filling attendance.
 * Format: [Nama Panggilan Guru] sudah mengisi absensi untuk [Hari] tanggal [Tanggal] pada [Kelas] dan [Jam]
 */
export function buildAttendanceNotificationMessage(
  teacherNickname: string,
  dayName: string,
  formattedDate: string,
  className: string,
  hour: number
): string {
  return `${teacherNickname} sudah mengisi absensi untuk ${dayName} tanggal ${formattedDate} pada ${className} dan Jam ${hour}`;
}
"},{"path":"prisma/schema.prisma","content":"generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

model Class {
  id          String             @id @default(cuid())
  name        String             @unique
  createdAt   DateTime           @default(now())
  updatedAt   DateTime           @updatedAt
  students    Student[]
  attendance  Attendance[]
  activities  AcademicActivity[]
  waliKelas   WaliKelas?
  schedules   WeeklySchedule[]
}

model Student {
  id        String      @id @default(cuid())
  name      String
  nisn      String      @default("")
  gender    String      @default("")
  whatsapp  String      @default("")
  classId   String
  createdAt DateTime    @default(now())
  updatedAt DateTime    @updatedAt
  class     Class       @relation(fields: [classId], references: [id], onDelete: Cascade)
  attendance Attendance[]
}

model Attendance {
  id        String   @id @default(cuid())
  studentId String
  classId   String
  date      String
  hour      Int
  status    String
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  student   Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)
  class     Class    @relation(fields: [classId], references: [id], onDelete: Cascade)

  @@unique([studentId, date, hour])
}

model AcademicActivity {
  id        String   @id @default(cuid())
  classId   String
  date      String
  status    String   @default("Masuk")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  class     Class    @relation(fields: [classId], references: [id], onDelete: Cascade)

  @@unique([classId, date])
}

model WaliKelas {
  id        String   @id @default(cuid())
  classId   String   @unique
  name      String   @default("")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  class     Class    @relation(fields: [classId], references: [id], onDelete: Cascade)
}

model Settings {
  key   String @id
  value String
}

model AcademicHoliday {
  id        String  @id @default(cuid())
  dayOfWeek Int     @unique
  name      String
  isActive  Boolean @default(true)
}

model DateHoliday {
  id        String   @id @default(cuid())
  date      String   @unique
  name      String
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model WeeklySchedule {
  id        String   @id @default(cuid())
  classId   String
  dayOfWeek Int      // 0=Ahad, 1=Senin, 2=Selasa, 3=Rabu, 4=Kamis, 5=Jumat, 6=Sabtu
  hour      Int      // 1-8
  teacher   String   @default("")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  class     Class    @relation(fields: [classId], references: [id], onDelete: Cascade)

  @@unique([classId, dayOfWeek, hour])
}

model Teacher {
  id        String   @id @default(cuid())
  nickname  String   @unique
  fullName  String   @default("")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}
