set -e
cd /home/z/my-project
git config user.name >/dev/null 2>&1 || git config user.name "Z.ai Code"
git config user.email >/dev/null 2>&1 || git config user.email "z@container"
if git diff --quiet && git diff --cached --quiet && [ -z "$(git ls-files --others --exclude-standard)" ]; then
  echo "[Auto-Commit] No changes to commit."
  exit 0
fi
git add -A
TIMESTAMP=$(date '+%Y-%m-%d %H:%M:%S')
git commit -m "Auto-commit: ${TIMESTAMP}" --no-verify 2>/dev/null || { echo "[Auto-Commit] Nothing to commit."; exit 0; }
echo "[Auto-Commit] ✓ Committed at ${TIMESTAMP}"
echo "[Auto-Commit] Commit: $(git rev-parse --short HEAD)"
if [ -f "db/custom.db" ] && [ -d "upload/db" ]; then cp db/custom.db upload/db/custom.db 2>/dev/null && echo "[Auto-Commit] ✓ DB synced" || true; fi
if [ -f "db/auto_restore.json" ] && [ -d "upload/backups" ]; then cp db/auto_restore.json upload/backups/auto_restore.json 2>/dev/null && echo "[Auto-Commit] ✓ Backup synced" || true; fi
echo "[Auto-Commit] Done."
"},{"path":"scripts/auto-restore.sh","content":"#!/bin/bash
set -e
cd /home/z/my-project
echo "[Auto-Restore] Starting restore from git..."
if [ ! -d ".git" ]; then echo "[Auto-Restore] No .git found."; exit 0; fi
LATEST=$(git rev-parse --short HEAD 2>/dev/null || echo "none")
DELETED=$(git status --porcelain 2>/dev/null | grep '^ D' | wc -l)
KEY_FILES="src/lib/db.ts src/lib/utils.ts src/app/api/auto-restore/route.ts src/components/app/AppShell.tsx prisma/schema.prisma"
MISSING=0
for f in $KEY_FILES; do [ ! -f "$f" ] && MISSING=$((MISSING+1)); done
if [ $MISSING -gt 0 ] || [ $DELETED -gt 0 ]; then
  echo "[Auto-Restore] Restoring ${MISSING} key + ${DELETED} deleted files from git..."
  git checkout -- . 2>/dev/null || true
  git clean -fd -e node_modules -e .next -e db -e upload -e dev.log 2>/dev/null || true
  echo "[Auto-Restore] ✓ Restored from ${LATEST}"
else
  echo "[Auto-Restore] All files present."
fi
[ ! -d "node_modules" ] && echo "[Auto-Restore] Running bun install..." && bun install 2>/dev/null && bun run db:generate 2>/dev/null || true
[ ! -f "db/custom.db" ] && [ -f "upload/db/custom.db" ] && mkdir -p db && cp upload/db/custom.db db/custom.db && echo "[Auto-Restore] ✓ DB restored from upload/" || true
[ ! -f ".env" ] && echo "DATABASE_URL=file:/home/z/my-project/db/custom.db" > .env && echo "[Auto-Restore] ✓ .env created" || true
echo "[Auto-Restore] Done. Commit: ${LATEST}"
"},{"path":"scripts/migrate-to-firebase.ts","content":"/**
 * Data migration script: SQLite (Prisma) → Firestore
 *
 * Reads all data from the existing SQLite database and writes to Firestore.
 * Run this ONCE during migration.
 *
 * Usage:
 *   bun run scripts/migrate-to-firebase.ts
 *
 * Before running:
 *   1. Set FIREBASE_* env vars in .env (or FIREBASE_KEY_PATH)
 *   2. Ensure upload/db/custom.db exists with data
 *   3. Run in sandbox — data syncs to cloud Firestore
 *
 * What this script does:
 *   1. Initializes Prisma (read-only — reads from SQLite)
 *   2. Initializes Firebase Admin SDK
 *   3. For each of the 9 tables:
 *      - Reads all records from SQLite (in batches if large)
 *      - Writes to Firestore using batch writes (450 per batch)
 *      - Uses composite document IDs for unique constraints
 *   4. Logs progress per collection
 *
 * After running:
 *   - Verify data in Firebase Console (Firestore → Data tab)
 *   - All 9 collections should have data
 *   - Document IDs match the composite key strategy
 */

// We import dynamically so the script can run even if firebase-admin
// isn't installed yet (for planning purposes)
import { firestore } from 'firebase-admin';

async function main() {
  console.log('=== Firebase Migration Script ===');
  console.log('');

  // 1. Initialize Firebase
  console.log('[1/4] Initializing Firebase Admin SDK...');
  const { firebaseApp, firestoreDb } = await import('../src/lib/firebase');
  if (!firestoreDb) {
    console.error('❌ Firebase not initialized. Check FIREBASE_* env vars.');
    process.exit(1);
  }
  console.log('✅ Firebase initialized:', firebaseApp?.options.projectId);
  console.log('');

  // 2. Initialize Prisma (read-only)
  console.log('[2/4] Initializing Prisma (read SQLite)...');
  const { PrismaClient } = await import('@prisma/client');
  const prisma = new PrismaClient({
    log: ['error', 'warn'],
  });
  console.log('✅ Prisma initialized');
  console.log('');

  // 3. Define collection mapping + document ID strategy
  type MigrateConfig = {
    name: string;
    collection: string;
    getData: () => Promise<any[]>;
    getDocId: (record: any) => string | undefined;
  };

  const configs: MigrateConfig[] = [
    {
      name: 'classes',
      collection: 'classes',
      getData: () => prisma.class.findMany(),
      getDocId: (r) => r.id, // auto-id (cuid) from SQLite
    },
    {
      name: 'students',
      collection: 'students',
      getData: () => prisma.student.findMany(),
      getDocId: (r) => r.id,
    },
    {
      name: 'attendance',
      collection: 'attendance',
      getData: () => prisma.attendance.findMany(),
      getDocId: (r) => `${r.studentId}_${r.date}_${r.hour}`,
    },
    {
      name: 'activities',
      collection: 'activities',
      getData: () => prisma.academicActivity.findMany(),
      getDocId: (r) => `${r.classId}_${r.date}`,
    },
    {
      name: 'waliKelas',
      collection: 'waliKelas',
      getData: () => prisma.waliKelas.findMany(),
      getDocId: (r) => r.classId, // @unique
    },
    {
      name: 'settings',
      collection: 'settings',
      getData: () => prisma.settings.findMany(),
      getDocId: (r) => r.key, // @id
    },
    {
      name: 'academicHolidays',
      collection: 'academicHolidays',
      getData: () => prisma.academicHoliday.findMany(),
      getDocId: (r) => String(r.dayOfWeek), // @unique
    },
    {
      name: 'dateHolidays',
      collection: 'dateHolidays',
      getData: () => prisma.dateHoliday.findMany(),
      getDocId: (r) => r.date, // @unique
    },
    {
      name: 'weeklySchedules',
      collection: 'weeklySchedules',
      getData: () => prisma.weeklySchedule.findMany(),
      getDocId: (r) => `${r.classId}_${r.dayOfWeek}_${r.hour}`,
    },
    {
      name: 'teachers',
      collection: 'teachers',
      getData: () => prisma.teacher.findMany(),
      getDocId: (r) => r.nickname, // @unique
    },
  ];

  // 4. Convert Prisma record to Firestore-ready data
  function toFirestoreData(record: any): Record<string, unknown> {
    const data: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(record)) {
      if (value instanceof Date) {
        // Firestore Timestamp
        data[key] = firestore.Timestamp.fromDate(value);
      } else {
        data[key] = value;
      }
    }
    return data;
  }

  // 5. Migrate each collection
  console.log('[3/4] Migrating data to Firestore...');
  console.log('');

  let totalMigrated = 0;
  const batchSize = 450; // Firestore batch limit is 500

  for (const config of configs) {
    console.log(`  Migrating ${config.name}...`);
    const records = await config.getData();
    console.log(`    Read ${records.length} records from SQLite`);

    if (records.length === 0) {
      console.log(`    ✓ Skipped (no data)`);
      continue;
    }

    let migrated = 0;
    for (let i = 0; i < records.length; i += batchSize) {
      const batch = firestoreDb.batch();
      const chunk = records.slice(i, i + batchSize);

      for (const record of chunk) {
        const docId = config.getDocId(record) || firestoreDb.collection(config.collection).doc().id;
        const ref = firestoreDb.collection(config.collection).doc(docId);
        const data = toFirestoreData(record);
        batch.set(ref, data, { merge: true }); // merge=true → overwrite existing
      }

      await batch.commit();
      migrated += chunk.length;

      // Progress log for large collections
      if (records.length > 1000 && migrated % 1000 === 0) {
        console.log(`    Progress: ${migrated}/${records.length}`);
      }
    }

    console.log(`    ✓ Migrated ${migrated} records to "${config.collection}" collection`);
    totalMigrated += migrated;
  }

  console.log('');
  console.log('[4/4] Migration complete!');
  console.log(`✅ Total records migrated: ${totalMigrated}`);
  console.log('');
  console.log('Next steps:');
  console.log('  1. Verify data in Firebase Console:');
  console.log('     https://console.firebase.google.com → Firestore → Data');
  console.log('  2. Change import in API routes:');
  console.log('     find src/app/api -name "route.ts" -exec sed -i "s|@/lib/db|@/lib/firebase-db|g" {} +');
  console.log('  3. Run: bun run dev');
  console.log('  4. Test endpoints with curl');
  console.log('');

  await prisma.$disconnect();
  process.exit(0);
}

// Run migration
main().catch((e) => {
  console.error('❌ Migration failed:', e instanceof Error ? e.message : String(e));
  if (e instanceof Error && e.stack) {
    console.error(e.stack.split('\n').slice(0, 5).join('\n'));
  }
  process.exit(1);
});
